prompt Creating table BLAGAJNE
prompt =======================
prompt
create table ACCOUNTING.BLAGAJNE
(
  id              NUMBER default on null accounting.blagajne_seq.nextval not null,
  ooj_id          NUMBER,
  kontna_klasa_id NUMBER,
  valuta_id       NUMBER,
  tip             VARCHAR2(2 CHAR),
  naziv           VARCHAR2(255 CHAR),
  valid           VARCHAR2(1 CHAR) default on null 'Y' not null,
  row_version     INTEGER not null,
  created         DATE not null,
  created_by      VARCHAR2(255 CHAR) not null,
  updated         DATE not null,
  updated_by      VARCHAR2(255 CHAR) not null
)
;
create index ACCOUNTING.BLAGAJNE_I1 on ACCOUNTING.BLAGAJNE (OOJ_ID);
create index ACCOUNTING.BLAGAJNE_I2 on ACCOUNTING.BLAGAJNE (KONTNA_KLASA_ID);
create index ACCOUNTING.BLAGAJNE_I3 on ACCOUNTING.BLAGAJNE (VALUTA_ID);
alter table ACCOUNTING.BLAGAJNE
  add constraint BLAGAJNE_ID_PK primary key (ID);
alter table ACCOUNTING.BLAGAJNE
  add constraint BLAGAJNE_KONTNA_KLASA_ID_FK foreign key (KONTNA_KLASA_ID)
  references SIF.ACC_KONTNI_OKVIR_KLASE (ID)
  disable
  novalidate;
alter table ACCOUNTING.BLAGAJNE
  add constraint BLAGAJNE_OOJ_ID_FK foreign key (OOJ_ID)
  references CORE.OOJ (ID)
  disable
  novalidate;
alter table ACCOUNTING.BLAGAJNE
  add constraint BLAGAJNE_VALUTA_ID_FK foreign key (VALUTA_ID)
  references SIF.ACC_VALUTE (ID)
  disable
  novalidate;
alter table ACCOUNTING.BLAGAJNE
  add constraint BLAGAJNE_TIP_CK
  check ( tip in ( 'B', 'DB' ) )
  disable
  novalidate;
alter table ACCOUNTING.BLAGAJNE
  add constraint BLAGAJNE_VALID_CK
  check ( valid in ( 'Y', 'N' ) )
  disable
  novalidate;

