  storniran_id     NUMBER,
  ooj_banka_id     NUMBER,
  broj_izvoda      NUMBER,
  pocetno_stanje   NUMBER,
  zakljucno_stanje NUMBER,
  valid            VARCHAR2(1 CHAR) default on null 'Y' not null,
  row_version      INTEGER not null,
