create table ACCOUNTING.UGOVORI
(
  id                    NUMBER default on null accounting.ugovori_seq.nextval not null,
  ooj_id                NUMBER,
  klijent_id            NUMBER,
  valuta_id             NUMBER,
  izvrsilac_narucioc    VARCHAR2(1 CHAR),
  ugovor_start          DATE,
  ugovor_end            DATE,
  iznos                 NUMBER,
  broj                  NUMBER not null,
  predmet               VARCHAR2(4000 CHAR),
  valid                 VARCHAR2(1 CHAR) default on null 'Y' not null,
  naziv                 VARCHAR2(255 CHAR),
  referenca             VARCHAR2(1 CHAR),
  referenca_id          NUMBER,
  oj_id                 NUMBER,
  interval_id           NUMBER,
  system                VARCHAR2(1 CHAR) default 'N' not null,
  godina                NUMBER,
  vrsta_ugovora_id      NUMBER,
  status                VARCHAR2(1 CHAR) default 'P' not null,
  kurs                  NUMBER(12,6),
  iznos_km              NUMBER,
  dan_dospijeca         NUMBER(2),
  otkazni_rok_dana      NUMBER(4),
  automatsko_produzenje VARCHAR2(1 CHAR) default 'N' not null,
  produzenje_mjeseci    NUMBER(3),
  aneks_broj            NUMBER(3),
  row_version           INTEGER not null,
  created               DATE not null,
  created_by            VARCHAR2(255 CHAR) not null,
  updated               DATE not null,
  updated_by            VARCHAR2(255 CHAR) not null
)
;
comment on table ACCOUNTING.UGOVORI
  is 'Zaglavlje ugovora sa partnerom; aneks je novi red koji pokazuje na osnovni ugovor';
comment on column ACCOUNTING.UGOVORI.izvrsilac_narucioc
  is 'Uloga klijenta: N = klijent je naručilac (firma izdaje fakture), I = klijent je izvršilac (firma prima fakture)';
comment on column ACCOUNTING.UGOVORI.ugovor_start
  is 'Prvi dan važenja ugovora';
comment on column ACCOUNTING.UGOVORI.ugovor_end
  is 'Posljednji dan važenja ugovora';
comment on column ACCOUNTING.UGOVORI.iznos
  is 'Ukupna vrijednost ugovora u valuti ugovora; kad ugovor ima stavke, zbir stavki';
comment on column ACCOUNTING.UGOVORI.referenca
  is 'Y = aneks osnovnog ugovora, N = osnovni ugovor';
comment on column ACCOUNTING.UGOVORI.referenca_id
  is 'Osnovni ugovor na koji se aneks odnosi';
comment on column ACCOUNTING.UGOVORI.vrsta_ugovora_id
  is 'FK - sif.acc_vrste_ugovora.id - vrsta ugovora';
comment on column ACCOUNTING.UGOVORI.status
  is 'Status ugovora: P - u pripremi (može se mijenjati), Z - zaključen (ne mijenja se), R - raskinut; istekao se izvodi iz UGOVOR_END';
comment on column ACCOUNTING.UGOVORI.kurs
  is 'Kurs valute ugovora prema KM na dan početka ugovora';
comment on column ACCOUNTING.UGOVORI.iznos_km
  is 'Ukupna vrijednost ugovora u KM: IZNOS x KURS';
comment on column ACCOUNTING.UGOVORI.dan_dospijeca
  is 'Dan u mjesecu do kojeg dospijeva plaćanje po ugovoru';
comment on column ACCOUNTING.UGOVORI.otkazni_rok_dana
  is 'Otkazni rok u danima';
comment on column ACCOUNTING.UGOVORI.automatsko_produzenje
  is 'Y = ugovor se produžava ako nije otkazan na vrijeme';
comment on column ACCOUNTING.UGOVORI.produzenje_mjeseci
  is 'Trajanje jednog produženja u mjesecima';
comment on column ACCOUNTING.UGOVORI.aneks_broj
  is 'Redni broj aneksa za osnovni ugovor (1, 2, 3 ...); prazno kod osnovnog ugovora';
create index ACCOUNTING.UGOVORI_I1 on ACCOUNTING.UGOVORI (OOJ_ID);
create index ACCOUNTING.UGOVORI_I2 on ACCOUNTING.UGOVORI (KLIJENT_ID);
create index ACCOUNTING.UGOVORI_I3 on ACCOUNTING.UGOVORI (VALUTA_ID);
create index ACCOUNTING.UGOVORI_REFERENCA_I on ACCOUNTING.UGOVORI (REFERENCA_ID);
create index ACCOUNTING.UGOVORI_VRSTA_UGOVORA_I on ACCOUNTING.UGOVORI (VRSTA_UGOVORA_ID);
