  references SIF.SIF_INTERVALI (ID)
  disable
  novalidate;
alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_KLIJENT_ID_FK foreign key (KLIJENT_ID)
  references ACCOUNTING.SEC_KLIJENTI (ID)
  disable
  novalidate;
alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_OJ_ID_FK foreign key (OJ_ID)
  references CORE.OJ (ID)
  disable
  novalidate;
alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_OOJ_ID_FK foreign key (OOJ_ID)
  references CORE.OOJ (ID)
  disable
  novalidate;
alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_REFERENCA_ID_FK foreign key (REFERENCA_ID)
  references ACCOUNTING.UGOVORI (ID)
  disable
  novalidate;
