  add constraint UGOVORI_VRSTA_UGOVORA_FK foreign key (VRSTA_UGOVORA_ID)
  references SIF.ACC_VRSTE_UGOVORA (ID);
alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_AUTOMATSKO_PRODUZENJE_CK
  check (automatsko_produzenje IN ('Y', 'N'));
