  add constraint UGOVORI_OTKAZNI_ROK_CK
  check (otkazni_rok_dana IS NULL OR otkazni_rok_dana >= 0);
alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_PRODUZENJE_MJESECI_CK
