alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_STATUS_CK
  check (status IN ('P', 'Z', 'R'));
alter table ACCOUNTING.UGOVORI
  add constraint UGOVORI_SYSTEM_CK
  check ( system in ( 'Y', 'N' ) )
  disable
  novalidate;
alter table ACCOUNTING.UGOVORI
