prompt Creating table KUF
prompt ==================
prompt
create table ACCOUNTING.KUF
(
  id                   NUMBER default on null accounting.kuf_seq.nextval not null,
  glavna_knjiga_id     NUMBER,
  ooj_id               NUMBER,
  klijent_id           NUMBER,
  datum_prijema        DATE,
  datum_fakture        DATE,
  datum_valute         DATE,
  iznos_bez_pdv        NUMBER,
  iznos_sa_pdv         NUMBER,
  valuta_id            NUMBER,
  valuta_iznos_bez_pdv NUMBER,
  valuta_iznos_sa_pdv  NUMBER,
  document             BLOB,
  document_filename    VARCHAR2(255),
  document_mimetype    VARCHAR2(255),
  document_charset     VARCHAR2(255),
  document_lastupd     DATE,
  tip_placanja_id      NUMBER not null,
  fiskalni_racun_broj  VARCHAR2(255),
  naziv_fakture        VARCHAR2(255),
  uio_tip_dokumenta_id NUMBER,
  stornirano           VARCHAR2(1 CHAR) default 'N',
  storniran_id         NUMBER,
  uplaceno             VARCHAR2(1 CHAR) default 'N',
  datum_uplatnice      DATE,
  naziv                VARCHAR2(255 CHAR),
  broj                 NUMBER,
  uplaceno_rucno       NUMBER,
  pdv_indikator_id     NUMBER,
  ugovor_id            NUMBER,
  godina               NUMBER,
  status               VARCHAR2(20) default 'P',
  valid                VARCHAR2(1) default on null 'Y' not null,
  row_version          INTEGER not null,
  created              DATE not null,
  created_by           VARCHAR2(255) not null,
  updated              DATE not null,
  updated_by           VARCHAR2(255) not null
)
;
comment on column ACCOUNTING.KUF.glavna_knjiga_id
  is 'referenca na nalog glavne knjige kroz koji je faktura proknjižena ';
comment on column ACCOUNTING.KUF.ooj_id
  is 'referenca na oj ';
comment on column ACCOUNTING.KUF.klijent_id
  is 'referenca na partnera';
comment on column ACCOUNTING.KUF.datum_prijema
  is 'datum protokolisanja fakture od strane firme kojoj je faktura isporučena';
comment on column ACCOUNTING.KUF.datum_fakture
  is 'datum izdavanja fakture, datum koji je bitan za knjiženje ';
comment on column ACCOUNTING.KUF.datum_valute
  is 'datum dospjeća fakture odnosno datum do koje se mora platiti';
comment on column ACCOUNTING.KUF.iznos_bez_pdv
  is 'iznos u KM, referentan za knjiženje i pdv prijavu';
comment on column ACCOUNTING.KUF.iznos_sa_pdv
  is 'iznos u KM, referntan za knjiženej i pdv prijavu';
comment on column ACCOUNTING.KUF.valuta_id
  is 'valuta fakture';
comment on column ACCOUNTING.KUF.valuta_iznos_bez_pdv
  is 'iznos u valuti, iz kojeg se preračunava iznos u KM';
comment on column ACCOUNTING.KUF.valuta_iznos_sa_pdv
  is 'iznos u valuti, iz kojeg se preračunava iznos u KM';
comment on column ACCOUNTING.KUF.document
  is 'skenirani dokument';
comment on column ACCOUNTING.KUF.tip_placanja_id
  is 'vrsta plaćanja fakture ';
comment on column ACCOUNTING.KUF.fiskalni_racun_broj
  is 'fiskalni račun ';
comment on column ACCOUNTING.KUF.naziv_fakture
  is 'opis fakture';
comment on column ACCOUNTING.KUF.uio_tip_dokumenta_id
  is 'vrsta fakture (redovna, avansna itd)';
comment on column ACCOUNTING.KUF.ugovor_id
  is 'FK - ugovori.id - ugovor po kojem je ulazna faktura primljena';
comment on column ACCOUNTING.KUF.status
  is 'Status fakture: P - u pripremi, Z - zaključana, spremna za knjiženje, K - proknjižena';
create index ACCOUNTING.KUF_I1 on ACCOUNTING.KUF (GLAVNA_KNJIGA_ID);
create index ACCOUNTING.KUF_I2 on ACCOUNTING.KUF (OOJ_ID);
create index ACCOUNTING.KUF_I3 on ACCOUNTING.KUF (KLIJENT_ID);
