create index ACCOUNTING.UIO_KIF_I1 on ACCOUNTING.UIO_KIF (OOJ_ID);
create index ACCOUNTING.UIO_KIF_I2 on ACCOUNTING.UIO_KIF (FAKTURA_ID);
alter table ACCOUNTING.UIO_KIF
  add constraint UIO_KIF_ID_PK primary key (ID);
alter table ACCOUNTING.UIO_KIF
  add constraint UIO_KIF_FAKTURA_ID_FK foreign key (FAKTURA_ID)
  references ACCOUNTING.KIF (ID)
  disable
  novalidate;
