  add constraint UIO_KIF_OOJ_ID_FK foreign key (OOJ_ID)
  references CORE.OOJ (ID)
  disable
  novalidate;
alter table ACCOUNTING.UIO_KIF
  add constraint UIO_KIF_VALID_CK
  check ( valid in ( 'Y', 'N' ) )
  disable
