prompt
prompt Creating view VW_1007
prompt =====================
prompt
create or replace force view accounting.vw_1007 as
with obrazac_1007 as (
        select
            gks.iznos,
            soj.id                          as ooj_id,
            soj.jib,
            soj.naziv                       as naziv_obveznika,
            soj.adresa,
            soj.grad_id,
            (
                select
                    lpad(sg.sifra, 3, 0)
                from
                    sif.sif_gradovi sg
                where
                    sg.id = soj.grad_id
            )                               as sifra_grada,
            soj.tel,
            soj.email,
            gks.tip_stavke,
            trunc(gk.datum_dokumenta, 'mm') as datum_dokumenta
        from
            glavna_knjiga_stavke gks
            left join glavna_knjiga        gk on gk.id = gks.glavna_knjiga_id
            left join core.ooj             soj on gk.ooj_id = soj.id
        where
            gks.glavna_knjiga_id in (
                select
                    id
                from
                    glavna_knjiga
                where
                        vrsta_naloga_id = 3
                    and ooj_id = soj.id
            )
            and tip_stavke = 'P'
    )
    select
        unique(jib)               as jib,
        ooj_id,
        naziv_obveznika,
        adresa,
        sifra_grada,
        tel                       as telefon,
        email,
        sum(iznos) * 0.02         as porez,
        sum(iznos)                as naplaceni_prihod,
        datum_dokumenta,
        datum_dokumenta           as poreski_period_od,
        last_day(datum_dokumenta) as poreski_period_do
    from
        obrazac_1007
    group by
        jib,
        naziv_obveznika,
        adresa,
        sifra_grada,
        tel,
        email,
        datum_dokumenta,
        ooj_id;

prompt
prompt Creating view VW_BLAGAJNA_DNEVNIK
prompt =================================
prompt
create or replace force view accounting.vw_blagajna_dnevnik as
select
        bd.id,
        bd.ooj_id,
        ooj.naziv          as ooj_naziv,
        bd.blagajna_id,
        b.naziv            as blagajna_naziv,
        b.kontna_klasa_id,
        b.valuta_id,
        v.naziv as valuta_naziv,
        bd.glavna_knjiga_id,
        gk.broj            as glavna_knjiga_broj,
        gk.datum_knjizenja as glavna_knjiga_datum_knjizenja,
        bd.datum,
        bd.pocetno_stanje,
        bd.prijem,
        bd.placanja,
        bd.zakljucno_stanje,
        bd.godina,
        bd.row_version,
        bd.created,
        bd.created_by,
        bd.updated,
        bd.updated_by
    from
        blagajna_dnevnik bd
        left join core.ooj on bd.ooj_id = ooj.id
        left join blagajne         b on bd.blagajna_id = b.id
        left join glavna_knjiga    gk on bd.glavna_knjiga_id = gk.id
        left join sif.acc_valute   v on b.valuta_id = v.id;

prompt
prompt Creating view VW_BLAGAJNA_DNEVNIK_STAVKE
prompt ========================================
prompt
create or replace force view accounting.vw_blagajna_dnevnik_stavke as
select
        bds.id,
        bds.dnevnik_id,
        case
            when bd.zakljucno_stanje is not null then
                'Y'
            else
                'N'
        end as zakljucano,
        bd.datum     as dnevnik_datum,
        bd.godina,
        bd.ooj_id,
        ooj.naziv    as ooj_naziv,
        bd.blagajna_id,
        b.naziv AS blagajna_naziv,
        bds.tip_promjene_id,
        tp.naziv     as tip_promjene_naziv,
        tp.kontna_klasa_id,
        bds.radnik_id,
        r.ime
        || ' '
        || r.prezime as radnik_naziv,
        bds.klijent_id,
        k.naziv      as klijent_naziv,
        bds.oj_id,
        oj.naziv     as oj_naziv,
        bds.redni_broj,
        bds.tip,
        bds.iznos,
        b.valuta_id,
        v.naziv      as valuta_naziv,
        bds.row_version,
        bds.created,
        bds.created_by,
        bds.updated,
        bds.updated_by
    from
        blagajna_dnevnik_stavke  bds
        left join blagajna_dnevnik         bd on bds.dnevnik_id = bd.id
        left join blagajne                 b  on bd.blagajna_id = b.id
        left join sif.acc_valute           v  on b.valuta_id = v.id
        left join blagajna_tipovi_promjena tp on bds.tip_promjene_id = tp.id
        left join hrm.hr_radnici           r on bds.radnik_id = r.id
        left join sec_klijenti             k on bds.klijent_id = k.id
        left join core.oj on bds.oj_id = oj.id
        left join core.ooj on bd.ooj_id = ooj.id;

prompt
prompt Creating view VW_BUDZETI
prompt ========================
prompt
create or replace force view accounting.vw_budzeti as
select
        b.id,
        b.ooj_id,
        ooj.naziv      as ooj_naziv,
        b.status_id,
        bs.naziv       as status_naziv,
        bs.sifra       as status_sifra,
        bs.color_code  as status_color_code,
        b.interval_id,
        i.naziv        as interval_naziv,
        i.broj_mjeseci as interval_broj_mjeseci,
        b.valuta_id,
        v.naziv        as valuta_naziv,
        v.sifra        as valuta_sifra,
        b.budzet_id,
        n.napomena     as budzet_napomena,
        case
            when b.budzet_id is not null then
                row_number()
                over(partition by b.budzet_id
                     order by
                         b.budzet_id
                )
            else
                null
        end            as budzet_rebalans_rb,
        case
            when b.budzet_id is not null then
                b.godina
                || ' ( '
                || to_char(row_number()
                           over(partition by b.budzet_id
                                order by
                                    b.id
                ))
                || ' )'
            else
                to_char(b.godina)
        end            as godina_naziv,
        b.godina,
        b.napomena,
        b.valid,
        b.row_version,
        b.created,
        b.created_by,
        b.updated,
        b.updated_by
    from
        budzeti            b
        left join core.ooj on b.ooj_id = ooj.id
        left join sif.budzet_statusi bs on b.status_id = bs.id
        left join sif.sif_intervali  i on b.interval_id = i.id
        left join sif.acc_valute     v on b.valuta_id = v.id
        left join budzeti            n on b.budzet_id = n.id;

prompt
prompt Creating view VW_BUDZETSKE_STAVKE
prompt =================================
prompt
create or replace force view accounting.vw_budzetske_stavke as
select
