        bs.stavka_id,
        s.naziv   as stavka_naziv,
        bs.oj_id,
        oj.naziv  as oj_naziv,
        bs.naziv,
        bs.valid,
        bs.row_version,
        bs.created,
        bs.created_by,
        bs.updated,
        bs.updated_by
    from
        budzetske_stavke bs
        left join core.ooj on bs.ooj_id = ooj.id
        left join budzetske_stavke s on bs.stavka_id = s.id
        left join core.oj on bs.oj_id = oj.id;

