prompt Creating view VW_BUDZET_STAVKE
prompt ==============================
prompt
create or replace force view accounting.vw_budzet_stavke as
select
        s.id,
        s.budzet_id,
        s.oj_id,
        oj.naziv     as oj_naziv,
        s.stavka_id,
        bs.naziv     as stavka_naziv,
        bs.stavka_id as stavka_parent_id,
        s.projekat_id,
        p.naziv      as projekat_naziv,
        s.period,
        s.iznos,
        s.iznos_realizacija,
        s.napomena,
        s.valid,
        s.row_version,
        s.created,
        s.created_by,
        s.updated,
        s.updated_by
    from
        budzet_stavke    s
        left join budzetske_stavke bs on s.stavka_id = bs.id
        left join hrm.p_projekti   p on s.projekat_id = p.id
        left join core.oj on s.oj_id = oj.id;

prompt
prompt Creating view VW_BUDZET_OJ
prompt ==========================
prompt
create or replace force view accounting.vw_budzet_oj as
select
        boj.id,
        boj.budzet_id,
        boj.oj_id,
        oj.naziv      as oj_naziv,
        boj.max_iznos,
        boj.status_id,
        bs.naziv      as status_naziv,
        bs.sifra      as status_sifra,
        bs.color_code as status_color_code,
        (
            select
                sum(iznos)
            from
                vw_budzet_stavke vwbs
            where
                    boj.budzet_id = vwbs.budzet_id
                and boj.oj_id = vwbs.oj_id
        )             as stavke_sum,
        boj.row_version,
        boj.created,
        boj.created_by,
        boj.updated,
        boj.updated_by
    from
        budzet_oj          boj
        left join core.oj on boj.oj_id = oj.id
        left join sif.budzet_statusi bs on boj.status_id = bs.id;

