prompt
prompt Creating view VW_BUDZET_REALOKACIJA
prompt ===================================
prompt
create or replace force view accounting.vw_budzet_realokacija as
select
        br.id,
        br.budzet_id,
        br.stavka_1_id,
        bs1.stavka_id as budzetska_stavka_1_id,
        s1.naziv      as stavka_1_naziv,
        bs1.oj_id     as oj_1_id,
        bs1.period    as period_1,
        br.stavka_2_id,
        bs2.stavka_id as budzetska_stavka_2_id,
        s2.naziv      as stavka_2_naziv,
        bs2.oj_id     as oj_2_id,
        bs2.period    as period_2,
        br.iznos,
        br.napomena,
        br.datum,
        br.row_version,
        br.created,
        br.created_by,
        br.updated,
        br.updated_by
    from
