        left join vw_budzet_stavke   bs1 on br.stavka_1_id = bs1.id
        left join vw_budzet_stavke   bs2 on br.stavka_2_id = bs2.id
        left join budzetske_stavke   s1 on bs1.stavka_id = s1.id
        left join budzetske_stavke   s2 on bs2.stavka_id = s2.id;

