prompt
prompt Creating view VW_CJENOVNIK_STAVKE
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_CJENOVNIK_STAVKE AS
SELECT
	cs.id,
    cs.cjenovnik_id,
    cj.sifra AS cjenovnik_sifra,
    cj.naziv AS cjenovnik_naziv,
	cs.stavka_id,
	s.ooj_id,
	s.sifra AS stavka_sifra,
	s.naziv AS stavka_naziv,
	s.grupa_id AS grupa_id,
	gs.naziv AS grupa_naziv,
	s.klasa_id AS klasa_id,
	ks.naziv AS klasa_naziv,
  ts.id as stavka_tip_id,
  ts.naziv as stavka_tip_naziv,

	cs.datum,
	cs.nabavna_cijena,
	cs.mpc,
	cs.vpc,
	cs.valid,
	cs.row_version,
	cs.created,
	cs.created_by,
	cs.updated,
	cs.updated_by
FROM cjenovnik_stavke cs
LEFT JOIN cjenovnici cj ON cs.cjenovnik_id = cj.id
LEFT JOIN sec_stavke s ON cs.stavka_id = s.id
LEFT JOIN sif.acc_tipovi_stavki ts on ts.id=s.tip_stavke_id
LEFT JOIN sif.acc_grupe_stavki gs ON s.grupa_id = gs.id
LEFT JOIN sec_klase_stavki ks ON s.klasa_id = ks.id;

prompt
prompt Creating view VW_GK_ANALITIKA_ZATVARANJA
prompt ========================================
prompt
create or replace force view accounting.vw_gk_analitika_zatvaranja as
select z.id,
       gs1.opis as opis_stavke_o,gs1.datum_dokumenta datum_dokumenta_o, gsd1.dokument referentni_dokument_o, gsd1.opis as opis_referentnog_dokumenta_o,
       gs2.opis as opis_stavke_z,gs2.datum_dokumenta datum_dokumenta_z, gsd2.dokument referentni_dokument_z, gsd2.opis as opis_referentnog_dokumenta_z,
       gs1.iznos as iznos_o,gs2.iznos as iznos_z,
       case when gs1.tip_stavke = 'P' then 'Potražuje' else 'Duguje' end as strana_knjizena_o,
       case when gs2.tip_stavke = 'P' then 'Potražuje' else 'Duguje' end as strana_knjizena_z,
       rpad(ak.code, o.konto_duzina, '0') || '-' || ak.naziv as konto, ak.id as konto_id,
       lpad(gg.sifra, 3, '0') || '-' || gg.naziv as opstina, gg.id as opstina_id,
       kl.naziv as partner,kl.id as partner_id,
       gs1.radnik_id,
       gs1.oj_id mt_id, mt.naziv as mjesto_troska,
       o.id as ooj_id,
       z.iznos_zatvaranja, z.created as datum_zatvaranja, z.broj, z.storno
from accounting.gk_analitika_zatvaranja z
join accounting.glavna_knjiga_stavke gs1 on z.o_stavka_id=gs1.id
join core.ooj o on o.id=z.ooj_id
join accounting.gk_stavke_dokument gsd1 on gsd1.glavna_knjiga_stavka_id=gs1.id
join accounting.glavna_knjiga_stavke gs2 on z.z_stavka_id=gs2.id
join accounting.gk_stavke_dokument gsd2 on gsd2.glavna_knjiga_stavka_id=gs2.id
left join accounting.sec_klijenti kl on kl.id = gs1.klijent_id
left join sif.acc_kontni_okvir_klase ak on ak.id = gs1.kontna_klasa_id
left join sif.sif_gradovi gg on gg.id = gs1.grad_id
left join core.oj mt on mt.id=gs1.oj_id;

prompt
prompt Creating view VW_GK_OTVORENE_STAVKE
prompt ===================================
prompt
create or replace force view accounting.vw_gk_otvorene_stavke as
select gks.id,gks.opis as opis_stavke, gsd.dokument referentni_dokument, gsd.opis as opis_referentnog_dokumenta,
       gks.iznos, gks.otvoreni_iznos,
       gks.tip_stavke,
       case when gks.tip_stavke = 'P' then 'Potražuje' else 'Duguje' end as strana_knjizena,
       rpad(ak.code, o.konto_duzina, '0') || '-' || ak.naziv as konto, ak.id as konto_id,
       lpad(gg.sifra, 3, '0') || '-' || gg.naziv as opstina, gg.id as opstina_id,
       kl.naziv as partner,kl.id as partner_id,
       gks.acc_radnik_id as radnik_id, r.ime||'- '||r.prezime as radnik,
       gks.datum_dokumenta,
       gks.mjesto_troska_id mt_id, mt.sifra||'-'||mt.naziv as mjesto_troska,
       o.id as ooj_id
from accounting.glavna_knjiga gk
join accounting.glavna_knjiga_stavke gks on gk.id = gks.glavna_knjiga_id
join core.ooj o on o.id=gk.ooj_id
left join accounting.gk_stavke_dokument gsd on gsd.glavna_knjiga_stavka_id = gks.id
left join accounting.sec_klijenti kl on kl.id = gks.klijent_id
left join sif.acc_kontni_okvir_klase ak on ak.id = gks.kontna_klasa_id
left join sif.sif_gradovi gg on gg.id = gks.grad_id
left join sif.acc_mjesta_troska mt on mt.id=gks.mjesto_troska_id
left join sif.acc_radnici r on r.id=gks.radnik_id
where 1=1
and gks.otvorena in ('O','DZ')
and gks.otvoreni_iznos<>0;

prompt
prompt Creating view VW_KUFOVI
prompt =======================
prompt
create or replace force view accounting.vw_kufovi as
select ooj.id as ooj_id, ooj.naziv as ooj_naziv,kl.id as partner_id, kl.naziv as partner_naziv,
       k.id as kuf_id, k.godina,k.naziv_fakture, k.uio_tip_dokumenta_id,ut.code tip_dokumenta_sifra, ut.code||'-'||ut.naziv as tip_dokumenta,
       k.broj, k.datum_prijema, k.datum_fakture, k.datum_valute, v.id as valuta_id, v.sifra as valuta,
       tp.id as tip_placanja_id, tp.naziv as tip_placanje,
       k.iznos_bez_pdv, k.iznos_sa_pdv, k.valuta_iznos_bez_pdv, k.valuta_iznos_sa_pdv,
       k.status,vn.id as vrsta_naloga_id,case when k.glavna_knjiga_id is null then null else vn.sifra||'/'||gk.broj||'/'||gk.godina end  as nalog_gk,
       k.pdv_indikator_id,pd.sifra as pdv_indikator_sifra, pd.naziv as pdv_indikator,
       k.naziv as interni_naziv
from accounting.kuf k
join core.ooj ooj on k.ooj_id = ooj.id
join sec_klijenti            kl on k.klijent_id = kl.id
join sif.acc_tipovi_placanja tp on k.tip_placanja_id = tp.id
join sif.acc_valute          v on k.valuta_id = v.id
join sif.acc_uio_tipovi_dokumenata ut on ut.id=k.uio_tip_dokumenta_id
left join sif.acc_pdv_indikatori pd on pd.id=k.pdv_indikator_id
left join accounting.glavna_knjiga gk on gk.id=k.glavna_knjiga_id
join sif.sif_vrste_naloga vn on vn.sifra='UF' and vn.ooj_id=k.ooj_id;

prompt
prompt Creating view VW_GK_REFERENTNI_DOKUMENTI
prompt ========================================
prompt
create or replace force view accounting.vw_gk_referentni_dokumenti as
select 1 as modul_id,iz.id as dokument_id,zr.sifra,  iz.godina, iz.broj, iz.datum, iz.novi_saldo-iz.prethodni_saldo as promet, iz.opis,null as partner,  null as pdv_indikator, null iznos_bez_pdv, null iznos_sa_pdv
from accounting.izvodi iz
join sif.sif_ziro_racuni zr on zr.id=iz.ziro_racun_id
union
select 3 as modul,k.kuf_id as dokument_id,'UF' as sifra, k.godina, k.broj, k.datum_fakture  as datum, null promet, k.naziv_fakture as opis, k.partner_naziv as partner, k.pdv_indikator, k.iznos_bez_pdv, k.iznos_sa_pdv
from vw_kufovi k;

prompt
prompt Creating view VW_GLAVNA_KNJIGA
prompt ==============================
prompt
create or replace force view accounting.vw_glavna_knjiga as
select
        k.id,
        k.ooj_id,
        ooj.naziv     as ooj_naziv,
        k.vrsta_naloga_id,
        vn.sifra      as vrsta_naloga_sifra,
        vn.naziv      as vrsta_naloga_naziv,
        k.godina,
        k.broj,
        k.datum_dokumenta,
        k.datum_knjizenja,
        k.proknjizeno,
        k.opis,
        k.stornirano,
        k.storniran_id,
        k.ooj_banka_id,
        ob.banka_id,
        b.naziv       as banka_naziv,
        ob.ziro_racun as ooj_banka_ziro_racun,
        ob.kontna_klasa_id,
        kk.code       as kontna_klasa_code,
        kk.naziv      as kontna_klasa_naziv,
        k.broj_izvoda,
        k.pocetno_stanje,
        k.zakljucno_stanje,
        (
            select
                count(*)
            from
                glavna_knjiga_stavke s
            where
                s.glavna_knjiga_id = k.id
        )             as stavke_count,
        (
            select
                sum(iznos)
            from
                glavna_knjiga_stavke s
            where
                    s.glavna_knjiga_id = k.id
                and s.tip_stavke = 'P'
        )             as p_sum,
        (
            select
                sum(iznos)
            from
                glavna_knjiga_stavke s
            where
                    s.glavna_knjiga_id = k.id
                and s.tip_stavke = 'D'
        )             as d_sum,
        (
            select
                sum(iznos)
            from
                glavna_knjiga_stavke s
            where
                s.glavna_knjiga_id = k.id
        )             as stavke_sum,
        (
            select
                kif.id
            from
                kif
            where
                kif.glavna_knjiga_id = k.id
        )             as kif_id,
        (
            select
                kuf.id
            from
                kuf
            where
                kuf.glavna_knjiga_id = k.id
        )             as kuf_id,
        k.valid,
        k.row_version,
        k.created,
        k.created_by,
        k.updated,
        k.updated_by
    from
        glavna_knjiga              k
        left join core.ooj on k.ooj_id = ooj.id
        left join sif.sif_vrste_naloga       vn on k.vrsta_naloga_id = vn.id
        left join core.ooj_banke             ob on k.ooj_banka_id = ob.id
        left join sif.sif_banke              b on ob.banka_id = b.id
        left join sif.acc_kontni_okvir_klase kk on ob.kontna_klasa_id = kk.id;

prompt
prompt Creating view VW_GLAVNA_KNJIGA_STAVKE
prompt =====================================
prompt
create or replace force view accounting.vw_glavna_knjiga_stavke as
select
        s.id,
        s.glavna_knjiga_id,
        gk.godina              as glavna_knjiga_godina,
        gk.broj                as glavna_knjiga_broj,
        gk.datum_knjizenja     as glavna_knjiga_datum_knjizenja,
        gk.datum_dokumenta     as glavna_knjiga_datum_dokumenta,
        gk.stornirano          as glavna_knjiga_stornirano,
        gk.storniran_id        as glavna_knjiga_storniran_id,
        gk.proknjizeno,
        gk.opis                as glavna_knjiga_opis,
        gk.ooj_banka_id,
        gk.ooj_id,
        ooj.naziv              as ooj_naziv,
        svn.id                 as vrsta_naloga_id,
        svn.naziv              as vrsta_naloga_naziv,
        svn.sifra              as vrsta_naloga_sifra,
        s.kontna_klasa_id,
        kok.code               as kontna_klasa_code,
        kok.naziv              as kontna_klasa_naziv,
        s.klijent_id,
        kl.naziv               as klijent_naziv,
        kl.kontna_klasa_id     as klijent_kontna_klasa_id,
        s.redni_broj,
        s.tip_stavke,
        case
            when s.tip_stavke = 'D' then
                'Duguje'
            when s.tip_stavke = 'P' then
                'Potražuje'
            else
                null
        end                    as tip_stavke_naziv,
        s.tip_stavke_izvoda,
        case
            when s.tip_stavke_izvoda = 'P' then
                'Priliv'
            when s.tip_stavke_izvoda = 'O' then
                'Odliv'
            else
                null
        end                    as tip_stavke_izvoda_naziv,
        s.opis,
        round(s.iznos, 2)      as iznos,
        s.prihod_rashod,
        case
            when s.prihod_rashod = 'P' then
                'Prihod'
            when s.prihod_rashod = 'R' then
                'Rashod'
            else
                'Ostalo'
        end                    as prihod_rashod_naziv,
        s.nacin_placanja_izvoda,
        case
            when s.nacin_placanja_izvoda = 'G' then
                'Gotovina'
            when s.nacin_placanja_izvoda = 'Z' then
                'Žiralno'
            else
                null
        end                    as nacin_placanja_izvoda_naziv,
        s.vrsta_prihoda_id,
        vp.naziv               as vrsta_prihoda_naziv,
        vp.sifra               as vrsta_prihoda_sifra,
        s.vrsta_rashoda_id,
        vr.naziv               as vrsta_rashoda_naziv,
        vr.sifra               as vrsta_rashoda_sifra,
        s.grad_id,
        g.naziv                as grad_naziv,
        g.sifra                as grad_sifra,
        s.sifra_prihoda,
        s.automatska,
        s.osnovno_sredstvo_id,
        os.naziv               as osnovno_sredstvo_naziv,
        os.inventurni_naziv    as osnovno_sredstvo_inventurni_naziv,
        s.transakcija_id,
        t.sifra                as transakcija_sifra,
        t.naziv                as transakcija_naziv,
        s.os_datum,
        s.interni_nalog,
        s.pdv_indikator_id,
        api.sifra              as pdv_indikator_sifra,
        api.naziv              as pdv_indikator_naziv,
        api.opis               as pdv_indikator_opis,
        api.vrijednost         as pdv_indikator_vrijednost,
        api.ui                 as pdv_indikator_ui,
        s.oj_id,
        oj.naziv               as oj_naziv,
        s.radnik_id,
        initcap(hr.ime)
        || ' '
        || initcap(hr.prezime) as radnik_naziv,
        s.valuta_id,
        v.naziv                as valuta_naziv,
        v.sifra                as valuta_sifra,
        s.valuta_iznos,
        s.kurs,
        s.kif_id,
        kif.naziv_fakture      as kif_naziv,
        kif.iznos_fakture      as kif_iznos,
        s.kuf_id,
        kuf.naziv_fakture      as kuf_naziv,
        kuf.iznos_sa_pdv       as kuf_iznos,
        s.priznat_rashod,
        s.dodjela,
        s.valid,
        s.row_version,
        s.created,
        s.created_by,
        s.updated,
        s.updated_by
    from
        glavna_knjiga_stavke       s
        left join glavna_knjiga              gk on s.glavna_knjiga_id = gk.id
        left join sif.acc_kontni_okvir_klase kok on s.kontna_klasa_id = kok.id
        left join sec_klijenti               kl on s.klijent_id = kl.id
        left join sif.sif_gradovi            g on s.grad_id = g.id
        left join sif.acc_vrste_prihoda      vp on vp.id = s.vrsta_prihoda_id
        left join sif.acc_vrste_rashoda      vr on vr.id = s.vrsta_rashoda_id
        left join core.ooj on gk.ooj_id = ooj.id
        left join sec_osnovna_sredstva       os on s.osnovno_sredstvo_id = os.id
        left join sif.acc_transakcije_os     t on s.transakcija_id = t.id
        left join sif.acc_pdv_indikatori     api on s.pdv_indikator_id = api.id
        left join sif.sif_vrste_naloga       svn on gk.vrsta_naloga_id = svn.id
        left join core.oj                    oj on s.oj_id = oj.id
        left join hrm.hr_radnici             hr on s.radnik_id = hr.id
        left join sif.acc_valute             v on s.valuta_id = v.id
        left join kif on s.kif_id = kif.id
        left join kuf on s.kuf_id = kuf.id;

prompt
prompt Creating function TO_BROJ
prompt =========================
prompt
create or replace function accounting.to_broj (
    p_in varchar2
) return number as
    l_retval   number;
    l_decimala number;
    l_pola     varchar2(100);
begin
    l_decimala := length(p_in) - instr(p_in, '.');
    for x in 1..l_decimala loop
        l_pola := l_pola || '0';
    end loop;
--dbms_output.put_line(l_pola);

    l_pola := 'fm9999999990.' || l_pola;
--l_retval := to_number(p_in,l_pola);
    l_retval := round(to_number(p_in, l_pola), 2);
    return l_retval;
exception
    when others then 
--Raise;
        return null;
end to_broj;
/

prompt
prompt Creating view VW_ISPORUKE
prompt =========================
prompt
create or replace force view accounting.vw_isporuke as
select
        kif.id,
        row_number()
        over(partition by kif.ooj_id, kif.poreski_period
             order by
                 kif.id asc
        )                                        as internal_no,
        kif.vrsta_sloga,
        kif.poreski_period,
        kif.redni_br,
        lpad(kif.tip_dokumenta, 2, 0)            as tip_dokumenta,
        kif.broj_fakture,
        to_char(kif.datum_fakture, 'YYYY-MM-DD') as datum_fakture,
        kif.naziv_kupca,
        kif.sjediste_kupca,
        lpad(kif.pdv_broj_kupca, 12, 0)          as pdv_broj_kupca,
        lpad(kif.jib_broj_kupca, 13, 0)          as jib_broj_kupca,
        to_broj(kif.iznos_fakture)               as iznos_fakture,
        to_broj(kif.iznos_fakture_interne)       as iznos_fakture_interne,
        to_broj(kif.iznos_fakture_izvozne)       as iznos_fakture_izvozne,
        to_broj(kif.iznos_ostale_bez_pdv)        as iznos_ostale_bez_pdv,
        to_broj(kif.iznos_osnovice_za_pdv)       as iznos_osnovice_za_pdv,
        to_broj(kif.iznos_izlaz_pdv_za_pdv)      as iznos_izlaz_pdv_za_pdv,
        to_broj(kif.iznos_osnovice_za_nepdv)     as iznos_osnovice_za_nepdv,
        to_broj(kif.iznos_izlaz_pdv_za_nepdv)    as iznos_izlaz_pdv_za_nepdv,
        to_broj(kif.iznos_pdv_32polje)           as iznos_pdv_32polje,
        to_broj(kif.iznos_pdv_33polje)           as iznos_pdv_33polje,
        to_broj(kif.iznos_pdv_34polje)           as iznos_pdv_34polje,
        kif.created_by,
        kif.ooj_id,
        ooj.naziv,
        ooj.pib                                  as ooj_pib
    from
             uio_kif kif
        join core.ooj on kif.ooj_id = ooj.id
    where
        kif.valid = 'Y';

prompt
prompt Creating view VW_IZVJESTAJI
prompt ===========================
prompt
create or replace force view accounting.vw_izvjestaji as
select
        i.id,
