prompt
prompt Creating view VW_IZVODI
prompt =======================
prompt
create or replace force view accounting.vw_izvodi as
select  zr.id as id_racuna, zr.sifra as sifra_racuna, zr.broj as broj_racuna,v.sifra as valuta,
        i.id as izvod_id,i.godina,i.broj, i.datum,i.prethodni_saldo prethodno_stanje, i.novi_saldo as novo_stanje,
        case when i.storno='N' then 'NE' else 'DA' end as storno,i.storno as storno_v,
        case when i.zakljucan='N' then 'NE' else 'DA' end as zakljucan,i.zakljucan as zakljucan_v,
        case when i.proknjizen='N'then 'NE' else 'DA' end as proknjizen,i.proknjizen as proknjizen_v,
        case when i.nalog_gk_id is null then null else vn.sifra||'/'||gk.broj||'/'||gk.godina end  as nalog_gk,
        i.ooj_id,
        i.opis,
        zr.vrsta_naloga_id



from accounting.izvodi i
join sif.sif_ziro_racuni zr on i.ziro_racun_id=zr.id
join sif.acc_valute v on v.id=zr.valuta_id
left join accounting.glavna_knjiga gk on gk.id=i.nalog_gk_id
left join sif.sif_vrste_naloga vn on vn.id=gk.vrsta_naloga_id;

prompt
prompt Creating view VW_KALKULACIJA_KUF
prompt ================================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_KALKULACIJA_KUF AS
SELECT
	kk.id,
	kk.kalkulacija_id,
	k.naziv AS kalkulacija_naziv,
	kk.kuf_id,
	kuf.naziv AS kuf_naziv,
	kuf.naziv_fakture AS kuf_naziv_fakture,
	kk.tip_kalkulacije,
	kk.row_version,
	kk.created,
	kk.created_by,
	kk.updated,
	kk.updated_by
FROM
	kalkulacija_kuf kk
	LEFT JOIN kalkulacije k ON kk.kalkulacija_id = k.id
	LEFT JOIN kuf ON kk.kuf_id = kuf.id;

prompt
prompt Creating view VW_KALKULACIJA_OPERACIJE
prompt ======================================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_KALKULACIJA_OPERACIJE AS
SELECT
	ko.id,
	ko.kalkulacija_id,
	k.naziv AS kalkulacija_naziv,
	ko.operacija_id,
	o.naziv AS operacija_naziv,
	ko.row_version,
	ko.created,
	ko.created_by,
	ko.updated,
	ko.updated_by
FROM
	kalkulacija_operacije ko 
	LEFT JOIN kalkulacije k ON ko.kalkulacija_id = k.id
	LEFT JOIN operacije o ON ko.operacija_id = o.id;

prompt
prompt Creating view VW_SKLADISTA
prompt ==========================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_SKLADISTA AS
SELECT
	s.id,
	s.ooj_id,
	ooj.naziv AS ooj_naziv,
	s.nadredjeno_id,
	n.naziv AS nadredjeno_naziv,
	s.valuta_id,
	v.naziv AS valuta_naziv,
	s.tip_skladista_id,
	ts.naziv AS tip_skladista_naziv,
	ts.sifra AS tip_skladista_sifra,
	s.tip_cijene_id,
	ts.naziv AS tip_cijene_naziv,
	ts.sifra AS tip_cijene_sifra,
    s.cjenovnik_id,
    cj.sifra AS cjenovnik_sifra,
    cj.naziv AS cjenovnik_naziv,
	s.kontna_klasa_id,
	kok.naziv AS kontna_klasa_naziv,
	kok.code AS kontna_klasa_code,
	s.radnik_id,
	r.ime || ' ' || r.prezime AS radnik_naziv,
	s.oj_id,
	oj.naziv AS oj_naziv,
	
	s.naziv,
	s.sifra,
	s.adresa,
	s.fax,
	s.napomena,
	s.valid,
	s.row_version,
	s.created,
	s.created_by,
	s.updated,
	s.updated_by
FROM
	skladista s
	LEFT JOIN core.ooj ON s.ooj_id = ooj.id
	LEFT JOIN skladista n ON s.nadredjeno_id = n.id
	LEFT JOIN sif.acc_valute v ON s.valuta_id = v.id
	LEFT JOIN sif.acc_tipovi_skladista ts ON s.tip_skladista_id = ts.id
	LEFT JOIN sif.acc_tipovi_cijena tc ON s.tip_cijene_id = tc.id
	LEFT JOIN sif.acc_kontni_okvir_klase kok ON s.kontna_klasa_id = kok.id
	LEFT JOIN hrm.hr_radnici r ON s.radnik_id = r.id
	LEFT JOIN core.oj ON s.oj_id = oj.id
    LEFT JOIN cjenovnici cj ON s.cjenovnik_id = cj.id;

prompt
prompt Creating view VW_OPERACIJE
prompt ==========================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_OPERACIJE AS
SELECT
	o.id,
	o.ooj_id,
	ooj.naziv AS ooj_naziv,
	o.tip_kretanja_id,
	tk.sifra AS tip_kretanja_sifra,
	tk.naziv AS tip_kretanja_naziv,
    tk.tip_kretanja,
    tk.vrsta_naloga_id,
    vn.sifra AS vrsta_naloga_sifra,
    vn.naziv AS vrsta_naloga_naziv,
	o.skladiste_id,
	s.naziv AS skladiste_naziv,
    s.tip_skladista_id,
    s.tip_skladista_sifra,
    s.tip_skladista_naziv,
    s.cjenovnik_id,
    s.cjenovnik_sifra,
    s.cjenovnik_naziv,
	o.faktura_id,
	kif.naziv_fakture AS faktura_naziv,
	o.glavna_knjiga_id,
	gk.broj AS glavna_knjiga_broj,
    CASE
        WHEN o.glavna_knjiga_id IS null THEN
            'N'
        ELSE
            'Y'
    END AS proknjizeno,
	o.trebovanje_id,
	t.naziv AS trebovanje_naziv,
	o.oj_id,
	oj.naziv AS oj_naziv,
	o.broj,
	o.naziv,
	o.godina,
	o.datum,
	o.opis,
	o.stornirano,
	o.storniran_id,
	st.naziv AS storniran_naziv,
	o.osnovno_sredstvo_id,
	os.naziv AS osnovno_sredstvo_naziv,
	o.radni_nalog_id,
	rn.naziv AS radni_nalog_naziv,
	o.zakljucano,
	o.kalkulacija_id,
	kalk.naziv AS kalkulacija_naziv,
	o.veza_id,
	v.naziv AS veza_naziv,
	o.skladiste_prenos_id,
	sp.naziv AS skladiste_prenos_naziv,
	o.klijent_id,
	k.naziv AS klijent_naziv,
	t.ugovor_id,
	u.naziv AS ugovor_naziv,
	t.radnik_id,
	r.ime || ' ' || r.prezime AS radnik_naziv,
	t.primio_radnik_id,
	rp.ime || ' ' || rp.prezime AS primio_radnik_naziv,
	t.odobrio_radnik_id,
	ro.ime || ' ' || ro.prezime AS odobrio_radnik_naziv,
	
	o.valid,
	o.row_version,
	o.created,
	o.created_by,
	o.updated,
	o.updated_by
FROM
	operacije o
	LEFT JOIN core.ooj ON o.ooj_id = ooj.id
	LEFT JOIN sif.acc_tipovi_kretanja_robe tk ON o.tip_kretanja_id = tk.id
    LEFT JOIN sif.sif_vrste_naloga vn ON tk.vrsta_naloga_id = vn.id
	LEFT JOIN core.oj ON o.oj_id = oj.id
	LEFT JOIN kif ON o.faktura_id = kif.id
	LEFT JOIN glavna_knjiga gk ON o.glavna_knjiga_id = gk.id
	LEFT JOIN trebovanja t ON o.trebovanje_id = t.id
	LEFT JOIN sec_osnovna_sredstva os ON o.osnovno_sredstvo_id = os.id
	LEFT JOIN radni_nalozi rn ON o.radni_nalog_id = rn.id
	LEFT JOIN operacije st ON o.storniran_id = st.id
	LEFT JOIN vw_skladista s ON o.skladiste_id = s.id
	LEFT JOIN kalkulacije kalk ON o.kalkulacija_id =  kalk.id
	LEFT JOIN operacije v ON o.veza_id = v.id
	LEFT JOIN skladista sp ON o.skladiste_prenos_id = sp.id
	LEFT JOIN sec_klijenti k ON o.klijent_id = k.id
	LEFT JOIN ugovori u ON o.ugovor_id = u.id
	LEFT JOIN hrm.hr_radnici r ON o.radnik_id = r.id
	LEFT JOIN hrm.hr_radnici rp ON o.primio_radnik_id = rp.id
	LEFT JOIN hrm.hr_radnici ro ON o.odobrio_radnik_id = ro.id;

prompt
prompt Creating view VW_STAVKE
prompt =======================
prompt
create or replace force view accounting.vw_stavke as
select
        s.id,
        s.ooj_id,
        ooj.naziv     as ooj_naziv,
        s.tip_stavke_id,
        ts.naziv      as tip_stavke_naziv,
        s.grupa_id,
        g.naziv       as grupa_naziv,
        g.sifra       as grupa_sifra,
        s.jm_id,
        jm.naziv      as jm_naziv,
        s.naziv,
        s.sifra,
        s.marza,
        s.klasa_id,
        ks.naziv as klasa_naziv,
        s.pdv_indikator,
        s.pdv_indikator_id,
        pi.naziv      as pdv_indikator_naziv,
        pi.sifra      as pdv_indikator_sifra,
        nvl(pi.vrijednost,17) as pdv_indikator_vrijednost,
        pi.ui         as pdv_indikator_ui,
        s.ino_usluga,
        s.valid,
        s.row_version,
        s.created,
        s.created_by,
        s.updated,
        s.updated_by
    from
        sec_stavke             s
        left join core.ooj on s.ooj_id = ooj.id
        left join sif.acc_tipovi_stavki  ts on s.tip_stavke_id = ts.id
        left join sif.acc_grupe_stavki   g on s.grupa_id = g.id
        left join sif.acc_jedinice_mjere jm on s.jm_id = jm.id
        left join sif.acc_pdv_indikatori pi on s.pdv_indikator_id = pi.id
        left join sec_klase_stavki ks on s.klasa_id = ks.id;

prompt
prompt Creating view VW_KALKULACIJA_STAVKE
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_KALKULACIJA_STAVKE AS
SELECT
	ks.id,
	ks.kalkulacija_id,
	k.naziv AS kalkulacija_naziv,
	ks.operacija_stavka_id,
	os.stavka_id,
	s.sifra AS stavka_sifra,
	s.naziv AS stavka_naziv,
    s.tip_stavke_id,
    s.tip_stavke_naziv,
    o.skladiste_id,
    o.tip_skladista_id,
    o.tip_skladista_naziv,
    o.tip_skladista_sifra,
    o.cjenovnik_id,
    o.cjenovnik_sifra,
    o.cjenovnik_naziv,
	ks.kolicina,
	ks.cijena,
    ks.iznos,
	ks.row_version,
	ks.created,
	ks.created_by,
	ks.updated,
	ks.updated_by
FROM
	kalkulacija_stavke ks
	LEFT JOIN kalkulacije k ON ks.kalkulacija_id = k.id
	LEFT JOIN operacija_stavke os ON ks.operacija_stavka_id = os.id
	LEFT JOIN vw_stavke s ON os.stavka_id = s.id
    LEFT JOIN vw_operacije o ON os.operacija_id = o.id;

prompt
prompt Creating view VW_KIF
prompt ====================
prompt
create or replace force view accounting.vw_kif as
select
        kif.id,
        kif.glavna_knjiga_id,
        kif.klijent_id,
        k.naziv                                                                            as klijent_naziv,
        k.grad                                                                             as klijent_grad,
        k.adresa                                                                           as klijent_adresa,
        k.postanski_broj                                                                   as klijent_postanski_broj,
        k.jib                                                                              as klijent_jib,
        k.pib                                                                              as klijent_pib,
        case
            when k.drzava_id = 28 then
                'N'
            else
                'Y'
        end                                                                                as klijent_stranac,
        case
            when k.pib is null then
                'N'
            else
                'Y'
        end                                                                                as klijent_pdv_obaveznik,
        k.tip_klijenta_id,
        k.sablon_id,
        kif.valuta_id,
        v.naziv                                                                            as valuta_naziv,
        v.sifra                                                                            as valuta_sifra,
        kif.valuta_iznos,
        to_char(kif.valuta_iznos, 'FM999G999G999G999G990D00')                              as valuta_iznos_char,
        kif.valuta_iznos_pdv,
        to_char(kif.valuta_iznos_pdv, 'FM999G999G999G999G990D00')                          as valuta_iznos_pdv_char,
        case
            when kif.valuta_id = 1 then
                null
            else
                sif.spell_pkg.spell_serbian_number(
                    coalesce(
                        round(
                            sif.acc_pkg.convert_bam(
                                p_valuta_id => 1,
                                p_bam       => kif.iznos_fakture
                            ),
                            2
                        ),
                        0
                    ),
                    'Y',
                    'J',
                    'KM'
                )
        end                                                                                as valuta_iznos_slovima,
        firme.id                                                                           as firma_id,
        firme.naziv                                                                        as firma_naziv,
        firme.logo                                                                         as firma_logo,
        kif.ooj_id,
        ooj.naziv                                                                          as ooj_naziv,
        ooj.grad_id,
        g.naziv                                                                            as grad_naziv,
        ooj.adresa                                                                         as ooj_adresa,
        ooj.zip                                                                            as ooj_zip,
        ooj.tel                                                                            as ooj_tel,
        ooj.fax                                                                            as ooj_fax,
        ooj.email                                                                          as ooj_email,
        ooj.jib                                                                            as ooj_jib,
        ooj.pib                                                                            as ooj_pib,
        ooj.mbs                                                                            as ooj_mbs,
        ooj.mb                                                                             as ooj_mb,
        ooj.pdv_sistem                                                                     as ooj_pdv_sistem,
        ooj.rjesenje                                                                       as ooj_rjesenje,
        ooj.broj_rjesenja                                                                  as ooj_broj_rjesenja,
        ooj.datum_rjesenja                                                                 as ooj_datum_rjesenja,
        ooj.izdavaoc_rjesenja                                                              as ooj_izdavaoc_rjesenja,
        kif.predracun_id,
        p.naziv_fakture                                                                    as predracun_naziv,
        kif.faktura_broj,
        kif.naziv_fakture,
        kif.godina,
        kif.datum_uplatnice,
        kif.datum_fakture,
        kif.datum_valute,
        kif.iznos_fakture,
        to_char(kif.iznos_fakture, 'FM999G999G999G999G990D00')                             as iznos_fakture_char,
        kif.iznos_slovima,
        kif.iznos_fakture_nopdv,
        to_char(kif.iznos_fakture_nopdv, 'FM999G999G999G999G990D00')                       as iznos_fakture_nopdv_char,
        ( kif.iznos_fakture - kif.iznos_fakture_nopdv )                                    as pdv,
        to_char((kif.iznos_fakture - kif.iznos_fakture_nopdv), 'FM999G999G999G999G990D00') as pdv_char,
        kif.uplaceno,
        (
            select
                coalesce(
                    sum(abs(iznos)),
                    0
                )
            from
                glavna_knjiga_stavke gks
            where
                gks.kif_id = kif.id
        )                                                                                  as uplaceno_izvod,
        coalesce(kif.uplaceno_rucno, 0)                                                    as uplaceno_rucno,
        kif.posebne_napomene,
        kif.tip_placanja_id,
        tp.naziv                                                                           as tip_placanja_naziv,
        tp.sifra                                                                           as tip_placanja_sifra,
        kif.print_pn,
        kif.fiskalni_racun_broj,
        kif.fiskalni_racun,
        kif.fiskalni_racun_filename,
        kif.fiskalni_racun_mimetype,
        kif.fiskalni_racun_charset,
        kif.fiskalni_racun_lastupd,
        kif.fiskalizovano,
        kif.uio_tip_dokumenta_id,
        uio.code                                                                           as uio_tip_dokumenta_code,
        uio.naziv                                                                          as uio_tip_dokumenta_naziv,
        kif.system,
        kif.stornirano,
        kif.storniran_id,
        s.naziv_fakture AS storniran_naziv,
        kif.vrsta_fakture_id,
        vd.naziv                                                                           as vrsta_fakture_naziv,
        vd.fiskalna_sifra                                                                  as vrsta_fakture_sifra,
        case when vd.fiskalna_sifra in ('Advance', 'Normal') then 'Y' else 'N'  end        as vrsta_fakture_fiskalizacija,
        vd.vrsta_naloga_id,
        vn.naziv                                                                           as vrsta_naloga_naziv,
        lower(vn.sifra)                                                                    as vrsta_naloga_sifra,
        (
            select
                count(*)
            from
                kif_stavke
            where
                kif_id = kif.id
        )                                                                                  as stavke_count,
        (
            select
                count(*)
            from
                uio_kif uio
            where
                uio.faktura_id = kif.id
        )                                                                                  as uio_kif_count,
        kif.faktura_id,
        f.naziv_fakture                                                                    as referenca_faktura_naziv,
        kif.tip_cijene,
        kif.ugovor_id,
        u.naziv                                                                            as ugovor_naziv,
        u.predmet                                                                          as ugovor_predmet,
        kif.oj_id,
        oj.naziv as oj_naziv,
        kif.radni_nalog_id,
        rn.naziv as radni_nalog_naziv,
        kif.skladiste_id,
        kif.valid,
        kif.row_version,
        kif.created,
        kif.created_by,
        kif.updated,
        kif.updated_by
    from
        kif
        left join sec_klijenti                  k on kif.klijent_id = k.id
        left join sif.acc_valute                v on kif.valuta_id = v.id
        left join core.ooj on kif.ooj_id = ooj.id
        left join sif.acc_tipovi_placanja       tp on kif.tip_placanja_id = tp.id
        left join kif                           p on kif.predracun_id = p.id
        left join sif.acc_uio_tipovi_dokumenata uio on kif.uio_tip_dokumenta_id = uio.id
        --left join sif.acc_vrste_faktura         vf on kif.vrsta_fakture_id = vf.id
        left join sif.vrste_dokumenata vd on vd.id=kif.vrsta_fakture_id
        left join sif.sif_vrste_naloga          vn on vd.vrsta_naloga_id = vn.id
        left join kif                           f on kif.faktura_id = f.id
        left join core.firme on ooj.firma_id = firme.id
        left join sif.sif_gradovi               g on ooj.grad_id = g.id
        left join ugovori                       u on kif.ugovor_id = u.id
        left join core.oj                       oj on kif.oj_id = oj.id
        left join kif                           s on kif.storniran_id = s.id
        left join car_service.radni_nalozi rn on kif.radni_nalog_id=rn.id
;

