prompt
prompt Creating view VW_KIF_RASPOLOZIVI_AVANSI
prompt =======================================
prompt
create or replace force view accounting.vw_kif_raspolozivi_avansi as
select k.ooj_id, vd.sifra, vd.naziv, k.id,k.datum_fakture, k.naziv_fakture, k.iznos_fakture,k.iznos_fakture_nopdv,k.iznos_fakture-k.iznos_fakture_nopdv as faktura_pdv,
        k.valuta_iznos, k.valuta_iznos_pdv,k.valuta_iznos_pdv-k.valuta_iznos as valuta_pdv,v.sifra as valuta_sifra, v.naziv valuta_naziv, v.id as valuta_id,
        sum(nvl(az.iznos,0)) as iskorisceno,
        sum(k.valuta_iznos_pdv-nvl(az.iznos,0)) as raspolozivo,
        k.stornirano,
        pdv.vrijednost stopa_pdv,
        k.klijent_id


from accounting.kif k
join sif.vrste_dokumenata vd on vd.id=k.vrsta_fakture_id
join sif.acc_valute v on v.id=k.valuta_id
left join accounting.kif_avansi_zatvaranje az on az.avans_id=k.id
left join sif.acc_pdv_indikatori pdv on pdv.id=k.pdv_indikator_id
where vd.sifra='AV'
and nvl(k.stornirano,'N')='N'
group by k.ooj_id, vd.sifra, vd.naziv, k.id, k.naziv_fakture, k.iznos_fakture,k.iznos_fakture_nopdv,
         k.valuta_iznos, k.valuta_iznos_pdv,v.sifra, v.naziv, v.id, k.stornirano,k.datum_fakture, pdv.vrijednost,k.klijent_id
having sum(k.valuta_iznos_pdv-nvl(az.iznos,0));

prompt
prompt Creating view VW_KIF_STAVKE
prompt ===========================
prompt
create or replace force view accounting.vw_kif_stavke as
select
        ks.id,
        ks.kif_id,
        kif.datum_fakture                                                            as datum_fakture,
        kif.naziv_fakture                                                            as faktura_naziv,
        kif.faktura_broj                                                             as faktura_broj,
        kif.valuta_id,
        kif.ooj_id,
        kif.tip_cijene,
        kif.godina                                                                   as godina,
        kif.vrsta_naloga_sifra,
        v.naziv                                                                      as valuta_naziv,
        v.sifra                                                                      as valuta_sifra,
        ks.stavka_id,
        s.ino_usluga                                                                 as stavka_ino_usluga,
        s.sifra                                                                      as stavka_sifra,
        s.tip_stavke_id,
        ts.naziv                                                                     as tip_stavke_naziv,
        ks.naziv                                                                     as stavka_naziv,
        ks.jm_id,
        jm.naziv                                                                     as jm_naziv,
        ks.kolicina,
        ks.cijena,
        to_char(ks.cijena, 'FM999G999G999G999G990D00')                               as cijena_char,
        ( ks.cijena + ( ks.cijena ) * ks.pdv / 100 )                                 as cijena_pdv,
        to_char((ks.cijena +(ks.cijena) * ks.pdv / 100), 'FM999G999G999G999G990D00') as cijena_pdv_char,
        ks.rabat,
        case
            when rabat != 0 then
                'Y'
            else
                'N'
        end                                                                          as ima_rabat,
        ks.pdv,
        ks.iznos,
        to_char(ks.iznos, 'FM999G999G999G999G990D00')                                as iznos_char,
        ( ks.iznos + ( ks.iznos * ks.pdv / 100 ) )                                   as iznos_pdv,
        to_char((ks.iznos +(ks.iznos * ks.pdv / 100)), 'FM999G999G999G999G990D00')   as iznos_pdv_char,
        ( ks.iznos + ( ks.iznos * ks.rabat / 100 ) )                                 as iznos_bez_rabata,
        to_char((ks.iznos +(ks.iznos * ks.rabat / 100)), 'FM999G999G999G999G990D00') as iznos_bez_rabata_char,
        ks.pdv_indikator_id,
        api.sifra                                                                    as pdv_indikator_sifra,
        api.naziv                                                                    as pdv_indikator_naziv,
        ks.valid,
        ks.row_version,
        ks.created,
        ks.created_by,
        ks.updated,
        ks.updated_by
    from
        kif_stavke             ks
        left join vw_kif                 kif on ks.kif_id = kif.id
        left join sec_stavke             s on ks.stavka_id = s.id
        left join sif.acc_jedinice_mjere jm on ks.jm_id = jm.id
        left join sif.acc_valute         v on kif.valuta_id = v.id
        left join sif.acc_pdv_indikatori api on ks.pdv_indikator_id = api.id
        left join sif.acc_tipovi_stavki  ts on s.tip_stavke_id = ts.id;

prompt
prompt Creating view VW_KLIJENTI
prompt =========================
prompt
create or replace force view accounting.vw_klijenti as
select
        k.id,
        k.ooj_id,
        ooj.naziv    as ooj_naziv,
        k.vrsta_klijenta,
        k.tip_klijenta_id,
        tk.naziv     as tip_klijenta_naziv,
        tk.sifra     as tip_klijenta_sifra,
        k.radnik_id,
        r.ime
        || ' '
        || r.prezime as radnik_naziv,
        k.drzava_id,
        d.name       as drzava_naziv,
        case
            when drzava_id = 28 then
                'N'
            else
                'Y'
        end          as ino_drzava,
        k.entitet_id,
        e.naziv      as entitet_naziv,
        e.sifra      as entitet_sifra,
        k.naziv,
        k.adresa,
        k.grad,
        k.postanski_broj,
        k.tel,
        k.email,
        k.web,
        k.sud,
        k.jib,
        k.pib,
        case
            when k.pib is null then
                'N'
            else
                'Y'
        end          as pdv_obaveznik,
        k.ziro_racun,
        k.sablon_id,
        s.naziv      as sablon_naziv,
        k.valid,
        k.row_version,
        k.created,
        k.created_by,
        k.updated,
        k.updated_by
    from
        sec_klijenti             k
        left join core.ooj on k.ooj_id = ooj.id
        left join sif.acc_tipovi_klijenata tk on k.tip_klijenta_id = tk.id
        left join hrm.hr_radnici           r on k.radnik_id = r.id
        left join sif.sif_drzave           d on k.drzava_id = d.id
        left join sif.sif_entiteti         e on k.entitet_id = e.id
        left join sabloni                  s on k.sablon_id = s.id;

prompt
prompt Creating view VW_KNJIGA_PROMETA
prompt ===============================
prompt
create or replace force view accounting.vw_knjiga_prometa as
with a as (
        select
            ooj_id,
            to_char(glavna_knjiga_datum_knjizenja, 'dd.mm.yyyy hh24:mi:ss') as datum,
            extract(year from glavna_knjiga_datum_knjizenja)                as godina,
            extract(month from glavna_knjiga_datum_knjizenja)               as mjesec,
            glavna_knjiga_opis                                              as broj_racuna,
            gks.opis                                                        as opis_knjizenja,
            case
                when gks.nacin_placanja_izvoda = 'G' then
                    gks.iznos
                else
                    0
            end                                                             as iznos_gotovina,
            case
                when gks.nacin_placanja_izvoda = 'Z' then
                    gks.iznos
                else
                    0
            end                                                             as iznos_banka
        from
            vw_glavna_knjiga_stavke gks
        where
            lower(vrsta_naloga_sifra) = 'iz'
    )
    select
        datum,
        broj_racuna,
        opis_knjizenja,
        iznos_gotovina,
        iznos_banka,
        ( iznos_gotovina + iznos_banka ) as ukupno_iznos,
        ooj_id,
        godina,
        mjesec
    from
        a
    union all
    select
        null                              as datum,
        'Ukupno za: '
        || mjesec
        || '. MJESEC'                     as broj_racuna,
        null                              as opis_knjizenja,
        sum(iznos_gotovina)               as sum_gotovina,
        sum(iznos_banka)                  as sum_banka,
        sum(iznos_gotovina + iznos_banka) as ukupno_iznos,
        ooj_id,
        godina,  -- Uključujemo godinu
        mjesec
    from
        a
    group by
        ooj_id,
        godina,
        mjesec
    union all
    select
        null                              as datum,
        'Ukupno za SVE MJESECE'           as broj_racuna,
        null                              as opis_knjizenja,
        sum(iznos_gotovina)               as ukupno_gotovina,
        sum(iznos_banka)                  as ukupno_banka,
        sum(iznos_gotovina + iznos_banka) as ukupno_iznos,
        ooj_id,  -- Prikazuje ooj_id za ukupne sume
        godina,  -- Uključujemo godinu
        null                              as mjesec
    from
        a
    group by
        ooj_id,
        godina
    order by
        mjesec,
        ooj_id,
        datum desc nulls last
;

prompt
prompt Creating view VW_KUF
prompt ====================
prompt
create or replace force view accounting.vw_kuf as
select
        k.id,
        k.glavna_knjiga_id,
        k.ooj_id,
        ooj.naziv                            as ooj_naziv,
        k.klijent_id,
        kl.naziv                             as klijent_naziv,
        k.datum_prijema,
        k.datum_fakture,
        k.datum_valute,
        k.iznos_bez_pdv,
        k.iznos_sa_pdv,
        ( k.iznos_sa_pdv - k.iznos_bez_pdv ) as pdv,
        k.valuta_id,
        v.naziv                              as valuta_naziv,
        k.valuta_iznos_bez_pdv,
        k.valuta_iznos_sa_pdv,
        k.document,
        k.document_filename,
        k.document_mimetype,
        k.document_charset,
        k.document_lastupd,
        k.tip_placanja_id,
        tp.naziv                             as tip_placanja_naziv,
        tp.sifra                             as tip_placanja_sifra,
        k.fiskalni_racun_broj,
        k.naziv_fakture,
        extract(year from k.datum_fakture)   as godina,
        (
            select
                count(*)
            from
                uio_kuf uio
            where
                uio.faktura_id = k.id
        )                                    as uio_kuf_count,
        k.uio_tip_dokumenta_id,
        k.stornirano,
        k.storniran_id,
        k.uplaceno,
        (
            select
                coalesce(
                    sum(abs(iznos)),
                    0
                )
            from
                glavna_knjiga_stavke gks
            where
                gks.kuf_id = k.id
        )                                    as uplaceno_izvod,
        coalesce(k.uplaceno_rucno, 0)        as uplaceno_rucno,
        k.datum_uplatnice,
        k.naziv,
        k.broj,
        k.valid,
        k.row_version,
        k.created,
        k.created_by,
        k.updated,
        k.updated_by,
        -- Nove kolone
        k.ugovor_id,
        ug.naziv                             as ugovor_naziv
    from
        kuf                     k
        left join core.ooj on k.ooj_id = ooj.id
        left join sec_klijenti            kl on k.klijent_id = kl.id
        left join sif.acc_tipovi_placanja tp on k.tip_placanja_id = tp.id
        left join sif.acc_valute          v on k.valuta_id = v.id
        left join ugovori                 ug on k.ugovor_id = ug.id
;

prompt
prompt Creating view VW_NABAVKE
prompt ========================
prompt
create or replace force view accounting.vw_nabavke as
select
        kuf.id,
        row_number()
        over(partition by kuf.ooj_id, kuf.poreski_period
             order by
                 kuf.id asc
        )                                                as internal_no,
        kuf.vrsta_sloga,
        kuf.poreski_period,
        kuf.redni_br,
        lpad(kuf.tip_dokumenta, 2, 0)                    as tip_dokumenta,
        kuf.broj_fakture,
        to_char(kuf.datum_fakture, 'YYYY-MM-DD')         as datum_fakture,
        to_char(kuf.datum_fakture, 'yyyymm')             as mjesec_fakture,
        to_char(kuf.datum_prijema_fakture, 'YYYY-MM-DD') as datum_prijema_fakture,
        to_char(kuf.datum_prijema_fakture, 'yyyymm')     as mjesec_prijema_fakture,
        kuf.naziv_dobavljaca,
        kuf.sjediste_dobavljaca,
        lpad(kuf.pdv_broj_dobavljaca, 12, 0)             as pdv_broj_dobavljaca,
        lpad(kuf.jib_broj_dobavljaca, 13, 0)             as jib_broj_dobavljaca,
        to_broj(kuf.iznos_fakture_bezpdv)                as iznos_fakture_bezpdv,
        to_broj(kuf.iznos_fakture_sapdv)                 as iznos_fakture_sapdv,
        to_broj(kuf.iznos_pausal)                        as iznos_pausal,
        to_broj(kuf.iznos_ulaznog_pdv)                   as iznos_ulaznog_pdv,
        to_broj(kuf.iznos_ulazpdv_odbiti)                as iznos_ulazpdv_odbiti,
        to_broj(kuf.iznos_ulazpdv_neodbiti)              as iznos_ulazpdv_neodbiti,
        to_broj(kuf.iznos_pdv_32polje)                   as iznos_pdv_32polje,
        to_broj(kuf.iznos_pdv_33polje)                   as iznos_pdv_33polje,
        to_broj(kuf.iznos_pdv_34polje)                   as iznos_pdv_34polje,
        kuf.created_by,
        kuf.ooj_id,
        ooj.naziv,
        ooj.pib                                          as ooj_pib
    from
             uio_kuf kuf
        join core.ooj on kuf.ooj_id = ooj.id
    where
        kuf.valid = 'Y';

prompt
prompt Creating view VW_NALOZI_GK
prompt ==========================
prompt
create or replace force view accounting.vw_nalozi_gk as
select gk.id as nalog_id, gk.godina,gk.broj, gk.datum_knjizenja as datum_naloga, gk.opis, gk.stornirano,gk.proknjizeno,
       sum(case gks.tip_stavke  when 'D' then gks.iznos else 0 end ) as duguje,
       sum(case gks.tip_stavke  when 'P' then gks.iznos else 0 end) as potrazuje,
       case when gk1.id is not null then vn.sifra||'/'||gk1.broj||'/'||gk1.godina else null end as storno,
       vn.id as vrsta_naloga_id, vn.sifra, vn.naziv, mm.id as modul_id, mm.opis as modul,
       kor.ime ||' '||kor.prezime as nalog_kreirao,
       ooj.id as ooj_id
from glavna_knjiga gk
join glavna_knjiga_stavke gks on gk.id=gks.glavna_knjiga_id
join core.korisnici kor on upper(kor.korisnicko_ime)=upper(gk.created_by)
left join glavna_knjiga gk1 on gk1.id=gk.storniran_id
left join core.ooj on gk.ooj_id = ooj.id
left join sif.sif_vrste_naloga vn on gk.vrsta_naloga_id = vn.id
left join sif.acc_moduli mm on mm.id=vn.acc_modul_id
where 1=1
group by gk.id, gk.godina,gk.broj, gk.datum_knjizenja , gk.opis, gk.stornirano, gk1.id,vn.sifra||'/'||gk1.broj||'/'||gk1.godina,gk.proknjizeno, vn.sifra, vn.naziv, mm.opis, kor.ime ||' '||kor.prezime,ooj.id,vn.id,mm.id;

prompt
prompt Creating view VW_NALOZI_GK_STAVKE
prompt =================================
prompt
create or replace force view accounting.vw_nalozi_gk_stavke as
select gk.id as nalog_id,
       gks.id as stavka_id, gks.redni_broj, gks.datum_dokumenta,gks.os_datum as datum_dospjeca, gks.opis,
       gks.tip_stavke, case gks.tip_stavke when 'D' then 'Duguje' else 'Potražuje' end as strana_knjizenja,
       v.id as valuta_id, v.sifra as valuta, gks.valuta_iznos,
       gks.iznos as iznos,
       k.id as parner_id, k.naziv as partner,
       mt.id as mt_id, mt.sifra||'-'||mt.naziv as mjesto_troska,
       gks.acc_radnik_id as radnik_id, ar.ime||'-'||ar.prezime as radnik,
       g.id as opstina_id, g.naziv as opstina,
       kon.id as konto_id, rpad(kon.code, oj.konto_duzina, '0') || '-' || kon.naziv as konto,
       dok.dokument_id as ref_dokument_id, dok.dokument as ref_dokument, dok.opis as ref_opis_dokumenta,dok.modul_id,
       oj.id as ooj_id,
       gks.dodjela
from accounting.glavna_knjiga gk
join core.ooj oj on oj.id=gk.ooj_id
join accounting.glavna_knjiga_stavke gks on gks.glavna_knjiga_id=gk.id
left join accounting.gk_stavke_dokument dok on dok.glavna_knjiga_stavka_id=gks.id
left join accounting.sec_klijenti k on k.id=gks.klijent_id
left join sif.acc_mjesta_troska mt on mt.id=gks.mjesto_troska_id
left join sif.acc_valute v on v.id=gks.valuta_id
left join sif.acc_radnici ar on ar.id=gks.mjesto_troska_id
left join sif.sif_gradovi g on g.id=gks.grad_id
left join sif.acc_kontni_okvir_klase kon on kon.id=gks.kontna_klasa_id
where 1=1
--and gk.ooj_id=219
;

prompt
prompt Creating view VW_OPERACIJA_STAVKE
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_OPERACIJA_STAVKE AS
SELECT
	os.id,
	os.operacija_id,
    o.ooj_id,
    o.ooj_naziv,
    o.oj_id,
    o.oj_naziv,
	o.broj AS operacija_broj,
	o.naziv AS operacija_naziv,
    o.datum AS operacija_datum,
    o.godina,
    o.tip_kretanja_id,
    o.tip_kretanja,
    o.tip_kretanja_sifra,
    o.tip_kretanja_naziv,
    o.skladiste_id,
    skladista.naziv AS skladiste_naziv,
    o.glavna_knjiga_id,
    gk.datum_knjizenja,
    gk.broj AS glavna_knjiga_broj,
    gk.vrsta_naloga_id,
    svn.naziv AS vrsta_naloga_naziv,
    o.zakljucano,
    
	os.stavka_id,
    s.sifra AS stavka_sifra,
	s.naziv AS stavka_naziv,
    s.tip_stavke_id,
    ats.naziv AS tip_stavke_naziv,
    s.grupa_id,
    ags.naziv AS grupa_naziv,
	os.kolicina,
	os.opis,
	os.valid,
	os.row_version,
	os.created,
	os.created_by,
	os.updated,
	os.updated_by,
	os.porez,
	os.porez_procenat,
	os.marza,
	os.marza_procenat,
	os.rabat,
	os.rabat_procenat,
	os.nabavna_cijena,
	os.mpc,
    (os.nabavna_cijena * os.obradjena_kolicina) AS iznos,
	os.obradjena_kolicina
FROM
	operacija_stavke os
	LEFT JOIN vw_operacije o ON os.operacija_id = o.id
    LEFT JOIN skladista ON o.skladiste_id = skladista.id
	LEFT JOIN sec_stavke s ON os.stavka_id = s.id
    LEFT JOIN sif.acc_grupe_stavki ags ON s.grupa_id = ags.id
    LEFT JOIN sif.acc_tipovi_stavki ats ON s.tip_stavke_id = ats.id
    LEFT JOIN glavna_knjiga gk ON o.glavna_knjiga_id = gk.id
    LEFT JOIN sif.sif_vrste_naloga svn ON gk.vrsta_naloga_id = svn.id;

