prompt
prompt Creating package OS_PKG
prompt =======================
prompt
create or replace package accounting.os_pkg as
    
    --------------------------------------------------------------
    -- procedures for table SEC_OSNOVNA_SREDSTVA
    --------------------------------------------------------------

    procedure get_inventurni_broj (
        p_ooj_id           in number,
        p_klasa_id         in number,
        p_inventurni_broj  out number,
        p_inventurni_naziv out varchar2
    );

    procedure get_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    );

    procedure insert_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    );

    procedure update_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    );

    procedure delete_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    );
    
    --------------------------------------------------------------
    -- procedures for table SEC_OSNOVNO_SREDSTVO_ODRZAVANJE
    --------------------------------------------------------------

    procedure get_osnovno_sredstvo_odrzavanje (
        p_os_odrzavanje in out t_sec_osnovno_sredstvo_odrzavanje
    );

    procedure insert_osnovno_sredstvo_odrzavanje (
        p_os_odrzavanje in out t_sec_osnovno_sredstvo_odrzavanje
    );

    procedure delete_osnovno_sredstvo_odrzavanje (
        p_os_odrzavanje in out t_sec_osnovno_sredstvo_odrzavanje
    );

    --------------------------------------------------------------
    -- procedures for table OS_INDIKATORI
    --------------------------------------------------------------

    procedure get_os_indikator (
        p_id     in number,
        p_ooj_id out number,
        p_sifra  out varchar2,
        p_naziv  out varchar2,
        p_opis   out varchar2,
        p_valid  out varchar2
    );

    procedure insert_os_indikator (
        p_ooj_id in number,
        p_sifra  in varchar2,
        p_naziv  in varchar2,
        p_opis   in varchar2
    );

    procedure update_os_indikator (
        p_id     in number,
        p_ooj_id in number,
        p_sifra  in varchar2,
        p_naziv  in varchar2,
        p_opis   in varchar2,
        p_valid  in varchar2
    );

    procedure delete_os_indikator (
        p_id in number
    );

    --------------------------------------------------------------
    -- procedures for table SEC_OSNOVNO_SREDSTVO_AKTIVIRANJA
    --------------------------------------------------------------

    procedure insert_os_aktiviranje (
        p_osnovno_sredstvo_id in number,
        p_glavna_knjiga_id    in number,
        p_priprema_id         in number,
        p_datum               in date,
        p_iznos               in number
    );
    
    --------------------------------------------------------------
    -- other procedures
    --------------------------------------------------------------
    
    procedure insert_os_priprema_klase (
        p_ooj_id in number
    );
    
    procedure insert_os_priprema (
        p_ooj_id   in number,
        p_klasa_id in number
    );

    function is_osnovno_sredstvo_editable (
        p_id in number
    ) return boolean;

    procedure insert_group_os (
        p_os       in t_sec_osnovna_sredstva,
        p_kolicina in number
    );

    function get_vrijednost_priprema (
        p_id    in number,
        p_datum in date
    ) return number;

    function get_vrijednost_nabavka (
        p_id    in number,
        p_datum in date
    ) return number;

    function get_amortizacija_do_datuma (
        p_id    in number,
        p_datum in date
    ) return number;

    function get_amortizacija_za_godinu (
        p_id     in number,
        p_godina in number
    ) return number;

    function get_knjigovodstvena_vrijednost (
        p_id in number
    ) return number;

    function get_otpis_vrijednost (
        p_id in number
    ) return number;

    function get_prodaja_vrijednost (
        p_id in number
    ) return number;

    function get_manjak_vrijednost (
        p_id in number
    ) return number;

    function get_stepen_amortizovanosti (
        p_id in number
    ) return number;

    function aktiviraj_osnovno_sredstvo (
        p_id               in number,
        p_vrijednost       in number,
        p_godina           in number,
        p_datum            in date,
        p_glavna_knjiga_id in number
    ) return number;

    function otpis_osnovno_sredstvo (
        p_id                    in number,
        p_godina                in number,
        p_proknjizeno           in varchar2,
        p_otpis_razlog          in varchar2,
        p_otpis_datum           in date,
        p_otpis_odgovorna_osoba in varchar2,
        p_kolicina              in number
    ) return number;

    function prodaja_osnovno_sredstvo (
        p_id                  in number,
        p_godina              in number,
        p_proknjizeno         in varchar2,
        p_prodajna_vrijednost in number,
        p_kolicina            in number,
        p_datum               in date
    ) return number;

    function popis_osnovno_sredstvo (
        p_id             in number,
        p_godina         in number,
        p_kolicina       in number,
        p_stara_kolicina in number,
        p_proknjizeno    in varchar2,
        p_datum          in date
    ) return number;

    function prenos_osnovno_sredstvo (
        p_id          in number,
        p_prenos_id   in number,
        p_godina      in number,
        p_datum       in date,
        p_proknjizeno in varchar2,
        p_kolicina    in number
    ) return number;

    procedure grupni_transfer (
        p_radnik_id        in number,
        p_os_list          in varchar2,
        p_transfer_id      in number,
        p_oj_id            in number,
        p_history_komentar in varchar2
    );

end os_pkg;
/

prompt
prompt Creating view VW_OSNOVNA_SREDSTVA
prompt =================================
prompt
create or replace force view accounting.vw_osnovna_sredstva as
select
        os.id,
        os.ooj_id,
        ooj.naziv             as ooj_naziv,
        os.jm_id,
        jm.naziv              as jm_naziv,
        os.oj_id,
        oj.naziv              as oj_naziv,
        oj.lat                as oj_latitude,
        oj.lng                as oj_longitude,
        os.lokacija_id,
        lo.naziv              as lokacija_naziv,
        lo.adresa             as lokacija_adresa,
        lo.lat                as lokacija_lat,
        lo.lng                as lokacija_lng,
        os.prostorija_id,
        lop.broj              as prostorija_broj,
        lop.naziv             as prostorija_naziv,
        os.grad_id,
        g.naziv               as grad_naziv,
        lpad(g.sifra, 3, '0') as grad_sifra,
        os.radnik_id,
        r.ime
        || ' '
        || r.prezime          as radnik_naziv,
        r.zaposlen_do         as radnik_zaposlen_do,
        os.klijent_id,
        k.naziv               as klijent_naziv,
        k.jib                 as klijent_jib,
        os.inventurni_broj,
        os.inventurni_naziv,
        os.stari_inventurni_broj,
        os.naziv,
        os.kolicina,
--        os.nabavna_vrijednost,
        os.datum,
        os.klasa_id,
        kos.naziv             as klasa_naziv,
        kos.sifra             as klasa_sifra,
        sif.acc_pkg.get_klasa_os_kontna_klasa_id(
            p_klasa_id => os.klasa_id,
            p_sifra    => 'nabavke'
        )                     as konto_nabavke_id,
        (
            select
                code
            from
                sif.acc_kontni_okvir_klase kok
            where
                kok.id = sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                    p_klasa_id => os.klasa_id,
                    p_sifra    => 'nabavke'
                )
        )                     as konto_nabavke_code,
        os.vijek_trajanja,
        os.amortizaciona_stopa,
        os.procijenjeni_vijek_trajanja,
        os.poreska_amortizaciona_stopa,
        os.donacija,
        os.reg_oznaka,
        os.dokument,
        os.dokument_filename,
        os.dokument_mimetype,
        os.dokument_charset,
        os.dokument_lastupd,
        os.dokument_broj,
        os.dokument_datum,
--        os.vrijednost_poreske_amortizacije,
--        os.revalorizovana_vrijednost,
        os.vrijednost_donacija,
        os.odlozeni_porezi,
        os.rezidualna_vrijednost,
--        os.povecanje_vrijednost,
        os.priprema,
        os.priprema_id,
        p.inventurni_naziv    as priprema_inventurni_naziv,
        p.naziv               as priprema_naziv,
        os.aktivirano,
        os.history_id,
        os.history_date,
        os.history_komentar,
        os.status_id,
        s.naziv               as status_naziv,
        s.sifra               as status_sifra,
        s.color_code          as status_color_code,
        s.icon                as status_icon,
        os.automatska_amortizacija,
        os.otpis_razlog,
        os.otpis_datum,
        os.otpis_odgovorna_osoba,
        os.indikator_id,
        if.naziv AS indikator_naziv,
        if.sifra AS indikator_sifra,
        
        os_pkg.get_vrijednost_priprema(os.id, sysdate) AS pripremna_vrijednost,
        os_pkg.get_vrijednost_nabavka(os.id, sysdate) AS nabavna_vrijednost,
        os_pkg.get_knjigovodstvena_vrijednost(os.id) AS knjigovodstvena_vrijednost,
        os_pkg.get_amortizacija_do_datuma(os.id, sysdate) as amortizacija_vrijednost,
        os_pkg.get_stepen_amortizovanosti(os.id) as stepen_amortizovanosti,  
        os_pkg.get_otpis_vrijednost(os.id) AS otpis_vrijednost,
        os_pkg.get_prodaja_vrijednost(os.id) AS prodajna_vrijednost,
        os_pkg.get_manjak_vrijednost(os.id) AS manjak_vrijednost,      

        os.valid,
        os.row_version,
        os.created,
        os.created_by,
        os.updated,
        os.updated_by
    from
        sec_osnovna_sredstva         os
        left join core.ooj on os.ooj_id = ooj.id
        left join sif.acc_jedinice_mjere       jm on os.jm_id = jm.id
        left join core.oj on os.oj_id = oj.id
        left join core.ooj_lokacije            lo on os.lokacija_id = lo.id
        left join core.ooj_lokacija_prostorije lop on os.prostorija_id = lop.id
        left join sif.sif_gradovi              g on os.grad_id = g.id
        left join hrm.hr_radnici               r on os.radnik_id = r.id
        left join sec_klijenti                 k on os.klijent_id = k.id
        left join sif.acc_klase_os             kos on os.klasa_id = kos.id
        left join sec_osnovna_sredstva         p on os.priprema_id = p.id
        left join sif.sif_statusi              s on os.status_id = s.id
        left join sec_os_indikatori            if on os.indikator_id = if.id
;

