prompt
prompt Creating view VW_SKLADISTE_STAVKE
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_SKLADISTE_STAVKE AS
SELECT
    ooj_id,
    skladiste_id,
    skladiste_naziv,
    stavka_id,
    stavka_naziv,
    stavka_sifra,
    grupa_id,
    grupa_naziv,
    tip_stavke_id,
    tip_stavke_naziv,

    SUM(
        CASE tip_kretanja
            WHEN 'U' THEN obradjena_kolicina
            WHEN 'I' THEN -obradjena_kolicina
            WHEN 'N' THEN obradjena_kolicina
        END
    ) AS stanje_kolicina,

    CASE
        WHEN SUM(
            CASE tip_kretanja
                WHEN 'U' THEN obradjena_kolicina
                WHEN 'I' THEN -obradjena_kolicina
                WHEN 'N' THEN obradjena_kolicina
            END) = 0 THEN 0
        ELSE
            SUM(
                CASE tip_kretanja 
                    WHEN 'U' THEN obradjena_kolicina * nabavna_cijena
                    WHEN 'I' THEN -(obradjena_kolicina * nabavna_cijena)
                    WHEN 'N' THEN obradjena_kolicina * nabavna_cijena
                END
            )
    END AS saldo,
    
    CASE
        WHEN SUM(
            CASE tip_kretanja
                WHEN 'U' THEN obradjena_kolicina
                WHEN 'I' THEN -obradjena_kolicina
                WHEN 'N' THEN obradjena_kolicina
            END) = 0 THEN 0
        ELSE
            SUM(
                CASE tip_kretanja 
                    WHEN 'U' THEN obradjena_kolicina * nabavna_cijena
                    WHEN 'I' THEN -(obradjena_kolicina * nabavna_cijena)
                    WHEN 'N' THEN obradjena_kolicina * nabavna_cijena
                END
            )/SUM(
                CASE tip_kretanja
                    WHEN 'U' THEN obradjena_kolicina
                    WHEN 'I' THEN -obradjena_kolicina
                    WHEN 'N' THEN obradjena_kolicina
                END
            )
    END AS prosjecna_cijena

FROM 
    vw_operacija_stavke
GROUP BY
    ALL;

