prompt Creating view VW_TREBOVANJA
prompt ===========================
prompt
CREATE OR REPLACE FORCE VIEW ACCOUNTING.VW_TREBOVANJA AS
SELECT
	t.id,
	t.ooj_id,
	ooj.naziv AS ooj_naziv,
	t.tip_kretanja_id,
	tk.sifra AS tip_kretanja_sifra,
	tk.naziv AS tip_kretanja_naziv,
	tk.tip_kretanja AS tip_kretanja,
	t.skladiste_id,
	s.naziv AS skladiste_naziv,
	t.status_id,
	st.naziv AS status_naziv,
	st.sifra AS status_sifra,
	st.color_code AS status_color_code,
	t.oj_id,
	oj.naziv AS oj_naziv,
	t.broj,
	t.naziv,
	t.godina,
	t.datum,
	t.opis,
	t.valid,
	t.row_version,
	t.created,
	t.created_by,
	t.updated,
	t.updated_by,
	t.faktura_id,
	kif.naziv_fakture AS faktura_naziv,
	t.zakljucano,
	t.veza_id,
	o.naziv AS veza_naziv,
	t.osnovno_sredstvo_id,
	os.naziv AS osnovno_sredstvo_naziv,
	t.radni_nalog_id,
	rn.naziv AS radni_nalog_naziv,
	t.skladiste_prenos_id,
	sp.naziv AS skladiste_prenos_naziv,
	t.klijent_id,
	k.naziv AS klijent_naziv,
	t.ugovor_id,
	u.naziv AS ugovor_naziv,
	t.radnik_id,
	r.ime || ' ' || r.prezime AS radnik_naziv,
	t.primio_radnik_id,
	rp.ime || ' ' || rp.prezime AS primio_radnik_naziv,
	t.odobrio_radnik_id,
	ro.ime || ' ' || ro.prezime AS odobrio_radnik_naziv
    
FROM
	trebovanja t
	LEFT JOIN core.ooj ON t.ooj_id = ooj.id
	LEFT JOIN sif.acc_tipovi_kretanja_robe tk ON t.tip_kretanja_id = tk.id
	LEFT JOIN skladista s ON t.skladiste_id = s.id
	LEFT JOIN sif.acc_statusi st ON t.status_id = st.id
	LEFT JOIN core.oj ON t.oj_id = oj.id
	LEFT JOIN kif ON t.faktura_id = kif.id
	LEFT JOIN operacije o ON t.veza_id = o.id
	LEFT JOIN sec_osnovna_sredstva os ON t.osnovno_sredstvo_id = os.id
	LEFT JOIN radni_nalozi rn ON t.radni_nalog_id = rn.id
	LEFT JOIN skladista sp ON t.skladiste_prenos_id = sp.id
	LEFT JOIN sec_klijenti k ON t.klijent_id = k.id
	LEFT JOIN ugovori u ON t.ugovor_id = u.id
	LEFT JOIN hrm.hr_radnici r ON t.radnik_id = r.id
	LEFT JOIN hrm.hr_radnici rp ON t.primio_radnik_id = rp.id
	LEFT JOIN hrm.hr_radnici ro ON t.odobrio_radnik_id = ro.id;

