prompt
prompt Creating view VW_UGOVORI
prompt ========================
prompt
create or replace force view accounting.vw_ugovori as
select
        u.id,
        u.ooj_id,
        ooj.naziv         as ooj_naziv,
        u.klijent_id,
        k.naziv           as klijent_naziv,
        u.valuta_id,
        v.naziv           as valuta_naziv,
        v.sifra           as valuta_sifra,
        u.izvrsilac_narucioc,
        u.ugovor_start,
        u.ugovor_end,
        u.iznos,
        u.naziv,
        to_number(u.broj) as broj,
        u.predmet,
        u.referenca,
        u.referenca_id,
        r.naziv           as referenca_naziv,
        r.broj            as referenca_broj,
        (
            select
                count(*)
            from
                ugovori
            where
                referenca_id = u.id
        )                 as broj_referenci,
        u.oj_id,
        oj.naziv          as oj_naziv,
        u.interval_id,
        i.naziv           as interval_naziv,
        i.broj_mjeseci    as interval_broj_mjeseci,
        u.system,
        u.valid,
        u.row_version,
        u.created,
        u.created_by,
        u.updated,
        u.updated_by,
        -- Nove kolone
        u.vrsta_ugovora_id,
        vu.sifra          as vrsta_ugovora_sifra,
        vu.naziv          as vrsta_ugovora_naziv,
        u.status,
        -- Izvodi naziv statusa; istekao je zaključen ugovor čiji je posljednji dan važenja prošao (odgovor 13).
        case
            when u.status = 'P' then 'U pripremi'
            when u.status = 'R' then 'Raskinut'
            when u.ugovor_end < trunc(sysdate) then 'Istekao'
            else 'Zaključen'
        end               as status_naziv,
        u.kurs,
        u.iznos_km,
        u.dan_dospijeca,
        u.otkazni_rok_dana,
        u.automatsko_produzenje,
        u.produzenje_mjeseci,
        u.aneks_broj,
        (
            select
                count(*)
            from
                ugovor_stavke s
            where
                s.ugovor_id = u.id
        )                 as broj_stavki
    from
        ugovori           u
        left join core.ooj on u.ooj_id = ooj.id
        left join sec_klijenti      k on u.klijent_id = k.id
        left join sif.acc_valute    v on u.valuta_id = v.id
        left join ugovori           r on u.referenca_id = r.id
        left join core.oj on u.oj_id = oj.id
        left join sif.sif_intervali i on u.interval_id = i.id
        left join sif.acc_vrste_ugovora vu on u.vrsta_ugovora_id = vu.id
;

