prompt
prompt Creating view VW_UIO_KIF
prompt ========================
prompt
create or replace force view accounting.vw_uio_kif as
select
        uio.id,
        uio.ooj_id,
        ooj.naziv                                as ooj_naziv,
        ooj.pib                                  as ooj_pib,
        uio.faktura_id,
        kif.naziv_fakture,
        uio.vrsta_sloga,
        uio.poreski_period,
        uio.redni_br,
        row_number()
        over(partition by uio.ooj_id, uio.poreski_period
             order by
                 uio.id asc
        )                                        as internal_redni_broj,
        lpad(uio.tip_dokumenta, 2, 0)            as tip_dokumenta,
        uio.broj_fakture,
        to_char(uio.datum_fakture, 'YYYY-MM-DD') as datum_fakture,
        uio.naziv_kupca,
        uio.sjediste_kupca,
        lpad(uio.pdv_broj_kupca, 12, 0)          as pdv_broj_kupca,
        lpad(uio.jib_broj_kupca, 13, 0)          as jib_broj_kupca,
        uio.iznos_fakture                        as iznos_fakture_char,
        to_broj(uio.iznos_fakture)               as iznos_fakture,
        uio.iznos_fakture_interne                as iznos_fakture_interne_char,
        to_broj(uio.iznos_fakture_interne)       as iznos_fakture_interne,
        uio.iznos_fakture_izvozne                as iznos_fakture_izvozne_char,
        to_broj(uio.iznos_fakture_izvozne)       as iznos_fakture_izvozne,
        uio.iznos_ostale_bez_pdv                 as iznos_ostale_bez_pdv_char,
        to_broj(uio.iznos_ostale_bez_pdv)        as iznos_ostale_bez_pdv,
        uio.iznos_osnovice_za_pdv                as iznos_osnovice_za_pdv_char,
        to_broj(uio.iznos_osnovice_za_pdv)       as iznos_osnovice_za_pdv,
        uio.iznos_izlaz_pdv_za_pdv               as iznos_izlaz_pdv_za_pdv_char,
        to_broj(uio.iznos_izlaz_pdv_za_pdv)      as iznos_izlaz_pdv_za_pdv,
        uio.iznos_osnovice_za_nepdv              as iznos_osnovice_za_nepdv_char,
        to_broj(uio.iznos_osnovice_za_nepdv)     as iznos_osnovice_za_nepdv,
        uio.iznos_izlaz_pdv_za_nepdv             as iznos_izlaz_pdv_za_nepdv_char,
        to_broj(uio.iznos_izlaz_pdv_za_nepdv)    as iznos_izlaz_pdv_za_nepdv,
        uio.iznos_pdv_32polje                    as iznos_pdv_32polje_char,
        to_broj(uio.iznos_pdv_32polje)           as iznos_pdv_32polje,
        uio.iznos_pdv_33polje                    as iznos_pdv_33polje_char,
        to_broj(uio.iznos_pdv_33polje)           as iznos_pdv_33polje,
        uio.iznos_pdv_34polje                    as iznos_pdv_34polje_char,
        to_broj(uio.iznos_pdv_34polje)           as iznos_pdv_34polje,
        uio.valid,
        uio.row_version,
        uio.created,
        uio.created_by,
        uio.updated,
        uio.updated_by
    from
        uio_kif uio
        left join kif on uio.faktura_id = kif.id
        left join core.ooj on uio.ooj_id = ooj.id
    where
        uio.valid = 'Y';

prompt
prompt Creating view VW_UIO_KUF
prompt ========================
prompt
create or replace force view accounting.vw_uio_kuf as
select
        uio.id,
        uio.ooj_id,
        ooj.naziv                                        as ooj_naziv,
        ooj.pib                                          as ooj_pib,
        uio.faktura_id,
        kuf.naziv_fakture,
        uio.vrsta_sloga,
        uio.redni_br,
        row_number()
        over(partition by uio.ooj_id, uio.poreski_period
             order by
                 uio.id asc
        )                                                as internal_redni_broj,
        lpad(uio.tip_dokumenta, 2, 0)                    as tip_dokumenta,
        uio.broj_fakture,
        to_char(uio.datum_fakture, 'YYYY-MM-DD')         as datum_fakture,
        to_char(uio.datum_fakture, 'yyyymm')             as mjesec_fakture,
        to_char(uio.datum_prijema_fakture, 'YYYY-MM-DD') as datum_prijema_fakture,
        to_char(uio.datum_prijema_fakture, 'yyyymm')     as mjesec_prijema_fakture,
        uio.naziv_dobavljaca,
        uio.sjediste_dobavljaca,
        lpad(uio.pdv_broj_dobavljaca, 12, 0)             as pdv_broj_dobavljaca,
        lpad(uio.jib_broj_dobavljaca, 13, 0)             as jib_broj_dobavljaca,
        uio.iznos_fakture_bezpdv                         as iznos_fakture_bezpdv_char,
        to_broj(uio.iznos_fakture_bezpdv)                as iznos_fakture_bezpdv,
        uio.iznos_fakture_sapdv                          as iznos_fakture_sapdv_char,
        to_broj(uio.iznos_fakture_sapdv)                 as iznos_fakture_sapdv,
        uio.iznos_pausal                                 as iznos_pausal_char,
        to_broj(uio.iznos_pausal)                        as iznos_pausal,
        uio.iznos_ulaznog_pdv                            as iznos_ulaznog_pdv_char,
        to_broj(uio.iznos_ulaznog_pdv)                   as iznos_ulaznog_pdv,
        uio.iznos_ulazpdv_odbiti                         as iznos_ulazpdv_odbiti_char,
        to_broj(uio.iznos_ulazpdv_odbiti)                as iznos_ulazpdv_odbiti,
        uio.iznos_ulazpdv_neodbiti                       as iznos_ulazpdv_neodbiti_char,
        to_broj(uio.iznos_ulazpdv_neodbiti)              as iznos_ulazpdv_neodbiti,
        uio.iznos_pdv_32polje                            as iznos_pdv_32polje_char,
        to_broj(uio.iznos_pdv_32polje)                   as iznos_pdv_32polje,
        uio.iznos_pdv_33polje                            as iznos_pdv_33polje_char,
        to_broj(uio.iznos_pdv_33polje)                   as iznos_pdv_33polje,
        uio.iznos_pdv_34polje                            as iznos_pdv_34polje_char,
        to_broj(uio.iznos_pdv_34polje)                   as iznos_pdv_34polje,
        uio.poreski_period,
        uio.valid,
        uio.row_version,
        uio.created,
        uio.created_by,
        uio.updated,
        uio.updated_by
    from
        uio_kuf uio
        left join core.ooj on uio.ooj_id = ooj.id
        left join kuf on uio.faktura_id = kuf.id
    where
        uio.valid = 'Y';

