        p_vrsta_naloga_sifra out varchar2
    );

    -- Za print - filename
    procedure get_kif (
        p_id            in number,
        p_naziv_fakture out varchar2
    );
    
    -- eRibolovac
    function insert_kif (
        p_kif in kif%rowtype
    ) return number;

    function insert_kif (
        p_glavna_knjiga_id     in number,
        p_klijent_id           in number,
        p_valuta_id            in number,
        p_valuta_iznos         in number,
        p_valuta_iznos_pdv     in number,
