        p_nabavna_cijena in number,
        p_vpc            out number,
        p_mpc            out number
    );
    
    procedure get_stavka_cjenovnik_cijene (
      p_stavka_id in number,
      p_cjenovnik_id in number, 
      p_nabavna_cijena out number, 
