    ) return number;

    procedure insert_stavka (
        p_ooj_id           in number,
        p_tip_stavke_id    in number,
        p_grupa_id         in number,
        p_jm_id            in number,
        p_naziv            in varchar2,
        p_sifra            in varchar2,
        p_marza            in number,
        p_klasa_id         in number,
        p_pdv_indikator    in varchar2,
        p_pdv_indikator_id in number,
        p_ino_usluga       in varchar2,
        p_serijski_broj    in varchar2
    );

    procedure update_stavka (
        p_id               in number,
        p_ooj_id           in number,
        p_tip_stavke_id    in number,
        p_grupa_id         in number,
        p_jm_id            in number,
        p_naziv            in varchar2,
        p_sifra            in varchar2,
        p_marza            in number,
        p_klasa_id         in number,
        p_pdv_indikator    in varchar2,
        p_pdv_indikator_id in number,
        p_ino_usluga       in varchar2,
        p_serijski_broj    in varchar2,
        p_valid            in varchar2
    );

    procedure update_stavka_retroaktivno (
        p_stavka_id in number,
        p_naziv     in varchar2
    );

    procedure delete_stavka (
        p_id in number
    );

    -- eGroblje
    procedure get_stavka_groblje (
        p_id                    in number,
        p_ooj_id                out number,
        p_naziv                 out varchar2,
        p_sifra                 out varchar2,
        p_datum_od              out date,
        p_datum_do              out date,
        p_tip_grobnog_mjesta_id out number,
        p_valid                 out varchar2
    );

    procedure insert_stavka_groblje (
        p_ooj_id                in number,
        p_naziv                 in varchar2,
        p_sifra                 in varchar2,
        p_datum_od              in date,
        p_datum_do              in date,
        p_tip_grobnog_mjesta_id in number
    );

    procedure update_stavka_groblje (
        p_id                    in number,
        p_ooj_id                in number,
        p_naziv                 in varchar2,
        p_sifra                 in varchar2,
        p_datum_od              in date,
        p_datum_do              in date,
        p_tip_grobnog_mjesta_id in number,
        p_valid                 in varchar2
    );
    
    -- eRibolovac
    procedure get_stavka_ribolovac (
        p_id     in number,
        p_ooj_id out number,
        p_naziv  out varchar2,
        p_sifra  out varchar2,
        p_valid  out varchar2
    );

    procedure insert_stavka_ribolovac (
        p_ooj_id in number,
        p_naziv  in varchar2,
        p_sifra  in varchar2
    );

    procedure update_stavka_ribolovac (
        p_id     in number,
        p_ooj_id in number,
        p_naziv  in varchar2,
        p_sifra  in varchar2,
        p_valid  in varchar2
    );
    
    --Car Service
    procedure get_stavka_car_service (
    p_id               in number,
    p_ooj_id           out number,
    p_tip_stavke_id    out number,
    p_jm_id            out number,
    p_naziv            out varchar2,
    p_sifra            out varchar2,
    p_valid            out varchar2
    );
    
    procedure insert_stavka_car_service (
    p_ooj_id           in number,
    p_tip_stavke_id    in number,
    p_jm_id            in number,
    p_naziv            in varchar2,
    p_sifra            in varchar2
    );

    procedure update_stavka_car_service (
        p_id               in number,
        p_ooj_id           in number,
        p_tip_stavke_id    in number,
        p_jm_id            in number,
        p_naziv            in varchar2,
        p_sifra            in varchar2,
        p_valid            in varchar2
    );
    
    -- Cjenovnik
    procedure get_cjenovnik (
        p_id     in number,
        p_ooj_id out number,
        p_sifra  out varchar2,
        p_naziv  out varchar2,
        p_opis   out varchar2,
        p_tip    out varchar2,
        p_valid  out varchar2
