        p_sifra  in varchar2,
        p_naziv  in varchar2,
        p_opis   in varchar2,
        p_tip    in varchar2,
        p_valid  in varchar2
    );

    procedure delete_cjenovnik (
        p_id in number
    );

    -- Cjenovnik stavke
    function get_nabavna_cijena (
        p_cjenovnik_id in number,
        p_stavka_id    in number
    ) return number;

    function get_stavka_cijena (
        p_cjenovnik_id in number,
        p_stavka_id    in number,
        p_tip_cijene   in varchar2
    ) return number;

    procedure get_cjenovnik_stavka (
        p_id             in number,
        p_cjenovnik_id   out number,
        p_stavka_id      out number,
        p_datum          out date,
        p_nabavna_cijena out number,
        p_mpc            out number,
        p_vpc            out number,
        p_valid          out varchar2
    );

    procedure insert_cjenovnik_stavka (
        p_cjenovnik_id   in number,
        p_stavka_id      in number,
        p_datum          in date,
        p_nabavna_cijena in number,
        p_mpc            in number,
        p_vpc            in number
    );

    procedure insert_cjenovnik_stavka (
        p_cjenovnik_id   in number,
        p_stavka_id in number,
        p_cijena    in number
    );

    procedure update_cjenovnik_stavka (
        p_cjenovnik_id   in number,
        p_id             in number,
        p_stavka_id      in number,
        p_datum          in date,
        p_nabavna_cijena in number,
        p_mpc            in number,
        p_vpc            in number,
        p_valid          in varchar2
    );

    procedure delete_cjenovnik_stavka (
        p_id in number
    );
    
    procedure deaktiviraj_cjenovnik_stavka (
        p_id in number
    );

    

end stavke_pkg;
/

prompt
prompt Creating package UGOVORI_PKG
prompt ============================
prompt
CREATE OR REPLACE PACKAGE ACCOUNTING.ugovori_pkg IS

    --------------------------------------------------------------
    -- Procedures for table UGOVORI
    --------------------------------------------------------------

    -- Vraća naziv i broj novog aneksa za osnovni ugovor.
    procedure get_referenca (
        p_ooj_id       in number,
        p_referenca_id in number,
        p_godina       in number,
        p_naziv        out varchar2,
        p_broj         out number
    );

    procedure get_ugovor (
        p_id                 in number,
        p_ooj_id             out number,
        p_klijent_id         out number,
        p_valuta_id          out number,
        p_izvrsilac_narucioc out varchar2,
        p_ugovor_start       out date,
        p_ugovor_end         out date,
        p_iznos              out number,
        p_naziv              out varchar2,
        p_broj               out varchar2,
        p_predmet            out varchar2,
        p_referenca          out varchar2,
        p_referenca_id       out number,
        p_oj_id              out number,
        p_interval_id        out number,
        p_valid              out varchar2
    );

    -- Čita kolone dodate uz vrstu, status, kurs i uslove ugovora.
    procedure get_ugovor_dodatno (
        p_id                    in number,
        p_vrsta_ugovora_id      out number,
        p_status                out varchar2,
        p_status_naziv          out varchar2,
        p_kurs                  out number,
        p_iznos_km              out number,
        p_dan_dospijeca         out number,
        p_otkazni_rok_dana      out number,
        p_automatsko_produzenje out varchar2,
        p_produzenje_mjeseci    out number,
        p_aneks_broj            out number,
        p_broj_stavki           out number
    );

    procedure get_ugovor (
        p_id    in number,
        p_naziv out varchar2
    );

    -- Za kreiranje/azuriranje fakture
    procedure get_ugovor (
        p_id         in number,
        p_klijent_id out number,
        p_oj_id      out varchar2
    );

    -- Vraća posljednju zaključenu verziju ugovora (osnovni ugovor ili njegov posljednji aneks).
    function get_posljednja_verzija (
        p_osnovni_id in number
    ) return number;

    -- Vraća kurs valute prema KM na dan: BAM 1, EUR fiksni kurs, ostale valute iz kursne liste firme.
    function get_kurs (
        p_valuta_id in number,
        p_ooj_id    in number,
        p_datum     in date
    ) return number;

    -- Ugovor se smije mijenjati samo dok je u pripremi (status P).
    function is_ugovor_editable (
        p_id in number
    ) return boolean;

    -- Isto, kao Y ili N, za upite i uslove u APEX-u.
    function is_ugovor_editable_yn (
        p_id in number
    ) return varchar2;

    function insert_ugovor (
        p_ooj_id                in number,
        p_klijent_id            in number,
        p_valuta_id             in number,
        p_izvrsilac_narucioc    in varchar2,
        p_ugovor_start          in date,
        p_ugovor_end            in date,
        p_iznos                 in number,
        p_naziv                 in varchar2,
        p_broj                  in varchar2,
        p_predmet               in varchar2,
        p_referenca             in varchar2,
        p_referenca_id          in number,
        p_oj_id                 in number,
        p_interval_id           in number,
        p_system                in varchar2 default 'N',
        p_vrsta_ugovora_id      in number default null,
        p_status                in varchar2 default null,
        p_kurs                  in number default null,
        p_dan_dospijeca         in number default null,
        p_otkazni_rok_dana      in number default null,
        p_automatsko_produzenje in varchar2 default null,
        p_produzenje_mjeseci    in number default null,
        p_godina                in number default null
    ) return number;

    procedure update_ugovor (
        p_id                    in number,
        p_klijent_id            in number,
        p_valuta_id             in number,
        p_izvrsilac_narucioc    in varchar2,
        p_ugovor_start          in date,
        p_ugovor_end            in date,
        p_iznos                 in number,
        p_predmet               in varchar2,
        p_oj_id                 in number,
        p_interval_id           in number,
        p_system                in varchar2 default null,
        p_valid                 in varchar2,
        p_vrsta_ugovora_id      in number default null,
        p_kurs                  in number default null,
        p_dan_dospijeca         in number default null,
        p_otkazni_rok_dana      in number default null,
        p_automatsko_produzenje in varchar2 default null,
        p_produzenje_mjeseci    in number default null
    );

    -- Prebacuje ugovor iz pripreme (P) u zaključen (Z); nakon toga se ugovor ne mijenja.
    procedure zakljuci_ugovor (
        p_id in number
    );

    -- Prebacuje zaključen osnovni ugovor (Z) i sve njegove anekse u raskinut (R).
    -- Aneks se ne raskida zasebno.
    procedure raskini_ugovor (
