prompt
prompt Creating procedure CHECK_OS_ODRZAVANJE
prompt ======================================
prompt
create or replace procedure accounting.check_os_odrzavanje (
    p_app_id in number
) as

    cursor c_odrzavanja is
    (
        select
            firma_id,
            osnovno_sredstvo_naziv,
            naziv,
            datum,
            cijena,
            sledeci_servis,
            trunc(sledeci_servis) - trunc(sysdate) as broj_dana
        from
            vw_osnovno_sredstvo_odrzavanje
        where
                valid = 'Y'
            and trunc(sledeci_servis) - trunc(sysdate) in ( 30, 14, 7, 1, 0 )
    );

    cursor c_korisnici (
        p_firma_id in number
    ) is
    (
        select
            email,
            korisnicko_ime,
            ime
            || ' '
            || prezime as korisnik_naziv
        from
            core.korisnici
        where
                valid = 'Y'
            and firma_id = p_firma_id
            and core.korisnik_pkg.user_has_role(id, 'OS_NOTIFIKACIJE_RLE') > 0
    );

begin
    for odrzavanje in c_odrzavanja loop
        for korisnik in c_korisnici(odrzavanje.firma_id) loop
            mail_pkg.posalji_os_odrzavanje(
                p_app_id            => p_app_id,
                p_username          => korisnik.korisnicko_ime,
                p_mail_to           => korisnik.email,
                p_name              => korisnik.korisnik_naziv,
                p_os_razlika        => odrzavanje.broj_dana,
                p_os_naziv          => odrzavanje.osnovno_sredstvo_naziv,
                p_os_odrzavanje     => odrzavanje.naziv,
                p_os_datum          => odrzavanje.datum,
                p_os_cijena         => odrzavanje.cijena,
                p_os_sledeci_servis => odrzavanje.sledeci_servis
            );
        end loop;
    end loop;

    apex_mail.push_queue;
    apex_pwa.push_queue;
end check_os_odrzavanje;
/

