prompt Creating procedure DJ_MIGRACIJA_KONTNOG_PLANA
prompt =============================================
prompt
create or replace procedure accounting.dj_migracija_kontnog_plana is

  l_nad_konto number;
  l_nk_code varchar2(10);
  l_nk_ooj_id number;
  l_konto_id number;
begin
  ---dodjela dafoultnog kontnog plana korisniku----
  for ooj in (select distinct gk.ooj_id from accounting.glavna_knjiga gk where gk.ooj_id=219 )
  loop

        /*for kp in (SELECT *
                    FROM sif.acc_kontni_okvir_klase
                    WHERE ooj_id IS NULL
                    and length(code)>3
                    START WITH kontna_klasa_id IS NULL
                    CONNECT BY PRIOR id = kontna_klasa_id)
        loop

            dbms_output.put_line(kp.code||'-'||kp.kontna_klasa_id);
            select nk.code, nk.ooj_id
            into l_nk_code, l_nk_ooj_id
            from sif.acc_kontni_okvir_klase nk
            where id = kp.kontna_klasa_id;

            if l_nk_ooj_id is null and length(l_nk_code) <= 3 then
                l_nad_konto := kp.kontna_klasa_id;   -- roditelj je dijeljeni/defoultni konto - ne duplira se
            else
                select kk.id
                into l_nad_konto
                from sif.acc_kontni_okvir_klase kk
                where kk.code = l_nk_code
                  and kk.ooj_id = ooj.ooj_id;
            end if;

            sif.acc_pkg.insert_kontni_okvir_klasa(kp.entitet_id ,
                                                  l_nad_konto ,
                                                  ooj.ooj_id          ,
                                                  kp.code            ,
                                                  kp.naziv           ,
                                                  kp.os            ,
                                                  kp.klijent         ,
                                                  kp.oj              ,
                                                  kp.radnik          ,
                                                  kp.pdv_indikator   ,
                                                  kp.pdv_indikator_sifra,
                                                  kp.otvorene_stavke );


        end loop;*/


       ----za migraciju ako je korisnik dodavao svoja konta, potrebno mapirati novi nadređeni konto----

       for k in (select * from sif.acc_kontni_okvir_klase kk
                 where kk.ooj_id=ooj.ooj_id
                 and trunc(kk.created)<trunc(sysdate)-1)
       loop


            select nk.code, nk.ooj_id
            into l_nk_code, l_nk_ooj_id
            from sif.acc_kontni_okvir_klase nk
            where id = k.kontna_klasa_id;

            if l_nk_ooj_id is null and length(l_nk_code) <= 3 then
                l_nad_konto := k.kontna_klasa_id;   -- roditelj je dijeljeni/defoultni konto - ne duplira se
            else
                select kk.id
                into l_nad_konto
                from sif.acc_kontni_okvir_klase kk
                where kk.code = l_nk_code
                and kk.ooj_id = ooj.ooj_id;
            end if;



             sif.acc_pkg.update_kontni_okvir_klasa(k.id,
                                                   k.entitet_id,
                                                   l_nad_konto,
                                                   ooj.ooj_id,
                                                   k.code,
                                                   k.naziv,
                                                   k.os,
                                                   k.klijent,
                                                   k.oj,
                                                   k.radnik,
                                                   k.pdv_indikator,
                                                   k.pdv_indikator_sifra,
                                                   k.valid,
                                                   k.otvorene_stavke);

       end loop;

       ---------updejt id-eva konta u vezanim tabelama--------
       ---blagajne tipovi promjena
       /*for bt in (select btp.*, ak.id as konto_id, ak.code
                  from accounting.BLAGAJNA_TIPOVI_PROMJENA btp
                  join sif.acc_kontni_okvir_klase ak on ak.id=btp.kontna_klasa_id
                  where btp.ooj_id=ooj.ooj_id)
       loop

           if length(bt.code)<=3 then
             null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = bt.code
             and kk.ooj_id = ooj.ooj_id;


             accounting.blagajna_pkg.update_blagajna_tip_promjene(bt.id,
                                                                  bt.ooj_id,
                                                                  l_konto_id,
                                                                  bt.naziv,
                                                                  bt.radnik,
                                                                  bt.klijent,
                                                                  bt.oj,
                                                                  bt.valid);
           end if;

       end loop;

       -----
       --blagajne
       for b in (select bl.*, ak.id as konto_id, ak.code
                  from accounting.blagajne bl
                  join sif.acc_kontni_okvir_klase ak on ak.id=bl.kontna_klasa_id
                  where bl.ooj_id=ooj.ooj_id)
       loop

           if length(b.code)<=3 then
             null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = b.code
             and kk.ooj_id = ooj.ooj_id;


             accounting.blagajna_pkg.update_blagajna( b.id,
                                                      b.ooj_id,
                                                      l_konto_id,
                                                      b.valuta_id,
                                                      b.tip,
                                                      b.naziv,
                                                      b.valid);
           end if;

       end loop;
       --
       --glavana knjiga stavke--
       for st in (select gks.*, ak.id as konto_id, ak.code
                  from accounting.glavna_knjiga_stavke gks
                  join accounting.glavna_knjiga gk on gk.id=gks.glavna_knjiga_id
                  join sif.acc_kontni_okvir_klase ak on ak.id=gks.kontna_klasa_id
                  where gk.ooj_id=ooj.ooj_id
                  )

       loop

           if length(st.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = st.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.glavna_knjiga_stavke gks
             set gks.kontna_klasa_id=l_konto_id
             where gks.id=st.id;


           end if;


       end loop;
       ---

       --izvodi stavke
       for i in (select ist.id,  ak.id as konto_id, ak.code
                  from accounting.izvod_stavke ist
                  join accounting.izvodi i on i.id=ist.izvod_id
                  join sif.acc_kontni_okvir_klase ak on ak.id=ist.konto_id
                  where i.ooj_id=ooj.ooj_id
                  )
       loop

           if length(i.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = i.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.izvod_stavke ist
             set ist.konto_id=l_konto_id
             where ist.id=i.id;


           end if;


       end loop;

       --
       ---sabloni knjiženja---
       for s in (select sk.id,  ak.id as konto_id, ak.code
                 from accounting.sabloni s
                 join accounting.sabloni_konta sk on s.id=sk.sablon_id
                 join sif.acc_kontni_okvir_klase ak on ak.id=sk.kontna_klasa_id
                 where s.ooj_id=ooj.ooj_id)
       loop

           if length(s.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = s.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.sabloni_konta sk
             set sk.kontna_klasa_id=l_konto_id
             where sk.id=s.id;


             end if;

        end loop;
         --
       ---sec klijenti---
       for skk in (select sk.*, ak.id as konto_id, ak.code
                   from accounting.sec_klijenti sk
                   join sif.acc_kontni_okvir_klase ak on ak.id=sk.kontna_klasa_id
                   where sk.ooj_id=ooj.ooj_id)

       loop


           if length(skk.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = skk.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.sec_klijenti sk
             set sk.kontna_klasa_id=l_konto_id
             where sk.id=skk.id;


             end if;



       end loop;
       --
       ---sec klijenti konta---
       for k2 in (select k1.*, ak.id as konto_id, ak.code
                   from accounting.sec_klijent_konta k1
                   join accounting.sec_klijenti sk1 on sk1.id=k1.sec_klijent_id
                   join sif.acc_kontni_okvir_klase ak on ak.id=k1.kontna_klasa_id
                   where sk1.ooj_id=ooj.ooj_id)

       loop


           if length(k2.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = k2.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.sec_klijent_konta sk
             set sk.kontna_klasa_id=l_konto_id
             where sk.id=k2.id;


             end if;



       end loop;
       ----
       --core ooj_banke--
       for b1 in (select b.*, ak.id as konto_id, ak.code
                  from core.ooj_banke b
                  join sif.acc_kontni_okvir_klase ak on ak.id=b.kontna_klasa_id
                  where b.ooj_id=ooj.ooj_id)

       loop


           if length(b1.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = b1.code
             and kk.ooj_id = ooj.ooj_id;

             update core.ooj_banke bb
             set bb.kontna_klasa_id=l_konto_id
             where bb.id=b1.id;



             end if;




       end loop;
       ----
       for zr1 in (select zr.*, ak.id as konto_id, ak.code
                  from sif.sif_ziro_racuni zr
                  join sif.acc_kontni_okvir_klase ak on ak.id=zr.kontna_klasa_id
                  where zr.ooj_id=ooj.ooj_id)

       loop


           if length(zr1.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = zr1.code
             and kk.ooj_id = ooj.ooj_id;


             update sif.sif_ziro_racuni szr
             set szr.kontna_klasa_id=l_konto_id
             where szr.id=zr1.id;

          end if;



       end loop;*/

       -------------------------------------------------------


  end loop;



end;
/

prompt
prompt Creating procedure LOCK_PERIOD_OOJ
prompt ==================================
prompt
create or replace procedure accounting.lock_period_ooj as
begin
    update core.ooj
    set
        period_zakljucan_do = add_months(
            last_day(sysdate),
            -1
        );

end lock_period_ooj;
/

prompt
prompt Creating procedure OS_AUTOMATSKA_AMORTIZACIJA
prompt =============================================
prompt
create or replace procedure accounting.os_automatska_amortizacija as

    cursor c_ooj_list is
    (
        select distinct
            ooj_id
        from
            vw_osnovna_sredstva
        where
                aktivirano = 'Y'
            and valid = 'Y'
            and knjigovodstvena_vrijednost > rezidualna_vrijednost
    );

    l_nalog_id number;
begin
    for ooj in c_ooj_list loop
        l_nalog_id := glavna_knjiga_pkg.knjizi_os_amortizcija_pp(
            p_ooj_id                  => ooj.ooj_id,
            p_pp                      => sysdate,
            p_proknjizeno             => 'N',
            p_automatska_amortizacija => 'Y'
        );
    end loop;
end os_automatska_amortizacija;
/

prompt
prompt Creating package body BLAGAJNA_PKG
prompt ==================================
prompt
create or replace package body accounting.blagajna_pkg is

    -- Tipovi promjena    
    procedure get_blagajna_tip_promjene (
        p_id              in number,
        p_ooj_id          out number,
        p_kontna_klasa_id out number,
        p_naziv           out varchar2,
        p_radnik          out varchar2,
        p_klijent         out varchar2,
        p_oj              out varchar2,
        p_valid           out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                blagajna_tipovi_promjena
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_kontna_klasa_id := c1.kontna_klasa_id;
            p_naziv := c1.naziv;
            p_radnik := c1.radnik;
            p_klijent := c1.klijent;
            p_oj := c1.oj;
            p_valid := c1.valid;
        end loop;
    end get_blagajna_tip_promjene;

    procedure insert_blagajna_tip_promjene (
        p_ooj_id          in number,
        p_kontna_klasa_id in number,
        p_naziv           in varchar2,
        p_radnik          in varchar2,
        p_klijent         in varchar2,
        p_oj              in varchar2
    ) is
    begin
        insert into blagajna_tipovi_promjena (
            ooj_id,
            kontna_klasa_id,
            naziv,
            radnik,
            klijent,
            oj
        ) values ( p_ooj_id,
                   p_kontna_klasa_id,
                   p_naziv,
                   p_radnik,
                   p_klijent,
                   p_oj );

    end insert_blagajna_tip_promjene;

    procedure update_blagajna_tip_promjene (
        p_id              in number,
        p_ooj_id          in number,
        p_kontna_klasa_id in number,
        p_naziv           in varchar2,
        p_radnik          in varchar2,
        p_klijent         in varchar2,
        p_oj              in varchar2,
        p_valid           in varchar2
    ) is
    begin
        update blagajna_tipovi_promjena
        set
            ooj_id = p_ooj_id,
            kontna_klasa_id = p_kontna_klasa_id,
            naziv = p_naziv,
            radnik = p_radnik,
            klijent = p_klijent,
            oj = p_oj,
            valid = p_valid
        where
            id = p_id;

    end update_blagajna_tip_promjene;

    procedure delete_blagajna_tip_promjene (
        p_id in number
    ) is
    begin
        delete from blagajna_tipovi_promjena
        where
            id = p_id;

    end delete_blagajna_tip_promjene;

    -- Blagajne
    procedure get_blagajna (
        p_id              in number,
        p_ooj_id          out number,
        p_kontna_klasa_id out number,
        p_valuta_id       out number,
        p_tip             out varchar2,
        p_naziv           out varchar2,
        p_valid           out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                blagajne
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_kontna_klasa_id := c1.kontna_klasa_id;
            p_valuta_id := c1.valuta_id;
            p_tip := c1.tip;
            p_naziv := c1.naziv;
            p_valid := c1.valid;
        end loop;
    end get_blagajna;

    procedure insert_blagajna (
        p_ooj_id          in number,
        p_kontna_klasa_id in number,
        p_valuta_id       in number,
        p_tip             in varchar2,
        p_naziv           in varchar2
    ) is
    begin
        insert into blagajne (
            ooj_id,
            kontna_klasa_id,
            valuta_id,
            tip,
            naziv
        ) values ( p_ooj_id,
                   p_kontna_klasa_id,
                   p_valuta_id,
                   p_tip,
                   p_naziv );

    end insert_blagajna;

    procedure update_blagajna (
        p_id              in number,
        p_ooj_id          in number,
        p_kontna_klasa_id in number,
        p_valuta_id       in number,
        p_tip             in varchar2,
        p_naziv           in varchar2,
        p_valid           in varchar2
    ) is
    begin
        update blagajne
        set
            ooj_id = p_ooj_id,
            kontna_klasa_id = p_kontna_klasa_id,
            valuta_id = p_valuta_id,
            tip = p_tip,
            naziv = p_naziv,
            valid = p_valid
        where
            id = p_id;

    end update_blagajna;

    procedure delete_blagajna (
        p_id in number
    ) is
    begin
        delete from blagajne
        where
            id = p_id;

    end delete_blagajna;

    -- Dnevnik
    function is_dnevnik_editable (
        p_dnevnik_id in number
    ) return number is
    begin
        for c1 in (
            select
                *
            from
                blagajna_dnevnik
            where
                id = p_dnevnik_id
        ) loop
            if c1.glavna_knjiga_id is not null then
                return 0;
            elsif c1.zakljucno_stanje is not null then
                return 0;
            end if;

            return 1;
        end loop;
    end is_dnevnik_editable;

    function get_dnevnik_broj_stavke (
        p_dnevnik_id in number
    ) return number is
    begin
        for c1 in (
            select
                coalesce(
                    max(redni_broj),
                    0
                ) as output
            from
                blagajna_dnevnik_stavke
            where
                dnevnik_id = p_dnevnik_id
        ) loop
            return c1.output + 1;
        end loop;
    end get_dnevnik_broj_stavke;

    function get_pocetno_stanje_blagajne (
        p_ooj_id      in number,
        p_blagajna_id in number,
        p_godina      in number
    ) return number is
    begin
        for c1 in (
            select
                zakljucno_stanje
            from
                blagajna_dnevnik
            where
                    ooj_id = p_ooj_id
                and blagajna_id = p_blagajna_id
                and godina = p_godina
            order by
                datum desc
            fetch first row only
        ) loop
            return c1.zakljucno_stanje;
        end loop;

        return null;
    end get_pocetno_stanje_blagajne;

    procedure get_blagajna_dnevnik (
        p_id             in number,
        p_ooj_id         out number,
        p_blagajna_id    out number,
        p_datum          out date,
        p_pocetno_stanje out number,
        p_godina         out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                blagajna_dnevnik
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_blagajna_id := c1.blagajna_id;
            p_datum := c1.datum;
            p_pocetno_stanje := c1.pocetno_stanje;
            p_godina := c1.godina;
        end loop;
    end get_blagajna_dnevnik;

    procedure get_blagajna_dnevnik_zakljucavanje (
        p_id               in number,
        p_pocetno_stanje   out number,
        p_prijem           out number,
        p_placanja         out number,
        p_zakljucno_stanje out number
    ) is
    begin
        for c1 in (
            select
                pocetno_stanje,
                (
                    select
                        sum(s.iznos)
                    from
                        blagajna_dnevnik_stavke s
                    where
                            s.dnevnik_id = p_id
                        and s.tip = 'U'
                ) as prijem,
                (
                    select
                        sum(s.iznos)
                    from
                        blagajna_dnevnik_stavke s
                    where
                            s.dnevnik_id = p_id
                        and s.tip = 'I'
                ) as placanja
            from
                blagajna_dnevnik
            where
                id = p_id
        ) loop
            p_pocetno_stanje := coalesce(c1.pocetno_stanje, 0);
            p_prijem := coalesce(c1.prijem, 0);
            p_placanja := coalesce(c1.placanja, 0);
            p_zakljucno_stanje := coalesce(c1.pocetno_stanje, 0) + coalesce(c1.prijem, 0) - coalesce(c1.placanja, 0);

        end loop;
    end get_blagajna_dnevnik_zakljucavanje;

    function insert_blagajna_dnevnik (
        p_ooj_id         in number,
        p_blagajna_id    in number,
        p_datum          in date,
        p_pocetno_stanje in number,
        p_godina         in number
    ) return number is
        l_id number;
    begin
        insert into blagajna_dnevnik (
            ooj_id,
            blagajna_id,
            datum,
            pocetno_stanje,
            godina
        ) values ( p_ooj_id,
                   p_blagajna_id,
                   p_datum,
                   p_pocetno_stanje,
                   p_godina ) returning id into l_id;

        return l_id;
    end insert_blagajna_dnevnik;

    procedure update_blagajna_dnevnik (
        p_id             in number,
        p_ooj_id         in number,
        p_blagajna_id    in number,
        p_datum          in date,
        p_pocetno_stanje in number,
        p_godina         in number
    ) is
    begin
        update blagajna_dnevnik
        set
            ooj_id = p_ooj_id,
            blagajna_id = p_blagajna_id,
            datum = p_datum,
            pocetno_stanje = p_pocetno_stanje,
            godina = p_godina
        where
            id = p_id;

    end update_blagajna_dnevnik;

    procedure update_blagajna_dnevnik_zakljucavanje (
        p_id               in number,
        p_prijem           in number,
        p_placanja         in number,
        p_zakljucno_stanje in number
    ) is
    begin
        update blagajna_dnevnik
        set
            prijem = p_prijem,
            placanja = p_placanja,
            zakljucno_stanje = p_zakljucno_stanje
        where
            id = p_id;

    end update_blagajna_dnevnik_zakljucavanje;

    procedure delete_blagajna_dnevnik (
        p_id in number
    ) is
    begin
        delete from blagajna_dnevnik
        where
            id = p_id;

    end delete_blagajna_dnevnik;

    -- Dnevnik stavke
    procedure insert_blagajna_dnevnik_stavka (
        p_dnevnik_id      in number,
        p_tip_promjene_id in number,
        p_radnik_id       in number,
        p_klijent_id      in number,
        p_oj_id           in number,
        p_tip             in varchar2,
        p_iznos           in number
    ) is
        l_redni_broj number;
    begin
        l_redni_broj := get_dnevnik_broj_stavke(p_dnevnik_id);
        insert into blagajna_dnevnik_stavke (
            dnevnik_id,
            tip_promjene_id,
            radnik_id,
            klijent_id,
            oj_id,
            redni_broj,
            tip,
            iznos
        ) values ( p_dnevnik_id,
                   p_tip_promjene_id,
                   p_radnik_id,
                   p_klijent_id,
                   p_oj_id,
                   l_redni_broj,
                   p_tip,
                   p_iznos );

    end insert_blagajna_dnevnik_stavka;

    procedure update_blagajna_dnevnik_stavka (
        p_id              in number,
        p_dnevnik_id      in number,
        p_tip_promjene_id in number,
        p_radnik_id       in number,
        p_klijent_id      in number,
        p_oj_id           in number,
        p_tip             in varchar2,
        p_iznos           in number
    ) is
    begin
        update blagajna_dnevnik_stavke
        set
            dnevnik_id = p_dnevnik_id,
            tip_promjene_id = p_tip_promjene_id,
            radnik_id = p_radnik_id,
            klijent_id = p_klijent_id,
            oj_id = p_oj_id,
            tip = p_tip,
            iznos = p_iznos
        where
            id = p_id;

    end update_blagajna_dnevnik_stavka;

    procedure delete_blagajna_dnevnik_stavka (
        p_id in number
    ) is
    begin
        delete from blagajna_dnevnik_stavke
        where
            id = p_id;

    end delete_blagajna_dnevnik_stavka;

end blagajna_pkg;
/

prompt
prompt Creating package body BUDZET_PKG
prompt ================================
prompt
create or replace package body accounting.budzet_pkg is

    -- Helper
    function get_column_headings (
        p_broj_mjeseci in number
    ) return varchar2 is
        l_cols varchar2(255) := 'Organizaciona jedinica:Stavka:Projekat:';
    begin
        apex_debug.message(l_cols);
        case
            when p_broj_mjeseci = 12 then
                l_cols := l_cols || 'P1:xx:xx:xx:xx:xx:xx:xx:xx:xx:xx:xx';
            when p_broj_mjeseci = 6 then
                l_cols := l_cols || 'P1:xx:xx:xx:xx:xx:P2:xx:xx:xx:xx:xx';
            when p_broj_mjeseci = 3 then
                l_cols := l_cols || 'P1:xx:xx:P2:xx:xx:P3:xx:xx:P4:xx:xx';
            when p_broj_mjeseci = 1 then
                l_cols := l_cols || 'P1:P2:P3:P4:P5:P6:P7:P8:P9:P10:P11:P12';
        end case;

        apex_debug.message(l_cols);
        return l_cols || ':Ukupno';
    end get_column_headings;

    -- Budzetske stavke
    function get_budzetska_stavka_oj_id (
        p_id in number
    ) return number is
    begin
        for c1 in (
            select
                *
            from
                budzetske_stavke
            where
                id = p_id
        ) loop
            return c1.oj_id;
        end loop;

        return null;
    end get_budzetska_stavka_oj_id;

    procedure get_budzetska_stavka (
        p_id        in number,
        p_ooj_id    out number,
        p_stavka_id out number,
        p_oj_id     out number,
        p_naziv     out varchar2,
        p_valid     out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                budzetske_stavke
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_stavka_id := c1.stavka_id;
            p_oj_id := c1.oj_id;
            p_naziv := c1.naziv;
            p_valid := c1.valid;
        end loop;
    end get_budzetska_stavka;

    procedure insert_budzetska_stavka (
        p_ooj_id    in number,
        p_stavka_id in number,
        p_oj_id     in number,
        p_naziv     in varchar2
    ) is
    begin
        insert into budzetske_stavke (
            ooj_id,
            stavka_id,
            oj_id,
            naziv
        ) values ( p_ooj_id,
                   p_stavka_id,
                   p_oj_id,
                   p_naziv );

    end insert_budzetska_stavka;

    procedure update_budzetska_stavka (
        p_id        in number,
        p_ooj_id    in number,
        p_stavka_id in number,
        p_oj_id     in number,
        p_naziv     in varchar2,
        p_valid     in varchar2
    ) is
    begin
        update budzetske_stavke
        set
            ooj_id = p_ooj_id,
            stavka_id = p_stavka_id,
            oj_id = p_oj_id,
            naziv = p_naziv,
            valid = p_valid
        where
            id = p_id;

    end update_budzetska_stavka;

    procedure delete_budzetska_stavka (
        p_id in number
    ) is
    begin
        delete from budzetske_stavke
        where
            id = p_id;

    end delete_budzetska_stavka;

    -- Budzeti
    procedure get_budzet (
        p_id          in number,
        p_ooj_id      out number,
        p_interval_id out number,
        p_valuta_id   out number,
        p_godina      out number,
        p_napomena    out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                budzeti
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_interval_id := c1.interval_id;
            p_valuta_id := c1.valuta_id;
            p_godina := c1.godina;
            p_napomena := c1.napomena;
        end loop;
    end get_budzet;

    -- Za unos stavki (setup)
    procedure get_budzet (
        p_id           in number,
        p_broj_mjeseci out number,
        p_godina       out number,
        p_status_sifra out varchar2
    ) is
    begin
        for c1 in (
            select
                interval_broj_mjeseci,
                godina,
                status_sifra
            from
                vw_budzeti
            where
                id = p_id
        ) loop
            p_broj_mjeseci := c1.interval_broj_mjeseci;
            p_godina := c1.godina;
            p_status_sifra := c1.status_sifra;
        end loop;
    end get_budzet;

    procedure get_budzet (
        p_id        in number,
        p_max_iznos out number,
        p_suma      out number
    ) is
    begin
        for c1 in (
            select
                sum(max_iznos)  as max_iznos,
                sum(stavke_sum) as suma
            from
                vw_budzet_oj
            where
                budzet_id = p_id
        ) loop
            p_max_iznos := c1.max_iznos;
            p_suma := c1.suma;
        end loop;
    end get_budzet;

    function insert_budzet (
        p_ooj_id      in number,
        p_interval_id in number,
        p_valuta_id   in number,
        p_budzet_id   in number,
        p_godina      in number,
        p_napomena    in varchar2,
        p_radnik_id   in number
    ) return number is

        l_id        number;
        l_status_id number := sif.budzet_pkg.get_status_with_sifra('10');
        cursor c_oj is
        (
            select
                id
            from
                core.oj
            where
                ooj_id = p_ooj_id
        );

    begin
        insert into budzeti (
            ooj_id,
            status_id,
            interval_id,
            valuta_id,
            budzet_id,
            godina,
            napomena
        ) values ( p_ooj_id,
                   l_status_id,
                   p_interval_id,
                   p_valuta_id,
                   p_budzet_id,
                   p_godina,
                   p_napomena ) returning id into l_id;

        insert_budzet_hist(
            p_budzet_id => l_id,
            p_status_id => l_status_id,
            p_radnik_id => p_radnik_id,
            p_komentar  => null,
            p_datum     => sysdate
        );

        return l_id;
    end insert_budzet;

    procedure update_budzet (
        p_id          in number,
        p_ooj_id      in number,
        p_interval_id in number,
        p_valuta_id   in number,
        p_godina      in number,
        p_napomena    in varchar2
    ) is
    begin
        update budzeti
        set
            ooj_id = p_ooj_id,
            interval_id = p_interval_id,
            valuta_id = p_valuta_id,
            godina = p_godina,
            napomena = p_napomena
        where
            id = p_id;

    end update_budzet;

    procedure delete_budzet (
        p_id in number
    ) is
    begin
        delete from budzeti
        where
            id = p_id;

    end delete_budzet;

    -- Budzet HIST
    procedure insert_budzet_hist (
        p_budzet_id in number,
        p_status_id in number,
        p_radnik_id in number,
        p_komentar  in varchar2,
        p_datum     in date
    ) is
    begin
        update budzeti
        set
            status_id = p_status_id
        where
            id = p_budzet_id;

        insert into budzet_hist (
            budzet_id,
            status_id,
            radnik_id,
            komentar,
            datum
        ) values ( p_budzet_id,
                   p_status_id,
                   p_radnik_id,
                   p_komentar,
                   p_datum );

    end insert_budzet_hist;

    -- Budzet OJ
    procedure get_budzet_oj (
        p_budzet_id in number,
        p_oj_id     in number,
        p_max_iznos out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                budzet_oj
            where
                    budzet_id = p_budzet_id
                and oj_id = p_oj_id
        ) loop
            p_max_iznos := c1.max_iznos;
        end loop;
    end get_budzet_oj;

    procedure get_budzet_oj (
        p_budzet_id in number,
        p_oj_id     in number,
        p_max_iznos out number,
        p_suma      out number
    ) is
    begin
        for c1 in (
            select
                max_iznos,
                stavke_sum
            from
                vw_budzet_oj
            where
                    budzet_id = p_budzet_id
                and oj_id = p_oj_id
        ) loop
            p_max_iznos := c1.max_iznos;
            p_suma := c1.stavke_sum;
        end loop;
    end get_budzet_oj;

    procedure get_budzet_oj (
        p_budzet_id    in number,
        p_oj_id        in number,
        p_status_sifra out varchar2
    ) is
    begin
        for c1 in (
            select
                status_sifra
            from
                vw_budzet_oj
            where
                    budzet_id = p_budzet_id
                and oj_id = p_oj_id
        ) loop
            p_status_sifra := c1.status_sifra;
        end loop;
    end get_budzet_oj;

    procedure insert_budzet_oj (
        p_budzet_id in number,
        p_oj_id     in number,
        p_max_iznos in number,
        p_radnik_id in number
    ) is
        l_status_id number := sif.budzet_pkg.get_status_with_sifra('10');
    begin
        insert into budzet_oj (
            budzet_id,
            oj_id,
            max_iznos,
            status_id
        ) values ( p_budzet_id,
                   p_oj_id,
                   p_max_iznos,
                   l_status_id );

        insert_budzet_oj_hist(
            p_budzet_id => p_budzet_id,
            p_oj_id     => p_oj_id,
            p_status_id => l_status_id,
            p_radnik_id => p_radnik_id,
            p_komentar  => null,
            p_datum     => sysdate
        );

    end insert_budzet_oj;

    procedure update_budzet_oj (
        p_budzet_id in number,
        p_oj_id     in number,
        p_max_iznos in number
    ) is
    begin
        update budzet_oj
        set
            max_iznos = p_max_iznos
        where
                budzet_id = p_budzet_id
            and oj_id = p_oj_id;

    end update_budzet_oj;

    procedure delete_budzet_oj (
        p_budzet_id in number,
        p_oj_id     in number
    ) is
    begin
        delete from budzet_oj_hist
        where
                budzet_id = p_budzet_id
            and oj_id = p_oj_id;

        delete from budzet_oj
        where
                budzet_id = p_budzet_id
            and oj_id = p_oj_id;

    end delete_budzet_oj;

    -- Budzet OJ hist
    procedure insert_budzet_oj_hist (
        p_budzet_id in number,
        p_oj_id     in number,
        p_status_id in number,
        p_radnik_id in number,
        p_komentar  in varchar2,
        p_datum     in date
    ) is
        l_oj_count number;
        l_count    number;
    begin
        update budzet_oj
        set
            status_id = p_status_id
        where
                budzet_id = p_budzet_id
            and oj_id = p_oj_id;

        -- Azuriraj status budzeta ukoliko su sve org jedinice poslale ili odobrene
        if p_status_id in ( 2, 4, 6, 7 ) then
            select
                count(*),
                count(
                    case
                        when status_id = p_status_id then
                            1
                    end
                )
            into
                l_count,
                l_oj_count
            from
                budzet_oj
            where
                budzet_id = p_budzet_id;

            if l_count = l_oj_count then
                insert_budzet_hist(
                    p_budzet_id => p_budzet_id,
                    p_status_id => p_status_id,
                    p_radnik_id => p_radnik_id,
                    p_komentar  => null,
                    p_datum     => sysdate
                );

            end if;

        elsif p_status_id in ( 1 ) then
            select
                count(*),
                count(
                    case
                        when status_id = p_status_id then
                            1
                    end
                )
            into
                l_count,
                l_oj_count
            from
                budzet_oj
            where
                budzet_id = p_budzet_id;

            if l_count != l_oj_count then
                insert_budzet_hist(
                    p_budzet_id => p_budzet_id,
                    p_status_id => p_status_id,
                    p_radnik_id => p_radnik_id,
                    p_komentar  => null,
                    p_datum     => sysdate
                );

            end if;

        end if;

        insert into budzet_oj_hist (
            budzet_id,
            oj_id,
            status_id,
            radnik_id,
            komentar,
            datum
        ) values ( p_budzet_id,
                   p_oj_id,
                   p_status_id,
                   p_radnik_id,
                   p_komentar,
                   p_datum );

    end insert_budzet_oj_hist;

    -- Budzet stavke
    procedure get_budzet_stavka (
        p_budzet_id in number,
        p_stavka_id in number,
        p_period    in varchar2,
        p_id        out number,
        p_oj_id     out number
    ) is
    begin
        for c1 in (
            select
                id,
                oj_id
            from
                budzet_stavke
            where
                    budzet_id = p_budzet_id
                and stavka_id = p_stavka_id
                and to_char(period, 'MM') = p_period
        ) loop
            p_id := c1.id;
            p_oj_id := c1.oj_id;
        end loop;
    end get_budzet_stavka;

    procedure get_budzet_stavka (
        p_id          in number,
        p_budzet_id   out number,
        p_stavka_id   out number,
        p_projekat_id out number,
        p_period      out date,
        p_iznos       out number,
        p_napomena    out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                budzet_stavke
            where
                id = p_id
        ) loop
            p_budzet_id := c1.budzet_id;
            p_stavka_id := c1.stavka_id;
            p_projekat_id := c1.projekat_id;
            p_period := c1.period;
            p_iznos := c1.iznos;
            p_napomena := c1.napomena;
        end loop;
    end get_budzet_stavka;

    procedure insert_budzet_stavka (
        p_budzet_id   in number,
        p_oj_id       in number,
        p_stavka_id   in number,
        p_projekat_id in number,
        p_period      in date,
        p_iznos       in number,
        p_napomena    in varchar2
    ) is
    begin
        insert into budzet_stavke (
            budzet_id,
            oj_id,
            stavka_id,
            projekat_id,
            period,
            iznos,
            napomena
        ) values ( p_budzet_id,
                   p_oj_id,
                   p_stavka_id,
                   p_projekat_id,
                   p_period,
                   p_iznos,
                   p_napomena );

    end insert_budzet_stavka;

    procedure update_budzet_stavka (
        p_id          in number,
        p_budzet_id   in number,
        p_oj_id       in number,
        p_stavka_id   in number,
        p_projekat_id in number,
        p_period      in date,
        p_iznos       in number,
        p_napomena    in varchar2
    ) is
    begin
        update budzet_stavke
        set
            budzet_id = p_budzet_id,
            oj_id = p_oj_id,
            stavka_id = p_stavka_id,
            projekat_id = p_projekat_id,
            period = p_period,
            iznos = p_iznos,
            napomena = p_napomena
        where
            id = p_id;

    end update_budzet_stavka;

    procedure delete_budzet_stavka (
        p_id in number
    ) is
    begin
        delete from budzet_stavke
        where
            id = p_id;

    end delete_budzet_stavka;

    -- Budzet stavka dokument
    procedure insert_budzet_stavka_dokument (
        p_stavka_id in number,
        p_dokument  in varchar2
    ) is

        l_blob     blob;
        l_filename varchar2(255);
        l_mimetype varchar2(255);
        cursor c_dokumenti is
        (
            select
                column_value as dokument
            from
                apex_string.split(p_dokument, ':')
        );

    begin
        for c1 in c_dokumenti loop
            sif.utils_pkg.get_apex_file_upload(
                p_apex_filename => c1.dokument,
                p_blob          => l_blob,
                p_filename      => l_filename,
                p_mimetype      => l_mimetype
            );

            insert into budzet_stavka_dokumenti (
                stavka_id,
                dokument,
                dokument_filename,
                dokument_mimetype,
                dokument_lastupd
            ) values ( p_stavka_id,
                       l_blob,
                       l_filename,
                       l_mimetype,
                       sysdate );

        end loop;
    end insert_budzet_stavka_dokument;

    procedure delete_budzet_stavka_dokument (
        p_id in number
    ) is
    begin
        delete from budzet_stavka_dokumenti
        where
            id = p_id;

    end delete_budzet_stavka_dokument;

    -- Budzet stavka komentari
    procedure insert_budzet_stavka_komentar (
        p_stavka_id in number,
        p_radnik_id in number,
        p_komentar  in varchar2
    ) is
    begin
        insert into budzet_stavka_komentari (
            stavka_id,
            radnik_id,
            komentar,
            datum
        ) values ( p_stavka_id,
                   p_radnik_id,
                   p_komentar,
                   current_date );

    end insert_budzet_stavka_komentar;

    procedure delete_budzet_stavka_komentar (
        p_id in number
    ) is
    begin
        delete from budzet_stavka_komentari
        where
            id = p_id;

    end delete_budzet_stavka_komentar;

    -- Budzet realokacija
    procedure insert_budzet_realokacija (
        p_budzet_id   in number,
        p_stavka_1_id in number,
        p_stavka_2_id in number,
        p_iznos       in number,
        p_napomena    in varchar2
    ) is
        r_stavka budzet_stavke%rowtype;
    begin
        select
            *
        into r_stavka
        from
            budzet_stavke
        where
            id = p_stavka_1_id;

        if ( r_stavka.iznos - r_stavka.iznos_realizacija ) > p_iznos then
            raise_application_error(-20001, 'Ne možete realocirati taj iznos.');
        end if;

        update budzet_stavke
        set
            iznos = iznos - p_iznos
        where
            id = p_stavka_1_id;

        update budzet_stavke
        set
            iznos = iznos + p_iznos
        where
            id = p_stavka_2_id;

        insert into budzet_realokacija (
            budzet_id,
            stavka_1_id,
            stavka_2_id,
            iznos,
            napomena,
            datum
        ) values ( p_budzet_id,
                   p_stavka_1_id,
                   p_stavka_2_id,
                   p_iznos,
                   p_napomena,
                   sysdate );

    end insert_budzet_realokacija;

    -- Rebalans
    procedure zapocni_rebalans_budzeta (
        p_budzet_id in number,
        p_napomena  in varchar2,
        p_radnik_id in number
    ) is

        l_budzet_id number;
        r_budzet    budzeti%rowtype;
        l_status_id number := sif.budzet_pkg.get_status_with_sifra('70');
    begin
        select
            *
        into r_budzet
        from
            budzeti
        where
            id = p_budzet_id;

        l_budzet_id := insert_budzet(
            p_ooj_id      => r_budzet.ooj_id,
            p_interval_id => r_budzet.interval_id,
            p_valuta_id   => r_budzet.valuta_id,
            p_budzet_id   => p_budzet_id,
            p_godina      => r_budzet.godina,
            p_napomena    => p_napomena,
            p_radnik_id   => p_radnik_id
        );

        for c1 in (
            select
                oj_id,
                max_iznos
            from
                budzet_oj
            where
                budzet_id = p_budzet_id
        ) loop
            insert_budzet_oj_hist(
                p_budzet_id => p_budzet_id,
                p_oj_id     => c1.oj_id,
                p_status_id => l_status_id,
                p_radnik_id => p_radnik_id,
                p_komentar  => p_napomena,
                p_datum     => sysdate
            );

            insert_budzet_oj(
                p_budzet_id => l_budzet_id,
                p_oj_id     => c1.oj_id,
                p_max_iznos => c1.max_iznos,
                p_radnik_id => p_radnik_id
            );

        end loop;

        insert into budzet_stavke (
            budzet_id,
            stavka_id,
            projekat_id,
            period,
            iznos,
            iznos_realizacija,
            napomena
        )
            select
                l_budzet_id,
                stavka_id,
                projekat_id,
                period,
                iznos,
                iznos_realizacija,
                napomena
            from
                budzet_stavke
            where
                budzet_id = p_budzet_id;

    end zapocni_rebalans_budzeta;

end budzet_pkg;
/

prompt
prompt Creating package body CSV_PKG
prompt =============================
prompt
create or replace package body accounting.csv_pkg as

    function create_file_name (
        p_type       in number,
        p_ooj_id     in number,
        p_pdv_period in number,
        p_file_no    in number
    ) return varchar2 as
        l_retval varchar2(255);
    begin
        -- Nabavka
        if p_type = 1 then
            select
                ooj_pib
                || '_'
                || p_pdv_period
                || '_'
                || p_type
                || '_'
                || to_char(p_file_no, 'fm00')
            into l_retval
            from
                vw_nabavke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period
                and rownum = 1;

        -- Isporuka
        else
            select
                ooj_pib
                || '_'
                || p_pdv_period
                || '_'
                || p_type
                || '_'
                || to_char(p_file_no, 'fm00')
            into l_retval
            from
                vw_isporuke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period
                and rownum = 1;

        end if;

        return l_retval;
    end create_file_name;

    function create_header_row (
        p_type       in number,
        p_ooj_id     in number,
        p_pdv_period in number,
        p_file_no    in number
    ) return varchar2 as
        l_retval varchar2(32000);
    begin
        -- Nabavke
        if p_type = 1 then
            select
                g_zaglavlje
                || g_separator
                || ooj_pib
                || g_separator
                || poreski_period
                || g_separator
                || to_char(p_type)
                || g_separator
                || to_char(p_file_no, 'fm09')
                || g_separator
                || to_char(sysdate, 'YYYY-MM-DD')
                || g_separator
                || to_char(sysdate, 'HH24:MI:SS')
            into l_retval
            from
                vw_nabavke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period
                and rownum = 1;

        -- Isporuke
        else
            select
                g_zaglavlje
                || g_separator
                || ooj_pib
                || g_separator
                || poreski_period
                || g_separator
                || to_char(p_type)
                || g_separator
                || to_char(p_file_no, 'fm09')
                || g_separator
                || to_char(sysdate, 'YYYY-MM-DD')
                || g_separator
                || to_char(sysdate, 'HH24:MI:SS')
            into l_retval
            from
                vw_isporuke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period
                and rownum = 1;

        end if;

        l_retval := g_encloser
                    || l_retval
                    || g_encloser;
        return l_retval;
    end create_header_row;

    function get_parts_no (
        p_type       in number,
        p_ooj_id     in number,
        p_pdv_period in number
    ) return number as
        l_retval number;
        l_clob   clob;
        l_red    varchar2(32000);
        l_size   number;
    begin
        -- Nabavke
        if p_type = 1 then
            for x in (
                select
                    *
                from
                    vw_nabavke
                where
                        ooj_id = p_ooj_id
                    and poreski_period = p_pdv_period
            ) loop
                l_red := g_encloser
                         || g_sadrzaj
                         || g_separator
                         || x.poreski_period
                         || g_separator
                         || x.redni_br
                         || g_separator
                         || x.tip_dokumenta
                         || g_separator
                         || x.broj_fakture
                         || g_separator
                         || x.datum_fakture
                         || g_separator
                         || x.mjesec_fakture
                         || g_separator
                         || x.datum_prijema_fakture
                         || g_separator
                         || x.mjesec_prijema_fakture
                         || g_separator
                         || x.naziv_dobavljaca
                         || g_separator
                         || x.sjediste_dobavljaca
                         || g_separator
                         || x.pdv_broj_dobavljaca
                         || g_separator
                         || x.jib_broj_dobavljaca
                         || g_separator
                         || x.iznos_fakture_bezpdv
                         || g_separator
                         || x.iznos_fakture_sapdv
                         || g_separator
                         || x.iznos_pausal
                         || g_separator
                         || x.iznos_ulaznog_pdv
                         || g_separator
                         || x.iznos_ulazpdv_odbiti
                         || g_separator
                         || x.iznos_ulazpdv_neodbiti
                         || g_separator
                         || x.iznos_pdv_32polje
                         || g_separator
                         || x.iznos_pdv_33polje
                         || g_separator
                         || x.iznos_pdv_34polje
                         || g_encloser
                         || chr(13);

                l_clob := l_clob || l_red;
            end loop;

            l_size := ceil(dbms_lob.getlength(l_clob) / 1024 / 1024);  -- size in MB, 

        -- Isporuke
        else
            for x in (
                select
                    *
                from
                    vw_isporuke
                where
                        ooj_id = p_ooj_id
                    and poreski_period = p_pdv_period
            ) loop
                l_red := g_encloser
                         || g_sadrzaj
                         || g_separator
                         || x.poreski_period
                         || g_separator
                         || x.redni_br
                         || g_separator
                         || x.tip_dokumenta
                         || g_separator
                         || x.broj_fakture
                         || g_separator
                         || x.datum_fakture
                         || g_separator
                         || x.naziv_kupca
                         || g_separator
                         || x.sjediste_kupca
                         || g_separator
                         || x.pdv_broj_kupca
                         || g_separator
                         || x.jib_broj_kupca
                         || g_separator
                         || x.iznos_fakture
                         || g_separator
                         || x.iznos_fakture_interne
                         || g_separator
                         || x.iznos_fakture_izvozne
                         || g_separator
                         || x.iznos_ostale_bez_pdv
                         || g_separator
                         || x.iznos_osnovice_za_pdv
                         || g_separator
                         || x.iznos_izlaz_pdv_za_pdv
                         || g_separator
                         || x.iznos_osnovice_za_nepdv
                         || g_separator
                         || x.iznos_izlaz_pdv_za_nepdv
                         || g_separator
                         || x.iznos_pdv_32polje
                         || g_separator
                         || x.iznos_pdv_33polje
                         || g_separator
                         || x.iznos_pdv_34polje
                         || g_encloser
                         || chr(13);

                l_clob := l_clob || l_red;
            end loop;

            l_size := ceil(dbms_lob.getlength(l_clob) / 1024 / 1024);  -- size in MB, 

            dbms_output.put_line('velicina u MB je: ' || l_size);
        end if;

        l_retval := ceil(l_size / 5);
        return l_retval;
    end get_parts_no;

    function get_content (
        p_type       in number,
        p_ooj_id     in number,
        p_pdv_period in number,
        p_which      in number,
        p_total      in number
    ) return clob as

        l_pocetak number;
        l_kraj    number;
        l_slogova number;
        l_clob    clob;
        l_red     varchar2(32000);
        l_header  varchar2(2000);
        l_footer  varchar2(2000);
        l_part    number;
    begin
        -- Nabavke
        if p_type = 1 then
            select
                max(internal_no),
                ( p_which - 1 ) * ( ceil(max(internal_no) / p_total) ) + 1,
                p_which * ( ceil(max(internal_no) / p_total) )
            into
                l_slogova,
                l_pocetak,
                l_kraj
            from
                vw_nabavke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period;

            if l_kraj > l_slogova then
                l_kraj := l_slogova;
            end if;
            dbms_output.put_line(l_pocetak
                                 || '-'
                                 || l_kraj
                                 || ' od '
                                 || l_slogova);

            for x in (
                select
                    *
                from
                    vw_nabavke
                where
                        ooj_id = p_ooj_id
                    and poreski_period = p_pdv_period
                    and internal_no between l_pocetak and l_kraj
            ) loop
                l_red := g_encloser
                         || g_sadrzaj
                         || g_separator
                         || x.poreski_period
                         || g_separator
                         || x.redni_br
                         || g_separator
                         || x.tip_dokumenta
                         || g_separator
                         || x.broj_fakture
                         || g_separator
                         || x.datum_fakture
                         || g_separator
                         || x.datum_prijema_fakture
                         || g_separator
                         || x.naziv_dobavljaca
                         || g_separator
                         || x.sjediste_dobavljaca
                         || g_separator
                         || x.pdv_broj_dobavljaca
                         || g_separator
                         || x.jib_broj_dobavljaca
                         || g_separator
                         || to_char(x.iznos_fakture_bezpdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_fakture_sapdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_pausal, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_ulaznog_pdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_ulazpdv_odbiti, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_ulazpdv_neodbiti, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_pdv_32polje, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_pdv_33polje, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_pdv_34polje, 'fm9999999990.00')
                         || g_encloser
                         || chr(13);

                l_clob := l_clob || l_red;
            end loop;

            l_header := create_header_row(p_type, p_ooj_id, p_pdv_period, p_which);  

            -- Footer

            l_part := ( l_kraj - l_pocetak ) + 1;
            select
                g_encloser
                || g_footer
                || g_separator
                || to_char(
                    round(
                        sum(iznos_fakture_bezpdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_fakture_sapdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_pausal),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_ulaznog_pdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_ulazpdv_odbiti),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_ulazpdv_neodbiti),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_pdv_32polje),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_pdv_33polje),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_pdv_34polje),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || l_part
                || g_encloser
            into l_footer
            from
                vw_nabavke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period
                and internal_no between l_pocetak and l_kraj;

            l_clob := l_header
                      || chr(13)
                      || l_clob
                      || l_footer;
        -- Isporuke
        else
            select
                max(internal_no),
                ( p_which - 1 ) * ( ceil(max(internal_no) / p_total) ) + 1,
                p_which * ( ceil(max(internal_no) / p_total) )
            into
                l_slogova,
                l_pocetak,
                l_kraj
            from
                vw_isporuke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period;

            if l_kraj > l_slogova then
                l_kraj := l_slogova;
            end if;
            dbms_output.put_line(l_pocetak
                                 || '-'
                                 || l_kraj
                                 || ' od '
                                 || l_slogova);

            for x in (
                select
                    *
                from
                    vw_isporuke
                where
                        ooj_id = p_ooj_id
                    and poreski_period = p_pdv_period
                    and internal_no between l_pocetak and l_kraj
            ) loop
                l_red := g_encloser
                         || g_sadrzaj
                         || g_separator
                         || x.poreski_period
                         || g_separator
                         || x.redni_br
                         || g_separator
                         || x.tip_dokumenta
                         || g_separator
                         || x.broj_fakture
                         || g_separator
                         || x.datum_fakture
                         || g_separator
                         || x.naziv_kupca
                         || g_separator
                         || x.sjediste_kupca
                         || g_separator
                         || x.pdv_broj_kupca
                         || g_separator
                         || x.jib_broj_kupca
                         || g_separator
                         || to_char(x.iznos_fakture, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_fakture_interne, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_fakture_izvozne, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_ostale_bez_pdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_osnovice_za_pdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_izlaz_pdv_za_pdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_osnovice_za_nepdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_izlaz_pdv_za_nepdv, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_pdv_32polje, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_pdv_33polje, 'fm9999999990.00')
                         || g_separator
                         || to_char(x.iznos_pdv_34polje, 'fm9999999990.00')
                         || g_encloser
                         || chr(13);

                l_clob := l_clob || l_red;
            end loop;

            l_header := create_header_row(p_type, p_ooj_id, p_pdv_period, p_which);  

            -- FOOTER

            l_part := ( l_kraj - l_pocetak ) + 1;
            select
                g_encloser
                || g_footer
                || g_separator
                || to_char(
                    round(
                        sum(iznos_fakture),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_fakture_interne),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_fakture_izvozne),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_ostale_bez_pdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_osnovice_za_pdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_izlaz_pdv_za_pdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_osnovice_za_nepdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_izlaz_pdv_za_nepdv),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_pdv_32polje),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_pdv_33polje),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || to_char(
                    round(
                        sum(iznos_pdv_34polje),
                        2
                    ),
                    'fm9999999990.00'
                )
                || g_separator
                || l_part
                || g_encloser
            into l_footer
            from
                vw_isporuke
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_pdv_period
                and internal_no between l_pocetak and l_kraj;

            l_clob := l_header
                      || chr(13)
                      || l_clob
                      || l_footer;
        end if;

        return l_clob;
    exception
        when others then
            raise;
    end get_content;

    procedure create_csv (
        p_type           in number,
        p_ooj_id         in number,
        p_pdv_period     in number,
        p_download_token in varchar2
    ) is
        l_total_parts number;
    begin
        l_total_parts := get_parts_no(p_type, p_ooj_id, p_pdv_period);
        if coalesce(l_total_parts, 0) = 0 then
            raise_application_error(-20001, 'Nemate unešenih podataka. Ne možete generisati CSV.');
        elsif l_total_parts = 1 then
            create_single_csv(
                p_type           => p_type,
                p_ooj_id         => p_ooj_id,
                p_pdv_period     => p_pdv_period,
                p_download_token => p_download_token
            );
        else
            create_zipped_csv(
                p_type           => p_type,
                p_ooj_id         => p_ooj_id,
                p_pdv_period     => p_pdv_period,
                p_download_token => p_download_token
            );
        end if;

    end create_csv;

    procedure create_single_csv (
        p_type           in number,
        p_ooj_id         in number,
        p_pdv_period     in number,
        p_download_token in varchar2
    ) is
        l_clob     clob;
        l_filename varchar2(255);
--        l_export       apex_data_export.t_export;
        l_blob     blob;
    begin
        l_clob := get_content(p_type, p_ooj_id, p_pdv_period, 1, 1);
        l_filename := create_file_name(p_type, p_ooj_id, p_pdv_period, 1);
        l_filename := l_filename || '.csv';

--        l_export := apex_data_export.t_export (
--            file_name    => l_filename, 
--            format       => apex_data_export.c_format_csv,
--            mime_type    => 'text/csv', 
--            as_clob      => true,
--            content_clob => l_clob
--        );

--        apex_data_export.download (
--            p_export => l_export
--        );

        l_blob := apex_util.clob_to_blob(p_clob => l_clob);

        -- Send headers (cookie first!), then the file
        owa_util.mime_header('text/csv', false);
        htp.p('Set-Cookie: '
              || 'fileDownload_'
              || p_download_token
              || '=ok; Max-Age=300; Path=/; SameSite=Lax');
        htp.p('Content-Disposition: attachment; filename="'
              || l_filename
              || '"');
        htp.p('Content-Length: ' || dbms_lob.getlength(l_blob));
        owa_util.http_header_close;
        wpg_docload.download_file(l_blob);
        apex_application.stop_apex_engine;
    exception
        when others then
                -- If we can, signal an error cookie so the overlay closes with a message
            begin
                owa_util.mime_header('text/plain', false);
                htp.p('Set-Cookie: '
                      || 'fileDownload_'
                      || coalesce(p_download_token, 'x')
                      || '=error; Max-Age=300; Path=/; SameSite=Lax');

                htp.p('Cache-Control: no-store');
                owa_util.http_header_close;
                htp.prn('Failed to generate the XLS demo.');
            exception
                when others then
                    null;
            end;

            apex_application.stop_apex_engine;
    end create_single_csv;

    procedure create_zipped_csv (
        p_type           in number,
        p_ooj_id         in number,
        p_pdv_period     in number,
        p_download_token in varchar2
    ) is

        l_total_parts  number;
        l_clob         clob;
        l_blob         blob;
        l_filename     varchar2(255);
        l_zip_blob     blob;
        l_zip_filename varchar2(255);
    begin
        l_total_parts := get_parts_no(p_type, p_ooj_id, p_pdv_period);
        dbms_output.put_line('test' || l_total_parts);
        for x in 1..l_total_parts loop
            l_clob := get_content(p_type, p_ooj_id, p_pdv_period, x, l_total_parts);
            l_filename := create_file_name(p_type, p_ooj_id, p_pdv_period, x);
            l_filename := l_filename || '.csv';
            l_blob := apex_util.clob_to_blob(p_clob => l_clob);
            apex_zip.add_file(
                p_zipped_blob => l_zip_blob,
                p_file_name   => l_filename,
                p_content     => l_blob
            );

        end loop;

        l_zip_filename := 'UIO_'
                          || to_char(p_pdv_period)
                          || '_'
                          || p_type
                          || '.zip';

        apex_zip.finish(p_zipped_blob => l_zip_blob);

        -- Send headers (cookie first!), then the file
        owa_util.mime_header('application/zipsheet', false);
        htp.p('Set-Cookie: '
              || 'fileDownload_'
              || p_download_token
              || '=ok; Max-Age=300; Path=/; SameSite=Lax');
        htp.p('Content-Disposition: attachment; filename="'
              || l_zip_filename
              || '"');
        htp.p('Content-Length: ' || dbms_lob.getlength(l_zip_blob));
        owa_util.http_header_close;
        wpg_docload.download_file(l_zip_blob);
        apex_application.stop_apex_engine;
    exception
        when others then
                -- If we can, signal an error cookie so the overlay closes with a message
            begin
                owa_util.mime_header('text/plain', false);
                htp.p('Set-Cookie: '
                      || 'fileDownload_'
                      || coalesce(p_download_token, 'x')
                      || '=error; Max-Age=300; Path=/; SameSite=Lax');

                htp.p('Cache-Control: no-store');
                owa_util.http_header_close;
                htp.prn('Failed to generate the XLS demo.');
            exception
                when others then
                    null;
            end;

            apex_application.stop_apex_engine;
    end create_zipped_csv;

end csv_pkg;
/

prompt
prompt Creating package body FINANSIJE_PKG
prompt ===================================
prompt
create or replace package body accounting.finansije_pkg is

    g_predracun_sifra constant varchar2(16) := 'pr';
    g_kif_sifra       constant varchar2(16) := 'if';

    --------------------------------------------------------------
    -- procedures for table KIF
    --------------------------------------------------------------
    
     procedure get_pdv_indikator (
        p_id               in number,
        p_pdv_indikator_id     out number

    ) is
    begin
        for i in (select k.pdv_indikator_id from kif k where k.id=p_id)
        loop
          
            p_pdv_indikator_id:=i.pdv_indikator_id;
          
        end loop;
            
    end;

    
    

    procedure get_kif_indikator_uio (
        p_ooj_id               in number,
        p_klijent_id           in number,
        p_vrsta_fakture_id     in number,
        p_pdv_indikator_id     out number,
        p_uio_tip_dokumenta_id out number
    ) is

        l_tip_klijenta_sifra varchar2(16);
        l_pdv_obaveznik      varchar2(1);
        l_entitet_sifra      varchar2(16);
        l_ino_drzava         varchar2(1);
        l_vrsta_naloga_sifra varchar2(64);
        l_pdv_indikator      varchar2(2);
        l_uio_tip_dokumenta  varchar2(2);
        l_ooj_pdv_sistem     varchar2(1);
    begin
        select
            pdv_sistem
        into l_ooj_pdv_sistem
        from
            core.ooj
        where
            id = p_ooj_id;

        sec_pkg.get_klijent(
            p_id                 => p_klijent_id,
            p_tip_klijenta_sifra => l_tip_klijenta_sifra,
            p_pdv_obaveznik      => l_pdv_obaveznik,
            p_entitet_sifra      => l_entitet_sifra,
            p_ino_drzava         => l_ino_drzava
        );

        ---prelazak na vrstu dokumenata
        --djordjije 21.09.2028--
        
        /*sif.acc_pkg.get_vrsta_fakture(
            p_id                 => p_vrsta_fakture_id,
            p_vrsta_naloga_sifra => l_vrsta_naloga_sifra
        );*/
        
        l_vrsta_naloga_sifra:=sif.acc_pkg.get_vd_sifra(p_id  => p_vrsta_fakture_id);
        
        ----
        case
            when l_vrsta_naloga_sifra = 'av' then
                l_uio_tip_dokumenta := '03';
                if
                    l_ino_drzava = 'Y'
                    and l_pdv_obaveznik = 'Y'
                then
                    l_pdv_indikator := null;
                    l_uio_tip_dokumenta := null;
                elsif
                    l_ino_drzava = 'Y'
                    and l_pdv_obaveznik = 'N'
                then
                    l_pdv_indikator := 'B4';
                elsif l_pdv_obaveznik = 'Y' then
                    l_pdv_indikator := 'A7';
                else
                    case
                        when l_entitet_sifra = 'rs' then
                            l_pdv_indikator := 'B4';
                        when l_entitet_sifra = 'fbih' then
                            l_pdv_indikator := 'B5';
                        when l_entitet_sifra = 'brd' then
                            l_pdv_indikator := 'B6';
                    end case;
                end if;

            when l_vrsta_naloga_sifra = 'ko' then
                l_uio_tip_dokumenta := '01';
                if
                    l_ino_drzava = 'Y'
                    and l_pdv_obaveznik = 'Y'
                then
                    l_pdv_indikator := 'I1';
                    l_uio_tip_dokumenta := '04';
                elsif
                    l_ino_drzava = 'Y'
                    and l_pdv_obaveznik = 'N'
                then
                    l_pdv_indikator := 'I1';
                    l_uio_tip_dokumenta := '04';
                elsif l_pdv_obaveznik = 'Y' then
                    l_pdv_indikator := 'O6';
                else
                    case
                        when l_entitet_sifra = 'rs' then
                            l_pdv_indikator := 'B1';
                        when l_entitet_sifra = 'fbih' then
                            l_pdv_indikator := 'B2';
                        when l_entitet_sifra = 'brd' then
                            l_pdv_indikator := 'B3';
                    end case;
                end if;

            when l_vrsta_naloga_sifra in ( 'pr', 'if', 'kz' ) then
                l_uio_tip_dokumenta := '01';
                if l_ino_drzava = 'Y' and l_pdv_obaveznik = 'Y' then
                    l_pdv_indikator := 'I1';
                    l_uio_tip_dokumenta := '04';
                elsif l_ino_drzava = 'Y' and l_pdv_obaveznik = 'N' then
                    l_pdv_indikator := 'I1';
                    l_uio_tip_dokumenta := '04';
                elsif l_pdv_obaveznik = 'Y' then l_pdv_indikator := 'A1';
                else
                    case
                        when l_entitet_sifra = 'rs' then
                            l_pdv_indikator := 'B1';
                        when l_entitet_sifra = 'fbih' then
                            l_pdv_indikator := 'B2';
                        when l_entitet_sifra = 'brd' then
                            l_pdv_indikator := 'B3';
                    end case;
                end if;

            when l_vrsta_naloga_sifra in ( 'in' ) then
                l_uio_tip_dokumenta := '02';
                l_pdv_indikator := 'A2';
        end case;

        if l_ooj_pdv_sistem = 'N' then
            l_uio_tip_dokumenta := null;
            l_pdv_indikator := 'XI';
        end if;
        p_uio_tip_dokumenta_id := sif.acc_pkg.get_uio_tip_dokumenta_id(
            p_ui   => 'I',
            p_code => l_uio_tip_dokumenta
        );

        p_pdv_indikator_id := sif.acc_pkg.get_pdv_indikator_id(
            p_ui    => 'I',
            p_sifra => l_pdv_indikator
        );

    end get_kif_indikator_uio;

    procedure get_kif_pdv (
        p_ooj_id     in number,
        p_klijent_id in number,
        p_pdv        out number
    ) is

        l_tip_klijenta_sifra varchar2(16);
        l_pdv_obaveznik      varchar2(1);
        l_entitet_sifra      varchar2(16);
        l_ino_drzava         varchar2(1);
        l_ooj_pdv_sistem     varchar2(1);
    begin
        select
            pdv_sistem
        into l_ooj_pdv_sistem
        from
            core.ooj
        where
            id = p_ooj_id;

        sec_pkg.get_klijent(
            p_id                 => p_klijent_id,
            p_tip_klijenta_sifra => l_tip_klijenta_sifra,
            p_pdv_obaveznik      => l_pdv_obaveznik,
            p_entitet_sifra      => l_entitet_sifra,
            p_ino_drzava         => l_ino_drzava
        );

        if l_ino_drzava = 'Y'
        or l_pdv_obaveznik = 'N'
        or l_ooj_pdv_sistem = 'N' then
            p_pdv := 0;
        else
            p_pdv := 17;
        end if;

    end get_kif_pdv;

    function create_kif_from_predracun (
        p_godina        in number,
        p_predracun_id  in number,
        p_datum_fakture in date,
        p_datum_valute  in date,
        p_print_pn      in varchar2,
        p_ugovor_id     in number default null
    ) return number is

        l_faktura_id      number;
        l_faktura_naziv   varchar2(255);
        l_faktura_broj    number;
        l_vrsta_naloga_id number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga(g_predracun_sifra);
        l_ugovor_id       number;
        cursor c_predracun_stavke is
        (
            select
                id,
                stavka_id,
                jm_id,
                kolicina,
                cijena,
                rabat,
                pdv,
                iznos,
                pdv_indikator_id
            from
                kif_stavke
            where
                kif_id = p_predracun_id
        );

        r_predracun       kif%rowtype;
    begin
        select
            *
        into r_predracun
        from
            kif
        where
            id = p_predracun_id;

        core.protokoli_pkg.get_brojac(
            p_ooj_id             => r_predracun.ooj_id,
            p_vrsta_naloga_sifra => g_kif_sifra,
            p_godina             => p_godina,
            p_broj               => r_predracun.faktura_broj,
            p_naziv              => r_predracun.naziv_fakture
        );

        if p_ugovor_id is not null then
            l_ugovor_id := p_ugovor_id;
        else
            l_ugovor_id := r_predracun.ugovor_id;
        end if;

        l_faktura_id := insert_kif(
            p_glavna_knjiga_id     => null,
            p_klijent_id           => r_predracun.klijent_id,
            p_valuta_id            => r_predracun.valuta_id,
            p_valuta_iznos         => r_predracun.valuta_iznos,
            p_valuta_iznos_pdv     => r_predracun.valuta_iznos_pdv,
            p_ooj_id               => r_predracun.ooj_id,
            p_predracun_id         => p_predracun_id,
            p_faktura_broj         => r_predracun.faktura_broj,
            p_naziv_fakture        => r_predracun.naziv_fakture,
            p_godina               => p_godina,
            p_datum_uplatnice      => null,
            p_iznos_fakture        => r_predracun.iznos_fakture,
            p_iznos_slovima        => r_predracun.iznos_slovima,
            p_datum_valute         => p_datum_valute,
            p_iznos_fakture_nopdv  => r_predracun.iznos_fakture_nopdv,
            p_uplaceno             => 'Y',
            p_posebne_napomene     => r_predracun.posebne_napomene,
            p_datum_fakture        => p_datum_fakture,
            p_print_pn             => p_print_pn,
            p_tip_placanja_id      => r_predracun.tip_placanja_id,
            p_uio_tip_dokumenta_id => r_predracun.uio_tip_dokumenta_id,
            p_system               => r_predracun.system,
            p_vrsta_fakture_id     => l_vrsta_naloga_id,
            p_faktura_id           => r_predracun.faktura_id,
            p_tip_cijene           => r_predracun.tip_cijene,
            p_dani_dospijeca       => r_predracun.dani_dospijeca,
            p_ugovor_id            => l_ugovor_id,
            p_oj_id                => r_predracun.oj_id,
            p_skladiste_id         => r_predracun.skladiste_id,
            p_pdv_indikator_id     => r_predracun.pdv_indikator_id
        );

        for stavka in c_predracun_stavke loop
            insert_kif_stavka(
                p_kif_id           => l_faktura_id,
                p_stavka_id        => stavka.stavka_id,
                p_jm_id            => stavka.jm_id,
                p_kolicina         => stavka.kolicina,
                p_cijena           => stavka.cijena,
                p_rabat            => stavka.rabat,
                p_pdv              => stavka.pdv,
                p_iznos            => stavka.iznos,
                p_pdv_indikator_id => stavka.pdv_indikator_id
            );
        end loop;

        update kif
        set
            uplaceno = 'Y'
        where
            id = p_predracun_id;

        core.protokoli_pkg.update_brojac(
            p_ooj_id             => r_predracun.ooj_id,
            p_vrsta_naloga_sifra => g_kif_sifra,
            p_godina             => p_godina,
            p_value              => 1
        );
        
--        if l_vrsta_naloga_id = 1 then
--            skladista_pkg.insert_kif (
--                p_ooj_id => r_predracun.ooj_id,
--                p_godina => r_predracun.godina,
--                p_kif_id => l_faktura_id
--            );
--        end if;

        return l_faktura_id;
    end create_kif_from_predracun;

    procedure get_kif (
        p_id         in number,
        p_klijent_id out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                kif
            where
                id = p_id
        ) loop
            p_klijent_id := c1.klijent_id;
        end loop;
    end get_kif;

    -- Za azuriranje KIF-a
    procedure get_kif (
        p_id                   in number,
        p_naziv_fakture        out varchar2,
        p_klijent_id           out number,
        p_valuta_id            out number,
        p_tip_placanja_id      out number,
        p_datum_fakture        out date,
        p_datum_valute         out date,
        p_iznos_fakture_nopdv  out number,
        p_iznos_fakture        out number,
        p_valuta_iznos         out number,
        p_iznos_slovima        out varchar2,
        p_print_pn             out varchar2,
        p_posebne_napomene     out varchar2,
        p_uio_tip_dokumenta_id out number,
        p_ugovor_id            out number,
        p_oj_id                out number, 
        p_status               out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                kif
            where
                id = p_id
        ) loop
            p_naziv_fakture := c1.naziv_fakture;
            p_klijent_id := c1.klijent_id;
            p_valuta_id := c1.valuta_id;
            p_tip_placanja_id := c1.tip_placanja_id;
            p_datum_fakture := c1.datum_fakture;
            p_datum_valute := c1.datum_valute;
            p_iznos_fakture_nopdv := c1.iznos_fakture_nopdv;
            p_iznos_fakture := c1.iznos_fakture;
            p_valuta_iznos := c1.valuta_iznos;
            p_iznos_slovima := c1.iznos_slovima;
            p_print_pn := c1.print_pn;
            p_posebne_napomene := c1.posebne_napomene;
            p_uio_tip_dokumenta_id := c1.uio_tip_dokumenta_id;
            p_ugovor_id := c1.ugovor_id;
            p_oj_id := c1.oj_id;
            p_status := c1.status;
        end loop;
    end get_kif;

