    procedure update_kif (
        p_id                   in number,
        p_klijent_id           in number,
        p_valuta_id            in number,
        p_tip_placanja_id      in number,
        p_datum_fakture        in date,
        p_datum_valute         in date,
        p_iznos_slovima        in varchar2,
        p_print_pn             in varchar2,
