            print_pn = p_print_pn,
            posebne_napomene = p_posebne_napomene,
            uio_tip_dokumenta_id = p_uio_tip_dokumenta_id,
            oj_id = p_oj_id
        where
            id = p_id;

    end update_kif;
    --STORNIRANJE KIF-a
    --djordjije dorada za uvezane avanse  --26.10.2026---
    function storniraj_kif (
    p_id    in number,
    p_datum in date
) return number is
    cursor c_stavke is
    (
        select
            stavka_id,
            kolicina,
            cijena,
            rabat,
            pdv,
            iznos,
            jm_id,
            pdv_indikator_id
        from
            accounting.kif_stavke
        where
            kif_id = p_id
    )
    order by id asc;

    l_id         number;
    r_kif        kif%rowtype;
    l_broj       number;
    l_naziv      varchar2(255);
    l_sifra      varchar2(64);
    l_status_id  number;
    l_avz_id     number;
    l_a_id       number;
begin
    -- 1. Učitavanje originalne fakture
    select *
    into r_kif
    from kif
    where id = p_id;

    -- 2. Provjera da li je faktura vec stornirana
    if r_kif.stornirano = 'Y' then
        raise_application_error(-20001, 'Faktura je već stornirana.');
    end if;

    -- 3. Uzimanje sifre vrste naloga + dodaj 's' za storno (npr. 'if' -> 'ifs')
    select vrsta_naloga_sifra-- || 's'
    into l_sifra
    from vw_kif
    where id = p_id;

    -- 4. Sledeci broj za fakturu storno
    core.protokoli_pkg.get_brojac(
        p_ooj_id             => r_kif.ooj_id,
        p_vrsta_naloga_sifra => l_sifra,
        p_godina             => r_kif.godina,
        p_broj               => l_broj,
        p_naziv              => l_naziv
    );

    -- 5. Priprema novog reda — kopija originala s negativnim iznosima
    r_kif.id                 := null;        
    r_kif.glavna_knjiga_id   := null;         
    r_kif.valuta_iznos       := (r_kif.valuta_iznos       * -1);
    r_kif.valuta_iznos_pdv   := (r_kif.valuta_iznos_pdv   * -1);
    r_kif.iznos_fakture      := (r_kif.iznos_fakture      * -1);
    r_kif.iznos_fakture_nopdv := (r_kif.iznos_fakture_nopdv * -1);
    r_kif.datum_fakture      := p_datum;
    r_kif.datum_valute       := add_months(p_datum, 1);
    r_kif.faktura_broj       := l_broj;
    r_kif.naziv_fakture      := l_naziv;
    r_kif.stornirano         := 'Y';          
    r_kif.storniran_id       := p_id;         
    r_kif.radni_nalog_id     := null;         --Storno faktura nema vezu sa radnim nalogom

    -- 6. Insert novog storno kifa
    insert into kif values r_kif returning id into l_id;

    -- 7. Kopiranje stavki s negativnim iznosima i kolicinama
    for stavka in c_stavke loop
        insert_kif_stavka(
            p_kif_id           => l_id,
            p_stavka_id        => stavka.stavka_id,
            p_jm_id            => stavka.jm_id,
            p_kolicina         => stavka.kolicina * -1,
            p_cijena           => stavka.cijena,
            p_rabat            => stavka.rabat,
            p_pdv              => stavka.pdv,
            p_iznos            => stavka.iznos * -1,
            p_pdv_indikator_id => stavka.pdv_indikator_id
        );
    end loop;

    -- 8. Ažuriranje brojača za storno vrstu naloga
    core.protokoli_pkg.update_brojac(
        p_ooj_id             => r_kif.ooj_id,
        p_vrsta_naloga_sifra => l_sifra,
        p_godina             => r_kif.godina,
        p_value              => 1
    );

    -- 9. Originalna faktura označena kao stornirana
    update kif
    set
        stornirano = 'Y'
    where id = p_id;

    -- 10. Vraćanje radnog naloga na status Zakljucen (nefakturisano)
    if r_kif.radni_nalog_id is not null then
        select id
        into l_status_id
        from sif.cs_statusi
        where sifra = 'ZAKLJUCEN' 
          and valid = 'Y';

        update radni_nalozi
        set status_id = l_status_id
        where id = r_kif.radni_nalog_id;
    end if;
    
    -- 11
    -----vraćanje avansnog zatvaranja ukoliko postoji-----
    for avz in (select * from kif_avansi_zatvaranje ka where ka.faktura_id=p_id)
    loop
      
              select *
              into r_kif
              from kif
              where id = avz.avans_zatvaranja_id;
            
              select vrsta_naloga_sifra-- || 's'
              into l_sifra
              from vw_kif
              where id = avz.avans_zatvaranja_id;

              -- 11.1. Podaci za fakturu zatavranja storno
              core.protokoli_pkg.get_brojac(
                  p_ooj_id             => r_kif.ooj_id,
                  p_vrsta_naloga_sifra => l_sifra,
                  p_godina             => r_kif.godina,
                  p_broj               => l_broj,
                  p_naziv              => l_naziv
              );
              
                r_kif.id                 := null;        
                r_kif.glavna_knjiga_id   := null;         
                r_kif.valuta_iznos       := (r_kif.valuta_iznos       * -1);
                r_kif.valuta_iznos_pdv   := (r_kif.valuta_iznos_pdv   * -1);
                r_kif.iznos_fakture      := (r_kif.iznos_fakture      * -1);
                r_kif.iznos_fakture_nopdv := (r_kif.iznos_fakture_nopdv * -1);
                r_kif.datum_fakture      := p_datum;
                r_kif.datum_valute       := p_datum;
                r_kif.faktura_broj       := l_broj;
                r_kif.naziv_fakture      := l_naziv;
                r_kif.stornirano         := 'Y';          
                r_kif.storniran_id       := avz.avans_zatvaranja_id;         
                r_kif.radni_nalog_id     := null;         --Storno avansa nema vezu sa radnim nalogom

                -- 11.2. Insert novog storno  kifa avansnog zatvaranja
                insert into kif values r_kif returning id into l_a_id;

                -- 11.3. Kopiranje stavki s negativnim iznosima i kolicinama
              for av_stavke in (select * from kif_stavke ks where ks.kif_id=avz.avans_zatvaranja_id)
              loop
                    insert_kif_stavka(
                        p_kif_id           => l_a_id,
                        p_stavka_id        => av_stavke.stavka_id,
                        p_jm_id            => av_stavke.jm_id,
                        p_kolicina         => av_stavke.kolicina * -1,
                        p_cijena           => av_stavke.cijena,
                        p_rabat            => av_stavke.rabat,
                        p_pdv              => av_stavke.pdv,
                        p_iznos            => av_stavke.iznos * -1,
                        p_pdv_indikator_id => av_stavke.pdv_indikator_id
                    );
                end loop;

                -- 11.4 Ažuriranje brojača za storno  kifa avansnog zatvaranja
                core.protokoli_pkg.update_brojac(
                    p_ooj_id             => r_kif.ooj_id,
                    p_vrsta_naloga_sifra => l_sifra,
                    p_godina             => r_kif.godina,
                    p_value              => 1
                );

                -- 11.5 Originalni avans zatavaranja označena kao stornirana
                
                update kif
                set
                    stornirano = 'Y', 
                    storniran_id=l_a_id
                where id = avz.avans_zatvaranja_id;
                
                
                ------vaze kif-avans-----

                finansije_pkg.insert_kif_avansi_zatvaranje (
                      p_ooj_id            =>  r_kif.ooj_id,
                      p_avans_id          =>  avz.avans_id,
                      p_faktura_id        =>  l_id,
                      p_avans_zatvaranja_id  => l_a_id,
                      p_datum_zatvaranja  =>  p_datum,
                      p_iznos             =>  -avz.iznos,
                      p_napomena          =>  l_naziv,
                      p_id                =>  l_avz_id
                );

      
    end loop;
    
    
    ------------------------------------------------------

    return l_id;

end storniraj_kif;
--GET procedura za kreiranje fakture iz predracuna
procedure get_kif (
        p_id            in number,
        p_naziv_fakture out varchar2,
        p_datum_fakture out date,
        p_datum_valute  out date
    ) is
    begin
        for c1 in (
            select
                naziv_fakture,
                datum_fakture,
                datum_valute

            from
                kif
            where
                id = p_id
        ) loop
            p_naziv_fakture := c1.naziv_fakture;
            p_datum_fakture := c1.datum_fakture;
            p_datum_valute := c1.datum_valute;

        end loop;
    end get_kif;
     --CREATE funkcija za kreiranje fakture iz predracuna
    function create_kif_from_predracun_car_service (
        p_predracun_id  in number,
        p_godina        in number,
        p_datum_fakture in date,
        p_datum_valute  in date,
        p_print_pn      in varchar2
    ) return number is

        l_faktura_id      number;
        l_faktura_broj    number;
        l_faktura_naziv   varchar2(255);
        l_vrsta_naloga_id number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga(g_predracun_sifra);
        r_predracun       kif%rowtype;
        cursor c_predracun_stavke is
        (
            select
                id,
                stavka_id,
                jm_id,
                kolicina,
                cijena,
                rabat,
                pdv,
                iznos,
                pdv_indikator_id
            from
                kif_stavke
            where
                kif_id = p_predracun_id
        );

    begin
    -- Uzmi predračun
        select
            *
        into r_predracun
        from
            kif
        where
            id = p_predracun_id;


    -- Uzmi broj i naziv fakture
        core.protokoli_pkg.get_brojac(
            p_ooj_id             => r_predracun.ooj_id,
            p_vrsta_naloga_sifra => g_kif_sifra,
            p_godina             => p_godina,
            p_broj               => r_predracun.faktura_broj,
            p_naziv              => r_predracun.naziv_fakture
        );

    -- Kreiraj zaglavlje fakture
        l_faktura_id := insert_kif(
            p_klijent_id           => r_predracun.klijent_id,
            p_valuta_id            => r_predracun.valuta_id,
            p_valuta_iznos         => r_predracun.valuta_iznos,
            p_valuta_iznos_pdv     => r_predracun.valuta_iznos_pdv,
            p_ooj_id               => r_predracun.ooj_id,
            p_oj_id                => r_predracun.oj_id,
            p_predracun_id         => p_predracun_id,
            p_faktura_broj         => r_predracun.faktura_broj,
            p_naziv_fakture        => r_predracun.naziv_fakture,
            p_godina               => p_godina,
            p_datum_uplatnice      => null,
            p_iznos_fakture        => r_predracun.iznos_fakture,
            p_iznos_slovima        => r_predracun.iznos_slovima,
            p_datum_valute         => p_datum_valute,
            p_iznos_fakture_nopdv  => r_predracun.iznos_fakture_nopdv,
            p_uplaceno             => 'Y',
            p_posebne_napomene     => r_predracun.posebne_napomene,
            p_datum_fakture        => p_datum_fakture,
            p_print_pn             => p_print_pn,
            p_tip_placanja_id      => r_predracun.tip_placanja_id,
            p_uio_tip_dokumenta_id => r_predracun.uio_tip_dokumenta_id,
            p_vrsta_fakture_id     => l_vrsta_naloga_id,
            p_faktura_id           => r_predracun.faktura_id,
            p_tip_cijene           => r_predracun.tip_cijene,
            p_dani_dospijeca       => r_predracun.dani_dospijeca,
            p_radni_nalog_id       => r_predracun.radni_nalog_id
        );

    -- Kopiraj stavke
        for stavka in c_predracun_stavke loop
            insert_kif_stavka(
                p_kif_id           => l_faktura_id,
                p_stavka_id        => stavka.stavka_id,
                p_jm_id            => stavka.jm_id,
                p_kolicina         => stavka.kolicina,
                p_cijena           => stavka.cijena,
                p_rabat            => stavka.rabat,
                p_pdv              => stavka.pdv,
                p_iznos            => stavka.iznos,
                p_pdv_indikator_id => stavka.pdv_indikator_id
            );
        end loop;

    -- Označi predračun kao iskorišten
        update kif
        set
            uplaceno = 'Y'
        where
            id = p_predracun_id;

    -- Ažuriraj brojač
        core.protokoli_pkg.update_brojac(
            p_ooj_id             => r_predracun.ooj_id,
            p_vrsta_naloga_sifra => g_kif_sifra,
            p_godina             => p_godina,
            p_value              => 1
        );

        return l_faktura_id;
    end create_kif_from_predracun_car_service;
    




    --END Car Service aplikacija 
    procedure update_kif (
        p_id                   in number,
        p_klijent_id           in number,
        p_valuta_id            in number,
        p_tip_placanja_id      in number,
        p_datum_fakture        in date,
        p_datum_valute         in date,
        p_iznos_slovima        in varchar2,
        p_print_pn             in varchar2,
        p_posebne_napomene     in varchar2,
        p_uio_tip_dokumenta_id in number,
        p_ugovor_id            in number,
        p_oj_id                in number
    ) is
    begin
        update kif
        set
            klijent_id = p_klijent_id,
            valuta_id = p_valuta_id,
            tip_placanja_id = p_tip_placanja_id,
            datum_fakture = p_datum_fakture,
            datum_valute = p_datum_valute,
            iznos_slovima = p_iznos_slovima,
            print_pn = p_print_pn,
            posebne_napomene = p_posebne_napomene,
            uio_tip_dokumenta_id = p_uio_tip_dokumenta_id,
            ugovor_id = p_ugovor_id,
            oj_id = p_oj_id
        where
            id = p_id;

    end update_kif;

    procedure update_kif (
        p_id             in number,
        p_uplaceno_rucno in number
    ) is
    begin
        update kif
        set
            uplaceno_rucno = p_uplaceno_rucno
        where
            id = p_id;

    end update_kif;

    procedure delete_kif (
        p_id in number
    ) is
    begin
        delete from kif_stavke
        where
            kif_id = p_id;

        delete from kif
        where
            id = p_id;

    end delete_kif;

    function is_kif_editable (
        p_id in number
    ) return boolean is

        l_fiskalizovano       varchar2(1);
        l_count               number;
        l_period_zakljucan_do date;
        l_datum_fakture       date;
        l_proknjizeno         varchar2(1);
        l_gk_exist            number;
    begin
        if p_id is null then
            return false;
        end if;
        select
            count(glavna_knjiga_id)
        into l_gk_exist
        from
            kif
        where
            id = p_id;

        -- Provjera da li je proknjizeno setovano na Y
        if ( l_gk_exist > 0 ) then
            select
                proknjizeno
            into l_proknjizeno
            from
                glavna_knjiga
            where
                id = (
                    select
                        glavna_knjiga_id
                    from
                        kif
                    where
                        id = p_id
                );

        end if;

        if ( l_proknjizeno = 'Y' ) then
            return false;
        end if;

        -- Provjera da li je faktura otisla u UIO
        select
            count(*)
        into l_count
        from
            uio_kif
        where
            faktura_id = p_id;

        if l_count > 0 then
            return false;
        end if;

        -- Provjera da li je fiskalizovana
        select
            fiskalizovano
        into l_fiskalizovano
        from
            kif
        where
            id = p_id;

        if l_fiskalizovano = 'Y' then
            return false;
        end if;

        -- Provjera da li je period zakljucan
        select
            period_zakljucan_do
        into l_period_zakljucan_do
        from
            core.ooj
        where
            id = (
                select
                    ooj_id
                from
                    kif
                where
                    id = p_id
            );

        select
            datum_fakture
        into l_datum_fakture
        from
            kif
        where
            id = p_id;

        if trunc(l_period_zakljucan_do) > trunc(l_datum_fakture, 'MM') then
            return false;
        end if;

        return true;
    end is_kif_editable;

    procedure calculate_kif (
        p_id in number
    ) is
    
    l_kurs number;
    
    
    begin
     for k in (select * from kif where id=p_id) 
     loop
       l_kurs:=sif.acc_pkg.get_kurs_na_dan (k.valuta_id,k.ooj_id,k.datum_fakture);
     end loop;
    
        for c1 in (
            select
                case
                    when valuta_naziv = 'KM' then
                        sif.spell_pkg.spell_serbian_number(
                            coalesce(
                                round(
                                    sum(iznos_pdv),
                                    2
                                ),
                                0
                            ),
                            'Y',
                            'J',
                            valuta_naziv
                        )
                    else
                        sif.spell_pkg.spell_serbian_number(
                            coalesce(
                                round(
                                    sum(iznos_pdv/l_kurs),
                                    2
                                ),
                                0
                            ),
                            'Y',
                            'J',
                            valuta_naziv
                        )
                end            as slovima,
                sum(iznos_pdv) as iznos,
                sum(iznos)     as iznos_nopdv,
                sum(round(iznos_pdv/l_kurs,2))  as iznos_valuta
            from
                vw_kif_stavke
            where
                kif_id = p_id
            group by
                valuta_id,
                valuta_naziv,
                valuta_sifra
        ) loop
            update kif
            set
                iznos_slovima = c1.slovima,
                iznos_fakture = c1.iznos,
                iznos_fakture_nopdv = c1.iznos_nopdv,
                valuta_iznos = c1.iznos_valuta,
                valuta_iznos_pdv = c1.iznos_valuta
            where
                id = p_id;

        end loop;
    end calculate_kif;

    procedure update_fiskalizacija (
        p_id             in number,
        p_fiskalni_racun in varchar2,
        p_fiskalizovano  in varchar2
    ) is
        l_blob     blob;
        l_filename varchar2(255);
        l_mimetype varchar2(255);
    begin
        if
            p_fiskalni_racun is not null
            and p_fiskalizovano = 'Y'
        then
            raise_application_error(-20001, 'Došlo je do greške, pokušajte opet.');
        end if;

        if p_fiskalizovano = 'Y' then
            sif.utils_pkg.get_apex_file_upload(
                p_apex_filename => p_fiskalni_racun,
                p_blob          => l_blob,
                p_filename      => l_filename,
                p_mimetype      => l_mimetype
            );

        end if;

        update kif
        set
            fiskalni_racun = l_blob,
            fiskalni_racun_filename = l_filename,
            fiskalni_racun_mimetype = l_mimetype,
            fiskalni_racun_lastupd = sysdate,
            fiskalizovano = p_fiskalizovano
        where
            id = p_id;

    end update_fiskalizacija;

    function storniraj_kif (
        p_id               in number,
        p_datum            in date,
        p_auto             in varchar2,
        p_glavna_knjiga_id in number
    ) return number is

        cursor c_stavke is
        (
            select
                stavka_id,
                kolicina,
                cijena,
                rabat,
                pdv,
                iznos,
                jm_id,
                pdv_indikator_id
            from
                kif_stavke
            where
                kif_id = p_id
        )
        order by
            id asc;

        l_id               number;
        l_glavna_knjiga_id number;
        r_kif              kif%rowtype;
        l_broj             number;
        l_naziv            varchar2(255);
        l_sifra            varchar2(64);
    begin
        select
            *
        into r_kif
        from
            kif
        where
            id = p_id;

        if
            p_auto = 'Y'
            and r_kif.glavna_knjiga_id is not null
        then
            l_glavna_knjiga_id := glavna_knjiga_pkg.storniraj_glavna_knjiga(
                p_id    => r_kif.glavna_knjiga_id,
                p_datum => p_datum,
                p_opis  => null,
                p_auto  => 'N'
            );

        end if;

        select
            vrsta_naloga_sifra || 's'
        into l_sifra
        from
            vw_kif
        where
            id = p_id;

        core.protokoli_pkg.get_brojac(
            p_ooj_id             => r_kif.ooj_id,
            p_vrsta_naloga_sifra => l_sifra,
            p_godina             => r_kif.godina,
            p_broj               => l_broj,
            p_naziv              => l_naziv
        );

        r_kif.id := null;
        if p_glavna_knjiga_id is null then
            r_kif.glavna_knjiga_id := l_glavna_knjiga_id;
        else
            r_kif.glavna_knjiga_id := p_glavna_knjiga_id;
        end if;

        r_kif.valuta_iznos := ( r_kif.valuta_iznos * -1 );
        r_kif.valuta_iznos_pdv := ( r_kif.valuta_iznos_pdv * -1 );
        r_kif.iznos_fakture := ( r_kif.iznos_fakture * -1 );
        r_kif.iznos_fakture_nopdv := ( r_kif.iznos_fakture_nopdv * -1 );
        r_kif.datum_fakture := p_datum;
        r_kif.datum_valute := add_months(r_kif.datum_fakture, 1);
        r_kif.faktura_broj := l_broj;
        r_kif.naziv_fakture := l_naziv;
        r_kif.stornirano := 'N';
        r_kif.storniran_id := p_id;
        insert into kif values r_kif returning id into l_id;

        for stavka in c_stavke loop
            insert_kif_stavka(
                p_kif_id           => l_id,
                p_stavka_id        => stavka.stavka_id,
                p_jm_id            => stavka.jm_id,
                p_kolicina         => stavka.kolicina * - 1,
                p_cijena           => stavka.cijena,
                p_rabat            => stavka.rabat,
                p_pdv              => stavka.pdv,
                p_iznos            => stavka.iznos * - 1,
                p_pdv_indikator_id => stavka.pdv_indikator_id
            );
        end loop;

        core.protokoli_pkg.update_brojac(
            p_ooj_id             => r_kif.ooj_id,
            p_vrsta_naloga_sifra => l_sifra,
            p_godina             => r_kif.godina,
            p_value              => 1
        );

        update kif
        set
            stornirano = 'Y'
        where
            id = p_id;

        return l_id;
    end storniraj_kif;
    

    function insert_system_predracun (
        p_klijent_id    in number,
        p_datum_fakture in date,
        p_datum_valute  in date
    ) return number is

        l_id                   number;
        l_valuta_id            number := 1;
        l_ooj_id               number := apex_app_setting.get_value('ESSCOM_OOJ_ID');
        l_oj_id                number := apex_app_setting.get_value('ESSCOM_SOFTWARE_OJ_ID');
        l_faktura_broj         number;
        l_naziv_fakture        varchar2(255);
        l_godina               number := extract(year from sysdate);
        l_datum_uplatnice      date := null;
        l_uplaceno             varchar2(1) := 'N';
        l_posebne_napomene     varchar2(1) := null;
        l_tip_placanja_id      number := 3;
        l_uio_tip_dokumenta_id number := 1;
        l_print_pn             varchar2(1) := 'N';
        l_vrsta_fakutre_id     number := 5;
    begin
        core.protokoli_pkg.get_brojac(
            p_ooj_id             => l_ooj_id,
            p_vrsta_naloga_sifra => 'pr',
            p_godina             => l_godina,
            p_broj               => l_faktura_broj,
            p_naziv              => l_naziv_fakture
        );

        dbms_output.put_line(l_godina);
        dbms_output.put_line(l_ooj_id);
        dbms_output.put_line(l_faktura_broj);
        dbms_output.put_line(l_naziv_fakture);
        l_id := insert_kif(
            p_glavna_knjiga_id     => null,
            p_klijent_id           => p_klijent_id,
            p_valuta_id            => l_valuta_id,
            p_valuta_iznos         => null,
            p_valuta_iznos_pdv     => null,
            p_ooj_id               => l_ooj_id,
            p_predracun_id         => null,
            p_faktura_broj         => l_faktura_broj,
            p_naziv_fakture        => l_naziv_fakture,
            p_godina               => l_godina,
            p_datum_uplatnice      => l_datum_uplatnice,
            p_datum_fakture        => p_datum_fakture,
            p_iznos_fakture        => null,
            p_iznos_slovima        => null,
            p_datum_valute         => p_datum_valute,
            p_iznos_fakture_nopdv  => null,
            p_uplaceno             => l_uplaceno,
            p_posebne_napomene     => l_posebne_napomene,
            p_print_pn             => l_print_pn,
            p_tip_placanja_id      => l_tip_placanja_id,
            p_uio_tip_dokumenta_id => l_uio_tip_dokumenta_id,
            p_system               => 'Y',
            p_vrsta_fakture_id     => l_vrsta_fakutre_id,
            p_tip_cijene           => 'M',
            p_dani_dospijeca       => 30,
            p_ugovor_id            => null,
            p_oj_id                => l_oj_id,
            p_skladiste_id         => null,
            p_pdv_indikator_id     => null
            
        );

        core.protokoli_pkg.update_brojac(
            p_ooj_id             => l_ooj_id,
            p_vrsta_naloga_sifra => 'pr',
            p_godina             => l_godina,
            p_value              => 1
        );

        return l_id;
    end insert_system_predracun;

    procedure update_system_predracun (
        p_predracun_id in number
    ) is
        l_iznos     number;
        l_iznos_pdv number;
        l_slovima   varchar2(1000);
    begin
        select
            sum(iznos)     as iznos,
            sum(iznos_pdv) as iznos_pdv,
            sif.spell_pkg.spell_serbian_number(
                sum(iznos_pdv),
                'Y',
                'J',
                'KM'
            )              as iznos_slovima
        into
            l_iznos,
            l_iznos_pdv,
            l_slovima
        from
            vw_kif_stavke
        where
            kif_id = p_predracun_id;

        update kif
        set
            iznos_fakture = l_iznos_pdv,
            iznos_fakture_nopdv = l_iznos,
            iznos_slovima = l_slovima
        where
            id = p_predracun_id;

    end update_system_predracun;

    function check_system_predracun_exist (
        p_klijent_id in number,
        p_modules    in varchar2
    ) return number is

        cursor c_predracuni is
        (
            select
                id
            from
                vw_kif
            where
                    klijent_id = p_klijent_id
                and uplaceno = 'N'
                and datum_valute > sysdate
                and vrsta_naloga_sifra = 'pr'
        );

        l_modul_list varchar2(1000);
    begin
        for predracun in c_predracuni loop
            select
                modul_list
            into l_modul_list
            from
                (
                    select
                        listagg(stavka_id, ',')
                        over(partition by kif_id) modul_list
                    from
                        kif_stavke
                    where
                        kif_id = predracun.id
                    order by
                        stavka_id asc
                )
            where
                rownum = 1;

            if l_modul_list = p_modules then
                return predracun.id;
                exit;
            end if;
        end loop;

        return 0;
    end check_system_predracun_exist;

    -- Procedure da li je faktura uplacena (iz izvoda)
    procedure check_kif_uplaceno (
        p_id               in number,
        p_glavna_knjiga_id in number
    ) is
        l_ooj_id        number;
        l_iznos         number;
        l_uplacen_iznos number;
        l_datum         date;
    begin
        glavna_knjiga_pkg.get_glavna_knjiga(
            p_id              => p_glavna_knjiga_id,
            p_datum_dokumenta => l_datum
        );
        get_kif(
            p_id            => p_id,
            p_ooj_id        => l_ooj_id,
            p_iznos_fakture => l_iznos
        );
        select
            sum(abs(iznos))
        into l_uplacen_iznos
        from
            vw_glavna_knjiga_stavke
        where
                ooj_id = l_ooj_id
            and kif_id = p_id;

        if l_uplacen_iznos >= l_iznos then
            update kif
            set
                uplaceno = 'Y',
                datum_uplatnice = l_datum
            where
                id = p_id;

        end if;

    end check_kif_uplaceno;

