    procedure get_kif_stavka (
        p_id               in number,
        p_kif_id           out number,
        p_stavka_id        out number,
        p_jm_id            out number,
        p_kolicina         out number,
        p_cijena           out number,
        p_rabat            out number,
        p_pdv              out number,
        p_iznos            out number,
        p_pdv_indikator_id out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                kif_stavke
            where
                id = p_id
        ) loop
            p_kif_id := c1.kif_id;
            p_stavka_id := c1.stavka_id;
            p_jm_id := c1.jm_id;
            p_kolicina := c1.kolicina;
            p_cijena := c1.cijena;
            p_rabat := c1.rabat;
            p_pdv := c1.pdv;
            p_iznos := c1.iznos;
            p_pdv_indikator_id := c1.pdv_indikator_id;
        end loop;
    end get_kif_stavka;

    procedure insert_kif_stavka (
        p_kif_id           in number,
        p_stavka_id        in number,
        p_jm_id            in number,
        p_kolicina         in number,
        p_cijena           in number,
        p_rabat            in number,
        p_pdv              in number,
        p_iznos            in number,
        p_pdv_indikator_id in varchar2
    ) is
    begin
        insert into kif_stavke (
            kif_id,
            stavka_id,
            naziv,
            jm_id,
            kolicina,
            cijena,
            rabat,
            pdv,
            iznos,
            pdv_indikator_id
        ) values ( p_kif_id,
                   p_stavka_id,
                   stavke_pkg.get_stavka_naziv(p_stavka_id),
                   p_jm_id,
                   p_kolicina,
                   p_cijena,
                   p_rabat,
                   p_pdv,
                   p_iznos,
                   p_pdv_indikator_id );

    end insert_kif_stavka;

    procedure update_kif_stavka (
        p_id               in number,
        p_kif_id           in number,
        p_stavka_id        in number,
        p_jm_id            in number,
        p_kolicina         in number,
        p_cijena           in number,
        p_rabat            in number,
        p_pdv              in number,
        p_iznos            in number,
        p_pdv_indikator_id in varchar2
    ) is
    begin
        update kif_stavke
        set
            kif_id = p_kif_id,
            stavka_id = p_stavka_id,
            naziv = stavke_pkg.get_stavka_naziv(p_stavka_id),
            jm_id = p_jm_id,
            kolicina = p_kolicina,
            cijena = p_cijena,
            rabat = p_rabat,
            pdv = p_pdv,
            iznos = p_iznos,
            pdv_indikator_id = p_pdv_indikator_id
        where
            id = p_id;

    end update_kif_stavka;

    procedure delete_kif_stavka (
        p_id in number
    ) is
    begin
        delete from kif_stavke
        where
            id = p_id;

    end delete_kif_stavka;

