    procedure insert_kif_email_history (
        p_kif_id      in number,
        p_korisnik_id in number,
        p_email_from  in varchar2,
        p_email_to    in varchar2,
        p_cc          in varchar2,
        p_bcc         in varchar2,
        p_subject     in varchar2,
        p_message     in clob,
        p_attachment  in varchar2
    ) is
        l_blob     blob;
        l_filename varchar2(255);
        l_mimetype varchar2(255);
    begin
        if p_attachment is not null then
            sif.utils_pkg.get_apex_file_upload(
                p_apex_filename => p_attachment,
                p_blob          => l_blob,
                p_filename      => l_filename,
                p_mimetype      => l_mimetype
            );
        end if;

        insert into kif_email_history (
            kif_id,
            korisnik_id,
            email_from,
            email_to,
            cc,
            bcc,
            subject,
            message,
            attachment,
            attachment_filename,
            attachment_mimetype,
            attachment_lastupd
        ) values ( p_kif_id,
                   p_korisnik_id,
                   p_email_from,
                   p_email_to,
                   p_cc,
                   p_bcc,
                   p_subject,
                   p_message,
                   l_blob,
                   l_filename,
                   l_mimetype,
                   sysdate );

    end insert_kif_email_history;
    
    
