                   p_naziv,
                   p_broj, 
                   p_pdv_indikator_id, 
                   p_ugovor_id, 
                   p_godina, 
                   p_status ) returning id into l_id;

        return l_id;
    end insert_kuf;

    procedure update_kuf (
        p_id                   in number,
        p_glavna_knjiga_id     in number,
        p_ooj_id               in number,
        p_klijent_id           in number,
        p_datum_prijema        in date,
