        p_godina               in number,
        p_status               in varchar2
    ) is
        l_blob     blob;
        l_filename varchar2(255);
        l_mimetype varchar2(255);
    begin
        if p_document is null then
            update kuf
            set
                glavna_knjiga_id = p_glavna_knjiga_id,
