                valuta_iznos_bez_pdv = p_valuta_iznos_bez_pdv,
                valuta_iznos_sa_pdv = p_valuta_iznos_sa_pdv,
                tip_placanja_id = p_tip_placanja_id,
                fiskalni_racun_broj = p_fiskalni_racun_broj,
                naziv_fakture = p_naziv_fakture,
                uio_tip_dokumenta_id = p_uio_tip_dokumenta_id,
                valid = p_valid,
                pdv_indikator_id = p_pdv_indikator_id,
                ugovor_id = p_ugovor_id,
                godina = p_godina,
                status = p_status
            where
                id = p_id;

        else
            sif.utils_pkg.get_apex_file_upload(
                p_apex_filename => p_document,
                p_blob          => l_blob,
                p_filename      => l_filename,
                p_mimetype      => l_mimetype
            );

            update kuf
            set
                glavna_knjiga_id = p_glavna_knjiga_id,
                ooj_id = p_ooj_id,
                klijent_id = p_klijent_id,
                datum_prijema = p_datum_prijema,
                datum_fakture = p_datum_fakture,
                datum_valute = p_datum_valute,
                iznos_bez_pdv = p_iznos_bez_pdv,
                iznos_sa_pdv = p_iznos_sa_pdv,
                valuta_id = p_valuta_id,
                valuta_iznos_bez_pdv = p_valuta_iznos_bez_pdv,
                valuta_iznos_sa_pdv = p_valuta_iznos_sa_pdv,
                document = l_blob,
                document_filename = l_filename,
                document_mimetype = l_mimetype,
                document_lastupd = sysdate,
                tip_placanja_id = p_tip_placanja_id,
                fiskalni_racun_broj = p_fiskalni_racun_broj,
                naziv_fakture = p_naziv_fakture,
                uio_tip_dokumenta_id = p_uio_tip_dokumenta_id,
                valid = p_valid,
                pdv_indikator_id = p_pdv_indikator_id,
                ugovor_id = p_ugovor_id,
                godina = p_godina,
                status = p_status
            where
                id = p_id;

        end if;
    end update_kuf;

