    function is_kuf_editable (
        p_id in number
    ) return boolean is
        l_count               number;
        l_period_zakljucan_do date;
        l_datum_fakture       date;
    begin
        if p_id is null then
            return false;
        end if;
        select
            count(*)
        into l_count
        from
            uio_kuf
        where
            faktura_id = p_id;

        if l_count > 0 then
            return false;
        end if;
        select
            count(*)
        into l_count
        from
            kuf
        where
                id = p_id
            and glavna_knjiga_id is not null;

        if l_count > 0 then
            return false;
        end if;

        -- Provjera da li je period zakljucan
        select
            period_zakljucan_do
        into l_period_zakljucan_do
        from
            core.ooj
        where
            id = (
                select
                    ooj_id
                from
                    kuf
                where
                    id = p_id
            );

        select
            datum_fakture
        into l_datum_fakture
        from
            kuf
        where
            id = p_id;

        if trunc(l_period_zakljucan_do) > trunc(l_datum_fakture, 'MM') then
            return false;
        end if;

        return true;
    end is_kuf_editable;

    procedure storniraj_kuf (
        p_id               in number,
        p_datum            in date,
        p_auto             in varchar2,
        p_glavna_knjiga_id in number
    ) is
        l_id               number;
        l_glavna_knjiga_id number;
        r_kuf              kuf%rowtype;
        l_broj             number;
        l_naziv            varchar2(255);
    begin
        select
            *
        into r_kuf
        from
            kuf
        where
            id = p_id;

        if
            p_auto = 'Y'
            and r_kuf.glavna_knjiga_id is not null
        then
            l_glavna_knjiga_id := glavna_knjiga_pkg.storniraj_glavna_knjiga(
                p_id    => r_kuf.glavna_knjiga_id,
                p_datum => p_datum,
                p_opis  => null, 
                p_auto  => 'N'
            );

        end if;

        r_kuf.id := null;
        if p_glavna_knjiga_id is null then
            r_kuf.glavna_knjiga_id := l_glavna_knjiga_id;
        else
            r_kuf.glavna_knjiga_id := p_glavna_knjiga_id;
        end if;

        r_kuf.valuta_iznos_sa_pdv := ( r_kuf.valuta_iznos_sa_pdv * -1 );
        r_kuf.valuta_iznos_bez_pdv := ( r_kuf.valuta_iznos_bez_pdv * -1 );
        r_kuf.iznos_bez_pdv := ( r_kuf.iznos_bez_pdv * -1 );
        r_kuf.iznos_sa_pdv := ( r_kuf.iznos_sa_pdv * -1 );
        r_kuf.stornirano := 'N';
        r_kuf.storniran_id := p_id;
        insert into kuf values r_kuf returning id into l_id;

        update kuf
        set
            stornirano = 'Y'
        where
            id = p_id;

    end storniraj_kuf;

    -- Procedure da li je faktura uplacena (iz izvoda)
    procedure check_kuf_uplaceno (
        p_id               in number,
        p_glavna_knjiga_id in number
    ) is
        l_ooj_id        number;
        l_iznos         number;
        l_uplacen_iznos number;
        l_datum         date;
    begin
        glavna_knjiga_pkg.get_glavna_knjiga(
            p_id              => p_glavna_knjiga_id,
            p_datum_dokumenta => l_datum
        );
        get_kuf(
            p_id            => p_id,
            p_ooj_id        => l_ooj_id,
            p_iznos_fakture => l_iznos
        );
        select
            sum(abs(iznos))
        into l_uplacen_iznos
        from
            vw_glavna_knjiga_stavke
        where
                ooj_id = l_ooj_id
            and kuf_id = p_id;

        if l_uplacen_iznos >= l_iznos then
            update kuf
            set
                uplaceno = 'Y',
                datum_uplatnice = l_datum
            where
                id = p_id;

        end if;

    end check_kuf_uplaceno;
    --------------------------------------------------------------
    -- procedure za tebalu izvodi
    -- djordjije ristanovic 10.07.2026
    --------------------------------------------------------------
    
    procedure get_izvod (
        p_id                in  number,
        p_ooj_id            out number,
        p_ziro_racun_id     out number,
        p_broj              out number,
        p_datum             out date,
        p_opis              out varchar2,
        p_prethodni_saldo   out number,
