        p_storno            out varchar2,
        p_zakljucan         out varchar2,
        p_proknjizen        out varchar2,
        p_nalog_gk_id       out number, 
        p_godina            out number
    ) is
    begin
        select ooj_id,
               ziro_racun_id,
               broj,
               datum,
               opis,
               prethodni_saldo,
               novi_saldo,
               storno,
               zakljucan,
               proknjizen,
               nalog_gk_id, 
               godina
          into p_ooj_id,
               p_ziro_racun_id,
               p_broj,
               p_datum,
               p_opis,
               p_prethodni_saldo,
               p_novi_saldo,
               p_storno,
               p_zakljucan,
               p_proknjizen,
               p_nalog_gk_id, 
               p_godina
          from izvodi
         where id = p_id;
    exception
        when no_data_found then
            p_ooj_id          := null;
            p_ziro_racun_id   := null;
            p_broj            := null;
            p_datum           := null;
            p_opis            := null;
            p_prethodni_saldo := null;
            p_novi_saldo      := null;
            p_storno          := 'N';
            p_zakljucan       := 'N';
            p_proknjizen      := 'N';
            p_nalog_gk_id     := null;
            p_godina          := null;
    end get_izvod;


    procedure insert_izvod (
        p_ooj_id            in number,
        p_ziro_racun_id     in number,
        p_broj              in number,
        p_datum             in date,
        p_opis              in varchar2,
        p_prethodni_saldo   in number,
