        p_godina            in number,
        p_id                out number 

    ) is
    begin
        insert into izvodi (
            ooj_id,
            ziro_racun_id,
            broj,
            datum,
            opis,
            prethodni_saldo,
            novi_saldo,
            storno,
            zakljucan,
            proknjizen,
            nalog_gk_id, 
            godina
        ) values (
            p_ooj_id,
            p_ziro_racun_id,
            p_broj,
            p_datum,
            p_opis,
            p_prethodni_saldo,
            p_novi_saldo,
            p_storno,
            p_zakljucan,
            p_proknjizen,
            p_nalog_gk_id, 
            p_godina
        )
        returning id into p_id;
    end insert_izvod;


    procedure update_izvod (
        p_id                in number,
        p_ooj_id            in number,
        p_ziro_racun_id     in number,
        p_broj              in number,
        p_datum             in date,
        p_opis              in varchar2,
        p_prethodni_saldo   in number,
