        p_storno            in varchar2,
        p_zakljucan         in varchar2,
        p_proknjizen        in varchar2,
        p_nalog_gk_id       in number, 
        p_godina            in number
    ) is
    begin
        update izvodi
           set ooj_id           = p_ooj_id,
               ziro_racun_id    = p_ziro_racun_id,
               broj             = p_broj,
               datum            = p_datum,
               opis             = p_opis,
               prethodni_saldo  = p_prethodni_saldo,
               novi_saldo       = p_novi_saldo,
               storno           = p_storno,
               zakljucan        = p_zakljucan,
               proknjizen       = p_proknjizen,
               nalog_gk_id      = p_nalog_gk_id, 
               godina           = p_godina
         where id = p_id;
    end update_izvod;


    procedure delete_izvod (
        p_id in number
    ) is
    begin
        delete from izvodi
         where id = p_id;
    end delete_izvod;
    
    
    --------------------------------------------------------------
    -- procedure za tebalu izvod stavke
    -- djordjije ristanovic 10.07.2026
    --------------------------------------------------------------
    procedure get_izvod_stavka (
        p_id                    in  number,
        p_izvod_id              out number,
