        )
        returning id into p_id;
    end insert_izvod_stavka;


    procedure update_izvod_stavka (
        p_id                    in number,
        p_izvod_id              in number,
        p_rbr                   in number,
        p_datum_transakcije     in date,
        p_smjer                 in varchar2,
        p_uplatio                in varchar2,
        p_svrha_doznake         in varchar2,
        p_poziv_na_broj         in varchar2,
        p_ref_ziro_racun        in varchar2,
        p_vrsta_placanja        in varchar2,
        p_vrsta_prihoda         in varchar2,
