         where id = p_id;
    end delete_izvod_stavka;
    
    
    function validate_change_kurs (p_ooj_id in number, 
                                   p_valuta_id in number, 
                                   p_datum in date ) 
    return varchar2 is 
     v_pom number;
    begin 
            ---provjera izvoda---
            select count(*)
            into v_pom 
            from accounting.izvodi iz 
            join sif.sif_ziro_racuni zr on iz.ziro_racun_id=zr.id
            where zr.valuta_id=p_valuta_id
            and iz.datum=p_datum
            and iz.ooj_id=p_ooj_id;
            
            if v_pom>0 then 
              
               return 'Kurs se ne može mijenjati jer je za njega već evidentiran izvod. Molimo prvo obrišite izvod, pa nastavite sa izmjenom kursa.';
      
            end if;
            
            return null;
    end;


end finansije_pkg;
/

