    --------------------------------------------------------------
    -- procedures for table GLAVNA_KNJIGA
    --------------------------------------------------------------

    function get_broj_naloga (
        p_ooj_id          in number,
        p_vrsta_naloga_id in number,
        p_godina          in number
    ) return number is
    begin
        for c1 in (
            select
                coalesce(
                    max(broj + 1),
                    1
                ) as output
            from
                glavna_knjiga
            where
                    ooj_id = p_ooj_id
                and vrsta_naloga_id = p_vrsta_naloga_id
                and godina = p_godina
        ) loop
            return c1.output;
        end loop;
    end get_broj_naloga;

    function get_broj_stavke (
        p_glavna_knjiga_id in number
    ) return number is
    begin
        for c1 in (
            select
                coalesce(
                    max(redni_broj),
                    0
                ) as output
            from
                glavna_knjiga_stavke
            where
                glavna_knjiga_id = p_glavna_knjiga_id
        ) loop
            return c1.output + 1;
        end loop;
    end get_broj_stavke;

    function get_glavna_knjiga_vrsta_naloga (
        p_id in number
    ) return varchar2 is
    begin
        for c1 in (
            select
                lower(vrsta_naloga_sifra) as vrsta_naloga_sifra
            from
                vw_glavna_knjiga
            where
                id = p_id
        ) loop
            return c1.vrsta_naloga_sifra;
        end loop;

        return '';
    end get_glavna_knjiga_vrsta_naloga;

    procedure get_glavna_knjiga (
        p_id              in number,
        p_ooj_id          out number,
        p_vrsta_naloga_id out number,
        p_godina          out number,
        p_broj            out varchar2,
        p_datum_dokumenta out date,
        p_datum_knjizenja out date,
        p_proknjizeno     out varchar2,
        p_opis            out varchar2,
        p_valid           out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
