            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_vrsta_naloga_id := c1.vrsta_naloga_id;
            p_godina := c1.godina;
            p_broj := c1.broj;
            p_datum_dokumenta := c1.datum_dokumenta;
            p_datum_knjizenja := c1.datum_knjizenja;
