            from
                glavna_knjiga
            where
                id = p_id
        ) loop
            p_godina := c1.godina;
        end loop;
    end get_glavna_knjiga;

    function insert_glavna_knjiga (
        p_ooj_id           in number,
        p_vrsta_naloga_id  in number,
        p_godina           in number,
        p_broj             in varchar2,
        p_datum_dokumenta  in date,
        p_datum_knjizenja  in date,
        p_opis             in varchar2,
        p_stornirano       in varchar2 default 'N',
        p_storniran_id     in varchar2 default null,
        p_ooj_banka_id     in number default null,
        p_broj_izvoda      in number default null,
        p_pocetno_stanje   in number default null,
        p_zakljucno_stanje in number default null,
        p_proknjizeno      in varchar2 default 'N'
    ) return number is
        l_id number;
    begin
        insert into glavna_knjiga (
            ooj_id,
            vrsta_naloga_id,
            godina,
            broj,
            datum_dokumenta,
            datum_knjizenja,
            opis,
            stornirano,
            storniran_id,
            ooj_banka_id,
            broj_izvoda,
            pocetno_stanje,
            zakljucno_stanje,
            proknjizeno
        ) values ( p_ooj_id,
                   p_vrsta_naloga_id,
                   p_godina,
                   p_broj,
                   p_datum_dokumenta,
                   p_datum_knjizenja,
                   p_opis,
                   p_stornirano,
                   p_storniran_id,
                   p_ooj_banka_id,
                   p_broj_izvoda,
                   p_pocetno_stanje,
                   p_zakljucno_stanje, 
                   p_proknjizeno ) returning id into l_id;

        return l_id;
    end insert_glavna_knjiga;

    procedure update_glavna_knjiga (
        p_id              in number,
        p_ooj_id          in number,
        p_vrsta_naloga_id in number,
        p_godina          in number,
        p_broj            in varchar2,
        p_datum_dokumenta in date,
        p_datum_knjizenja in date,
        p_proknjizeno     in varchar2,
        p_opis            in varchar2,
        p_valid           in varchar2
    ) is
    begin
        update glavna_knjiga
        set
            ooj_id = p_ooj_id,
            vrsta_naloga_id = p_vrsta_naloga_id,
            godina = p_godina,
            broj = p_broj,
            datum_dokumenta = p_datum_dokumenta,
            datum_knjizenja = p_datum_knjizenja,
            proknjizeno = p_proknjizeno,
            opis = p_opis,
            valid = p_valid
        where
            id = p_id;

    end update_glavna_knjiga;

    procedure update_glavna_knjiga (
        p_id               in number,
        p_ooj_id           in number,
        p_vrsta_naloga_id  in number,
        p_godina           in number,
        p_broj             in varchar2,
        p_datum_dokumenta  in date,
        p_datum_knjizenja  in date,
        p_opis             in varchar2,
        p_ooj_banka_id     in number,
        p_broj_izvoda      in number,
        p_pocetno_stanje   in number,
        p_zakljucno_stanje in number,
