            broj = p_broj,
            datum_dokumenta = p_datum_dokumenta,
            datum_knjizenja = p_datum_knjizenja,
            opis = p_opis,
            ooj_banka_id = p_ooj_banka_id,
            broj_izvoda = p_broj_izvoda,
            pocetno_stanje = p_pocetno_stanje,
            zakljucno_stanje = p_zakljucno_stanje,
            valid = p_valid
        where
