    end update_glavna_knjiga;

    procedure delete_glavna_knjiga (
        p_id in number
    ) is
    begin
        delete from glavna_knjiga_stavke
        where
            glavna_knjiga_id = p_id;

        delete from glavna_knjiga
        where
            id = p_id;

    end delete_glavna_knjiga;

    procedure set_proknjizeno (
        p_id                     in number,
        p_value                  in varchar2,
        p_tip_preduzetnika_sifra in varchar2 default 'doo'
    ) is
        l_count number;
        l_sum   number;
    begin
        select
            count(*)
        into l_count
        from
            glavna_knjiga_stavke
        where
            glavna_knjiga_id = p_id;

        if p_value = 'Y' and p_tip_preduzetnika_sifra not in ('msp', 'vsp_prosto') then
            select
                sum(iznos)
            into l_sum
            from
                glavna_knjiga_stavke
            where
                glavna_knjiga_id = p_id;

            if l_sum != 0 then
                raise_application_error(-20001, 'Nalog u neravnoteži, nije moguće proknjižiti nalog.');
            end if;
        end if;

        if l_count > 0 or p_value = 'N' then
            update glavna_knjiga
            set
                proknjizeno = p_value
            where
                id = p_id;

            for c1 in (
                select
                    kif_id,
                    kuf_id
                from
                    glavna_knjiga_stavke
                where
                        glavna_knjiga_id = p_id
                    and ( kif_id is not null
                          or kuf_id is not null )
            ) loop
                if c1.kif_id is not null then
                    finansije_pkg.check_kif_uplaceno(
                        p_id               => c1.kif_id,
                        p_glavna_knjiga_id => p_id
                    );
                end if;

                if c1.kuf_id is not null then
                    finansije_pkg.check_kuf_uplaceno(
                        p_id               => c1.kuf_id,
                        p_glavna_knjiga_id => p_id
                    );
                end if;

            end loop;

        else
            raise_application_error(-20001, 'Nemate unešenih stavki u nalogu');
        end if;

    end set_proknjizeno;

    function storniraj_glavna_knjiga (
        p_id    in number,
        p_datum in date,
        p_opis  in varchar2, 
        p_auto  in varchar2
       
    ) return number is

        cursor c_stavke is
        (
            select
                *
            from
                glavna_knjiga_stavke
            where
                glavna_knjiga_id = p_id
        )
        order by
            redni_broj asc;

        l_id            number;
        r_glavna_knjiga glavna_knjiga%rowtype;
        l_stavka_id  number;
        l_broj_zatvaranja number;
        l_id_zat number;
        l_id_dok number;
        l_broj_storno number;
        l_sifra_naloga varchar2(50);
    begin
        select
            *
        into r_glavna_knjiga
        from
            glavna_knjiga
        where
            id = p_id;

        r_glavna_knjiga.id := null;
        l_broj_storno := glavna_knjiga_pkg.get_broj_naloga(
            p_ooj_id          => r_glavna_knjiga.ooj_id,
            p_vrsta_naloga_id => r_glavna_knjiga.vrsta_naloga_id,
            p_godina          => r_glavna_knjiga.godina
        );

        l_id := insert_glavna_knjiga(
            p_ooj_id          => r_glavna_knjiga.ooj_id,
            p_vrsta_naloga_id => r_glavna_knjiga.vrsta_naloga_id,
            p_godina          => extract(year from p_datum),
            p_broj            => l_broj_storno,
            p_datum_dokumenta => r_glavna_knjiga.datum_dokumenta,
            p_datum_knjizenja => p_datum,
            p_opis            => p_opis,
            p_stornirano      => 'Y',
            p_storniran_id    => p_id
        );

        for r in c_stavke loop
            
            ---djordjije 08.01.2028.---
            insert_glavna_knjiga_stavka (
                    p_glavna_knjiga_id      => l_id,
                    p_kontna_klasa_id       => r.kontna_klasa_id,
                    p_klijent_id            => r.klijent_id,
                    p_tip_stavke            => r.tip_stavke,
                    p_opis                  => r.opis,
                    p_iznos                 => -r.iznos,
                    p_oj_id                 => r.oj_id,
                    p_grad_id               => r.grad_id,
                    p_prihod_rashod         => r.prihod_rashod,
                    p_vrsta_prihoda_id      => r.vrsta_prihoda_id,
                    p_vrsta_rashoda_id      => r.vrsta_rashoda_id,
                    p_nacin_placanja_izvoda => r.nacin_placanja_izvoda,
                    p_automatska            => r.automatska,
                    p_valuta_id             => r.valuta_id,
                    p_valuta_iznos          => -r.valuta_iznos,
                    p_kurs                  => r.kurs,
                    p_kif_id                => r.kif_id,
                    p_kuf_id                => r.kuf_id,
                    p_priznat_rashod        => r.priznat_rashod,
                    p_datum_dokumenta       => r.datum_dokumenta,
                    p_otvorena              => 'Z',
                    p_otvoreni_iznos        => 0,
                    p_mjesto_troska_id      => r.mjesto_troska_id,
                    p_acc_radnik_id         => r.acc_radnik_id,
                    p_id                    => l_stavka_id
                );
                
             ------- dodaj referentni dokument ----
             
              select sn.sifra
              into l_sifra_naloga
              from sif.sif_vrste_naloga sn 
              where sn.id=r_glavna_knjiga.vrsta_naloga_id;
               
              insert_gk_stavka_dokument (
                        p_ooj_id                    => r_glavna_knjiga.ooj_id,
                        p_modul_id                  => 2,
                        p_dokument_id               => p_id,
                        p_dokument                  => 'Glavna knjiga - '||l_sifra_naloga||'/'||r_glavna_knjiga.broj||'/'||r_glavna_knjiga.godina,
                        p_opis                      => r_glavna_knjiga.opis,
                        p_glavna_knjiga_stavka_id   => l_stavka_id,
                        p_id                        => l_id_dok
                 );
                
             ---zatvaranje otvorene stavke---
             if r.otvorena='O' then 
               
                ---insert zatvaranja---
                l_broj_zatvaranja := get_broj_zatvaranja(r_glavna_knjiga.ooj_id);
                insert_gk_analitika_zatvaranja (
                    p_ooj_id            => r_glavna_knjiga.ooj_id,
                    p_broj              => l_broj_zatvaranja,
                    p_o_stavka_id       => r.id,
                    p_z_stavka_id       => l_stavka_id,
                    p_iznos_zatvaranja  => -r.iznos,
                    p_storno            => null, 
                    p_id                => l_id_zat
                );

                
                --update otvorene stavke
                  update glavna_knjiga_stavke gks
                  set gks.otvorena='Z', gks.otvoreni_iznos=0
                  where gks.id=r.id;
                          
               
             end if;
            
        end loop;

        update glavna_knjiga
        set
            stornirano = 'Y',
            storniran_id = l_id
            
        where
            id = p_id;

        if r_glavna_knjiga.proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_id,
                p_value => r_glavna_knjiga.proknjizeno
            );
        end if;
        
        ----djordjije 08.02.2029----
        ---razvezivanje origibalnog nalooga od referentnih dokumenata---
        for k in (select distinct st.modul_id, st.dokument_id
                  from accounting.gk_stavke_dokument st
                  join accounting.glavna_knjiga_stavke gks on gks.id=st.glavna_knjiga_stavka_id 
                  where gks.glavna_knjiga_id=p_id)
        loop
          
               if k.modul_id=1 then ---izvodi
               
                  update  accounting.izvodi iz
                  set iz.proknjizen='N',
                      iz.nalog_gk_id=null
                  where iz.id=k.dokument_id; 
               
               end if;
        
        end loop;
        
        
        
        
        -----

        -- Provjera da li zelimo da storniram dalje (kif, kuf, kretanje robe povezan sa ovim nalogom)
        -- Saljemo paramter p_auto, ako je Y, storniracemo sta god je povezano sa nalogom
        << storn >> declare
            l_kif_id           number;
            l_kuf_id           number;
            l_kretanje_robe_id number;
        begin
            if p_auto = 'Y' then
                for kif in (
                    select
                        id
                    from
                        kif
                    where
                        glavna_knjiga_id = p_id
                ) loop
                    l_kif_id := finansije_pkg.storniraj_kif(
                        p_id               => kif.id,
                        p_datum            => p_datum,
                        p_auto             => 'N',
                        p_glavna_knjiga_id => l_id
                    );
                end loop;

                for kuf in (
                    select
                        id
                    from
                        kuf
                    where
                        glavna_knjiga_id = p_id
                ) loop
                    finansije_pkg.storniraj_kuf(
                        p_id               => kuf.id,
                        p_datum            => p_datum,
                        p_auto             => 'N',
                        p_glavna_knjiga_id => l_id
                    );
                end loop;

                for operacija in (
                    select
                        id
                    from
                        operacije
                    where
                        glavna_knjiga_id = p_id
                ) loop
--                    l_kretanje_robe_id := skladista_pkg.storniraj_kretanje_robe (
--                        p_id    => operacija.id,
--                        p_datum => p_datum,
--                        p_auto  => 'N'
--                    );
                    null;
                end loop;

            end if;
        end;

        return l_id;
    end storniraj_glavna_knjiga;
    
    
       
    ---- provjera da li je moguće stornirati nalog gk ---
    ---- djordjije 01.08.2026
    function check_storno_glavna_knjiga (
        p_id    in number
    ) return varchar2 is
    
    v_postoje_os number;
    
    begin
      
      select count(*)
      into v_postoje_os
      from glavna_knjiga_stavke gks
      join sif.acc_kontni_okvir_klase ko on ko.id=gks.kontna_klasa_id and ko.otvorene_stavke='Y'
      where gks.glavna_knjiga_id=p_id
      and gks.otvorena!='O';
      
      if v_postoje_os>0 then
         
         return 'Nalog nije moguće stornirati jer su otvorene stavke na kontima koja se prate po tom principu već zatvorene. Da biste nastavili sa storniranjem, prvo stornirajte zatvaranja povezana sa ovim nalogom.';
          
      end if;
     
      return null;
    exception when others then 
      
        return 'Nalog nije moguće stornirati. Za pomoć obratite se administratoru.';
      
    end;
    
    

    procedure insert_auto_izvod_stavka (
        p_id in number
    ) is

        l_opis              varchar2(255);
        l_kontna_klasa_id   number;
        l_pocetno_stanje    number;
        l_zakljucno_stanje  number;
        l_iznos             number;
        l_tip_stavke_izvoda varchar2(1);
    begin
        get_glavna_knjiga(
            p_id               => p_id,
            p_opis             => l_opis,
            p_kontna_klasa_id  => l_kontna_klasa_id,
            p_pocetno_stanje   => l_pocetno_stanje,
            p_zakljucno_stanje => l_zakljucno_stanje
        );

        l_iznos := ( l_zakljucno_stanje - l_pocetno_stanje );
        if l_iznos > 0 then
            l_tip_stavke_izvoda := 'P';
        elsif l_iznos < 0 then
            l_tip_stavke_izvoda := 'O';
        end if;

        glavna_knjiga_pkg.insert_glavna_knjiga_stavka(
            p_glavna_knjiga_id      => p_id,
            p_kontna_klasa_id       => l_kontna_klasa_id,
            p_klijent_id            => null,
            p_tip_stavke_izvoda     => l_tip_stavke_izvoda,
            p_opis                  => l_opis,
            p_iznos                 => l_iznos,
            p_grad_id               => null,
            p_prihod_rashod         => null,
            p_vrsta_prihoda_id      => null,
            p_vrsta_rashoda_id      => null,
            p_nacin_placanja_izvoda => null,
            p_automatska            => 'Y',
            p_valuta_id             => 1,
            p_valuta_iznos          => null,
            p_kurs                  => null,
            p_kif_id                => null,
            p_kuf_id                => null,
            p_priznat_rashod        => 'N'
        );

    end insert_auto_izvod_stavka;

    procedure delete_auto_izvod_stavka (
        p_id in number
    ) is
    begin
        delete from glavna_knjiga_stavke
        where
                glavna_knjiga_id = p_id
            and automatska = 'Y';

    end delete_auto_izvod_stavka;

    function get_broj_izvoda (
        p_ooj_id       in number,
        p_godina       in number,
        p_ooj_banka_id in number
    ) return number is
    begin
        for c1 in (
            select
                coalesce(
                    max(broj_izvoda + 1),
                    1
                ) as broj_izvoda
            from
                glavna_knjiga
            where
                    ooj_id = p_ooj_id
                and ooj_banka_id = p_ooj_banka_id
                and godina = p_godina
        ) loop
            return c1.broj_izvoda;
        end loop;

        return 1;
    end get_broj_izvoda;

    function get_opis_izvoda (
        p_ooj_id       in number,
        p_godina       in number,
        p_ooj_banka_id in number,
        p_datum        in date
    ) return varchar2 is
        l_broj_izvoda number := get_broj_izvoda(p_ooj_id, p_godina, p_ooj_banka_id);
    begin
        for c1 in (
            select
                substr(ziro_racun, 1, 3)   as sifra,
                to_char(p_datum, 'DDMMYY') as datum
            from
                core.vw_ooj_banke
            where
                id = p_ooj_banka_id
        ) loop
            return c1.sifra
                   || ' '
                   || lpad(l_broj_izvoda, 3, '0')
                   || ' '
                   || c1.datum;
        end loop;

        return '-';
    end get_opis_izvoda;

    function get_pocetno_stanje_izvoda (
        p_ooj_id       in number,
        p_ooj_banka_id in number,
        p_godina       in number
    ) return number is
    begin
        for c1 in (
            select
                zakljucno_stanje
            from
                glavna_knjiga
            where
                    ooj_id = p_ooj_id
                and ooj_banka_id = p_ooj_banka_id
                and godina = p_godina
            order by
                broj_izvoda desc
            fetch first row only
        ) loop
            return c1.zakljucno_stanje;
        end loop;

        return null;
    end get_pocetno_stanje_izvoda;

    function is_glavna_knjiga_editable (
        p_id in number
    ) return boolean is
        l_period_zakljucan_do date;
        l_datum_dokumenta     date;
        l_datum_knjizenja     date;
        l_count               number;
    begin
        if p_id is null then
            return false;
        end if;
        
        -- Provjera da li je period zakljucan
        select
            period_zakljucan_do
        into l_period_zakljucan_do
        from
            core.ooj
        where
            id = (
                select
                    ooj_id
                from
                    glavna_knjiga
                where
                    id = p_id
            );

        select
            datum_knjizenja,
            datum_dokumenta
        into
            l_datum_knjizenja,
            l_datum_dokumenta
        from
            glavna_knjiga
        where
            id = p_id;

        if trunc(l_period_zakljucan_do) > trunc(l_datum_knjizenja, 'MM') then
            return false;
        end if;

        if trunc(l_period_zakljucan_do) > trunc(l_datum_dokumenta, 'MM') then
            return false;
        end if;
        
        -- Ukoliko se nalog koristio za aktiviranje os
        select
            count(*)
        into
            l_count
        from
            sec_osnovno_sredstvo_aktiviranja
        where
            glavna_knjiga_id = p_id;
        
        if l_count > 0 then
            return false;
        end if;

        return true;
    end is_glavna_knjiga_editable;

    --------------------------------------------------------------
    -- procedures for table GLAVNA_KNJIGA_STAVKE
    --------------------------------------------------------------

    procedure get_glavna_knjiga_stavka (
        p_id                  in number,
        p_glavna_knjiga_id    out number,
        p_kontna_klasa_id     out number,
        p_klijent_id          out number,
        p_redni_broj          out number,
        p_tip_stavke          out varchar2,
        p_opis                out varchar2,
        p_iznos               out number,
        p_grad_id             out number,
        p_osnovno_sredstvo_id out number,
        p_transakcija_id      out number,
        p_os_datum            out date,
        p_interni_nalog       out varchar2,
        p_pdv_indikator_id    out number,
        p_oj_id               out number,
        p_radnik_id           out number,
        p_dodjela             out varchar2,
        p_datum_dokumenta     out date,
        p_otvorena            out varchar2,
        p_otvoreni_iznos      out number,
        p_mjesto_troska_id    out number,
        p_acc_radnik_id       out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                glavna_knjiga_stavke
            where
                id = p_id
        ) loop
            p_glavna_knjiga_id := c1.glavna_knjiga_id;
            p_kontna_klasa_id := c1.kontna_klasa_id;
            p_klijent_id := c1.klijent_id;
            p_redni_broj := c1.redni_broj;
            p_tip_stavke := c1.tip_stavke;
            p_opis := c1.opis;
            p_iznos := c1.iznos;
            p_grad_id := c1.grad_id;
            p_osnovno_sredstvo_id := c1.osnovno_sredstvo_id;
            p_transakcija_id := c1.transakcija_id;
            p_os_datum := c1.os_datum;
            p_interni_nalog := c1.interni_nalog;
            p_pdv_indikator_id := c1.pdv_indikator_id;
            p_oj_id := c1.oj_id;
            p_radnik_id := c1.radnik_id;
            p_dodjela := c1.dodjela;
            p_datum_dokumenta := c1.datum_dokumenta;
            p_otvorena := c1.otvorena;
            p_otvoreni_iznos := c1.otvoreni_iznos;
            p_mjesto_troska_id := c1.mjesto_troska_id;
            p_acc_radnik_id := c1.acc_radnik_id;            
        end loop;
    end get_glavna_knjiga_stavka;

    -- Get za izvod
    procedure get_glavna_knjiga_stavka (
        p_id                    in number,
        p_glavna_knjiga_id      out number,
        p_kontna_klasa_id       out number,
        p_klijent_id            out number,
        p_redni_broj            out number,
        p_tip_stavke_izvoda     out varchar2,
        p_opis                  out varchar2,
        p_iznos                 out number,
        p_grad_id               out number,
        p_prihod_rashod         out varchar2,
        p_vrsta_prihoda_id      out varchar2,
        p_vrsta_rashoda_id      out varchar2,
        p_nacin_placanja_izvoda out varchar2,
        p_sifra_prihoda         out varchar2,
        p_valuta_id             out number,
        p_valuta_iznos          out number,
        p_kurs                  out number,
        p_kif_id                out number,
        p_kuf_id                out number,
        p_priznat_rashod        out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                glavna_knjiga_stavke
            where
                id = p_id
        ) loop
            p_glavna_knjiga_id := c1.glavna_knjiga_id;
            p_kontna_klasa_id := c1.kontna_klasa_id;
            p_klijent_id := c1.klijent_id;
            p_redni_broj := c1.redni_broj;
            p_tip_stavke_izvoda := c1.tip_stavke_izvoda;
            p_opis := c1.opis;
            p_iznos := c1.iznos;
            p_grad_id := c1.grad_id;
            p_prihod_rashod := c1.prihod_rashod;
            p_vrsta_prihoda_id := c1.vrsta_prihoda_id;
            p_vrsta_rashoda_id := c1.vrsta_rashoda_id;
            p_nacin_placanja_izvoda := c1.nacin_placanja_izvoda;
            p_sifra_prihoda := c1.sifra_prihoda;
            p_valuta_id := c1.valuta_id;
            p_valuta_iznos := c1.valuta_iznos;
            p_kurs := c1.kurs;
            p_kif_id := c1.kif_id;
            p_kuf_id := c1.kuf_id;
            p_priznat_rashod := c1.priznat_rashod;
        end loop;
    end get_glavna_knjiga_stavka;

    procedure insert_glavna_knjiga_stavka (
        p_glavna_knjiga_id in number,
        p_kontna_klasa_id  in number,
        p_klijent_id       in number,
        p_redni_broj       in number,
        p_tip_stavke       in varchar2,
        p_opis             in varchar2,
        p_iznos            in number,
        p_grad_id          in number
    ) is
    begin
        insert into glavna_knjiga_stavke (
            glavna_knjiga_id,
            kontna_klasa_id,
            klijent_id,
            redni_broj,
            tip_stavke,
            opis,
            grad_id,
            iznos
        ) values ( p_glavna_knjiga_id,
                   p_kontna_klasa_id,
                   p_klijent_id,
                   p_redni_broj,
                   p_tip_stavke,
                   p_opis,
                   p_grad_id,
                   round(p_iznos, 2) );

    end insert_glavna_knjiga_stavka;

    -- Insert za nalog za knjizenje
    ---djordjije 28.07.2026 dodate nove kolone, datum_dokumenta, otvorena, otvoreni_iznos, dodat izlazni parametar id_stavke
    ----
    procedure insert_glavna_knjiga_stavka (
        p_glavna_knjiga_id    in number,
        p_kontna_klasa_id     in number,
        p_klijent_id          in number default null,
        p_tip_stavke          in varchar2,
        p_opis                in varchar2,
        p_iznos               in number,
        p_grad_id             in number default null,
        p_osnovno_sredstvo_id in number default null,
        p_transakcija_id      in number default null,
        p_os_datum            in date default null,
        p_interni_nalog       in varchar2 default 'N',
        p_pdv_indikator_id    in number default null,
        p_oj_id               in number default null,
        p_radnik_id           in number default null,
        p_dodjela             in varchar2 default null, 
        p_datum_dokumenta     in date default null, 
        p_otvorena            in varchar2 default 'Z',
        p_otvoreni_iznos      in number default 0,
        p_mjesto_troska_id    in number default null,
        p_acc_radnik_id       in number default null,
        p_id                  out number
        
    ) is

        l_redni_broj             number;
        l_vrsta_naloga_sifra     varchar2(64);
        l_pdv_indikator_id       number := p_pdv_indikator_id;
        l_kontna_klasa_code      varchar2(32);
        l_kontna_klasa_indikator varchar2(1);
        l_pdv_indikator_sifra    varchar2(2);
        l_pdv_indikator_prefix   varchar2(32);
    begin
        l_redni_broj := get_broj_stavke(p_glavna_knjiga_id => p_glavna_knjiga_id);
        if p_pdv_indikator_id is null then
            get_glavna_knjiga(
                p_id                 => p_glavna_knjiga_id,
                p_vrsta_naloga_sifra => l_vrsta_naloga_sifra
            );
            if l_vrsta_naloga_sifra in ( 'if', 'ifs', 'av', 'avs' ) then
                l_pdv_indikator_id := sif.acc_pkg.get_pdv_indikator_id(
                    p_ui    => 'I',
                    p_sifra => 'XI'
                );

            else
                l_pdv_indikator_id := sif.acc_pkg.get_pdv_indikator_id(
                    p_ui    => 'U',
                    p_sifra => 'XU'
                );
            end if;

        end if;

        -- Provjera da odredjeni indikatori mogu biti samo na kontima 47/27
        if l_vrsta_naloga_sifra != 'pdv' then
            sif.acc_pkg.get_pdv_indikator(
                p_id                  => l_pdv_indikator_id,
                p_sifra               => l_pdv_indikator_sifra,
                p_kontna_klasa_prefix => l_pdv_indikator_prefix
            );

            sif.acc_pkg.get_kontni_okvir_klasa(
                p_id            => p_kontna_klasa_id,
                p_code          => l_kontna_klasa_code,
                p_pdv_indikator => l_kontna_klasa_indikator
            );

            if l_kontna_klasa_indikator = 'Y' then
                if ( l_kontna_klasa_code not like coalesce(l_pdv_indikator_prefix, 0)
                                                  || '%' ) then
                    raise_application_error(-20001, 'Na konto '
                                                    || l_kontna_klasa_code
                                                    || ' indikator '
                                                    || l_pdv_indikator_sifra
                                                    || ' nije odgovarajući. 1');

                end if;
            end if;

            if l_pdv_indikator_prefix is not null then
                if ( l_kontna_klasa_code not like coalesce(l_pdv_indikator_prefix, 0)
                                                  || '%' ) then
                    raise_application_error(-20001, 'Na konto '
                                                    || l_kontna_klasa_code
                                                    || ' indikator '
                                                    || l_pdv_indikator_sifra
                                                    || ' nije odgovarajući. 2');

                end if;
            end if;

        end if;

        insert into glavna_knjiga_stavke (
            glavna_knjiga_id,
            kontna_klasa_id,
            klijent_id,
            redni_broj,
            tip_stavke,
            opis,
            grad_id,
            iznos,
            osnovno_sredstvo_id,
            transakcija_id,
            os_datum,
            interni_nalog,
            pdv_indikator_id,
            oj_id,
            radnik_id,
            dodjela, 
            datum_dokumenta, 
            otvorena, 
            otvoreni_iznos,
            mjesto_troska_id, 
            acc_radnik_id
        ) values ( p_glavna_knjiga_id,
                   p_kontna_klasa_id,
                   p_klijent_id,
                   l_redni_broj,
                   p_tip_stavke,
                   p_opis,
                   p_grad_id,
                   round(p_iznos, 2),
                   p_osnovno_sredstvo_id,
                   p_transakcija_id,
                   p_os_datum,
                   p_interni_nalog,
                   l_pdv_indikator_id,
                   p_oj_id,
                   p_radnik_id,
                   p_dodjela, 
                   p_datum_dokumenta,
                   p_otvorena, 
                   p_otvoreni_iznos, 
                   p_mjesto_troska_id,
                   p_acc_radnik_id )
         returning id into p_id;

    end insert_glavna_knjiga_stavka;

    -- Insert za izvod  
    procedure insert_glavna_knjiga_stavka (
        p_glavna_knjiga_id      in number,
        p_kontna_klasa_id       in number,
        p_klijent_id            in number,
