    ) is
        l_redni_broj number;
        l_tip_stavke varchar2(1);
    begin
        if p_iznos > 0 then
            l_tip_stavke := 'D';
        else
            l_tip_stavke := 'P';
        end if;

        l_redni_broj := get_broj_stavke(p_glavna_knjiga_id => p_glavna_knjiga_id);
        insert into glavna_knjiga_stavke (
            glavna_knjiga_id,
            kontna_klasa_id,
            klijent_id,
            redni_broj,
            tip_stavke,
            tip_stavke_izvoda,
            opis,
            grad_id,
            iznos,
            prihod_rashod,
            vrsta_prihoda_id,
            vrsta_rashoda_id,
            nacin_placanja_izvoda,
            automatska,
            valuta_id,
            valuta_iznos,
            kurs,
            kif_id,
            kuf_id,
            priznat_rashod
        ) values ( p_glavna_knjiga_id,
                   p_kontna_klasa_id,
                   p_klijent_id,
                   l_redni_broj,
                   l_tip_stavke,
                   p_tip_stavke_izvoda,
                   p_opis,
                   p_grad_id,
                   round(p_iznos, 2),
                   p_prihod_rashod,
                   p_vrsta_prihoda_id,
                   p_vrsta_rashoda_id,
                   p_nacin_placanja_izvoda,
                   p_automatska,
                   p_valuta_id,
                   p_valuta_iznos,
                   p_kurs,
                   p_kif_id,
                   p_kuf_id,
                   p_priznat_rashod );

    end insert_glavna_knjiga_stavka;
    
    
