    -- Update za nalog za knjizenje
    procedure update_glavna_knjiga_stavka (
        p_id                  in number,
        p_glavna_knjiga_id    in number,
        p_kontna_klasa_id     in number,
        p_klijent_id          in number,
        p_redni_broj          in number,
        p_tip_stavke          in varchar2,
        p_opis                in varchar2,
        p_iznos               in number,
        p_grad_id             in number,
        p_osnovno_sredstvo_id in number,
        p_transakcija_id      in number,
        p_os_datum            in date,
        p_interni_nalog       in varchar2,
        p_pdv_indikator_id    in number,
        p_oj_id               in number,
        p_radnik_id           in number,
        p_dodjela             in varchar2,
        p_datum_dokumenta     in date, 
        p_otvorena            in varchar2,
        p_otvoreni_iznos      in number,
        p_mjesto_troska_id    in number,
        p_acc_radnik_id       in number

    ) is

        l_vrsta_naloga_sifra     varchar2(64);
        l_pdv_indikator_id       number := p_pdv_indikator_id;
        l_kontna_klasa_code      varchar2(32);
        l_kontna_klasa_indikator varchar2(1);
        l_pdv_indikator_sifra    varchar2(2);
        l_pdv_indikator_prefix   varchar2(32);
    begin
        if p_pdv_indikator_id is null then
            get_glavna_knjiga(
                p_id                 => p_glavna_knjiga_id,
                p_vrsta_naloga_sifra => l_vrsta_naloga_sifra
            );
            if l_vrsta_naloga_sifra in ( 'if', 'ifs', 'av', 'avs' ) then
                l_pdv_indikator_id := sif.acc_pkg.get_pdv_indikator_id(
                    p_ui    => 'I',
                    p_sifra => 'XI'
                );

            else
                l_pdv_indikator_id := sif.acc_pkg.get_pdv_indikator_id(
                    p_ui    => 'U',
                    p_sifra => 'XU'
                );
            end if;

        end if;

        -- Provjera da odredjeni indikatori mogu biti samo na kontima 47/27
        if l_vrsta_naloga_sifra != 'pdv' then
            sif.acc_pkg.get_pdv_indikator(
                p_id                  => l_pdv_indikator_id,
                p_sifra               => l_pdv_indikator_sifra,
                p_kontna_klasa_prefix => l_pdv_indikator_prefix
            );

            sif.acc_pkg.get_kontni_okvir_klasa(
                p_id            => p_kontna_klasa_id,
                p_code          => l_kontna_klasa_code,
                p_pdv_indikator => l_kontna_klasa_indikator
            );

            if l_kontna_klasa_indikator = 'Y' then
                if ( l_kontna_klasa_code not like coalesce(l_pdv_indikator_prefix, 0)
                                                  || '%' ) then
                    raise_application_error(-20001, 'Na konto '
                                                    || l_kontna_klasa_code
                                                    || ' indikator '
                                                    || l_pdv_indikator_sifra
                                                    || ' nije odgovarajući. 1');

                end if;
            end if;

            if l_pdv_indikator_prefix is not null then
                if ( l_kontna_klasa_code not like coalesce(l_pdv_indikator_prefix, 0)
                                                  || '%' ) then
                    raise_application_error(-20001, 'Na konto '
                                                    || l_kontna_klasa_code
                                                    || ' indikator '
                                                    || l_pdv_indikator_sifra
                                                    || ' nije odgovarajući. 2');

                end if;
            end if;

        end if;

        update glavna_knjiga_stavke
        set
            glavna_knjiga_id = p_glavna_knjiga_id,
            kontna_klasa_id = p_kontna_klasa_id,
            klijent_id = p_klijent_id,
            redni_broj = p_redni_broj,
            tip_stavke = p_tip_stavke,
            opis = p_opis,
            iznos = p_iznos,
            grad_id = p_grad_id,
            osnovno_sredstvo_id = p_osnovno_sredstvo_id,
            transakcija_id = p_transakcija_id,
            os_datum = p_os_datum,
            interni_nalog = p_interni_nalog,
            pdv_indikator_id = l_pdv_indikator_id,
            oj_id = p_oj_id,
            radnik_id = p_radnik_id,
            dodjela = p_dodjela,
            datum_dokumenta = p_datum_dokumenta,
            otvorena = p_otvorena,
            otvoreni_iznos = p_otvoreni_iznos, 
            mjesto_troska_id = p_mjesto_troska_id,
            acc_radnik_id = p_acc_radnik_id
            
        where
            id = p_id;

    end update_glavna_knjiga_stavka;
    
    procedure update_glavna_knjiga_stavka_dodjela (
        p_id      in number,
        p_dodjela in varchar2
    ) is
    begin
        update glavna_knjiga_stavke
        set
