    ---djordjije 28.07 -- brisanje veznog dokumenta
    procedure delete_glavna_knjiga_stavka (
        p_id in number
    ) is
    begin
      
            ---brisanje veznog dokumenta--
        delete from gk_stavke_dokument gks
        where
            gks.glavna_knjiga_stavka_id = p_id;
            
        delete from glavna_knjiga_stavke
        where
            id = p_id;
            


    end delete_glavna_knjiga_stavka;

    procedure copy_glavna_knjiga_stavke (
