            klijent_id,
            redni_broj,
            tip_stavke,
            opis,
            grad_id,
            iznos,
            osnovno_sredstvo_id,
            transakcija_id,
            interni_nalog,
            pdv_indikator_id,
            oj_id,
            radnik_id
        )
            select
                p_nalog_id,
                kontna_klasa_id,
                klijent_id,
                redni_broj,
                tip_stavke,
                opis,
                grad_id,
                round(iznos, 2),
                osnovno_sredstvo_id,
                transakcija_id,
                interni_nalog,
                pdv_indikator_id,
                oj_id,
                radnik_id
            from
                glavna_knjiga_stavke
            where
                glavna_knjiga_id = p_copy_id;

    end copy_glavna_knjiga_stavke;

    --------------------------------------------------------------
    -- procedures for AUTOMATION
    --------------------------------------------------------------

    function knjizi_plate (
        p_ooj_id      in number,
        p_mjesec      in date,
        p_proknjizeno in varchar2
    ) return number is
        -- Nalog
        l_nalog_id        number;
        l_broj            number;
        l_vrsta_naloga_id number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('pl');
        l_godina          number := extract(year from p_mjesec);
        l_mjesec          varchar2(255) := hrm.plate_pkg.month_name(p_mjesec);
        l_datum           date := last_day(p_mjesec);
        l_opis            varchar2(255) := 'Plata za '
                                || l_mjesec
                                || ' '
                                || l_godina;
        cursor c_tipovi_ugovora is
        (
            select distinct
                tip_ugovora_id
            from
                hrm.vw_pl_plate
            where
                    ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
        );

    begin
        l_broj := get_broj_naloga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => l_godina
        );

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => l_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => l_datum,
            p_datum_knjizenja => l_datum,
            p_opis            => l_opis
        );

        for tip in c_tipovi_ugovora loop
            case
                when tip.tip_ugovora_id in ( 1, 6 ) then
                    knjizi_plate_puno_radno_vrijeme(
                        p_nalog_id       => l_nalog_id,
                        p_ooj_id         => p_ooj_id,
                        p_mjesec         => p_mjesec,
                        p_tip_ugovora_id => tip.tip_ugovora_id
                    );
                when tip.tip_ugovora_id = 2 then
                    knjizi_plate_stipendija(
                        p_nalog_id       => l_nalog_id,
                        p_ooj_id         => p_ooj_id,
                        p_mjesec         => p_mjesec,
                        p_tip_ugovora_id => tip.tip_ugovora_id
                    );
                when tip.tip_ugovora_id = 3 then
                    knjizi_plate_djelo_dopunski_rad(
                        p_nalog_id       => l_nalog_id,
                        p_ooj_id         => p_ooj_id,
                        p_mjesec         => p_mjesec,
                        p_tip_ugovora_id => tip.tip_ugovora_id
                    );
                when tip.tip_ugovora_id = 4 then
                    knjizi_plate_menadzerski_ugovor(
                        p_nalog_id       => l_nalog_id,
                        p_ooj_id         => p_ooj_id,
                        p_mjesec         => p_mjesec,
                        p_tip_ugovora_id => tip.tip_ugovora_id
                    );
                when tip.tip_ugovora_id in ( 5, 7 ) then
                    knjizi_plate_privremeni_povremeni(
                        p_nalog_id       => l_nalog_id,
                        p_ooj_id         => p_ooj_id,
                        p_mjesec         => p_mjesec,
                        p_tip_ugovora_id => tip.tip_ugovora_id
                    );
                else
                    raise_application_error(-20111, 'Pogrešna vrsta ugovora.');
            end case;
        end loop;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        knjizi_obustave_plate(
            p_ooj_id      => p_ooj_id,
            p_mjesec      => p_mjesec,
            p_proknjizeno => p_proknjizeno
        );
        return l_nalog_id;
    end knjizi_plate;

    procedure knjizi_plate_puno_radno_vrijeme (
        p_nalog_id       in number,
        p_ooj_id         in number,
        p_mjesec         in date,
        p_tip_ugovora_id in number
    ) is

        l_stavka_gk_id        number;
        l_godina              number := extract(year from p_mjesec);
        l_mjesec              number := extract(month from p_mjesec);
        l_opis                varchar2(255) := 'Plata za '
                                || l_mjesec
                                || '/'
                                || l_godina; 

        -- Konta
        l_konto_neto_p        number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_neto_p
        );
        l_konto_bolovanje_p   number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_bolovanje_p
        );
        l_konto_porez_p       number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_porez_p
        );
        l_konto_doprinos_p    number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_doprinos_p
        );
        l_konto_odbici_p      number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_odbici_p
        );
        l_konto_topli_obrok_p number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_topli_obrok_p
        );
        l_konto_prevoz        number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_prevoz
        );
        l_konto_bruto_d       number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_bruto_d
        );
        l_konto_topli_obrok_d number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_topli_obrok_d
        );
        l_konto_prevoz_d      number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_prevoz_d
        );
        l_konto_minuli_d      number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_minuli_d
        );
        l_konto_bolovanje_d   number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_bolovanje_d
        );
        l_konto_inv_d         number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_inv_d
        );
        l_konto_inv_p         number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_inv_p
        );
        cursor c_porezi is
        (
            select
                round(
                    sum(porez_dohodak),
                    2
                )              as porez_dohodak,
                radnik_grad_id as grad_id
            from
                hrm.vw_pl_plate
            where
                    tip_ugovora_id = p_tip_ugovora_id
                and ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
            group by
                radnik_grad_id
        );

        cursor c_podaci is
        (
            select
                coalesce(
                    round(
                        sum(neto_poslije_poreza),
                        2
                    ),
                    0
                ) as neto_iznos,
                coalesce(
                    round(
                        sum(redovan_rad_neto_iznos),
                        2
                    ),
                    0
                ) as redovan_rad_neto_iznos,
                coalesce(
                    round(
                        sum(ukupno_dadzbina),
                        2
                    ),
                    0
                ) as doprinos,
                coalesce(
                    round(
                        sum(poreska_umanjenje),
                        2
                    ),
                    0
                ) as poreski_odbici,
                coalesce(
                    round(
                        sum(topli_obrok_isplata),
                        2
                    ),
                    0
                ) as topli_obrok_neto,
                coalesce(
                    round(
                        sum(prevoz),
                        2
                    ),
                    0
                ) as prevoz,
                coalesce(
                    round(
                        sum(iznos_bruto),
                        2
                    ),
                    0
                ) as bruto_iznos,
                coalesce(
                    round(
                        sum(redovan_rad_iznos),
                        2
                    ),
                    0
                ) as redovan_rad_iznos,
                coalesce(
                    round(
                        sum(bolovanje_iznos),
                        2
                    ),
                    0
                ) as bolovanje_iznos,
                coalesce(
                    round(
                        sum(porodiljsko_iznos),
                        2
                    ),
                    0
                ) as porodiljsko_iznos,
                coalesce(
                    round(
                        sum(minuli_rad),
                        2
                    ),
                    0
                ) as minuli_rad,
                coalesce(
                    round(
                        sum(topli_obrok),
                        2
                    ),
                    0
                ) as topli_obrok_bruto
            from
                hrm.vw_pl_plate
            where
                    tip_ugovora_id = p_tip_ugovora_id
                and ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
        );

        cursor c_podaci_oj is
        (
            select
                coalesce(
                    round(
                        sum(neto_poslije_poreza),
                        2
                    ),
                    0
                ) as neto_iznos,
                coalesce(
                    round(
                        sum(redovan_rad_neto_iznos),
                        2
                    ),
                    0
                ) as redovan_rad_neto_iznos,
                coalesce(
                    round(
                        sum(ukupno_dadzbina),
                        2
                    ),
                    0
                ) as doprinos,
                coalesce(
                    round(
                        sum(poreska_umanjenje),
                        2
                    ),
                    0
                ) as poreski_odbici,
                coalesce(
                    round(
                        sum(topli_obrok_isplata),
                        2
                    ),
                    0
                ) as topli_obrok_neto,
                coalesce(
                    round(
                        sum(prevoz),
                        2
                    ),
                    0
                ) as prevoz,
                coalesce(
                    round(
                        sum(iznos_bruto),
                        2
                    ),
                    0
                ) as bruto_iznos,
                coalesce(
                    round(
                        sum(redovan_rad_iznos),
                        2
                    ),
                    0
                ) as redovan_rad_iznos,
                coalesce(
                    round(
                        sum(bolovanje_iznos),
                        2
                    ),
                    0
                ) as bolovanje_iznos,
                coalesce(
                    round(
                        sum(bruto_umanjenje),
                        2
                    ),
                    0
                ) as bruto_umanjenje_iznos,
                coalesce(
                    round(
                        sum(porodiljsko_iznos),
                        2
                    ),
                    0
                ) as porodiljsko_iznos,
                coalesce(
                    round(
                        sum(minuli_rad),
                        2
                    ),
                    0
                ) as minuli_rad,
                coalesce(
                    round(
                        sum(topli_obrok),
                        2
                    ),
                    0
                ) as topli_obrok_bruto,
                oj_id
            from
                hrm.vw_pl_plate
            where
                    tip_ugovora_id = p_tip_ugovora_id
                and ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
            group by
                oj_id
        );

        cursor c_doprinos_invalidi is
        (
            select
                round(sum(ukupno_troskova) * hrm.plate_pkg.fn_koeficijent('DOP_INV_RS', 1),
                      2) as doprinos_inv
            from
                hrm.vw_pl_plate
            where
                    tip_ugovora_id = p_tip_ugovora_id
                and ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
        );

    begin
         /* **************************

            Potrazna strana (-)

        ************************** */

        -- Porez - 4510
        for porez in c_porezi loop
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_porez_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(porez.porez_dohodak * - 1),
                p_grad_id          => porez.grad_id,
                p_id     =>l_stavka_gk_id
            );
        end loop;

        for c1 in c_podaci loop
            -- Redovan rad (neto) - 4500
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_neto_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(c1.redovan_rad_neto_iznos - c1.topli_obrok_neto) *(- 1),
                p_id               =>l_stavka_gk_id
                
            ); 

            -- Bolovanje, godisnji (i ostalo..) - 4502
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_bolovanje_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(c1.neto_iznos - c1.redovan_rad_neto_iznos) *(- 1),
                p_id               => l_stavka_gk_id
            ); 

            -- Doprinos - 4520
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_doprinos_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            => (c1.doprinos * - 1),
                p_id               => l_stavka_gk_id
            ); 

            -- Poreske kartice - 45101
--            insert_glavna_knjiga_stavka(
--                p_glavna_knjiga_id => p_nalog_id,
--                p_kontna_klasa_id  => l_konto_odbici_p,
--                p_tip_stavke       => 'P',
--                p_opis             => l_opis,
--                p_iznos            =>(c1.poreski_odbici * - 1)
--            ); 

            -- Topli obrok (neto) - 4560
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_topli_obrok_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(c1.topli_obrok_neto * - 1),
                p_id               => l_stavka_gk_id
            ); 

            -- Prevoz - 4632
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_prevoz,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(c1.prevoz * - 1),
                p_id               => l_stavka_gk_id
            );

        end loop;

        for c1 in c_podaci_oj loop
            /* **************************

                Dugovna strana (+)

            ************************** */
            -- Redovan rad (bruto) - 5200
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_bruto_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => (c1.bruto_iznos - (c1.bolovanje_iznos + c1.porodiljsko_iznos)),
                p_oj_id            => c1.oj_id,
                p_id               => l_stavka_gk_id
            ); 

            -- Bolovanje - 5293
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_bolovanje_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => c1.bolovanje_iznos + c1.porodiljsko_iznos - c1.bruto_umanjenje_iznos,
                p_oj_id            => c1.oj_id,
                p_id               => l_stavka_gk_id
            ); 

            -- Topli obrok (bruto) - 5290
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_topli_obrok_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => c1.topli_obrok_bruto,
                p_oj_id            => c1.oj_id,
                p_id               => l_stavka_gk_id
            ); 

            -- Minuli rad - 5219
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_minuli_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => c1.minuli_rad,
                p_oj_id            => c1.oj_id,
                p_id               => l_stavka_gk_id
            ); 

            -- Prevoz - 5210
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_prevoz_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => c1.prevoz,
                p_oj_id            => c1.oj_id,
                p_id               => l_stavka_gk_id
            );

        end loop;

        -- Doprinos invalidi
        for doprinos in c_doprinos_invalidi loop
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_inv_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(doprinos.doprinos_inv * - 1),
                p_id               => l_stavka_gk_id
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => l_konto_inv_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            =>(doprinos.doprinos_inv),
                p_id               =>l_stavka_gk_id
            );

        end loop;

    end knjizi_plate_puno_radno_vrijeme;

    procedure knjizi_plate_stipendija (
        p_nalog_id       in number,
        p_ooj_id         in number,
        p_mjesec         in date,
        p_tip_ugovora_id in number
    ) is

        l_stavka_gk_id       number;
        l_godina             number := extract(year from p_mjesec);
        l_mjesec             number := extract(month from p_mjesec);
        l_opis               varchar2(255) := 'Stipendije '
                                || l_mjesec
                                || '/'
                                || l_godina; 

        -- Konta
        l_konto_stipendija_d number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id),
            p_code       => g_konto_stipendija_d
        );
        l_konto_stipendija_p number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id),
            p_code       => g_konto_stipendija_p
        );
        cursor c_podaci is
        (
            select
                coalesce(
                    round(
                        sum(iznos_bruto),
                        2
                    ),
                    0
                ) as bruto_iznos,
                coalesce(
                    round(
                        sum(neto_poslije_poreza),
                        2
                    ),
                    0
                ) as neto_iznos
            from
                hrm.vw_pl_plate
            where
                    tip_ugovora_id = p_tip_ugovora_id
                and ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
        );

        cursor c_podaci_oj is
        (
            select
                coalesce(
                    round(
                        sum(iznos_bruto),
                        2
                    ),
                    0
                ) as bruto_iznos,
                coalesce(
                    round(
                        sum(neto_poslije_poreza),
                        2
                    ),
                    0
                ) as neto_iznos,
                oj_id
            from
                hrm.vw_pl_plate
            where
                    tip_ugovora_id = p_tip_ugovora_id
                and ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
            group by
