            group by
                oj_id
        );

    begin
        if p_tip_ugovora_id = 5 then
            l_opis := 'Privremeni i povremeni - proizvodne usluge '
                      || l_mjesec
                      || '/'
                      || l_godina;
        elsif p_tip_ugovora_id = 7 then
            l_opis := 'Privremeni i povremeni - neproizvodne usluge '
                      || l_mjesec
                      || '/'
                      || l_godina;
        end if;

         /* **************************

