    procedure knjizi_obustave_plate (
        p_ooj_id      in number,
        p_mjesec      in date,
        p_proknjizeno in varchar2
    ) is
        -- Nalog
        l_stavka_gk_id         number;        
        l_nalog_id            number;
        l_broj                number;
        l_vrsta_naloga_id     number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('pl');
        l_godina              number := extract(year from p_mjesec);
        l_mjesec              number := extract(month from p_mjesec);
        l_datum               date := last_day(p_mjesec);
        l_opis                varchar2(255) := 'Obustave za '
                                || l_mjesec
                                || '/'
                                || l_godina; 

        -- Konta
        l_konto_obustave_p    number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_obustave_p
        );
        l_konto_solidarnost_p number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_solidarnost_p
        );
        l_konto_neto_d        number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_neto_p
        );
        cursor c_podaci is
        (
            select
                coalesce(
                    round(
                        sum(izos_obustave),
                        2
                    ),
                    0
                ) as obustave,
                coalesce(
                    round(
                        sum(rehabilitacija),
                        2
                    ),
                    0
                ) as fond_solidarnosti
            from
                hrm.vw_pl_plate
            where
                    ooj_id = p_ooj_id
                and trunc(datum_obracuna_od, 'MM') = trunc(p_mjesec, 'MM')
        );

    begin
        l_broj := get_broj_naloga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => l_godina
        );

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => l_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => l_datum,
            p_datum_knjizenja => l_datum,
            p_opis            => l_opis
        );

        for c1 in c_podaci loop
             /* **************************

                Potrazna strana (-)

            ************************** */
            -- Fond solidarnosti - 4833
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_solidarnost_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(c1.fond_solidarnosti * - 1),
                p_id               =>l_stavka_gk_id
            ); 

            -- Obustave - 4506
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_obustave_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            =>(c1.obustave * - 1),
                p_id               =>l_stavka_gk_id
            );   

            /* **************************

                Dugovna strana (+)

            ************************** */   
            -- Obustave - 4500
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_neto_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            =>(c1.obustave + c1.fond_solidarnosti),
                p_id               =>l_stavka_gk_id
            );

        end loop;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

    end knjizi_obustave_plate;

    function check_nalog_plate (
        p_nalog_id in number
    ) return varchar2 is
        l_sum_iznos number;
        l_sum_plata number;
        l_ooj_id    number;
        l_mjesec    date;
    begin
        select
            ooj_id,
            datum_knjizenja
        into
            l_ooj_id,
            l_mjesec
        from
            glavna_knjiga
        where
            id = p_nalog_id;

        select
            sum(iznos)
        into l_sum_iznos
        from
            glavna_knjiga_stavke
        where
                glavna_knjiga_id = p_nalog_id
            and iznos > 0;

        select
            sum(ukupno_troskova) + sum(prevoz)
        into l_sum_plata
        from
            hrm.vw_pl_plate
        where
                ooj_id = l_ooj_id
            and trunc(datum_obracuna_od, 'MM') = trunc(l_mjesec, 'MM');

        if l_sum_iznos = l_sum_plata then
            return 'Y';
        end if;
        return 'N';
    end check_nalog_plate;

    --------------------------------------------------------------
    -- procedures for AUTOMATION KREATNJA ROBE
    --------------------------------------------------------------

    function knjizi_operacije_pp (
        p_ooj_id          in number,
        p_godina          in number,
        p_tip_kretanja_id in varchar2,
        p_pp              in date,
        p_proknjizeno     in varchar2
    ) return number is

        cursor c_operacije is
        (
            select
                id
            from
                operacije
            where
                ooj_id = p_ooj_id
                and godina = p_godina
                and trunc(datum, 'MM') = trunc(p_pp, 'MM')
                and glavna_knjiga_id is null
                and valid = 'Y'
                and (tip_kretanja_id in (
                    select
                        column_value
                    from
                        apex_string.split(p_tip_kretanja_id, ':')
                ) or p_tip_kretanja_id IS null)
                and zakljucano = 'Y'
        )
        order by
            broj asc;

        l_nalog_id number;
        l_stavka_gk_id  number;          
    begin
        for kretanje_robe in c_operacije loop
            l_nalog_id := knjizi_operacija_single(
                p_id              => kretanje_robe.id,
                p_ooj_id          => p_ooj_id,
                p_godina          => p_godina,
                p_proknjizeno     => p_proknjizeno,
                p_collection_only => 'N'
            );
        end loop;

        return l_nalog_id;
    end knjizi_operacije_pp;

    function knjizi_operacija_single (
        p_id              in number,
        p_ooj_id          in number,
        p_godina          in number,
        p_proknjizeno     in varchar2,
        p_collection_only in varchar2
    ) return number is
        l_stavka_gk_id         number;
        l_nalog_id number;
        l_broj number;
        l_opis                 varchar2(255);  
                
        CURSOR c_stavke IS (
            SELECT
                grupa_id,
                sum(iznos) AS iznos
            FROM
                vw_operacija_stavke
            WHERE
                operacija_id = p_id
            GROUP BY
                grupa_id
        );
        
        CURSOR c_skladiste_stavka IS (
            SELECT
                sum(iznos) AS iznos
            FROM
                vw_operacija_stavke
            WHERE
                operacija_id = p_id
        );
        
        r_operacija vw_operacije%rowtype;
        r_skladiste vw_skladista%rowtype;
        
        l_tip_stavke varchar2(1);
        l_iznos      number;
        l_kontna_klasa_id number;
        
    begin
        apex_collection.create_or_truncate_collection(p_collection_name => 'OPERACIJA_KONTA');
        
        select * into r_operacija from vw_operacije where id = p_id;
        
        select * into r_skladiste from vw_skladista where id = r_operacija.skladiste_id;
        
        apex_debug.message('dbg1');
        
        -- Zaglavlje naloga za knjiženje
        if p_collection_only = 'N' then
        apex_debug.message('dbg1.1');
            l_opis := 'Automatsko knjiženje - ' || r_operacija.naziv;
            l_broj := get_broj_naloga(
                p_ooj_id          => p_ooj_id,
                p_vrsta_naloga_id => r_operacija.vrsta_naloga_id,
                p_godina          => p_godina
            );

            l_nalog_id := insert_glavna_knjiga(
                p_ooj_id          => p_ooj_id,
                p_vrsta_naloga_id => r_operacija.vrsta_naloga_id,
                p_godina          => p_godina,
                p_broj            => l_broj,
                p_datum_dokumenta => r_operacija.datum,
                p_datum_knjizenja => last_day(r_operacija.datum),
                p_opis            => l_opis
            );
            
        end if;
        
        -- Prvi stav (konto skladišta)
        apex_debug.message('dbg2');
        l_tip_stavke := 'D';
        
        for c1 in c_skladiste_stavka loop
        apex_debug.message('dbg2.2');
            l_iznos := c1.iznos;
        
            if p_collection_only = 'N' then
                insert_glavna_knjiga_stavka(
                    p_glavna_knjiga_id => l_nalog_id,
                    p_kontna_klasa_id  => r_skladiste.kontna_klasa_id,
                    p_tip_stavke       => l_tip_stavke,
                    p_opis             => l_opis,
                    p_iznos            => l_iznos,
                    p_id               => l_stavka_gk_id 
                );
                
            else
                apex_collection.add_member(
                    p_collection_name => 'OPERACIJA_KONTA',
                    p_c001            => r_skladiste.kontna_klasa_id,
                    p_c002            => l_tip_stavke,
                    p_c003            => l_iznos
                );
            end if;
        end loop;
        
        -- Stavovi po stavkama
        apex_debug.message('dbg3');
        for c2 in c_stavke loop
        apex_debug.message('dbg3.3');
            l_iznos := c2.iznos * -1;
            
            sif.acc_pkg.get_grupa_stavke_konta (
                p_grupa_stavke_id => c2.grupa_id,
                p_tip_kretanja_id => r_operacija.tip_kretanja_id,
                p_kontna_klasa_id => l_kontna_klasa_id,
                p_tip_stavke      => l_tip_stavke
            );
        
            if p_collection_only = 'N' then
                insert_glavna_knjiga_stavka(
                    p_glavna_knjiga_id => l_nalog_id,
                    p_kontna_klasa_id  => l_kontna_klasa_id,
                    p_tip_stavke       => l_tip_stavke,
                    p_opis             => l_opis,
                    p_iznos            => l_iznos,
                    p_id               => l_stavka_gk_id
                );
                
            else
                apex_collection.add_member(
                    p_collection_name => 'OPERACIJA_KONTA',
                    p_c001            => l_kontna_klasa_id,
                    p_c002            => l_tip_stavke,
                    p_c003            => l_iznos
                );
            end if;
        end loop;
        
        apex_debug.message('dbg4');
        -- Ako ima referencu na neki stornirani dokument..
        if r_operacija.storniran_id is not null then
        apex_debug.message('dbg4.4');
            update glavna_knjiga_stavke set
                iznos = -iznos,
                tip_stavke = decode(tip_stavke, 'D', 'P', 'P', 'D', tip_stavke)
            where
                glavna_knjiga_id = l_nalog_id;
        end if;
        
        apex_debug.message('dbg5');
        -- Ažuriramo operaciju da je knjižena
        apex_debug.message('dbg5.5');
        if p_collection_only = 'N' then
            UPDATE operacije SET
                glavna_knjiga_id = l_nalog_id
            WHERE
                id = p_id;
                
        end if;

        -- Knjižimo nalog
        apex_debug.message('dbg6');
        if p_proknjizeno = 'Y' then
        apex_debug.message('dbg6.6');
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_operacija_single;

    --------------------------------------------------------------
    -- procedures for AUTOMATION OS
    --------------------------------------------------------------

    function knjizi_os_aktiviranje (
        p_godina              in number,
        p_osnovno_sredstvo_id in number,
        p_priprema_id         in number,
        p_vrijednost          in number,
        p_datum               in date
    ) return number is 
        -- Nalog
        l_nalog_id            number;
        l_broj                number;
        l_vrsta_naloga_id     number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('os');
        l_opis                varchar2(255); 

        -- Konta
        l_konto_os_nabavka_d  number;
        l_konto_os_nabavka_p  number;

        -- Transakcije
        l_transakcija_nabavke  number := sif.acc_pkg.get_transakcija_id('nabavke');
        l_transakcija_pripreme number := sif.acc_pkg.get_transakcija_id('priprema');

        -- Osnovno sredstvo
        l_os                  t_sec_osnovna_sredstva;
        l_os_priprema         t_sec_osnovna_sredstva;
        l_stavka_gk_id  number;           
    begin
        -- Osnovno sredstvo koje nije u pripremi
        l_os := t_sec_osnovna_sredstva();
        l_os.id := p_osnovno_sredstvo_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os);

        -- Osnovno sredstvo koje je u pripremi
        l_os_priprema := t_sec_osnovna_sredstva();
        l_os_priprema.id := p_priprema_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os_priprema);
        l_opis := 'Aktiviranje osnovnog sredstva - '
                  || l_os.naziv
                  || ' ( '
                  || l_os.inventurni_naziv
                  || ' )';

        -- Kreiranje naloga
        l_broj := get_broj_naloga(
            p_ooj_id          => l_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina
        );

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => l_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => p_datum,
            p_datum_knjizenja => p_datum,
            p_opis            => l_opis
        );

        if p_vrijednost != 0 then

            -- **************************

            --  Sredstvo u pripremi

            -- **************************

            l_konto_os_nabavka_p := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => l_os_priprema.klasa_id,
                p_sifra    => 'priprema'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_os_nabavka_p,
                p_tip_stavke          => 'P',
                p_opis                => l_opis,
                p_iznos               =>(p_vrijednost * - 1),
                p_osnovno_sredstvo_id => l_os_priprema.id,
                p_transakcija_id      => l_transakcija_pripreme,
                p_os_datum            => p_datum,
                p_id                  => l_stavka_gk_id
            );

            -- **************************

            --  Sredstvo koje nije u pripremi

            -- **************************
            l_konto_os_nabavka_d := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => l_os.klasa_id,
                p_sifra    => 'nabavke'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_os_nabavka_d,
                p_tip_stavke          => 'D',
                p_opis                => l_opis,
                p_iznos               => p_vrijednost,
                p_osnovno_sredstvo_id => l_os.id,
                p_transakcija_id      => l_transakcija_nabavke,
                p_os_datum            => p_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        return l_nalog_id;
    end knjizi_os_aktiviranje;

    function knjizi_os_amortizcija_pp_list (
        p_ooj_id      in number,
        p_pp_list     in varchar2,
        p_proknjizeno in varchar2
    ) return number is

        cursor c_pp_list is
        (
            select
                to_date(column_value, 'MMYY') as datum
            from
                apex_string.split(p_pp_list, ':')
        )
        order by
            to_date(column_value, 'MMYY') asc;

        l_nalog_id number;
    begin
        for pp in c_pp_list loop
            l_nalog_id := knjizi_os_amortizcija_pp(
                p_ooj_id      => p_ooj_id,
                p_pp          => pp.datum,
                p_proknjizeno => p_proknjizeno
            );
        end loop;

        return l_nalog_id;
    end knjizi_os_amortizcija_pp_list;

    function knjizi_os_amortizcija_pp (
        p_ooj_id                  in number,
        p_pp                      in date,
        p_proknjizeno             in varchar2,
        p_automatska_amortizacija in varchar2 default 'N'
    ) return number is
        -- Nalog
        l_nalog_id                   number;
        l_broj                       number;
        l_vrsta_naloga_id            number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('os');
        l_datum                      date := last_day(trunc(p_pp, 'MM'));
        l_opis                       varchar2(255);
        l_godina                     number := extract(year from p_pp);
        l_stavka_gk_id               number; 
                  
        cursor c_os is
        (
            SELECT
                x.osnovno_sredstvo_id,
                x.inventurni_naziv,
                x.am_konto_d,
                x.am_konto_p,
                SUM(x.amortizacija) AS amortizacija
            FROM (
                SELECT
                    g.osnovno_sredstvo_id,
                    os.inventurni_naziv,
                    os.inventurni_broj,
                    g.iznos,
                    os.vijek_trajanja,
                    os.rezidualna_vrijednost,
                    
                    sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                        p_klasa_id => klasa_id,
                        p_sifra    => 'am_d'
                    ) as am_konto_d,
                    sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                        p_klasa_id => klasa_id,
                        p_sifra    => 'am_p'
                    ) as am_konto_p,
            
                    -- mjesečna amortizacija po nabavci
                    (g.iznos / (os.vijek_trajanja * 12)) AS mjesecna_amortizacija,
            
                    -- početak amortizacije
                    ADD_MONTHS(TRUNC(g.os_datum, 'MM'), 1) AS start_date,
            
                    -- koliko mjeseci je prošlo do izabranog mjeseca
                    FLOOR(
                        MONTHS_BETWEEN(
                            TRUNC(p_pp, 'MM'),
                            ADD_MONTHS(TRUNC(g.os_datum, 'MM'), 1)
                        )
                    ) + 1 AS broj_mjeseci,
            
                    -- amortizacija za TRAŽENI mjesec (ključni dio)
                    CASE
                        -- nije još krenula amortizacija
                        WHEN TRUNC(p_pp, 'MM') < ADD_MONTHS(TRUNC(g.os_datum, 'MM'), 1)
                            THEN 0
            
                        -- prošao cijeli vijek
                        WHEN FLOOR(
                                MONTHS_BETWEEN(
                                    TRUNC(p_pp, 'MM'),
                                    ADD_MONTHS(TRUNC(g.os_datum, 'MM'), 1)
                                )
                             ) >= os.vijek_trajanja * 12
                            THEN 0
            
                        ELSE
                            -- izračun preostale vrijednosti prije ovog mjeseca
                            LEAST(
                                -- standardna mjesečna
                                (g.iznos / (os.vijek_trajanja * 12)),
            
                                -- koliko još smije amortizovati (do rezidualne)
                                GREATEST(
                                    0,
                                    g.iznos
                                    - (
                                        (g.iznos / (os.vijek_trajanja * 12))
                                        * (
                                            FLOOR(
                                                MONTHS_BETWEEN(
                                                    TRUNC(p_pp, 'MM'),
                                                    ADD_MONTHS(TRUNC(g.os_datum, 'MM'), 1)
                                                )
                                            )
                                        )
                                    )
                                    - os.rezidualna_vrijednost
                                )
                            )
                    END AS amortizacija
            
                FROM
                    glavna_knjiga_stavke g
                JOIN
                    sec_osnovna_sredstva os ON os.id = g.osnovno_sredstvo_id
                WHERE
                    g.transakcija_id = 2
                    and os.valid = 'Y'
                    and os.ooj_id = p_ooj_id
                    and os.aktivirano = 'Y'
                    and os.history_id is null
            ) x
            GROUP BY
                ALL
        );
        

        -- Vrijednosti
        l_os                         t_sec_osnovna_sredstva;
        l_transakcija_am_p           number := sif.acc_pkg.get_transakcija_id('am_p');
        l_count                      number := 0;
    begin
        l_opis := 'Amortizacija OS - ' || to_char(l_datum, 'MM.YYYY');
        dbms_output.put_line(l_opis);

        -- Kreiranje naloga
        l_broj := get_broj_naloga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => l_godina
        );

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => l_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => l_datum,
            p_datum_knjizenja => l_datum,
            p_opis            => l_opis
        );

        for os in c_os loop
            l_count := l_count + 1;

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => os.am_konto_d,
                p_tip_stavke       => 'D',
                p_opis             => 'Amortizacija - ' || os.inventurni_naziv,
                p_iznos            => os.amortizacija * - 1,
                p_id                  => l_stavka_gk_id
--                p_os_datum         => last_day(p_pp)
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => os.am_konto_p,
                p_tip_stavke          => 'P',
                p_opis                => 'Amortizacija - ' || os.inventurni_naziv,
                p_iznos               => os.amortizacija,
                p_osnovno_sredstvo_id => os.osnovno_sredstvo_id,
                p_transakcija_id      => l_transakcija_am_p,
                p_os_datum            => last_day(p_pp),
                p_id                  => l_stavka_gk_id
            );
        end loop;

        -- Ukoliko nije bilo OS izbrisi nalog..
        if l_count = 0 then
            delete_glavna_knjiga(p_id => l_nalog_id);
            l_nalog_id := null;
        end if;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_os_amortizcija_pp;
    
    function knjizi_os_otpis (
        p_os          in out t_sec_osnovna_sredstva,
        p_godina      in number,
        p_kolicina    in number,
        p_proknjizeno in varchar2
    ) return number is
        -- Nalog
        l_nalog_id             number;
        l_broj                 number;
        l_vrsta_naloga_id      number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('os');
        l_datum                date := p_os.otpis_datum;
        l_opis                 varchar2(255); 

        -- Konta
        l_konto_nabavka_p      number;
        l_konto_amortizacija_d number;
        l_konto_otpis_d        number;

        -- Transakcije
        l_transakcija_otpis    number := sif.acc_pkg.get_transakcija_id('otpis');
        l_transakcija_am_p     number := sif.acc_pkg.get_transakcija_id('am_p');
        l_transakcija_nabavke  number := sif.acc_pkg.get_transakcija_id('nabavke');

        -- Osnovno sredstvo
        l_procenat             number;
        l_vrijednost_nabavka   number;
        l_vrijednost_am_p      number;
        l_vrijednost_otpis     number;
        
        -- Trenutne vrijednosti
        l_trenutno_nabavka         number;
        l_trenutno_amortizacija    number;
        l_trenutno_knjigovodstvena number;
        --stavka gk
        l_stavka_gk_id  number;   
    begin
        l_procenat := 1 - ( p_kolicina / p_os.kolicina );
        l_opis := 'Otpis osnovnog sredstva - '
                  || p_os.naziv
                  || ' ( '
                  || p_os.inventurni_naziv
                  || ' )';

        l_broj := get_broj_naloga(
            p_ooj_id          => p_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina
        );
        
        l_trenutno_nabavka := os_pkg.get_vrijednost_nabavka(p_os.id, l_datum);
        l_trenutno_amortizacija := os_pkg.get_amortizacija_do_datuma(p_os.id, l_datum);
        l_trenutno_knjigovodstvena := os_pkg.get_knjigovodstvena_vrijednost(p_os.id);

        l_vrijednost_nabavka := ( l_trenutno_nabavka * l_procenat * -1 );
        l_vrijednost_am_p := ( l_trenutno_amortizacija ) * l_procenat;
        l_vrijednost_otpis := l_trenutno_knjigovodstvena * l_procenat;
        
        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => l_datum,
            p_datum_knjizenja => l_datum,
            p_opis            => l_opis
        );

        -- **************************

        --  Potrazna strana - Nabavna vrijednost

        -- **************************
        if l_vrijednost_nabavka != 0 then
            l_konto_nabavka_p := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'nabavke'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_nabavka_p,
                p_tip_stavke          => 'P',
                p_opis                => l_opis,
                p_iznos               => l_vrijednost_nabavka,
                p_osnovno_sredstvo_id => p_os.id,
                p_transakcija_id      => l_transakcija_nabavke,
                p_os_datum            => l_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        -- **************************

        --  Dugovna strana - Suma amortizacija do sad + (Nabavna vrijednost, Suma amortizacija do sad)

        -- **************************
        if l_vrijednost_am_p != 0 then
            l_konto_amortizacija_d := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'am_p'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_amortizacija_d,
                p_tip_stavke          => 'D',
                p_opis                => l_opis,
                p_iznos               => l_vrijednost_am_p,
                p_osnovno_sredstvo_id => p_os.id,
                p_transakcija_id      => l_transakcija_am_p,
                p_os_datum            => l_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        -- Otpis
        if l_vrijednost_otpis != 0 then
            l_konto_otpis_d := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'otpis'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_otpis_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => l_vrijednost_otpis,
                p_osnovno_sredstvo_id => p_os.id,
                p_transakcija_id      => l_transakcija_otpis,
                p_os_datum            => l_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_os_otpis;

    function knjizi_os_prodaja (
        p_os                  in out t_sec_osnovna_sredstva,
        p_godina              in number,
        p_kolicina            in number,
        p_proknjizeno         in varchar2,
        p_prodajna_vrijednost in number,
        p_datum               in date
    ) return number is
        -- Nalog
        l_nalog_id             number;
        l_broj                 number;
        l_vrsta_naloga_id      number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('os');
        l_opis                 varchar2(255); 

        -- Konta
        l_konto_nabavka_p      number;
        l_konto_amortizacija_d number;
        l_konto_os_prodaja_d   number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_os.ooj_id),
            p_code       => g_konto_os_prodaja_d
        );
        l_konto_dobitak_p      number;
        l_konto_gubitak_d      number;

        -- Transakcije
        l_transakcija_prodaja  number;
        l_transakcija_am_p     number := sif.acc_pkg.get_transakcija_id('am_p');
        l_transakcija_nabavke  number := sif.acc_pkg.get_transakcija_id('nabavke');

        -- Osnovno sredstvo
        l_procenat             number;
        l_razlika              number;
        l_vrijednost_nabavka   number;
        l_vrijednost_am_p      number;
        
        -- Trenutne vrijednosti
        l_trenutno_nabavka         number;
        l_trenutno_amortizacija    number;
        l_trenutno_knjigovodstvena number;
        --stavka GK
        l_stavka_gk_id  number;   
    begin
        l_procenat := 1 - ( p_kolicina / p_os.kolicina );
        l_opis := 'Prodaja osnovnog sredstva - '
                  || p_os.naziv
                  || ' ( '
                  || p_os.inventurni_naziv
                  || ' )';

        l_broj := get_broj_naloga(
            p_ooj_id          => p_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina
        );
        
        l_trenutno_nabavka := os_pkg.get_vrijednost_nabavka(p_os.id, p_datum);
        l_trenutno_amortizacija := os_pkg.get_amortizacija_do_datuma(p_os.id, p_datum);
        l_trenutno_knjigovodstvena := os_pkg.get_knjigovodstvena_vrijednost(p_os.id);

        l_vrijednost_nabavka := ( l_trenutno_nabavka * l_procenat * -1 );
        l_vrijednost_am_p := ( l_trenutno_amortizacija ) * l_procenat;
        l_razlika := p_prodajna_vrijednost - ( l_trenutno_knjigovodstvena * l_procenat );
        
        if l_razlika > 0 then -- Dobitak
            l_transakcija_prodaja := sif.acc_pkg.get_transakcija_id('pr_d');
        elsif l_razlika < 0 then
            l_transakcija_prodaja := sif.acc_pkg.get_transakcija_id('pr_g');
        end if;

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => p_datum,
            p_datum_knjizenja => p_datum,
            p_opis            => l_opis
        );

        -- **************************

        --  Potrazna strana - Nabavna vrijednost

        -- **************************
        if l_vrijednost_nabavka != 0 then
            l_konto_nabavka_p := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'nabavke'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_nabavka_p,
                p_tip_stavke          => 'P',
                p_opis                => l_opis,
                p_iznos               => l_vrijednost_nabavka,
                p_osnovno_sredstvo_id => p_os.id,
                p_transakcija_id      => l_transakcija_nabavke,
                p_os_datum            => p_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        -- **************************

        --  Dugovna strana - Trenutna amortizacija + Prodajna vrijednost

        -- **************************
        if l_vrijednost_am_p != 0 then
            l_konto_amortizacija_d := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'am_p'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_amortizacija_d,
                p_tip_stavke          => 'D',
                p_opis                => l_opis,
                p_iznos               => l_vrijednost_am_p,
                p_osnovno_sredstvo_id => p_os.id,
                p_transakcija_id      => l_transakcija_am_p,
                p_os_datum            => p_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        insert_glavna_knjiga_stavka(
            p_glavna_knjiga_id => l_nalog_id,
            p_kontna_klasa_id  => l_konto_os_prodaja_d,
            p_tip_stavke       => 'D',
            p_opis             => l_opis,
            p_iznos            => p_prodajna_vrijednost,
            p_osnovno_sredstvo_id => p_os.id,
            p_transakcija_id      => l_transakcija_prodaja,
            p_os_datum            => p_datum,
            p_id                  => l_stavka_gk_id
        );  

        -- **************************

        --  Potrazna / Dugovna strana  - Razlika

        -- **************************

        if l_razlika > 0 then -- Dobitak
            l_konto_dobitak_p := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'pr_d'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_dobitak_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            => l_razlika * - 1,
                p_id                  => l_stavka_gk_id
            );

        elsif l_razlika < 0 then -- Gubitak
            l_konto_gubitak_d := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'pr_g'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_gubitak_d,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            => l_razlika * - 1,
                p_id               => l_stavka_gk_id
            );

        end if;
        
        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_os_prodaja;    
    
