    function knjizi_os_prenos (
        p_os          in out t_sec_osnovna_sredstva,
        p_os_prenos   in out t_sec_osnovna_sredstva,
        p_datum       in date,
        p_godina      in number,
        p_kolicina    in number,
        p_proknjizeno in varchar2
    ) return number is
        -- Nalog
        l_nalog_id             number;
        l_broj                 number;
        l_vrsta_naloga_id      number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('os');
        l_datum                date := sysdate;
        l_opis                 varchar2(255); 

        -- Konta
        l_konto_nabavka_p      number;
        l_konto_amortizacija_p number;
        l_konto_nabavka_d      number;
        l_konto_amortizacija_d number;

        -- Transakcije
        l_transakcija_prenos   number := sif.acc_pkg.get_transakcija_id('prenos');
        l_transakcija_am_p     number := sif.acc_pkg.get_transakcija_id('am_p');
        l_transakcija_nabavke  number := sif.acc_pkg.get_transakcija_id('nabavke');

        -- Osnovno sredstvo
        l_procenat             number;
        l_vrijednost_nabavka   number;
        l_vrijednost_am_p      number;
        
        -- Trenutne vrijednosti
        l_trenutno_nabavka         number;
        l_trenutno_amortizacija    number;
        l_trenutno_knjigovodstvena number;
        
        --stavka GK
        l_stavka_gk_id  number;         
    begin
        l_procenat := 1 - ( p_kolicina / p_os.kolicina );
        l_opis := 'Prenos osnovnog sredstva - '
                  || p_os.naziv
                  || ' ( '
                  || p_os.inventurni_naziv
                  || ' ) => '
                  || p_os_prenos.naziv
                  || ' ( '
                  || p_os_prenos.inventurni_naziv
                  || ' )';

        l_broj := get_broj_naloga(
            p_ooj_id          => p_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina
        );
        
        -- Vrijednosti
        l_trenutno_nabavka := os_pkg.get_vrijednost_nabavka(p_os.id, p_datum);
        l_trenutno_amortizacija := os_pkg.get_amortizacija_do_datuma(p_os.id, p_datum);
        l_trenutno_knjigovodstvena := os_pkg.get_knjigovodstvena_vrijednost(p_os.id);

        l_vrijednost_nabavka := ( l_trenutno_nabavka * l_procenat );
        l_vrijednost_am_p := ( l_trenutno_amortizacija * l_procenat );
        
        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_os.ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => p_datum,
            p_datum_knjizenja => p_datum,
            p_opis            => l_opis
        );

        l_opis := 'Prenos osnovnog sredstva';

        -- **************************

        --  Dugovna strana

        -- **************************
        l_konto_nabavka_d := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
            p_klasa_id => p_os_prenos.klasa_id,
            p_sifra    => 'nabavke'
        );

        insert_glavna_knjiga_stavka(
            p_glavna_knjiga_id    => l_nalog_id,
            p_kontna_klasa_id     => l_konto_nabavka_d,
            p_tip_stavke          => 'D',
            p_opis                => l_opis,
            p_iznos               => l_vrijednost_nabavka,
            p_osnovno_sredstvo_id => p_os_prenos.id,
            p_transakcija_id      => l_transakcija_nabavke,
            p_os_datum            => p_datum,
            p_id                  => l_stavka_gk_id
        );

        if l_vrijednost_am_p != 0 then
            l_konto_amortizacija_d := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os.klasa_id,
                p_sifra    => 'am_p'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_amortizacija_d,
                p_tip_stavke          => 'D',
                p_opis                => l_opis,
                p_iznos               => l_vrijednost_am_p,
                p_osnovno_sredstvo_id => p_os.id,
                p_transakcija_id      => l_transakcija_am_p,
                p_os_datum            => p_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        -- **************************

        --  Potrazna strana

        -- **************************
        l_konto_nabavka_p := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
            p_klasa_id => p_os.klasa_id,
            p_sifra    => 'nabavke'
        );

        insert_glavna_knjiga_stavka(
            p_glavna_knjiga_id    => l_nalog_id,
            p_kontna_klasa_id     => l_konto_nabavka_p,
            p_tip_stavke          => 'P',
            p_opis                => l_opis,
            p_iznos               => l_vrijednost_nabavka * - 1,
            p_osnovno_sredstvo_id => p_os.id,
            p_transakcija_id      => l_transakcija_nabavke,
            p_os_datum            => p_datum,
            p_id                  => l_stavka_gk_id
        );

        if l_vrijednost_am_p != 0 then
            l_konto_amortizacija_p := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                p_klasa_id => p_os_prenos.klasa_id,
                p_sifra    => 'am_p'
            );

            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id    => l_nalog_id,
                p_kontna_klasa_id     => l_konto_amortizacija_p,
                p_tip_stavke          => 'P',
                p_opis                => l_opis,
                p_iznos               => l_vrijednost_am_p * -1,
                p_osnovno_sredstvo_id => p_os_prenos.id,
                p_transakcija_id      => l_transakcija_am_p,
                p_os_datum            => p_datum,
                p_id                  => l_stavka_gk_id
            );

        end if;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_os_prenos;
    
    --------------------------------------------------------------
    -- procedures for AUTOMATION PDV PRIJAVA
    --------------------------------------------------------------

    function knjizi_pdv_prijava (
        p_ooj_id         in number,
        p_godina         in number,
        p_pdv_prijava_id in number,
        p_proknjizeno    in varchar2
    ) return number is
        -- Nalog
        l_nalog_id        number;
        l_broj            number;
        l_vrsta_naloga_id number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('pdv');
        l_opis            varchar2(255); 

        -- Konta
        l_konto_dobitak_p number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_dobitak_p
        );
        l_konto_gubitak_d number := sif.acc_pkg.get_id_with_code_klasa(
            p_entitet_id => core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => p_ooj_id),
            p_code       => g_konto_gubitak_d
        );

        -- PDV prijava
        l_71              number;
        l_datum           date;
        
        --stavka GK
        l_stavka_gk_id  number; 
    begin
        pdv_pkg.get_pdv_prijava(
            p_id                    => p_pdv_prijava_id,
            p_poreski_period        => l_datum,
            p_pdv_uplata_povrat_p71 => l_71
        );

        l_opis := 'Obracun PDV ' || to_char(l_datum, 'MM/YY');
        l_broj := get_broj_naloga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina
        );

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => last_day(l_datum),
            p_datum_knjizenja => last_day(l_datum),
            p_opis            => l_opis
        );

        if l_71 > 0 then
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_dobitak_p,
                p_tip_stavke       => 'P',
                p_opis             => l_opis,
                p_iznos            => l_71 * - 1,
                p_id               => l_stavka_gk_id
            );
        elsif l_71 < 0 then
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_gubitak_d,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => l_71 * - 1,
                p_id               => l_stavka_gk_id
            );
        end if;

        zatvori_konto(
            p_ooj_id       => p_ooj_id,
            p_nalog_id     => l_nalog_id,
            p_opis         => l_opis,
            p_datum_od     => trunc(l_datum, 'MM'),
            p_datum_do     => trunc(last_day(l_datum)),
            p_start_with   => '47',
            p_exclude_with => '479',
            p_tip_stavke   => 'D'
        );

        zatvori_konto(
            p_ooj_id       => p_ooj_id,
            p_nalog_id     => l_nalog_id,
            p_opis         => l_opis,
            p_datum_od     => trunc(l_datum, 'MM'),
            p_datum_do     => trunc(last_day(l_datum)),
            p_start_with   => '27',
            p_exclude_with => '279',
            p_tip_stavke   => 'P'
        );

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_pdv_prijava;

    procedure zatvori_konto (
        p_ooj_id       in number,
        p_nalog_id     in number,
        p_opis         in varchar2,
        p_datum_od     in date,
        p_datum_do     in date,
        p_start_with   in varchar2,
        p_exclude_with in varchar2,
        p_tip_stavke   in varchar2
    ) is

        cursor c_stavke is
        (
            select
                kontna_klasa_id,
                sum(iznos) * - 1 as iznos
            from
                vw_glavna_knjiga_stavke
            where
                        ooj_id = p_ooj_id
                    and trunc(glavna_knjiga_datum_knjizenja) >= p_datum_od
                    and trunc(glavna_knjiga_datum_knjizenja) <= p_datum_do
                                                                and kontna_klasa_code like p_start_with
                                                                || '%'
                                                                   and kontna_klasa_code not like p_exclude_with
                                                                || '%'
                and proknjizeno = 'Y'
            group by
                kontna_klasa_id
        );
        
        l_stavka_gk_id number;

    begin
        for stavka in c_stavke loop
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => p_nalog_id,
                p_kontna_klasa_id  => stavka.kontna_klasa_id,
                p_tip_stavke       => p_tip_stavke,
                p_opis             => p_opis,
                p_iznos            => stavka.iznos,
                p_id               => l_stavka_gk_id
            );
        end loop;
    end zatvori_konto;

    --------------------------------------------------------------
    -- procedures for AUTOMATION KIF
    --------------------------------------------------------------

    function knjizi_kif (
        p_ooj_id      in number,
        p_godina      in number,
        p_pp          in date,
        p_proknjizeno in varchar2
    ) return number is

        cursor c_kif is
        (
            select
                id,
                vrsta_naloga_sifra
            from
                vw_kif
            where
                    ooj_id = p_ooj_id
                and trunc(datum_fakture, 'MM') = trunc(p_pp, 'MM')
                and glavna_knjiga_id is null
                and valid = 'Y'
                and lower(vrsta_naloga_sifra) in ( 'if', 'ifs', 'kz', 'kzs', 'ko',
                                                   'kos', 'av', 'avs' )
                and godina = p_godina
        )
        order by
            faktura_broj;

        l_nalog_id number;
    begin
        for c1 in c_kif loop
            l_nalog_id := knjizi_kif_single(
                p_id              => c1.id,
                p_ooj_id          => p_ooj_id,
                p_godina          => p_godina,
                p_proknjizeno     => p_proknjizeno,
                p_collection_only => 'N'
            );
        end loop;

        return l_nalog_id;
    end knjizi_kif;

    function knjizi_kif_single (
        p_id              in number,
        p_ooj_id          in number,
        p_godina          in number,
        p_proknjizeno     in varchar2,
        p_collection_only in varchar2
    ) return number is
        l_nalog_id           number;
        l_vrsta_naloga_sifra varchar2(32);
    begin
        finansije_pkg.get_kif(
            p_id                 => p_id,
            p_vrsta_naloga_sifra => l_vrsta_naloga_sifra
        );
        if lower(l_vrsta_naloga_sifra) in ( 'if', 'ifs', 'kz', 'kzs', 'ko',
                                            'kos' ) then
            l_nalog_id := knjizi_kif_single_if(
                p_id              => p_id,
                p_ooj_id          => p_ooj_id,
                p_godina          => p_godina,
                p_proknjizeno     => p_proknjizeno,
                p_collection_only => p_collection_only
            );

        elsif lower(l_vrsta_naloga_sifra) in ( 'av', 'avs' ) then
            l_nalog_id := knjizi_kif_single_av(
                p_id              => p_id,
                p_ooj_id          => p_ooj_id,
                p_godina          => p_godina,
                p_proknjizeno     => p_proknjizeno,
                p_collection_only => p_collection_only
            );
        end if;

        return l_nalog_id;
    end knjizi_kif_single;

    function knjizi_kif_single_if (
        p_id              in number,
        p_ooj_id          in number,
        p_godina          in number,
        p_proknjizeno     in varchar2,
        p_collection_only in varchar2
    ) return number is
        -- Nalog
        l_nalog_id             number;
        l_broj                 number;
        l_vrsta_naloga_id      number;
        l_opis                 varchar2(255);
        l_naziv_fakture        varchar2(255);
        l_datum_fakture        date;
        l_pdv                  number;
        l_iznos_fakture        number;
        l_klijent_id           number;
        l_tip_cijene           varchar2(1);
        l_sablon_id            number;
        l_pdv_obaveznik        varchar2(1);
        l_ino_drzava           varchar2(1);
        l_entitet_sifra        varchar2(32);
        l_tip_klijenta_sifra   varchar2(64);
        l_vrsta_fakture_id     number;
        l_vrsta_fakture_sifra  varchar2(64);
        l_storniran_id         number;
        l_pdv_indikator_id     number;
        l_uio_tip_dokumenta_id number;
        cursor c_stavke is
        (
            select
                tip_stavke_id,
                tip_stavke_naziv,
                ima_rabat,
                stavka_ino_usluga,
                sum(iznos)             as iznos,
                sum(iznos_pdv)         as iznos_sa_pdv,
                sum(iznos_pdv - iznos) as pdv,
                sum(iznos_bez_rabata)  as iznos_bez_rabata
            from
                vw_kif_stavke
            where
                kif_id = p_id
            group by
                tip_stavke_id,
                tip_stavke_naziv,
                ima_rabat,
                stavka_ino_usluga
        );

        l_sifra_konto_osnovica varchar2(64) := 'OS';
        l_sifra_konto_pdv      varchar2(64) := 'PDV';
        l_sifra_konto_kupac    varchar2(64) := 'IZNOS_KUPAC';
        l_konto_osnovica       number;
        l_konto_pdv            number;
        l_konto_kupac          number;
        l_iznos_osnovica       number;
        l_iznos_pdv            number;
        l_iznos_kupac          number;
        l_stavka_gk_id         number;
    begin
        apex_collection.create_or_truncate_collection(p_collection_name => 'KIF_KONTA');
        finansije_pkg.get_kif(
            p_id                  => p_id,
            p_naziv_fakture       => l_naziv_fakture,
            p_datum_fakture       => l_datum_fakture,
            p_vrsta_naloga_id     => l_vrsta_naloga_id,
            p_iznos_fakture       => l_iznos_fakture,
            p_pdv                 => l_pdv,
            p_klijent_id          => l_klijent_id,
            p_tip_cijene          => l_tip_cijene,
            p_vrsta_fakture_id    => l_vrsta_fakture_id,
            p_vrsta_fakture_sifra => l_vrsta_fakture_sifra,
            p_storniran_id        => l_storniran_id
        );

        sec_pkg.get_klijent(
            p_id                 => l_klijent_id,
            p_sablon_id          => l_sablon_id,
            p_pdv_obaveznik      => l_pdv_obaveznik,
            p_ino_drzava         => l_ino_drzava,
            p_entitet_sifra      => l_entitet_sifra,
            p_tip_klijenta_sifra => l_tip_klijenta_sifra
        );

        if l_sablon_id is null then
            raise_application_error(-20001, 'Fakturu '
                                            || l_naziv_fakture
                                            || ' nije moguće knjižiti zato što njen klijent nema podešen šablon knjiženja.');
        end if;

        if p_collection_only = 'N' then
            l_opis := 'Automatsko knjiženje - ' || l_naziv_fakture;
            l_broj := get_broj_naloga(
                p_ooj_id          => p_ooj_id,
                p_vrsta_naloga_id => l_vrsta_naloga_id,
                p_godina          => p_godina
            );

            l_nalog_id := insert_glavna_knjiga(
                p_ooj_id          => p_ooj_id,
                p_vrsta_naloga_id => l_vrsta_naloga_id,
                p_godina          => p_godina,
                p_broj            => l_broj,
                p_datum_dokumenta => l_datum_fakture,
                p_datum_knjizenja => last_day(l_datum_fakture),
                p_opis            => l_opis
            );

        end if;

        -- Sifra za knjizenje PDV-a
        if l_pdv != 0 then
            finansije_pkg.get_kif_indikator_uio(
                p_ooj_id               => p_ooj_id,
                p_klijent_id           => l_klijent_id,
                p_vrsta_fakture_id     => l_vrsta_fakture_id,
                p_pdv_indikator_id     => l_pdv_indikator_id,
                p_uio_tip_dokumenta_id => l_uio_tip_dokumenta_id
            );

            if l_vrsta_fakture_sifra = 'ko' then
                if l_pdv_obaveznik = 'Y' then
                    l_sifra_konto_pdv := l_sifra_konto_pdv || '_KO';
                elsif
                    l_pdv_obaveznik = 'N'
                    and l_ino_drzava = 'Y'
                then
                    l_sifra_konto_pdv := l_sifra_konto_pdv || '_INO';
                else
                    l_sifra_konto_pdv := l_sifra_konto_pdv
                                         || '_'
                                         || l_entitet_sifra;
                end if;

            else
                if l_pdv_obaveznik = 'Y' then
                    l_sifra_konto_pdv := l_sifra_konto_pdv || '_OBAVEZNIK';
                elsif
                    l_pdv_obaveznik = 'N'
                    and l_ino_drzava = 'Y'
                then
                    l_sifra_konto_pdv := l_sifra_konto_pdv || '_INO';
                else
                    l_sifra_konto_pdv := l_sifra_konto_pdv
                                         || '_'
                                         || l_entitet_sifra;
                end if;
            end if;

            l_konto_pdv := sabloni_pkg.get_sablon_konto(
                p_sablon_id                  => l_sablon_id,
                p_automatsko_knjizenje_sifra => l_sifra_konto_pdv
            );
--            if l_vrsta_fakture_sifra = 'ko' then
--                l_iznos_pdv := l_pdv;
--            else
                l_iznos_pdv := l_pdv * -1;
--            end if;

            if p_collection_only = 'N' then
                insert_glavna_knjiga_stavka(
                    p_glavna_knjiga_id => l_nalog_id,
                    p_kontna_klasa_id  => l_konto_pdv,
                    p_tip_stavke       => 'P',
                    p_opis             => l_opis,
                    p_iznos            => l_iznos_pdv,
                    p_pdv_indikator_id => l_pdv_indikator_id,
                    p_id               => l_stavka_gk_id
                );
            end if;

            apex_collection.add_member(
                p_collection_name => 'KIF_KONTA',
                p_c001            => l_sifra_konto_pdv,
                p_c002            => l_konto_pdv,
                p_c003            => 'P',
                p_c004            => l_iznos_pdv,
                p_c005            => l_pdv_indikator_id,
                p_c006            => null
            );

        end if;

        -- Sifra za knjizenje kupca
        if l_ino_drzava = 'Y' then
            l_sifra_konto_kupac := l_sifra_konto_kupac || '_INO';
        else
            l_sifra_konto_kupac := l_sifra_konto_kupac
                                   || '_'
                                   || l_entitet_sifra;
        end if;

        l_konto_kupac := sabloni_pkg.get_sablon_konto(
            p_sablon_id                  => l_sablon_id,
            p_automatsko_knjizenje_sifra => l_sifra_konto_kupac
        );
--        if l_vrsta_fakture_sifra = 'ko' then
--            l_iznos_kupac := l_iznos_fakture * -1;
--        else
            l_iznos_kupac := l_iznos_fakture;
--        end if;

        if p_collection_only = 'N' then
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_kupac,
                p_tip_stavke       => 'D',
                p_opis             => l_opis,
                p_iznos            => l_iznos_kupac,
                p_klijent_id       => l_klijent_id,
                p_id     => l_stavka_gk_id
            );
        end if;

        apex_collection.add_member(
            p_collection_name => 'KIF_KONTA',
            p_c001            => l_sifra_konto_kupac,
            p_c002            => l_konto_kupac,
            p_c003            => 'D',
            p_c004            => l_iznos_kupac,
            p_c005            => null,
            p_c006            => l_klijent_id
        );

        -- Sifra za knjizenje osnovice
        for c1 in c_stavke loop
            if c1.ima_rabat = 'Y' then
                -- Ukoliko ima PDV, idu 2 stavke
                -- Iznos bez rabata, na potraznu stranu, minus
                l_sifra_konto_osnovica := get_stavka_konto_sifra(
                    p_tip_stavke_naziv   => c1.tip_stavke_naziv,
                    p_popust             => 'Y',
                    p_ino_drzava         => l_ino_drzava,
                    p_entitet_sifra      => l_entitet_sifra,
                    p_tip_cijene         => l_tip_cijene,
                    p_tip_klijenta_sifra => l_tip_klijenta_sifra,
                    p_ino_usluga         => c1.stavka_ino_usluga
                );

                l_konto_osnovica := sabloni_pkg.get_sablon_konto(
                    p_sablon_id                  => l_sablon_id,
                    p_automatsko_knjizenje_sifra => l_sifra_konto_osnovica
                );
--                if l_vrsta_fakture_sifra = 'ko' then
--                    l_iznos_osnovica := c1.iznos_bez_rabata;
--                else
                    l_iznos_osnovica := c1.iznos_bez_rabata * -1;
--                end if;

                if p_collection_only = 'N' then
                    insert_glavna_knjiga_stavka(
                        p_glavna_knjiga_id => l_nalog_id,
                        p_kontna_klasa_id  => l_konto_osnovica,
                        p_tip_stavke       => 'P',
                        p_opis             => l_opis,
                        p_iznos            => l_iznos_osnovica,
                        p_id               => l_stavka_gk_id
                    );
                end if;

                apex_collection.add_member(
                    p_collection_name => 'KIF_KONTA',
                    p_c001            => l_sifra_konto_osnovica,
                    p_c002            => l_konto_osnovica,
                    p_c003            => 'P',
                    p_c004            => l_iznos_osnovica,
                    p_c005            => null,
                    p_c006            => null
                );

                -- Iznos rabata, na dugovnu stranu, plus
                l_sifra_konto_osnovica := get_stavka_konto_sifra(
                    p_tip_stavke_naziv   => c1.tip_stavke_naziv,
                    p_popust             => 'N',
                    p_ino_drzava         => l_ino_drzava,
                    p_entitet_sifra      => l_entitet_sifra,
                    p_tip_cijene         => l_tip_cijene,
                    p_tip_klijenta_sifra => l_tip_klijenta_sifra,
                    p_ino_usluga         => c1.stavka_ino_usluga
                );

                l_konto_osnovica := sabloni_pkg.get_sablon_konto(
                    p_sablon_id                  => l_sablon_id,
                    p_automatsko_knjizenje_sifra => l_sifra_konto_osnovica
                );
                if l_vrsta_fakture_sifra = 'ko' then
                    l_iznos_osnovica := ( c1.iznos_bez_rabata - c1.iznos ) * -1;
                else
                    l_iznos_osnovica := ( c1.iznos_bez_rabata - c1.iznos );
                end if;

                if p_collection_only = 'N' then
                    insert_glavna_knjiga_stavka(
                        p_glavna_knjiga_id => l_nalog_id,
                        p_kontna_klasa_id  => l_konto_osnovica,
                        p_tip_stavke       => 'D',
                        p_opis             => l_opis,
                        p_iznos            => l_iznos_osnovica,
                        p_id               => l_stavka_gk_id
                    );
                end if;

                apex_collection.add_member(
                    p_collection_name => 'KIF_KONTA',
                    p_c001            => l_sifra_konto_osnovica,
                    p_c002            => l_konto_osnovica,
                    p_c003            => 'D',
                    p_c004            => l_iznos_osnovica,
                    p_c005            => null,
                    p_c006            => null
                );

            else
                l_sifra_konto_osnovica := get_stavka_konto_sifra(
                    p_tip_stavke_naziv   => c1.tip_stavke_naziv,
                    p_popust             => 'N',
                    p_ino_drzava         => l_ino_drzava,
                    p_entitet_sifra      => l_entitet_sifra,
                    p_tip_cijene         => l_tip_cijene,
                    p_tip_klijenta_sifra => l_tip_klijenta_sifra,
                    p_ino_usluga         => c1.stavka_ino_usluga
                );

                l_konto_osnovica := sabloni_pkg.get_sablon_konto(
                    p_sablon_id                  => l_sablon_id,
                    p_automatsko_knjizenje_sifra => l_sifra_konto_osnovica
                );
--                if l_vrsta_fakture_sifra = 'ko' then
--                    l_iznos_osnovica := c1.iznos;
--                else
                    l_iznos_osnovica := c1.iznos * -1;
--                end if;

                if p_collection_only = 'N' then
                    insert_glavna_knjiga_stavka(
                        p_glavna_knjiga_id => l_nalog_id,
                        p_kontna_klasa_id  => l_konto_osnovica,
                        p_tip_stavke       => 'P',
                        p_opis             => l_opis,
                        p_iznos            => l_iznos_osnovica,
                        p_id               => l_stavka_gk_id
                    );
                end if;

                apex_collection.add_member(
                    p_collection_name => 'KIF_KONTA',
                    p_c001            => l_sifra_konto_osnovica,
                    p_c002            => l_konto_osnovica,
                    p_c003            => 'P',
                    p_c004            => l_iznos_osnovica,
                    p_c005            => null,
                    p_c006            => null
                );

            end if;
        end loop;

        update kif
        set
            glavna_knjiga_id = l_nalog_id
        where
            id = p_id;
            
        if l_storniran_id is not null then
            update glavna_knjiga_stavke set
                iznos = -iznos,
                tip_stavke = decode(tip_stavke, 'D', 'P', 'P', 'D', tip_stavke)
            where
                glavna_knjiga_id = l_nalog_id;
        end if;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_kif_single_if;

    function knjizi_kif_single_av (
        p_id              in number,
        p_ooj_id          in number,
        p_godina          in number,
        p_proknjizeno     in varchar2,
        p_collection_only in varchar2
    ) return number is
        -- Nalog
        l_nalog_id             number;
        l_broj                 number;
        l_vrsta_naloga_id      number;
        l_opis                 varchar2(255);
        l_naziv_fakture        varchar2(255);
        l_datum_fakture        date;
        l_pdv                  number;
        l_iznos_fakture        number;
        l_klijent_id           number;
        l_tip_cijene           varchar2(1);
        l_sablon_id            number;
        l_pdv_obaveznik        varchar2(1);
        l_ino_drzava           varchar2(1);
        l_entitet_sifra        varchar2(32);
        l_tip_klijenta_sifra   varchar2(64);
        l_vrsta_fakture_id     number;
        l_vrsta_fakture_sifra  varchar2(64);
        l_storniran_id         number;
        l_pdv_indikator_id     number;
        l_uio_tip_dokumenta_id number;
        l_sifra_konto_pdv      varchar2(64) := 'AV_PDV';
        l_sifra_konto_kupac    varchar2(64) := 'AV_IZNOS';
        l_konto_pdv            number;
        l_konto_kupac          number;
        l_stavka               varchar2(1);
        l_stavka_gk_id         number;
    begin
        apex_collection.create_or_truncate_collection(p_collection_name => 'KIF_KONTA');
        finansije_pkg.get_kif(
            p_id                  => p_id,
            p_naziv_fakture       => l_naziv_fakture,
            p_datum_fakture       => l_datum_fakture,
            p_vrsta_naloga_id     => l_vrsta_naloga_id,
            p_iznos_fakture       => l_iznos_fakture,
            p_pdv                 => l_pdv,
            p_klijent_id          => l_klijent_id,
            p_tip_cijene          => l_tip_cijene,
            p_vrsta_fakture_id    => l_vrsta_fakture_id,
            p_vrsta_fakture_sifra => l_vrsta_fakture_sifra,
            p_storniran_id        => l_storniran_id
        );

        sec_pkg.get_klijent(
            p_id                 => l_klijent_id,
            p_sablon_id          => l_sablon_id,
            p_pdv_obaveznik      => l_pdv_obaveznik,
            p_ino_drzava         => l_ino_drzava,
            p_entitet_sifra      => l_entitet_sifra,
            p_tip_klijenta_sifra => l_tip_klijenta_sifra
        );

        if l_sablon_id is null then
            raise_application_error(-20001, 'Fakturu '
                                            || l_naziv_fakture
                                            || ' nije moguće knjižiti zato što njen klijent nema podešen šablon knjiženja.');
        end if;

        if p_collection_only = 'N' then
            l_opis := 'Automatsko knjiženje - ' || l_naziv_fakture;
            l_broj := get_broj_naloga(
                p_ooj_id          => p_ooj_id,
                p_vrsta_naloga_id => l_vrsta_naloga_id,
                p_godina          => p_godina
            );

            l_nalog_id := insert_glavna_knjiga(
                p_ooj_id          => p_ooj_id,
                p_vrsta_naloga_id => l_vrsta_naloga_id,
                p_godina          => p_godina,
                p_broj            => l_broj,
                p_datum_dokumenta => l_datum_fakture,
                p_datum_knjizenja => last_day(l_datum_fakture),
                p_opis            => l_opis
            );

        end if;

        -- Sifra za knjizenje PDV-a
        if l_pdv != 0 then
            finansije_pkg.get_kif_indikator_uio(
                p_ooj_id               => p_ooj_id,
                p_klijent_id           => l_klijent_id,
                p_vrsta_fakture_id     => l_vrsta_fakture_id,
                p_pdv_indikator_id     => l_pdv_indikator_id,
                p_uio_tip_dokumenta_id => l_uio_tip_dokumenta_id
            );

            -- Dugovna strana
            l_sifra_konto_pdv := l_sifra_konto_pdv
                                 || '_D_'
                                 || l_entitet_sifra;
            l_konto_pdv := sabloni_pkg.get_sablon_konto(
                p_sablon_id                  => l_sablon_id,
                p_automatsko_knjizenje_sifra => l_sifra_konto_pdv
            );
            if l_storniran_id is null then
                l_stavka := 'D';
            else
                l_stavka := 'P';
            end if;

            if p_collection_only = 'N' then
                insert_glavna_knjiga_stavka(
                    p_glavna_knjiga_id => l_nalog_id,
                    p_kontna_klasa_id  => l_konto_pdv,
                    p_tip_stavke       => l_stavka,
                    p_opis             => l_opis,
                    p_iznos            => l_pdv,
                    p_id               => l_stavka_gk_id
                );
            end if;

            apex_collection.add_member(
                p_collection_name => 'KIF_KONTA',
                p_c001            => l_sifra_konto_pdv,
                p_c002            => l_konto_pdv,
                p_c003            => l_stavka,
                p_c004            => l_pdv,
                p_c005            => l_pdv_indikator_id,
                p_c006            => null
            );

            -- Potrazna strana
            l_sifra_konto_pdv := 'AV_PDV_P_' || l_entitet_sifra;
            l_konto_pdv := sabloni_pkg.get_sablon_konto(
                p_sablon_id                  => l_sablon_id,
                p_automatsko_knjizenje_sifra => l_sifra_konto_pdv
            );
            if l_storniran_id is null then
                l_stavka := 'P';
            else
                l_stavka := 'D';
            end if;

            if p_collection_only = 'N' then
                insert_glavna_knjiga_stavka(
                    p_glavna_knjiga_id => l_nalog_id,
                    p_kontna_klasa_id  => l_konto_pdv,
                    p_tip_stavke       => l_stavka,
                    p_opis             => l_opis,
                    p_iznos            => l_pdv * - 1,
                    p_pdv_indikator_id => l_pdv_indikator_id,
                    p_id               => l_stavka_gk_id
                );
            end if;

            apex_collection.add_member(
                p_collection_name => 'KIF_KONTA',
                p_c001            => l_sifra_konto_pdv,
                p_c002            => l_konto_pdv,
                p_c003            => l_stavka,
                p_c004            => l_pdv * - 1,
                p_c005            => l_pdv_indikator_id,
                p_c006            => null
            );

        end if;

        -- Iznos racuna
        -- Dugovna strana
        if l_ino_drzava = 'Y' then
            l_sifra_konto_kupac := l_sifra_konto_kupac || '_D_INO';
        else
            l_sifra_konto_kupac := l_sifra_konto_kupac
                                   || '_D_'
                                   || l_entitet_sifra;
        end if;

        l_konto_kupac := sabloni_pkg.get_sablon_konto(
            p_sablon_id                  => l_sablon_id,
            p_automatsko_knjizenje_sifra => l_sifra_konto_kupac
        );
        if l_storniran_id is null then
            l_stavka := 'D';
        else
            l_stavka := 'P';
        end if;

        if p_collection_only = 'N' then
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_kupac,
                p_tip_stavke       => l_stavka,
                p_opis             => l_opis,
                p_iznos            => l_iznos_fakture,
                p_id               => l_stavka_gk_id
            );
        end if;

        apex_collection.add_member(
            p_collection_name => 'KIF_KONTA',
            p_c001            => l_sifra_konto_kupac,
            p_c002            => l_konto_kupac,
            p_c003            => l_stavka,
            p_c004            => l_iznos_fakture,
            p_c005            => null,
            p_c006            => null
        );

        -- Potrazna strana
        if l_ino_drzava = 'Y' then
            l_sifra_konto_kupac := 'AV_IZNOS_P_INO';
        else
            l_sifra_konto_kupac := 'AV_IZNOS_P_' || l_entitet_sifra;
        end if;

        l_konto_kupac := sabloni_pkg.get_sablon_konto(
            p_sablon_id                  => l_sablon_id,
            p_automatsko_knjizenje_sifra => l_sifra_konto_kupac
        );
        if l_storniran_id is null then
            l_stavka := 'P';
        else
            l_stavka := 'D';
        end if;

        if p_collection_only = 'N' then
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => l_konto_kupac,
                p_tip_stavke       => l_stavka,
                p_opis             => l_opis,
                p_iznos            => l_iznos_fakture * - 1,
                p_id               => l_stavka_gk_id
            );
        end if;

        apex_collection.add_member(
            p_collection_name => 'KIF_KONTA',
            p_c001            => l_sifra_konto_kupac,
            p_c002            => l_konto_kupac,
            p_c003            => l_stavka,
            p_c004            => l_iznos_fakture * - 1,
            p_c005            => null,
            p_c006            => null
        );

        update kif
        set
            glavna_knjiga_id = l_nalog_id
        where
            id = p_id;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_kif_single_av;

    function get_stavka_konto_sifra (
        p_tip_stavke_naziv   in varchar2,
        p_popust             in varchar2,
        p_ino_drzava         in varchar2,
        p_entitet_sifra      in varchar2,
        p_tip_cijene         in varchar2,
        p_tip_klijenta_sifra in varchar2,
        p_ino_usluga         in varchar2
    ) return varchar is
        l_sifra varchar2(64) := 'OS';
    begin
        l_sifra := l_sifra
                   || '_'
                   || p_tip_stavke_naziv;
        if p_popust = 'Y' then
            l_sifra := l_sifra || '_POPUST';
            if p_ino_drzava = 'Y' then
                l_sifra := l_sifra || '_INO';
            else
                if p_tip_klijenta_sifra = 'ppl' then
                    l_sifra := l_sifra || '_PPL';
                else
                    l_sifra := l_sifra
                               || '_'
                               || p_entitet_sifra;
                end if;
            end if;

        else
            case
                when lower(p_tip_stavke_naziv) = 'roba' then
                    if p_ino_drzava = 'Y' then
                        l_sifra := l_sifra || '_INO';
                    else
                        l_sifra := l_sifra
                                   || '_'
                                   || p_tip_cijene
                                   || '_'
                                   || p_entitet_sifra;
                    end if;
                when lower(p_tip_stavke_naziv) = 'proizvod' then
                    if p_ino_drzava = 'Y' then
                        l_sifra := l_sifra || '_INO';
                    else
                        if p_tip_cijene = 'M' then
                            if lower(p_tip_klijenta_sifra) = 'fl' then
                                l_sifra := l_sifra
                                           || '_'
                                           || p_tip_cijene
                                           || '_'
                                           || p_entitet_sifra;
                            else
                                l_sifra := l_sifra
                                           || '_'
                                           || p_tip_klijenta_sifra
                                           || '_'
                                           || p_entitet_sifra;
                            end if;

                        else
                            l_sifra := l_sifra
                                       || '_'
                                       || p_tip_cijene
                                       || '_'
                                       || p_entitet_sifra;
                        end if;
                    end if;
                when lower(p_tip_stavke_naziv) = 'usluga' then
                    if p_ino_drzava = 'Y' then
                        if p_ino_usluga = 'Y' then
                            l_sifra := l_sifra || '_INO';
                        else
                            l_sifra := l_sifra || '_RS_INO';
                        end if;

                    else
                        if lower(p_tip_klijenta_sifra) = 'fl' then
                            l_sifra := l_sifra
                                       || '_F_'
                                       || p_entitet_sifra;
                        else
                            l_sifra := l_sifra
                                       || '_PL_'
                                       || p_entitet_sifra;
                        end if;
                    end if;
            end case;
        end if;

        return l_sifra;
    end get_stavka_konto_sifra;

    --------------------------------------------------------------
    -- procedures for AUTOMATION UIO
    --------------------------------------------------------------

    procedure nalog_to_kuf_uio (
        p_ooj_id in number,
        p_godina in number,
        p_pp     in date
    ) is

        cursor c_glavna_knjiga is
        (
            select
                id
            from
                vw_glavna_knjiga
            where
                    ooj_id = p_ooj_id
                and godina = p_godina
                and trunc(datum_knjizenja, 'MM') = trunc(p_pp, 'MM')
                and lower(vrsta_naloga_sifra) = 'uf'
                and proknjizeno = 'Y'
                and kuf_id not in (
                    select
                        faktura_id
                    from
                        uio_kuf
                    where
                        ooj_id = p_ooj_id
                        and faktura_id is not null
                )
                and kuf_id is not null
        );

    begin
        for c1 in c_glavna_knjiga loop
            nalog_to_kuf_uio_single(p_glavna_knjiga_id => c1.id);
        end loop;
    end nalog_to_kuf_uio;

    procedure nalog_to_kuf_uio_single (
        p_glavna_knjiga_id in number
    ) is

        r_glavna_knjiga  glavna_knjiga%rowtype;
        r_klijent        sec_klijenti%rowtype;
        r_kuf            kuf%rowtype;
        l_entitet_id     number;
        cursor c_stavke is
        (
            select
                pdv_indikator_sifra,
                iznos
            from
                vw_glavna_knjiga_stavke
            where
                    glavna_knjiga_id = p_glavna_knjiga_id
                and pdv_indikator_id is not null
        );

        l_redni_broj     number;
        l_poreski_period varchar2(4);
        l_tip_dokumenta  varchar2(16);
        l_3              number := 0;
        l_4              number := 0;
        l_5              number := 0;
        l_6              number := 0;
        l_7              number := 0;
        l_8              number := 0;
        l_9              number := 0;
    begin
        select
            *
        into r_glavna_knjiga
        from
            glavna_knjiga
        where
            id = p_glavna_knjiga_id;

        select
            *
        into r_kuf
        from
            kuf
        where
            glavna_knjiga_id = r_glavna_knjiga.id;

        select
            *
        into r_klijent
        from
            sec_klijenti
        where
            id = r_kuf.klijent_id;

        l_entitet_id := core.ooj_pkg.get_ooj_entitet_id(p_ooj_id => r_glavna_knjiga.ooj_id);
        sif.acc_pkg.get_uio_tip_dokumenta(
            p_id   => r_kuf.uio_tip_dokumenta_id,
            p_code => l_tip_dokumenta
        );

        l_redni_broj := uio_pkg.get_uio_kuf_redni_broj(
            p_ooj_id         => r_glavna_knjiga.ooj_id,
            p_poreski_period => to_char(r_kuf.datum_fakture, 'YYMM')
        );

        l_poreski_period := to_char(r_kuf.datum_fakture, 'YYMM');

	    -- Calculation
        for c1 in c_stavke loop
            if c1.pdv_indikator_sifra in ( 'P1', 'P2', 'P3', 'P6', 'P7',
                                           'P8', 'U1', 'U2' ) then
                l_4 := l_4 + c1.iznos;
                l_5 := l_5 + c1.iznos;
            end if;

            if c1.pdv_indikator_sifra in ( 'R1' ) then
                l_4 := l_4 + c1.iznos;
                l_6 := l_6 + c1.iznos;
                case
                    when l_entitet_id = 2 then -- FBiH
                        l_7 := l_7 + c1.iznos;
                    when l_entitet_id = 1 then -- RS
                        l_8 := l_8 + c1.iznos;
                    when l_entitet_id = 3 then -- Brcko Distrikt
                        l_9 := l_9 + c1.iznos;
                end case;

            end if;

        end loop;

--        if r_kuf.iznos_sa_pdv < 0 and r_kuf.storniran_id is null then
--            l_3 := l_3 * ( -1 );
--            l_4 := l_4 * ( -1 );
--            l_5 := l_5 * ( -1 );
--            l_6 := l_6 * ( -1 );
--            l_7 := l_7 * ( -1 );
--            l_8 := l_8 * ( -1 );
--            l_9 := l_9 * ( -1 );
--        end if;

        uio_pkg.insert_uio_kuf(
            p_ooj_id                 => r_kuf.ooj_id,
            p_faktura_id             => r_kuf.id,
            p_vrsta_sloga            => 2,
            p_redni_br               => l_redni_broj,
            p_poreski_period         => l_poreski_period,
            p_tip_dokumenta          => l_tip_dokumenta,
            p_broj_fakture           => r_kuf.naziv_fakture,
            p_datum_fakture          => r_kuf.datum_fakture,
            p_datum_prijema_fakture  => r_kuf.datum_prijema,
            p_naziv_dobavljaca       => r_klijent.naziv,
            p_sjediste_dobavljaca    => r_klijent.adresa,
            p_pdv_broj_dobavljaca    => lpad(r_klijent.pib, 12, 0),
            p_jib_broj_dobavljaca    => lpad(r_klijent.jib, 13, 0),
            p_iznos_fakture_bezpdv   => to_char(
                coalesce(r_kuf.iznos_bez_pdv, 0),
                'FM9999999990.00'
            ),
            p_iznos_fakture_sapdv    => to_char(
                coalesce(r_kuf.iznos_sa_pdv, 0),
                'FM9999999990.00'
            ),
            p_iznos_pausal           => to_char(
                coalesce(l_3, 0),
                'FM9999999990.00'
            ),
            p_iznos_ulaznog_pdv      => to_char(
                coalesce(l_4, 0),
                'FM9999999990.00'
            ),
            p_iznos_ulazpdv_odbiti   => to_char(
                coalesce(l_5, 0),
                'FM9999999990.00'
            ),
            p_iznos_ulazpdv_neodbiti => to_char(
                coalesce(l_6, 0),
                'FM9999999990.00'
            ),
            p_iznos_pdv_32polje      => to_char(
                coalesce(l_7, 0),
                'FM9999999990.00'
            ),
            p_iznos_pdv_33polje      => to_char(
                coalesce(l_8, 0),
                'FM9999999990.00'
            ),
            p_iznos_pdv_34polje      => to_char(
                coalesce(l_9, 0),
                'FM9999999990.00'
            )
        );

    end nalog_to_kuf_uio_single;

    procedure nalog_to_kif_uio (
        p_ooj_id in number,
        p_godina in number,
        p_pp     in date
    ) is

        cursor c_glavna_knjiga is
        (
            select
                id
            from
                vw_glavna_knjiga
            where
                    ooj_id = p_ooj_id
                and godina = p_godina
                and trunc(datum_knjizenja, 'MM') = trunc(p_pp, 'MM')
                and lower(vrsta_naloga_sifra) in ( 'if', 'ifs', 'kz', 'kzs', 'ko',
                                                   'kos', 'av', 'avs', 'in', 'ins' )
                and proknjizeno = 'Y'
                and kif_id not in (
                    select
                        faktura_id
                    from
                        uio_kif
                    where
                        ooj_id = p_ooj_id
                        and faktura_id is not null
                )
                and kif_id is not null
        );

    begin
        for c1 in c_glavna_knjiga loop
            nalog_to_kif_uio_single(p_glavna_knjiga_id => c1.id);
        end loop;
    end nalog_to_kif_uio;

    procedure nalog_to_kif_uio_single (
        p_glavna_knjiga_id in number
    ) is

        r_glavna_knjiga  glavna_knjiga%rowtype;
        r_klijent        sec_klijenti%rowtype;
        r_kif            kif%rowtype;
        cursor c_stavke is
        (
            select
                pdv_indikator_sifra,
                iznos
            from
                vw_glavna_knjiga_stavke
            where
                glavna_knjiga_id = p_glavna_knjiga_id
        );

        cursor c_kif_stavke is
        (
            select
                pdv_indikator_sifra,
                iznos,
                iznos_pdv
            from
                vw_kif_stavke
            where
                kif_id = (
                    select
                        id
                    from
                        kif
                    where
                        glavna_knjiga_id = p_glavna_knjiga_id
                )
        );

        l_redni_broj     number;
        l_poreski_period varchar2(4);
        l_tip_dokumenta  varchar2(16);
        l_1              number := 0;
        l_2              number := 0;
        l_3              number := 0;
        l_4              number := 0;
        l_5              number := 0;
        l_6              number := 0;
        l_7              number := 0;
        l_8              number := 0;
        l_9              number := 0;
        l_10             number := 0;
        l_11             number := 0;
    begin
        select
            *
        into r_glavna_knjiga
        from
            glavna_knjiga
        where
            id = p_glavna_knjiga_id;

        select
            *
        into r_kif
        from
            kif
        where
            glavna_knjiga_id = r_glavna_knjiga.id;

        select
            *
        into r_klijent
        from
            sec_klijenti
        where
            id = r_kif.klijent_id;

        sif.acc_pkg.get_uio_tip_dokumenta(
            p_id   => r_kif.uio_tip_dokumenta_id,
            p_code => l_tip_dokumenta
        );

        l_redni_broj := uio_pkg.get_uio_kif_redni_broj(
            p_ooj_id         => r_glavna_knjiga.ooj_id,
            p_poreski_period => to_char(r_kif.datum_fakture, 'YYMM')
        );

        l_poreski_period := to_char(r_kif.datum_fakture, 'YYMM');

        -- Calculation
        for c1 in c_stavke loop
--            IF c1.pdv_indikator_sifra = 'A6' THEN
--                l_1 := l_1 - c1.iznos;
--                l_6 := l_6 + c1.iznos;
--                l_5 := l_5 + abs(c1.iznos);
--
--            ELSIF c1.pdv_indikator_sifra = 'C5' THEN
--                l_7 := l_7 + abs(c1.iznos);
--
--            ELSIF c1.pdv_indikator_sifra = 'I1' THEN
--                l_3 := l_3 + abs(c1.iznos);
--
--            ELSIF c1.pdv_indikator_sifra = 'B2' THEN
--                l_9 := l_9 + abs(c1.iznos);
--                l_7 := l_7 + (l_1-abs(c1.iznos));
--                l_8 := l_8 + abs(c1.iznos);
--
--            ELSIF c1.pdv_indikator_sifra = 'B3' THEN
--                l_11 := l_11 + abs(c1.iznos);
--                l_7 := l_7 + (l_1 - abs(c1.iznos));
--                l_8 := l_8 + abs(c1.iznos);
--
--            ELSIF c1.pdv_indikator_sifra IN ('A2', 'A4', 'A5', 'B1', 'B4', 'D2') THEN
--                l_7 := l_7 + (l_1-abs(c1.iznos));
--                l_8 := l_8 + abs(c1.iznos);
--
--                IF c1.pdv_indikator_sifra IN ('A2', 'A4', 'A5') THEN
--                    l_2 := l_2 + abs(l_1);
--                END IF;
--                
--                IF c1.pdv_indikator_sifra IN ('A5', 'B1', 'B4', 'D2') THEN
--                    l_10 := l_10 + abs(c1.iznos);
--                END IF;
--
--            ELSIF c1.pdv_indikator_sifra IN ('A1', 'A7', 'D1') THEN
--                l_6 := l_6 + abs(c1.iznos);
--                l_5 := l_5 + (abs(l_1) - abs(c1.iznos));
--
--            ELSIF c1.pdv_indikator_sifra = 'B5' THEN
--                l_7 := l_7+ (l_1 - abs(c1.iznos));
--                l_8 := l_8 + abs(c1.iznos);
--                l_9 := l_9 + abs(c1.iznos);
--
--            ELSIF c1.pdv_indikator_sifra = 'B6' THEN
--                l_7 := l_7 + (l_1 - abs(c1.iznos));
--                l_8 := l_8 + abs(c1.iznos);
--                l_11 := l_11 + abs(c1.iznos);
--
--            ELSIF c1.pdv_indikator_sifra IN ('C1', 'C4') THEN
--                l_4 := l_4 + abs(c1.iznos);
--                l_7 := l_7 + abs(c1.iznos);
--                
--            END IF;

            if c1.pdv_indikator_sifra in ( 'A1', 'A7', 'D1', 'A6' ) then
                l_6 := l_6 + abs(c1.iznos);
            end if;

            if c1.pdv_indikator_sifra in ( 'B1', 'B2', 'B3', 'B4', 'B5',
                                           'B6', 'D2', 'A2', 'A4', 'A5' ) then
                l_8 := l_8 + abs(c1.iznos);
            end if;

            if c1.pdv_indikator_sifra in ( 'B2', 'B5', 'D3' ) then
                l_9 := l_9 + abs(c1.iznos);
            end if;

            if c1.pdv_indikator_sifra in ( 'B1', 'B4', 'D2' ) then
                l_10 := l_10 + abs(c1.iznos);
            end if;

            if c1.pdv_indikator_sifra in ( 'B3', 'B6', 'D4' ) then
                l_11 := l_11 + abs(c1.iznos);
            end if;

            if c1.pdv_indikator_sifra in ( 'A2', 'A4', 'A5' ) then
                case
                    when r_klijent.entitet_id = 2 then -- FBiH
                        l_9 := l_9 + abs(c1.iznos);
                    when r_klijent.entitet_id = 1 then -- RS
                        l_10 := l_10 + abs(c1.iznos);
                    when r_klijent.entitet_id = 3 then -- Brcko Distrikt
                        l_11 := l_11 + abs(c1.iznos);
                end case;
            end if;

        end loop;

        for c1 in c_kif_stavke loop
            -- Ukupan iznos fakture
            if c1.pdv_indikator_sifra != ( 'A6' ) then
                l_1 := l_1 + abs(c1.iznos_pdv);
            end if;

            if c1.pdv_indikator_sifra in ( 'A2', 'A4', 'A5' ) then
                l_2 := l_2 + abs(c1.iznos_pdv);
            end if;

            if c1.pdv_indikator_sifra in ( 'I1' ) then
                l_3 := l_3 + abs(c1.iznos_pdv);
            end if;

            if c1.pdv_indikator_sifra in ( 'C1', 'C2', 'C4', 'C5' ) then
                l_4 := l_4 + abs(c1.iznos_pdv);
            end if;

            -- Iznos osnovice
            if c1.pdv_indikator_sifra in ( 'A1', 'A7', 'D1' ) then
                l_5 := l_5 + abs(c1.iznos);
            end if;

            if c1.pdv_indikator_sifra in ( 'A2', 'A4', 'A5', 'B1', 'B2',
                                           'B3', 'B4', 'B5', 'B6', 'C1',
                                           'C2', 'C4', 'C5', 'D2' ) then
                l_7 := l_7 + abs(c1.iznos);
            end if;

        end loop;

        if r_glavna_knjiga.vrsta_naloga_id = sif.sif_pkg.get_id_with_sifra_vrsta_naloga('KO', r_glavna_knjiga.ooj_id) then
            l_1 := l_1 * ( -1 );
            l_2 := l_2 * ( -1 );
            l_3 := l_3 * ( -1 );
            l_4 := l_4 * ( -1 );
            l_5 := l_5 * ( -1 );
            l_6 := l_6 * ( -1 );
            l_7 := l_7 * ( -1 );
            l_8 := l_8 * ( -1 );
            l_9 := l_9 * ( -1 );
            l_10 := l_10 * ( -1 );
            l_11 := l_11 * ( -1 );
        end if;

        if r_kif.storniran_id is not null then
            l_1 := l_1 * ( -1 );
            l_2 := l_2 * ( -1 );
            l_3 := l_3 * ( -1 );
            l_4 := l_4 * ( -1 );
            l_5 := l_5 * ( -1 );
            l_6 := l_6 * ( -1 );
            l_7 := l_7 * ( -1 );
            l_8 := l_8 * ( -1 );
            l_9 := l_9 * ( -1 );
            l_10 := l_10 * ( -1 );
            l_11 := l_11 * ( -1 );
        end if;

        uio_pkg.insert_uio_kif(
            p_ooj_id                   => r_kif.ooj_id,
            p_faktura_id               => r_kif.id,
            p_vrsta_sloga              => 2,
            p_poreski_period           => l_poreski_period,
            p_redni_br                 => l_redni_broj,
            p_tip_dokumenta            => l_tip_dokumenta,
            p_broj_fakture             => r_kif.naziv_fakture,
            p_datum_fakture            => r_kif.datum_fakture,
            p_naziv_kupca              => r_klijent.naziv,
            p_sjediste_kupca           => r_klijent.adresa,
            p_pdv_broj_kupca           => r_klijent.pib,
            p_jib_broj_kupca           => r_klijent.jib,
            p_iznos_fakture            => to_char(
                coalesce(l_1, 0),
                'FM9999999990.00'
            ),
            p_iznos_fakture_interne    => to_char(
                coalesce(l_2, 0),
                'FM9999999990.00'
            ),
            p_iznos_fakture_izvozne    => to_char(
                coalesce(l_3, 0),
                'FM9999999990.00'
            ),
            p_iznos_ostale_bez_pdv     => to_char(
                coalesce(l_4, 0),
                'FM9999999990.00'
            ),
            p_iznos_osnovice_za_pdv    => to_char(
                coalesce(l_5, 0),
                'FM9999999990.00'
            ),
            p_iznos_izlaz_pdv_za_pdv   => to_char(
                coalesce(l_6, 0),
                'FM9999999990.00'
            ),
            p_iznos_osnovice_za_nepdv  => to_char(
                coalesce(l_7, 0),
                'FM9999999990.00'
            ),
            p_iznos_izlaz_pdv_za_nepdv => to_char(
                coalesce(l_8, 0),
                'FM9999999990.00'
            ),
            p_iznos_pdv_32polje        => to_char(
                coalesce(l_9, 0),
                'FM9999999990.00'
            ),
            p_iznos_pdv_33polje        => to_char(
                coalesce(l_10, 0),
                'FM9999999990.00'
            ),
            p_iznos_pdv_34polje        => to_char(
                coalesce(l_11, 0),
                'FM9999999990.00'
            )
        );

    end nalog_to_kif_uio_single;

    --------------------------------------------------------------
    -- procedures for AUTOMATION BLAGAJNA
    --------------------------------------------------------------

    function knjizi_blagajnu (
        p_ooj_id      in number,
        p_godina      in number,
        p_pp          in date,
        p_proknjizeno in varchar2
    ) return number is

        cursor c_dnevnici is
        (
            select
                id
            from
                blagajna_dnevnik
            where
                    ooj_id = p_ooj_id
                and glavna_knjiga_id is null
                and zakljucno_stanje is not null
                and trunc(datum, 'MM') = trunc(p_pp, 'MM')
        )
        order by
            datum asc;

        l_nalog_id number;
    begin
        apex_debug.message('DBG1 ' || p_ooj_id);
        apex_debug.message('DBG2 ' || p_godina);
        apex_debug.message('DBG3 ' || p_pp);
        apex_debug.message('DBG4 ' || p_proknjizeno);
        for c1 in c_dnevnici loop
            l_nalog_id := knjizi_blagajna_single(
                p_id          => c1.id,
                p_ooj_id      => p_ooj_id,
                p_godina      => p_godina,
                p_proknjizeno => p_proknjizeno
            );
        end loop;

        return l_nalog_id;
    end knjizi_blagajnu;

    function knjizi_blagajna_single (
        p_id          in number,
        p_ooj_id      in number,
        p_godina      in number,
        p_proknjizeno in varchar2
    ) return number is
        l_nalog_id         number;
        l_broj             number;
        l_vrsta_naloga_id  number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('bl');
        l_opis             varchar2(255);
        l_tip_stavke       varchar2(1);
        
        l_iznos            number;
        
        cursor c_stavke is
        (
            select
                case
                    when tip = 'U' then
                        abs(iznos) * - 1
                    else
                        abs(iznos)
                end as iznos,
                valuta_id,
                dnevnik_datum,
                kontna_klasa_id,
                case
                    when tip = 'U' then
                        'P'
                    else
                        'D'
                end as tip_stavke,
                radnik_id,
                klijent_id,
                oj_id
            from
                vw_blagajna_dnevnik_stavke
            where
                dnevnik_id = p_id
        );

        r_blagajna_dnevnik vw_blagajna_dnevnik%rowtype;
        l_stavka_gk_id number;
    begin
        select
            *
        into r_blagajna_dnevnik
        from
            vw_blagajna_dnevnik
        where
            id = p_id;

        l_opis := 'Automatsko knjiženje - '
                  || r_blagajna_dnevnik.blagajna_naziv
                  || ' - '
                  || to_char(r_blagajna_dnevnik.datum, 'DD.MM.YYYY');

        l_broj := get_broj_naloga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina
        );

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => r_blagajna_dnevnik.datum,
            p_datum_knjizenja => r_blagajna_dnevnik.datum,
            p_opis            => l_opis
        );

        if r_blagajna_dnevnik.zakljucno_stanje > r_blagajna_dnevnik.pocetno_stanje then
            l_tip_stavke := 'D';
        else
            l_tip_stavke := 'P';
        end if;
        
        l_iznos := (r_blagajna_dnevnik.zakljucno_stanje - r_blagajna_dnevnik.pocetno_stanje);
        if r_blagajna_dnevnik.valuta_id != 1 then
            l_iznos := sif.acc_pkg.convert_to_bam (
                p_valuta_id  => r_blagajna_dnevnik.valuta_id,
                p_vrijednost => l_iznos,
                p_datum      => r_blagajna_dnevnik.datum
            );
        end if;

        insert_glavna_knjiga_stavka(
            p_glavna_knjiga_id => l_nalog_id,
            p_kontna_klasa_id  => r_blagajna_dnevnik.kontna_klasa_id,
            p_tip_stavke       => l_tip_stavke,
            p_opis             => l_opis,
            p_iznos            => l_iznos,
            p_id               => l_stavka_gk_id
        );

        for stavka in c_stavke loop
            l_iznos := sif.acc_pkg.convert_to_bam (
                p_valuta_id  => r_blagajna_dnevnik.valuta_id,
                p_vrijednost => stavka.iznos,
                p_datum      => r_blagajna_dnevnik.datum
            );
        
            insert_glavna_knjiga_stavka(
                p_glavna_knjiga_id => l_nalog_id,
                p_kontna_klasa_id  => stavka.kontna_klasa_id,
                p_tip_stavke       => stavka.tip_stavke,
                p_opis             => l_opis,
                p_iznos            => l_iznos,
                p_radnik_id        => stavka.radnik_id,
                p_klijent_id       => stavka.klijent_id,
                p_oj_id            => stavka.oj_id,
                p_id               => l_stavka_gk_id
            );
        end loop;

        update blagajna_dnevnik
        set
            glavna_knjiga_id = l_nalog_id
        where
            id = p_id;

        if p_proknjizeno = 'Y' then
            set_proknjizeno(
                p_id    => l_nalog_id,
                p_value => p_proknjizeno
            );
        end if;

        return l_nalog_id;
    end knjizi_blagajna_single;

    --------------------------------------------------------------
    -- procedures for AUTOMATION SLUZBENI PUT (SP)
    --------------------------------------------------------------

    function knjizi_sp_zahtjev (
        p_zahtjev_id  in number,
        p_ooj_id      in number,
        p_godina      in number,
        p_proknjizeno in varchar2
    ) return number is

        l_nalog_id        number;
        l_broj            number;
        l_vrsta_naloga_id number := sif.sif_pkg.get_id_with_sifra_vrsta_naloga('spn');
        l_opis            varchar2(255);
        cursor c_troskovi is
        (
            select
                round(
                    sum(abs(iznos)),
                    2
                ) as iznos,
                tip_id,
                tip_naziv
            from
                hrm.vw_sp_troskovi
            where
                zahtjev_id = p_zahtjev_id
            group by
                tip_id,
                tip_naziv
        );

        l_bruto           number;
        l_porez           number;
        l_doprinos        number;
        l_neto            number;
        l_oj_id           number;
        l_entitet_id      number;
        l_kontna_klasa_id number;
        r_zahtjev         hrm.vw_sp_zahtjevi%rowtype;
        r_izvjestaj       hrm.vw_sp_izvjestaj%rowtype;
        l_stavka_gk_id    number;
    begin
        select
            *
        into r_zahtjev
        from
            hrm.vw_sp_zahtjevi
        where
            id = p_zahtjev_id;

        select
            *
        into r_izvjestaj
        from
            hrm.vw_sp_izvjestaj
        where
            zahtjev_id = p_zahtjev_id;

        hrm.evidencija_pkg.get_radnik(
            p_radnik_id  => r_zahtjev.radnik_id,
            p_oj_id      => l_oj_id,
            p_entitet_id => l_entitet_id
        );

        l_opis := 'Automatsko knjiženje - ' || r_zahtjev.broj_zahtjeva_naziv;
        l_broj := get_broj_naloga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina
        );

        l_nalog_id := insert_glavna_knjiga(
            p_ooj_id          => p_ooj_id,
            p_vrsta_naloga_id => l_vrsta_naloga_id,
            p_godina          => p_godina,
            p_broj            => l_broj,
            p_datum_dokumenta => last_day(r_zahtjev.datum_do),
            p_datum_knjizenja => last_day(r_zahtjev.datum_do),
            p_opis            => l_opis
        );

        for c1 in c_troskovi loop
            if c1.tip_id = 1 then -- Troškovi prevoza - putarine i ostalo
                if r_izvjestaj.ino_drzava = 'N' then
                    l_kontna_klasa_id := sif.acc_pkg.get_id_with_code_klasa(
                        p_entitet_id => l_entitet_id,
                        p_code       => '5252'
                    );

                    insert_glavna_knjiga_stavka(
                        p_glavna_knjiga_id => l_nalog_id,
                        p_kontna_klasa_id  => l_kontna_klasa_id,
                        p_tip_stavke       => 'D',
                        p_opis             => c1.tip_naziv,
                        p_iznos            => c1.iznos,
                        p_oj_id            => l_oj_id,
                        p_id               => l_stavka_gk_id
                    );

                    l_kontna_klasa_id := sif.acc_pkg.get_id_with_code_klasa(
                        p_entitet_id => l_entitet_id,
                        p_code       => '4630'
                    );

                    insert_glavna_knjiga_stavka(
                        p_glavna_knjiga_id => l_nalog_id,
                        p_kontna_klasa_id  => l_kontna_klasa_id,
                        p_tip_stavke       => 'P',
                        p_opis             => c1.tip_naziv,
                        p_iznos            => c1.iznos * - 1,
                        p_id               => l_stavka_gk_id
                    );

                else -- Inostranstvo
                    l_kontna_klasa_id := sif.acc_pkg.get_id_with_code_klasa(
                        p_entitet_id => l_entitet_id,
                        p_code       => '52521'
                    );

                    insert_glavna_knjiga_stavka(
                        p_glavna_knjiga_id => l_nalog_id,
                        p_kontna_klasa_id  => l_kontna_klasa_id,
                        p_tip_stavke       => 'D',
                        p_opis             => c1.tip_naziv,
                        p_iznos            => c1.iznos,
                        p_oj_id            => l_oj_id,
                        p_id               => l_stavka_gk_id
                    );

                    l_kontna_klasa_id := sif.acc_pkg.get_id_with_code_klasa(
                        p_entitet_id => l_entitet_id,
                        p_code       => '4630'
                    );

