                        p_iznos            => c1.iznos * - 1,
                        p_id               => l_stavka_gk_id
                    );

                end if;

            elsif c1.tip_id = 2 then -- Troškovi prevoza - gorivo
                l_bruto := round(c1.iznos / 0.61, 2);
                l_porez := round(l_bruto * 0.08, 2);
                l_doprinos := round(l_bruto * 0.31, 2);

                -- Bruto iznos 
