    --------------------------------------------------------------
    -- procedure/funkcije za analitiku zatvaranje otvorenih stavki u gk
    --------------------------------------------------------------
    
    function get_broj_zatvaranja (p_ooj_id number) return number is
      v_broj number;
    begin
         select COALESCE(MAX(z.broj) + 1, 1) AS sledeci_broj
         into v_broj
         from gk_analitika_zatvaranja z
         where z.ooj_id=p_ooj_id;
         
         return v_broj;
    end;
    
    procedure get_gk_analitika_zatvaranja (
        p_id                in  number,
        p_o_stavka_id       out number,
        p_z_stavka_id       out number,
        p_iznos_zatvaranja  out number
    ) is
    begin
        select o_stavka_id,
               z_stavka_id,
               iznos_zatvaranja
          into p_o_stavka_id,
               p_z_stavka_id,
               p_iznos_zatvaranja
          from gk_analitika_zatvaranja
         where id = p_id;
    exception
        when no_data_found then
            p_o_stavka_id      := null;
            p_z_stavka_id      := null;
            p_iznos_zatvaranja := null;
    end get_gk_analitika_zatvaranja;


    procedure insert_gk_analitika_zatvaranja (
        p_ooj_id            in number,
        p_broj              in number,
        p_o_stavka_id       in number,
        p_z_stavka_id       in number,
        p_iznos_zatvaranja  in number,
        p_storno            in varchar2, 
        p_id                out number
    ) is
    begin
        insert into gk_analitika_zatvaranja (
            ooj_id,
            broj,
            o_stavka_id,
            z_stavka_id,
            iznos_zatvaranja,
            storno
        ) values (
            p_ooj_id,
            p_broj,
            p_o_stavka_id,
            p_z_stavka_id,
            p_iznos_zatvaranja,
            p_storno
        )
        returning id into p_id;
    end insert_gk_analitika_zatvaranja;


    procedure update_gk_analitika_zatvaranja (
        p_id                in number,
        p_ooj_id            in number,
        p_broj              in number,
        p_o_stavka_id       in number,
        p_z_stavka_id       in number,
        p_iznos_zatvaranja  in number,
        p_storno            in varchar2 
    ) is
    begin
        update gk_analitika_zatvaranja
           set ooj_id            = p_ooj_id,
               broj              = p_broj,
               o_stavka_id       = p_o_stavka_id,
               z_stavka_id       = p_z_stavka_id,
               iznos_zatvaranja  = p_iznos_zatvaranja,
               storno            = p_storno
         where id = p_id;
    end update_gk_analitika_zatvaranja;


    procedure delete_gk_analitika_zatvaranja (
        p_id in number
    ) is
    begin
        delete from gk_analitika_zatvaranja
         where id = p_id;
    end delete_gk_analitika_zatvaranja;
    
    ----razvezivanje uparenih stavki---
    --- init djordjije ristanovic 27.07.2027---
    procedure razvezi_uparene_stavke_gk (
      p_id in number
    ) is 
    
    v_id number;
    p_broj number;
    p_ooj_id number;
    begin 
    
        ----
        select gz.ooj_id, gz.broj 
        into p_ooj_id,p_broj
        from accounting.gk_analitika_zatvaranja gz where gz.id=p_id;
        
        for r in (select gz.id, gz.iznos_zatvaranja,gz.ooj_id, gz.broj,
                         so.id as stavka_so, so.otvoreni_iznos as otvoreni_iznos_so, so.iznos iznos_so,
                         sz.id as stavka_sz, sz.otvoreni_iznos as otvoreni_iznos_sz, so.iznos iznos_sz
                  from accounting.gk_analitika_zatvaranja gz
                  join accounting.glavna_knjiga_stavke so on so.id=gz.o_stavka_id
                  join accounting.glavna_knjiga_stavke sz on sz.id=gz.z_stavka_id
                  where gz.ooj_id=p_ooj_id
                  and gz.broj=p_broj) 
        loop
          
             ----kako se ne bi narušila konzistencija izvještaja ne vršimo brisanje zatvaranja, već storniranje--
             
             --dodajemo storno iznos---
             accounting.glavna_knjiga_pkg.insert_gk_analitika_zatvaranja (
                p_ooj_id            =>r.ooj_id,
                p_broj              =>r.broj,
                p_o_stavka_id       =>r.stavka_so,
                p_z_stavka_id       =>r.stavka_sz,
                p_iznos_zatvaranja  =>-r.iznos_zatvaranja,
                p_storno            =>'S2',
                p_id                =>v_id
            );
            
            ---- updejtujemo originalno zatvaranje---
            
            update accounting.gk_analitika_zatvaranja zz
            set zz.storno='S1'
            where zz.id=r.id;
                        
            -----korigujemo otvorene iznose stavki gk---
            
            ----os--
            
            update accounting.glavna_knjiga_stavke so
            set so.otvoreni_iznos=so.otvoreni_iznos-r.iznos_zatvaranja,
                so.otvorena=case when so.otvoreni_iznos-r.iznos_zatvaranja=so.iznos then 'O' else 'DZ' end
            where so.id=r.stavka_so;
            
            ----sz--
            
            update accounting.glavna_knjiga_stavke sz
            set sz.otvoreni_iznos=sz.otvoreni_iznos+r.iznos_zatvaranja,
                sz.otvorena=case when sz.otvoreni_iznos+r.iznos_zatvaranja=sz.iznos then 'O' else 'DZ' end 
            where sz.id=r.stavka_sz;
            
        
        end loop;
    
    end;
    
    --------------------------------------------------------------
    -- procedure za vezu između stavke GK i izvornih dokumenata
    -- tabela gk_stavke_dokument 
    --------------------------------------------------------------
    
    procedure get_gk_stavka_dokument (
        p_id                        in  number,
        p_ooj_id                    out number,
        p_modul_id                  out number,
        p_dokument_id               out number,
        p_dokument                  out varchar2,
        p_opis                      out varchar2,
        p_glavna_knjiga_stavka_id   out number
    ) is
    begin
        select ooj_id,
               modul_id,
               dokument_id,
               dokument,
               opis,
               glavna_knjiga_stavka_id
          into p_ooj_id,
               p_modul_id,
               p_dokument_id,
               p_dokument,
               p_opis,
               p_glavna_knjiga_stavka_id
          from gk_stavke_dokument
         where id = p_id;
    exception
        when no_data_found then
            p_ooj_id                  := null;
            p_modul_id                := null;
            p_dokument_id             := null;
            p_dokument                := null;
            p_opis                    := null;
            p_glavna_knjiga_stavka_id := null;
    end get_gk_stavka_dokument;
 
 
    procedure insert_gk_stavka_dokument (
        p_ooj_id                    in number,
        p_modul_id                  in number,
        p_dokument_id               in number,
        p_dokument                  in varchar2,
        p_opis                      in varchar2,
        p_glavna_knjiga_stavka_id   in number,
        p_id                        out number
    ) is
    begin
        insert into gk_stavke_dokument (
            ooj_id,
            modul_id,
            dokument_id,
            dokument,
            opis,
            glavna_knjiga_stavka_id
        ) values (
            p_ooj_id,
            p_modul_id,
            p_dokument_id,
            p_dokument,
            p_opis,
            p_glavna_knjiga_stavka_id
        )
        returning id into p_id;
    end insert_gk_stavka_dokument;
 
 
    procedure update_gk_stavka_dokument (
        p_id                        in number,
        p_ooj_id                    in number,
        p_modul_id                  in number,
        p_dokument_id               in number,
        p_dokument                  in varchar2,
        p_opis                      in varchar2,
        p_glavna_knjiga_stavka_id   in number
    ) is
    begin
        update gk_stavke_dokument
           set ooj_id                   = p_ooj_id,
               modul_id                 = p_modul_id,
               dokument_id              = p_dokument_id,
               dokument                 = p_dokument,
               opis                     = p_opis,
               glavna_knjiga_stavka_id  = p_glavna_knjiga_stavka_id
         where id = p_id;
    end update_gk_stavka_dokument;
 
 
    procedure delete_gk_stavka_dokument (
        p_id in number
    ) is
    begin
        delete from gk_stavke_dokument
         where id = p_id;
    end delete_gk_stavka_dokument;

end glavna_knjiga_pkg;
