prompt
prompt Creating package body IZVJESTAJI_PKG
prompt ====================================
prompt
create or replace package body accounting.izvjestaji_pkg is

    --------------------------------------------------------------
    -- procedures for table SEC_IZVJESTAJI
    --------------------------------------------------------------

    procedure get_izvjestaj (
        p_id           in number,
        p_ooj_id       out number,
        p_izvjestaj_id out number,
        p_datum_od     out date,
        p_datum_do     out date,
        p_valid        out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_izvjestaji
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_izvjestaj_id := c1.izvjestaj_id;
            p_datum_od := c1.datum_od;
            p_datum_do := c1.datum_do;
            p_valid := c1.valid;
        end loop;
    end get_izvjestaj;

    function insert_izvjestaj (
        p_ooj_id       in number,
        p_izvjestaj_id in number,
        p_datum_od     in date,
        p_datum_do     in date
    ) return number is
        l_id number;
    begin
        insert into sec_izvjestaji (
            ooj_id,
            izvjestaj_id,
            datum_od,
            datum_do
        ) values ( p_ooj_id,
                   p_izvjestaj_id,
                   p_datum_od,
                   p_datum_do ) returning id into l_id;

        return l_id;
    end insert_izvjestaj;

    procedure delete_izvjestaj (
        p_id in number
    ) is
    begin
        delete from sec_izvjestaji
        where
            id = p_id;

    end delete_izvjestaj;

    --------------------------------------------------------------
    -- procedures for table SEC_IZVJESTAJI_AOP
    --------------------------------------------------------------

    procedure insert_izvjestaj_aop (
        p_izvjestaj_id     in number,
        p_aop_id           in number,
        p_bruto            in number,
        p_ispravka         in number,
        p_prethodna_godina in number
    ) is
    begin
        insert into sec_izvjestaji_aop (
            izvjestaj_id,
            aop_id,
            bruto,
            ispravka,
            prethodna_godina
        ) values ( p_izvjestaj_id,
                   p_aop_id,
                   p_bruto,
                   p_ispravka,
                   p_prethodna_godina );

    end insert_izvjestaj_aop;

    function is_aop_calculated (
        p_izvjestaj_id in number,
        p_aop_id       in number
    ) return number is
        l_count number;
    begin
        select
            count(*)
        into l_count
        from
            sec_izvjestaji_aop
        where
                izvjestaj_id = p_izvjestaj_id
            and aop_id = p_aop_id;

        return l_count;
    end is_aop_calculated;

    -- Bilans uspjeha
    procedure calculate_aop (
        p_izvjestaj_id     in number,
        p_aop_id           in number,
        p_bruto            out number,
        p_ispravka         out number,
        p_prethodna_godina out number
    ) is
    begin
        select
            sum(
                case
                    when g.sum_tip = 'P' then
                        a.bruto
                    when g.sum_tip = 'M' then
                        -(a.bruto)
                    else
                        0
                end
            ),
            sum(
                case
                    when g.sum_tip = 'P' then
                        a.ispravka
                    when g.sum_tip = 'M' then
                        -(a.ispravka)
                    else
                        0
                end
            ),
            sum(
                case
                    when g.sum_tip = 'P' then
                        a.prethodna_godina
                    when g.sum_tip = 'M' then
                        -(a.prethodna_godina)
                    else
                        0
                end
            )
        into
            p_bruto,
            p_ispravka,
            p_prethodna_godina
        from
            sec_izvjestaji_aop a
            left join sif.acc_aop_grupe  g on a.aop_id = g.sum_id
                                             and g.aop_id = p_aop_id
        where
                izvjestaj_id = p_izvjestaj_id
            and a.aop_id in (
                select
                    sum_id
                from
                    sif.acc_aop_grupe g
                where
                    g.aop_id = p_aop_id
            );

    end calculate_aop;

    function generate_izvjestaj (
        p_tip_izvjestaja_id in number,
        p_izvjestaj_id      in number
    ) return number is

        l_insert_count     number := 0;
        l_insert           number;
        l_bruto            number;
        l_ispravka         number;
        l_prethodna_godina number;
        cursor c_aop is
        (
            select
                id
            from
                sif.acc_izvjestaji_aop s
            where
                    s.izvjestaj_id = p_tip_izvjestaja_id
                and tip = 'G'
                and id not in (
                    select
                        aop_id
                    from
                        sec_izvjestaji_aop i
                    where
                        i.izvjestaj_id = p_izvjestaj_id
                )
        );

        cursor c_aop_grupe (
            p_aop_id number
        ) is
        (
            select
                sum_tip,
                sum_id
            from
                sif.acc_aop_grupe
            where
                aop_id = p_aop_id
        );

    begin
        for c1 in c_aop loop
            l_insert := 1;
            for c2 in c_aop_grupe(c1.id) loop
                if is_aop_calculated(p_izvjestaj_id, c2.sum_id) = 0 then
                    l_insert := 0;
                end if;
            end loop;

            if l_insert = 1 then
                calculate_aop(
                    p_izvjestaj_id     => p_izvjestaj_id,
                    p_aop_id           => c1.id,
                    p_bruto            => l_bruto,
                    p_ispravka         => l_ispravka,
                    p_prethodna_godina => l_prethodna_godina
                );

                l_bruto := greatest(0, l_bruto);
                l_ispravka := greatest(0, l_ispravka);
                l_prethodna_godina := greatest(0, l_prethodna_godina);
                insert_izvjestaj_aop(
                    p_izvjestaj_id     => p_izvjestaj_id,
                    p_aop_id           => c1.id,
                    p_bruto            => l_bruto,
                    p_ispravka         => l_ispravka,
                    p_prethodna_godina => l_prethodna_godina
                );

                l_insert_count := l_insert_count + 1;
            end if;

        end loop;

        if l_insert_count > 0 then
            return generate_izvjestaj(p_tip_izvjestaja_id, p_izvjestaj_id);
        else
            return 0;
        end if;

    end generate_izvjestaj;

end izvjestaji_pkg;
/

prompt
prompt Creating package body KASA_PKG
prompt ==============================
prompt
create or replace package body accounting.kasa_pkg as

    g_money    varchar2(32) := 'FM999999990D90';
    g_quantity varchar2(32) := 'FM999999990D990';

    function create_latest_version_json return clob is
        l_json clob;
    begin
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('latest_version', '0.9');
        apex_json.open_array('changelog');
        apex_json.write('* changed environment');
        apex_json.close_array;
        apex_json.write('mandatory', true);
        apex_json.close_object;

        -- Get JSON
        l_json := apex_json.get_clob_output;
        apex_json.free_output;
        dbms_output.put_line(l_json);
        return l_json;
    end create_latest_version_json;

    function generate_middleware_url (
        p_kasa_id         in number,
        p_korisnik_id     in number,
        p_ooj_id          in number,
        p_kif_id          in number,
        p_print_on_device in varchar2 default 'N',
        p_training        in varchar2 default 'N',
        p_email           in varchar2 default 'N',
        p_footer          in varchar2 default 'Y'
    ) return varchar2 is
        l_base_url varchar2(255) := 'http://localhost:5000/api/normal';
        l_full_url varchar2(255);
    begin
        l_full_url := l_base_url
                      || '?kasa_id='
                      || p_kasa_id
                      || '&'
                      || 'korisnik_id='
                      || p_korisnik_id
                      || '&'
                      || 'ooj_id='
                      || p_ooj_id
                      || '&'
                      || 'kif_id='
                      || p_kif_id
                      || '&'
                      || 'print_on_device='
                      || p_print_on_device
                      || '&'
                      || 'training='
                      || p_training
                      || '&'
                      || 'email='
                      || p_email
                      || '&'
                      || 'footer='
                      || p_footer;

        return l_full_url;
    end generate_middleware_url;

    function create_kif_json (
        p_kasa_id         in number,
        p_korisnik_id     in number,
        p_ooj_id          in number,
        p_kif_id          in number,
        p_copy            in varchar2 default 'N',
        p_referent_number in varchar2 default null,
        p_referent_dt     in timestamp default null,
        p_print_on_device in varchar2 default 'N',
        p_training        in varchar2 default 'N',
        p_email           in varchar2 default 'N',
        p_footer          in varchar2 default 'Y'
    ) return clob is

        cursor c_kasa is
        (
            select
                pin,
                bearer,
                host,
                ooj_id
            from
                sec_kase
            where
                id = p_kasa_id
        );

        cursor c_korisnik is
        (
            select
                initcap(ime)
                || ' '
                || initcap(prezime)
            from
                core.korisnici
            where
                id = p_korisnik_id
        );

        cursor c_kif is
        (
            select
                ooj_id,
                to_char(iznos_fakture, g_money) as iznos_fakture,
                tip_placanja_sifra,
                vrsta_fakture_sifra,
                vrsta_fakture_fiskalizacija,
                stornirano,
                fiskalizovano,
                upper(klijent_naziv)            as klijent_naziv
            from
                vw_kif
            where
                id = p_kif_id
        );

        cursor c_stavke is
        (
            select
                id,
                stavka_naziv                  as naziv,
                to_char(kolicina, g_quantity) as kolicina,
                to_char(cijena_pdv, g_money)  as cijena,
                to_char(iznos_pdv, g_money)   as iznos,
                pdv
            from
                vw_kif_stavke
            where
                kif_id = p_kif_id
        );

        cursor c_firma is
        (
            select
                logo_base64
            from
                core.firme
            where
                id = (
                    select
                        firma_id
                    from
                        core.ooj
                    where
                        id = p_ooj_id
                )
        );

        -- Racun
        l_ooj_id                      number;
        l_ukupan_iznos                varchar2(255);
        l_tip_placanja                varchar2(255);
        l_vrsta_fakture_sifra         varchar2(64);
        l_vrsta_fakture_fiskalizacija varchar2(1);
        l_stornirano                  varchar2(1);
        l_fiskalizovano               varchar2(1);
        l_transaction_type            varchar2(16);
        l_klijent_naziv               varchar2(255);

        -- Korisnik
        l_korisnik                    varchar2(255);

        -- Kasa
        l_kasa_ooj_id                 number;
        l_pin                         varchar2(32);
        l_bearer                      varchar2(255);
        l_host                        varchar2(255);

        -- Firma
        l_logo_base64                 clob;

        -- OOJ
        l_email                       varchar2(255);

        -- JSON
        l_json                        clob;
    begin
        -- Uzimamo podatke od fakture (i provjeravamo da li je OOJ_ID OK)
        open c_kif;
        fetch c_kif into
            l_ooj_id,
            l_ukupan_iznos,
            l_tip_placanja,
            l_vrsta_fakture_sifra,
            l_vrsta_fakture_fiskalizacija,
            l_stornirano,
            l_fiskalizovano,
            l_klijent_naziv;

        close c_kif;
        if p_ooj_id != l_ooj_id then
            raise_application_error(-20001, 'Ne možete fiskalizovati ovu fakturu. (1)');
        end if;
        if l_vrsta_fakture_fiskalizacija != 'Y' then
            raise_application_error(-20006, 'Ne možete fiskalizovati ovaj tip računa.');
        end if;
        if l_fiskalizovano = 'Y' then
            raise_application_error(-20004, 'Ovaj račun je već fiskalizovan.');
        end if;

        -- Uzimamo podatke od kase (i provjeravamo da li je OOJ_ID OK)
        open c_kasa;
        fetch c_kasa into
            l_pin,
            l_bearer,
            l_host,
            l_kasa_ooj_id;
        close c_kasa;
        if p_ooj_id != l_kasa_ooj_id then
            raise_application_error(-20002, 'Ne možete fiskalizovati ovu fakturu. (2)');
        end if;

        -- Uzimamo podatke od prodavca (i provjeravamo da li je OOJ_ID OK)
        open c_korisnik;
        fetch c_korisnik into l_korisnik;
        close c_korisnik;

        -- Uzimamo podatke od firme (logo za header)
        open c_firma;
        fetch c_firma into l_logo_base64;
        close c_firma;
        if l_stornirano = 'Y' then
            l_transaction_type := 'Refund';
        else
            l_transaction_type := 'Sale';
        end if;

        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.open_object('racun');
        -- Print
        if p_print_on_device = 'N' then
            apex_json.write('print', false);
            apex_json.write('receiptLayout', 'Slip');
            apex_json.write('receiptImageFormat', 'Png');
            apex_json.write('receiptSlipWidth', '386');
            apex_json.write('receiptSlipFontSizeNormal', 23);
            apex_json.write('receiptSlipFontSizeLarge', 27);
        end if;

        apex_json.write('renderReceiptImage', true);
        if p_email = 'Y' then
            core.ooj_pkg.get_ooj_email(
                p_id    => p_ooj_id,
                p_email => l_email
            );
            apex_json.write('email', l_email);
        end if;

        if p_footer = 'Y' then
            apex_json.open_array('receiptFooterTextLines');
            apex_json.write('Klijent: ' || l_klijent_naziv);
            apex_json.write('By ESSCOM');
            apex_json.close_array;
        end if;

        if l_logo_base64 is not null then
            apex_json.write('receiptHeaderImage', l_logo_base64);
        end if;
        apex_json.open_object('invoiceRequest');

        -- Testiranje
         if p_training = 'Y' then
             l_vrsta_fakture_sifra := 'Training';
         end if;
--        l_vrsta_fakture_sifra := 'Training';
        -- COPY
        if p_copy = 'Y' then
            apex_json.write('invoiceType', l_vrsta_fakture_sifra); -- Copy inace
            apex_json.write('transactionType', l_transaction_type);
            apex_json.write('referentDocumentNumber', p_referent_number);
            apex_json.write('referentDocumentDT', p_referent_dt);
        else
            apex_json.write('invoiceType', l_vrsta_fakture_sifra);
            apex_json.write('transactionType', l_transaction_type);
        end if;

        -- Payment
        apex_json.open_array('payment');
        apex_json.open_object;
        apex_json.write('amount', l_ukupan_iznos);
        apex_json.write('paymentType', l_tip_placanja);
        apex_json.close_object;
        apex_json.close_array;

        -- Items
        apex_json.open_array('items');
        for stavka in c_stavke loop
            apex_json.open_object;
            apex_json.write('name', stavka.naziv);
            apex_json.write('gtin',
                            lpad(stavka.id, 8, '0'));

            -- Labels
            apex_json.open_array('labels');
            if stavka.pdv > 0 then
                apex_json.write('Е'); -- Cirilica
            else
                apex_json.write('К'); -- Cirilica
            end if;

            apex_json.close_array;
            -- End of labels

            apex_json.write('totalAmount', stavka.iznos);
            apex_json.write('unitPrice', stavka.cijena);
            apex_json.write('quantity', stavka.kolicina);
            apex_json.close_object;
        end loop;

        apex_json.close_array;
        -- End of items

        apex_json.write('cashier', l_korisnik);
        apex_json.close_object; -- invoiceRequest
        apex_json.close_object; -- racun

        apex_json.open_object('kasa');
        apex_json.write('pin', l_pin);
        apex_json.write('bearer', l_bearer);
        apex_json.write('host', l_host);
        apex_json.close_object;
        apex_json.close_object; -- Global

        -- Get JSON
        l_json := apex_json.get_clob_output;
        apex_json.free_output;

--        dbms_output.put_line(l_json);
        return l_json;
    end create_kif_json;

    procedure update_kif_fiskalni_racun (
        p_kif_id           in number,
        p_fiskalni_racun   in blob,
        p_fiskalni_isjecak in varchar2
    ) is
        l_broj     number;
        l_sifra    varchar2(64);
        l_filename varchar2(255);
    begin
        finansije_pkg.get_kif(
            p_id                  => p_kif_id,
            p_faktura_broj        => l_broj,
            p_vrsta_fakture_sifra => l_sifra
        );

        l_filename := 'racun-'
                      || l_sifra
                      || '-'
                      || l_broj
                      || '.png';
        update kif
        set
            fiskalni_racun_broj = p_fiskalni_isjecak,
            fiskalni_racun = p_fiskalni_racun,
            fiskalni_racun_filename = l_filename,
            fiskalni_racun_mimetype = 'image/png',
            fiskalni_racun_lastupd = sysdate,
            fiskalizovano = 'Y'
        where
            id = p_kif_id;

    end update_kif_fiskalni_racun;

end kasa_pkg;
/

prompt
prompt Creating package body MAIL_PKG
prompt ==============================
prompt
create or replace package body accounting.mail_pkg as

    procedure posalji_faktura (
        p_ooj_id   in number,
        p_to       in varchar2,
        p_subject  in varchar2,
        p_cc       in varchar2,
        p_bcc      in varchar2,
        p_poruka   in varchar2,
        p_dokument in varchar2
    ) is

        l_email_id number;
        l_reply    varchar2(255);
        l_blob     blob;
        l_filename varchar2(255);
        l_mimetype varchar2(255);
    begin
        if p_dokument is null then
            raise_application_error(-20001, 'Došlo je do greške, pokušajte opet.');
        end if;
        sif.utils_pkg.get_apex_file_upload(
            p_apex_filename => p_dokument,
            p_blob          => l_blob,
            p_filename      => l_filename,
            p_mimetype      => l_mimetype
        );

        core.ooj_pkg.get_ooj_email(
            p_id    => p_ooj_id,
            p_email => l_reply
        );
        l_email_id := apex_mail.send(
--            p_to                 => p_to,
            p_to        => 'nikola.supic@esscom.ba',
            p_from      => hrm.mail_pkg.mail_from,
            p_replyto   => l_reply,
            p_cc        => p_cc,
            p_bcc       => p_bcc,
            p_subj      => p_subject,
            p_body      => p_poruka,
            p_body_html => p_poruka
        );

        apex_mail.add_attachment(
            p_mail_id    => l_email_id,
            p_attachment => l_blob,
            p_filename   => l_filename,
            p_mime_type  => l_mimetype
        );

        apex_mail.push_queue;
    end posalji_faktura;

    procedure posalji_os_odrzavanje (
        p_app_id            in varchar2,
        p_username          in varchar2,
        p_mail_to           in varchar2,
        p_name              in varchar2,
        p_os_razlika        in varchar2,
        p_os_naziv          in varchar2,
        p_os_odrzavanje     in varchar2,
        p_os_datum          in varchar2,
        p_os_cijena         in varchar2,
        p_os_sledeci_servis in varchar2
    ) is

        l_subject           varchar2(255);
        l_mini              varchar2(255);
        l_mailing           varchar2(1);
        l_sekretarice_email varchar2(512);
    begin
        if not hrm.mail_pkg.check_username(p_username) then
            return;
        end if;
        core.korisnik_pkg.get_korisnik_mailing(
            p_korisnicko_ime    => p_username,
            p_email             => p_mail_to,
            p_mailing           => l_mailing,
            p_sekretarice_email => l_sekretarice_email
        );

        l_subject := 'Održavanje osnovnog sredstva';
        l_mini := 'Održavanje osnovnog sredstva '
                  || p_os_naziv
                  || ' je za '
                  || p_os_razlika
                  || ' dana.';
        if l_mailing = 'Y' then
            apex_mail.send(
                p_application_id     => p_app_id,
                p_from               => hrm.mail_pkg.mail_from,
                p_to                 => p_mail_to,
                p_cc                 => l_sekretarice_email,
                p_template_static_id => 'OS_ODRZAVANJE',
                p_placeholders       => '{'
                                  || '    "SUBJECT":'
                                  || apex_json.stringify(l_subject)
                                  || '   ,"NAME":'
                                  || apex_json.stringify(p_name)
                                  || '   ,"OS_RAZLIKA":'
                                  || apex_json.stringify(p_os_razlika)
                                  || '   ,"OS_NAZIV":'
                                  || apex_json.stringify(p_os_naziv)
                                  || '   ,"OS_ODRZAVANJE":'
                                  || apex_json.stringify(p_os_odrzavanje)
                                  || '   ,"OS_DATUM":'
                                  || apex_json.stringify(p_os_datum)
                                  || '   ,"OS_CIJENA":'
                                  || apex_json.stringify(p_os_cijena)
                                  || '   ,"OS_SLEDECI_SERVIS":'
                                  || apex_json.stringify(p_os_sledeci_servis)
                                  || '   ,"LOGIN_URL":'
                                  || apex_json.stringify(hrm.mail_pkg.login_url)
                                  || '   ,"MAIL_FOOTER":'
                                  || apex_json.stringify(hrm.mail_pkg.footer)
                                  || '}'
            );
        end if;

        -- Posalji notifikaciju
        core.notifikacije_pkg.send_notification(
            p_application_id => p_app_id,
            p_sifra          => 'OS_ODRZAVANJE',
            p_user_name      => p_username,
            p_title          => l_subject,
            p_body           => l_mini
        );

    end posalji_os_odrzavanje;

    procedure posalji_uio_odgovor (
        p_app_id   in varchar2,
        p_username in varchar2,
        p_mail_to  in varchar2,
        p_name     in varchar2,
        p_odgovor  in varchar2
    ) is

        l_subject           varchar2(255);
        l_mini              varchar2(255);
        l_mailing           varchar2(1);
        l_sekretarice_email varchar2(512);
    begin
        if not hrm.mail_pkg.check_username(p_username) then
            return;
        end if;
        core.korisnik_pkg.get_korisnik_mailing(
            p_korisnicko_ime    => p_username,
            p_email             => p_mail_to,
            p_mailing           => l_mailing,
            p_sekretarice_email => l_sekretarice_email
        );

        l_subject := 'Automatski unio KIF / KUF fajlova';
        l_mini := 'Zahtjev za automatski unos fajlova je obrađen.';
        if l_mailing = 'Y' then
            apex_mail.send(
                p_application_id     => p_app_id,
                p_from               => hrm.mail_pkg.mail_from,
                p_to                 => p_mail_to,
                p_cc                 => l_sekretarice_email,
                p_template_static_id => 'UIO_ODGOVOR',
                p_placeholders       => '{'
                                  || '    "SUBJECT":'
                                  || apex_json.stringify(l_subject)
                                  || '   ,"NAME":'
                                  || apex_json.stringify(p_name)
                                  || '   ,"ODGOVOR":'
                                  || apex_json.stringify(p_odgovor)
                                  || '   ,"LOGIN_URL":'
                                  || apex_json.stringify(hrm.mail_pkg.login_url)
                                  || '   ,"MAIL_FOOTER":'
                                  || apex_json.stringify(hrm.mail_pkg.footer)
                                  || '}'
            );

            apex_mail.push_queue;
        end if;

        -- Posalji notifikaciju
        core.notifikacije_pkg.send_notification(
            p_application_id => p_app_id,
            p_sifra          => 'UIO_ODGOVOR',
            p_user_name      => p_username,
            p_title          => l_subject,
            p_body           => l_mini
        );

        apex_pwa.push_queue;
    end posalji_uio_odgovor;

end mail_pkg;
/

prompt
prompt Creating package body MIGRACIJA_PKG
prompt ===================================
prompt
create or replace package body accounting.MIGRACIJA_PKG is

 procedure migracija_pdv_indikatori is
   l_tdpi_id number;
 begin



      for i in (select 'A3' as sifra,'17% PDV po osn. utvrđenih manjkova na teret rashoda'    as naziv, 'Manjak kojim se tereti kompanija '                     as opis, 17 as vrijednost,'I' as UI, 47 as kontna_klasa, 'Y' as valid from dual
          /*union all
          select 'A6' as sifra,'17% usluge inodobavljača'                               as naziv, 'Usluge inodobavljača'                                  as opis, 17 as vrijednost,'I' as UI, 47 as kontna_klasa, 'Y' as valid from dual
          */union all
          select 'C6' as sifra,'0% primljeni avans - IPA fond'                          as naziv, 'Primljeni avans - IPA fond'                            as opis, 0 as vrijednost, 'I' as UI, 47 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'C7' as sifra,'0% prodaja nepokretnosti'                               as naziv, 'Prodaja nepokretnosti'                                 as opis, 0 as vrijednost, 'I' as UI, 47 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'D5' as sifra,'nabavka nepokr. imovine sa pravom na odb. PDV'          as naziv, 'Knjižna odobrenja za isporuke oslob. PDV-a'            as opis, 0 as vrijednost, 'I' as UI, 47 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'N1' as sifra,'17% nabavka nepokr. imovine sa pravom na odbitak'       as naziv, 'Nabavka nepokr. imovine sa pravom na odbitak'          as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'N2' as sifra,'17% nabavka opreme sa pravom na odbitak PDV'            as naziv, 'Nabavka opreme sa pravom na odbitak PDV'               as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'N3' as sifra,'17% knjižna odobrenja sa pravom na odbitak PDV'         as naziv, 'Knjižna odobrenja sa pravom na odbitak PDV'            as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'N4' as sifra,'5% knjižna odobrenja poljopr. sa pravom na odbitak PDV' as naziv, 'Knjižna odobrenja poljopr. sa pravom na odbitak PDV'   as opis, 5  as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'N5' as sifra,'17% knjižna odobrenja bez prava na odbitak'             as naziv, 'Knjižna odobrenja bez prava na odbitak'                as opis, 17 as vrijednost,'U' as UI, 28 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'O2' as sifra,'17% obračunski na date avanse'                          as naziv, 'Obračunski na date avanse'                             as opis, 17 as vrijednost,'U' as UI, 28 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'O3' as sifra,'17% obračunski prilikom uvoza obrtnih sredstava'        as naziv, 'Obračunski prilikom uvoza obrtnih sredstava'           as opis, 17 as vrijednost,'U' as UI, 28 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'O4' as sifra,'17% obračunski prilikom uvoza stalnih sredstava'        as naziv, 'Obračunski prilikom uvoza stalnih sredstava'           as opis, 17 as vrijednost,'U' as UI, 28 as kontna_klasa, 'Y' as valid from dual
          --union all
          --select 'O6' as sifra,'17% obračunski odobrenja kupcima'                       as naziv, 'Obračunski odobrenja kupcima'                          as opis, 17 as vrijednost,'U' as UI, 49 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'O7' as sifra,'17% primljene fakt. bez prava na odb prethodna godina'  as naziv, 'Primljene fakt. bez prava na odb prethodna godina'      as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'P4' as sifra,'5% na primljene fakture od poljoprivrednika'            as naziv, 'Na primljene fakture od poljoprivrednika'               as opis, 5  as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'P5' as sifra,'17% na usluge ino lica za nabavku obrtnih sredstava'    as naziv, 'Na usluge ino lica za nabavku obrtnih sredstava'        as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'R2' as sifra,'17% prim fak bez prava na odbitak - ino usluge'         as naziv, 'Prim fak bez prava na odbitak - ino usluge'             as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'R3' as sifra,'17% dati avans bez prava na odbitak'                    as naziv, 'Dati avans bez prava na odbitak'                        as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'R4' as sifra,'17% primljene fakture uvoz nema prava odbitka'          as naziv, 'Primljene fakture uvoz nema prava odbitka'              as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'U5' as sifra,'17% akont.PDV plaćen prilikom uvoza - IM6'              as naziv, 'Akont.PDV plaćen prilikom uvoza - IM6'                  as opis, 17 as vrijednost,'U' as UI, 27 as kontna_klasa, 'Y' as valid from dual
          union all
          select 'U7' as sifra,'17% uvoz bez prava odbitka - RUCNI'                     as naziv, 'Uvoz bez prava odbitka - RUCNI'                         as opis, 17 as vrijednost,'U' as UI, 28 as kontna_klasa, 'Y' as valid from dual
        )
        loop


                  sif.acc_pkg.insert_pdv_indikator(i.sifra, i.naziv, i.opis, i.vrijednost, i.ui, to_char(i.kontna_klasa));



        end loop;

        --dezaktivirati stare pdv indikatore
        for j in (select *
                  from sif.acc_pdv_indikatori apv
                  where apv.sifra in ('C2', 'C3', 'U3', 'U4', 'U6')
                  )
        loop
                sif.acc_pkg.update_pdv_indikator (j.id,j.sifra,j.naziv,j.opis,j.vrijednost,j.ui,j.kontna_klasa_prefix,'N');
        end loop;

        for j1 in (select *
                  from sif.acc_pdv_indikatori apv
                  where apv.sifra in ('A6')
                  )
        loop

                sif.acc_pkg.update_pdv_indikator (j1.id,j1.sifra,j1.naziv,j1.opis,j1.vrijednost,'I',j1.kontna_klasa_prefix,j1.valid);

        end loop;


        ----dodati mapiranje između uio tip dokumenta i pdv indikatora ----


        for k in (with indikatori as (select apv.id, apv.sifra,apv.naziv, apv.ui,apv.valid, case when apv.sifra in ('A1', 'A5', 'B1', 'B2', 'B3', 'C1', 'C4', 'C5', 'C7', 'D1', 'D2', 'D3', 'D4', 'D5') then '01'
                                               when apv.sifra in ('A2') then '02'
                                               when apv.sifra in ('A7', 'B4', 'B5', 'B6', 'C6') then '03'
                                               when apv.sifra in ('I1') then '04'
                                               when apv.sifra in ('A6') then '05'
                                               when apv.sifra in ('A3', 'A4') then '07'
                                               when apv.sifra in ('N1', 'N2', 'P1', 'P2', 'P4', 'R1', 'S1', 'S2') then '01'
                                               when apv.sifra in ('P3', 'R3') then '03'
                                               when apv.sifra in ('R4', 'U1', 'U2', 'U5', 'U7') then '04'
                                               when apv.sifra in ('P5', 'P6', 'P7', 'R2', 'S3', 'S4') then '05'
                                               when apv.sifra in ('N3', 'N4', 'N5') then '06'
                                          else null
                                          end as tip,

                                          case when apv.sifra in ('B1', 'B4', 'D2') then 'rs'
                                               when apv.sifra in ('B2', 'B5', 'D3') then 'fbih'
                                               when apv.sifra in ('B3', 'B6', 'D4') then 'brd'
                                               else null
                                          end as entitet

                       from sif.acc_pdv_indikatori apv)
                       select i.id pdv_id,i.sifra pdv_sifra, d.id dok_id,d.code as dok_sifra, sn.id ent_id, sn.sifra as ent_sifra from indikatori i
                       join sif.acc_uio_tipovi_dokumenata d on d.ui=i.ui and d.code=i.tip
                       left join sif.sif_entiteti sn on sn.sifra=i.entitet
                       order by d.id,i.sifra)
          loop

                       sif.acc_pkg.insert_uio_tip_dokumenta_pdv_indikatori(l_tdpi_id,k.dok_id, k.pdv_id, k.ent_id,'Y');

          end loop;

        -------------------------------------------------------------------

        commit;

end;

 procedure migracija_vrste_dokumenata is
   l_vd_id number;
   l_app_id number;
   l_fiskal_sifra varchar2;
   l_tip_kretanja varchar2;
   l_modul_id number;
 begin

       ---inicijalno popunjavanje vrste dokumenata, kasnije ćemo ručno odraditi korekcije
       for k in (select * from sif.sif_vrste_naloga sn)
       loop
             select ka.id
             into l_app_id
             from sif.sif_aplikacije ka
             where upper(ka.naziv)=(case k.app when 'ACC' then 'FINANSIJE' when 'CS' then 'CAR SERVICE' else 'HR' end);

             select case k.sifra
                                     when 'AV' then  'Advance'
                                     when 'IF' then  'Normal'
                                     when 'KZ' then  'KZ'
                                     when 'KO' then  'KO'
                                     when 'IN' then  'IN'
                                     when 'PR'  then 'PR'
                                     else null
                        end
             into l_tip_kretanja
             from dual;


             sif.acc_pkg.insert_vrste_dokumenata(
                    p_app_id          => l_app_id,
                    p_acc_modul_id    => k.acc_modul_id,
                    p_ooj_id          =>  k.ooj_id,
                    p_sifra           =>  k.sifra,
                    p_naziv           =>  k.naziv,
                    p_opis            =>  k.opis,
                    p_vrsta_naloga_id =>  k.id,
                    p_fiskalna_sifra  =>  l_fiskal_sifra,
                    p_tip_kretanja    =>  null,
                    p_valid           =>  k.valid,
                    p_id              =>  l_vd_id
             );

       end loop;
       
       ---dodavanje novih vrsta dokumenata----
       for ii in (select distinct vd.ooj_id from sif.vrste_dokumenata vd )
       loop
         --avnans zatvaranje ---
         
         for vdk in (select (select ka.id from sif.sif_aplikacije ka where upper(ka.naziv)='FINANSIJE') as app_id,
                            ( select am.id from sif.acc_moduli am where upper(am.sifra)='IF') as modul_id, 
                            'AVZ' sifra, 
                            'Avansna faktura - Zatvaranje' naziv, 
                            (select vd.vrsta_naloga_id from sif.vrste_dokumenata vd where UPPER(vd.Sifra)='AV' and vd.ooj_id=219) as nalog_id,
                            (select vd.fiskalna_sifra from sif.vrste_dokumenata vd where UPPER(vd.Sifra)='AV' and vd.ooj_id=219 ) as fiskalna_sifra 
                     from dual
                     )
         loop 
             
            
           sif.acc_pkg.insert_vrste_dokumenata(
                    p_app_id          => vdk.app_id,
                    p_acc_modul_id    => vdk.modul_id,
                    p_ooj_id          =>  ii.ooj_id,
                    p_sifra           =>  vdk.sifra,
                    p_naziv           =>  vdk.naziv,
                    p_opis            =>  vdk.naziv,
                    p_vrsta_naloga_id =>  vdk.nalog_id,
                    p_fiskalna_sifra  =>  vdk.fiskalna_sifra,
                    p_tip_kretanja    =>  null,
                    p_valid           =>  'Y',
                    p_id              =>  l_vd_id
             );
             
          end loop;
         
       end loop;
       ---

       -------
       ---mapiranje protokola --
       for p in (select * from core.protokoli p where p.ooj_id!=219)
       loop


         select vd.id
         into l_vd_id
         from sif.vrste_dokumenata vd
         where vd.vrsta_naloga_id=p.vrsta_naloga_id;


          core.protokoli_pkg.update_protokol (
              p_id              => p.id,
              p_ooj_id          => p.ooj_id,
              p_vrsta_naloga_id => l_vd_id,
              p_godina          => p.godina,
              p_prefix          => p.prefix,
              p_broj            => p.broj,
              p_sufix           => p.sufix,
              p_duzina          => p.duzina,
              p_auto_restart    => p.auto_restart,
              p_valid           => p.valid
             );

       end loop;


      ------

 end;

 procedure migracija_kontnog_plana is

  l_nad_konto number;
  l_nk_code varchar2(10);
  l_nk_ooj_id number;
  l_konto_id number;

  begin
  ---dodjela dafoultnog kontnog plana korisniku----
  for ooj in (select distinct gk.ooj_id from accounting.glavna_knjiga gk where gk.ooj_id=219 )
  loop

        for kp in (SELECT *
                    FROM sif.acc_kontni_okvir_klase
                    WHERE ooj_id IS NULL
                    and length(code)>3
                    START WITH kontna_klasa_id IS NULL
                    CONNECT BY PRIOR id = kontna_klasa_id)
        loop

            dbms_output.put_line(kp.code||'-'||kp.kontna_klasa_id);
            select nk.code, nk.ooj_id
            into l_nk_code, l_nk_ooj_id
            from sif.acc_kontni_okvir_klase nk
            where id = kp.kontna_klasa_id;

            if l_nk_ooj_id is null and length(l_nk_code) <= 3 then
                l_nad_konto := kp.kontna_klasa_id;   -- roditelj je dijeljeni/defoultni konto - ne duplira se
            else
                select kk.id
                into l_nad_konto
                from sif.acc_kontni_okvir_klase kk
                where kk.code = l_nk_code
                  and kk.ooj_id = ooj.ooj_id;
            end if;

            sif.acc_pkg.insert_kontni_okvir_klasa(kp.entitet_id ,
                                                  l_nad_konto ,
                                                  ooj.ooj_id          ,
                                                  kp.code            ,
                                                  kp.naziv           ,
                                                  kp.os            ,
                                                  kp.klijent         ,
                                                  kp.oj              ,
                                                  kp.radnik          ,
                                                  kp.pdv_indikator   ,
                                                  kp.pdv_indikator_sifra,
                                                  kp.otvorene_stavke );


        end loop;


       ----za migraciju ako je korisnik dodavao svoja konta, potrebno mapirati novi nadređeni konto----

       for k in (select * from sif.acc_kontni_okvir_klase kk
                 where kk.ooj_id=ooj.ooj_id
                 and trunc(kk.created)<trunc(sysdate)-1)
       loop


            select nk.code, nk.ooj_id
            into l_nk_code, l_nk_ooj_id
            from sif.acc_kontni_okvir_klase nk
            where id = k.kontna_klasa_id;

            if l_nk_ooj_id is null and length(l_nk_code) <= 3 then
                l_nad_konto := k.kontna_klasa_id;   -- roditelj je dijeljeni/defoultni konto - ne duplira se
            else
                select kk.id
                into l_nad_konto
                from sif.acc_kontni_okvir_klase kk
                where kk.code = l_nk_code
                and kk.ooj_id = ooj.ooj_id;
            end if;



             sif.acc_pkg.update_kontni_okvir_klasa(k.id,
                                                   k.entitet_id,
                                                   l_nad_konto,
                                                   ooj.ooj_id,
                                                   k.code,
                                                   k.naziv,
                                                   k.os,
                                                   k.klijent,
                                                   k.oj,
                                                   k.radnik,
                                                   k.pdv_indikator,
                                                   k.pdv_indikator_sifra,
                                                   k.valid,
                                                   k.otvorene_stavke);

       end loop;

       ---------updejt id-eva konta u vezanim tabelama--------
       ---blagajne tipovi promjena
       for bt in (select btp.*, ak.id as konto_id, ak.code
                  from accounting.BLAGAJNA_TIPOVI_PROMJENA btp
                  join sif.acc_kontni_okvir_klase ak on ak.id=btp.kontna_klasa_id
                  where btp.ooj_id=ooj.ooj_id)
       loop

           if length(bt.code)<=3 then
             null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = bt.code
             and kk.ooj_id = ooj.ooj_id;


             accounting.blagajna_pkg.update_blagajna_tip_promjene(bt.id,
                                                                  bt.ooj_id,
                                                                  l_konto_id,
                                                                  bt.naziv,
                                                                  bt.radnik,
                                                                  bt.klijent,
                                                                  bt.oj,
                                                                  bt.valid);
           end if;

       end loop;

       -----
       --blagajne
       for b in (select bl.*, ak.id as konto_id, ak.code
                  from accounting.blagajne bl
                  join sif.acc_kontni_okvir_klase ak on ak.id=bl.kontna_klasa_id
                  where bl.ooj_id=ooj.ooj_id)
       loop

           if length(b.code)<=3 then
             null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = b.code
             and kk.ooj_id = ooj.ooj_id;


             accounting.blagajna_pkg.update_blagajna( b.id,
                                                      b.ooj_id,
                                                      l_konto_id,
                                                      b.valuta_id,
                                                      b.tip,
                                                      b.naziv,
                                                      b.valid);
           end if;

       end loop;
       --
       --glavana knjiga stavke--
       for st in (select gks.*, ak.id as konto_id, ak.code
                  from accounting.glavna_knjiga_stavke gks
                  join accounting.glavna_knjiga gk on gk.id=gks.glavna_knjiga_id
                  join sif.acc_kontni_okvir_klase ak on ak.id=gks.kontna_klasa_id
                  where gk.ooj_id=ooj.ooj_id
                  )

       loop

           if length(st.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = st.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.glavna_knjiga_stavke gks
             set gks.kontna_klasa_id=l_konto_id
             where gks.id=st.id;


           end if;


       end loop;
       ---

       --izvodi stavke
       for i in (select ist.id,  ak.id as konto_id, ak.code
                  from accounting.izvod_stavke ist
                  join accounting.izvodi i on i.id=ist.izvod_id
                  join sif.acc_kontni_okvir_klase ak on ak.id=ist.konto_id
                  where i.ooj_id=ooj.ooj_id
                  )
       loop

           if length(i.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = i.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.izvod_stavke ist
             set ist.konto_id=l_konto_id
             where ist.id=i.id;


           end if;


       end loop;

       --
       ---sabloni knjiženja---
       for s in (select sk.id,  ak.id as konto_id, ak.code
                 from accounting.sabloni s
                 join accounting.sabloni_konta sk on s.id=sk.sablon_id
                 join sif.acc_kontni_okvir_klase ak on ak.id=sk.kontna_klasa_id
                 where s.ooj_id=ooj.ooj_id)
       loop

           if length(s.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = s.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.sabloni_konta sk
             set sk.kontna_klasa_id=l_konto_id
             where sk.id=s.id;


             end if;

        end loop;
         --
       ---sec klijenti---
       for skk in (select sk.*, ak.id as konto_id, ak.code
                   from accounting.sec_klijenti sk
                   join sif.acc_kontni_okvir_klase ak on ak.id=sk.kontna_klasa_id
                   where sk.ooj_id=ooj.ooj_id)

       loop


           if length(skk.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = skk.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.sec_klijenti sk
             set sk.kontna_klasa_id=l_konto_id
             where sk.id=skk.id;


             end if;



       end loop;
       --
       ---sec klijenti konta---
       for k2 in (select k1.*, ak.id as konto_id, ak.code
                   from accounting.sec_klijent_konta k1
                   join accounting.sec_klijenti sk1 on sk1.id=k1.sec_klijent_id
                   join sif.acc_kontni_okvir_klase ak on ak.id=k1.kontna_klasa_id
                   where sk1.ooj_id=ooj.ooj_id)

       loop


           if length(k2.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = k2.code
             and kk.ooj_id = ooj.ooj_id;

             update accounting.sec_klijent_konta sk
             set sk.kontna_klasa_id=l_konto_id
             where sk.id=k2.id;


             end if;



       end loop;
       ----
       --core ooj_banke--
       for b1 in (select b.*, ak.id as konto_id, ak.code
                  from core.ooj_banke b
                  join sif.acc_kontni_okvir_klase ak on ak.id=b.kontna_klasa_id
                  where b.ooj_id=ooj.ooj_id)

       loop


           if length(b1.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = b1.code
             and kk.ooj_id = ooj.ooj_id;

             update core.ooj_banke bb
             set bb.kontna_klasa_id=l_konto_id
             where bb.id=b1.id;



             end if;




       end loop;
       ----
       for zr1 in (select zr.*, ak.id as konto_id, ak.code
                  from sif.sif_ziro_racuni zr
                  join sif.acc_kontni_okvir_klase ak on ak.id=zr.kontna_klasa_id
                  where zr.ooj_id=ooj.ooj_id)

       loop


           if length(zr1.code)<=3 then
              null;
           else

             select kk.id
             into l_konto_id
             from sif.acc_kontni_okvir_klase kk
             where kk.code = zr1.code
             and kk.ooj_id = ooj.ooj_id;


             update sif.sif_ziro_racuni szr
             set szr.kontna_klasa_id=l_konto_id
             where szr.id=zr1.id;

          end if;



       end loop;

       -------------------------------------------------------


  end loop;

  end migracija_kontnog_plana;

 procedure migracija_mjesta_troska is
  v_nad_mt_id number;
  v_mt_id number;
  v_rbr number;
 begin

        for o in (select distinct ooj_id from core.oj oo where oo.ooj_id=219)
        loop
            v_rbr:=1;
            ---migrracija OJ u MJESTA TROSKA RADI POSTOJEĆIH PROKNJIŽENIH DOKUMENATA---
            /*for i in (SELECT *
                      FROM core.oj
                      where ooj_id=o.ooj_id
                      START WITH parent_id IS NULL
                      CONNECT BY PRIOR id = parent_id
                      ORDER SIBLINGS BY parent_id
                      )
            loop



                  if i.parent_id is null then
                    v_nad_mt_id:=null;
                  else
                    select mp.mjesto_troska_id
                    into v_nad_mt_id
                    from  accounting.migracija_oj_mjesta_troska_map  mp
                    where mp.oj_id=i.parent_id;
                  end if;


                  sif.acc_pkg.insert_acc_mjesta_troska(
                      p_ooj_id    => o.ooj_id,
                      p_sifra     => '00'||v_rbr,
                      p_naziv     => i.naziv,
                      p_nad_id    => v_nad_mt_id,
                      p_oj_id     => i.id,
                      p_valid     => i.valid,
                      p_radnik_id => null,
                      p_id        => v_mt_id
                  );

                    insert into accounting.migracija_oj_mjesta_troska_map (ooj_id, oj_id, mjesto_troska_id)
                    values (o.ooj_id, i.id, v_mt_id);
                    v_rbr:=v_rbr+1;

            end loop;*/

            ------
            for st in ( select gks.*
                        from accounting.glavna_knjiga_stavke gks
                        join accounting.glavna_knjiga gk on gk.id=gks.glavna_knjiga_id
                        where gk.ooj_id=o.ooj_id
                        and gks.oj_id is not null
                      )

             loop

                   select mp.mjesto_troska_id
                   into v_mt_id
                   from  accounting.migracija_oj_mjesta_troska_map  mp
                   where mp.oj_id=st.oj_id;

                   update accounting.glavna_knjiga_stavke gks
                   set gks.mjesto_troska_id=v_mt_id
                   where gks.id=st.id;

             end loop;

        end loop;



 end migracija_mjesta_troska;



  procedure migracija_acc_radnici is
      v_acc_rad_id number;
      v_rbr number;
   begin

          for o in (select distinct ooj_id from hrm.hr_radnici hr where hr.ooj_id=219)
          loop
              v_rbr:=1;
              --migracija hr_radnik u acc_radnik RADI POSTOJEĆIH PROKNJIŽENIH DOKUMENATA---

              for i in (SELECT h.*
                        FROM hrm.hr_radnici h
                        where h.ooj_id=o.ooj_id
                        order by h.id
                        )
              loop




                     sif.acc_pkg.insert_acc_radnici (
                        p_ooj_id       => o.ooj_id,
                        p_interni_broj => null,
                        p_ime          => initcap(i.ime),
                        p_prezime      => initcap(i.prezime),
                        p_email        => initcap(i.email),
                        p_oj_id        => i.oj_id,
                        p_valid        => 'Y',
                        p_id           => v_acc_rad_id
                    );

                      insert into accounting.migracija_hr_to_acc_radnik_map  (ooj_id, hr_radnik_id, acc_radnik_id)
                      values (o.ooj_id, i.id, v_acc_rad_id);

              end loop;

              ------
              for st in ( select gks.*
                          from accounting.glavna_knjiga_stavke gks
                          join accounting.glavna_knjiga gk on gk.id=gks.glavna_knjiga_id
                          where gk.ooj_id=o.ooj_id
                          and gks.radnik_id is not null
                        )

               loop

                     select mp1.acc_radnik_id
                     into v_acc_rad_id
                     from  accounting.migracija_hr_to_acc_radnik_map  mp1
                     where mp1.hr_radnik_id=st.radnik_id;

                     update accounting.glavna_knjiga_stavke gks
                     set gks.acc_radnik_id=v_acc_rad_id
                     where gks.id=st.id;

               end loop;

          end loop;



   end migracija_acc_radnici;

end MIGRACIJA_PKG;
/

prompt
prompt Creating package body OS_PKG
prompt ============================
prompt
create or replace package body accounting.os_pkg as
    
    --------------------------------------------------------------
    -- procedures for table SEC_OSNOVNA_SREDSTVA
    --------------------------------------------------------------

    procedure get_inventurni_broj (
        p_ooj_id           in number,
        p_klasa_id         in number,
        p_inventurni_broj  out number,
        p_inventurni_naziv out varchar2
    ) is
        l_konto_nabavka_id   number;
        l_konto_nabavka_code varchar2(64);
        l_sifra              varchar2(64);
    begin
        select
            sifra
        into l_sifra
        from
            sif.acc_klase_os
        where
            id = p_klasa_id;

        l_konto_nabavka_id := sif.acc_pkg.get_klasa_os_kontna_klasa_id(
            p_klasa_id => p_klasa_id,
            p_sifra    => 'nabavke'
        );

        l_konto_nabavka_code := sif.acc_pkg.get_kontni_okvir_klasa(p_id => l_konto_nabavka_id);
        for c1 in (
            select
                nvl(
                    max(inventurni_broj),
                    0
                ) as output
            from
                sec_osnovna_sredstva
            where
                    ooj_id = p_ooj_id
                and substr(
                    sif.acc_pkg.get_kontni_okvir_klasa(sif.acc_pkg.get_klasa_os_kontna_klasa_id(
                        p_klasa_id => klasa_id,
                        p_sifra    => 'nabavke'
                    )),
                    2,
                    2
                ) = substr(l_konto_nabavka_code, 2, 2)
        ) loop
            p_inventurni_naziv := substr(l_konto_nabavka_code, 2, 2)
                                  || '-'
                                  || lpad(c1.output + 1, 5, 0);

            p_inventurni_broj := c1.output + 1;
        end loop;

    end get_inventurni_broj;

    procedure get_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    ) as
    begin
        if p_os.id is null then
            raise_application_error(-20002, 'Primary key required for get');
        end if;
        for c1 in (
            select
                *
            from
                sec_osnovna_sredstva
            where
                id = p_os.id
        ) loop
            p_os.id := c1.id;
            p_os.ooj_id := c1.ooj_id;
            p_os.jm_id := c1.jm_id;
            p_os.oj_id := c1.oj_id;
            p_os.lokacija_id := c1.lokacija_id;
            p_os.prostorija_id := c1.prostorija_id;
            p_os.grad_id := c1.grad_id;
            p_os.radnik_id := c1.radnik_id;
            p_os.klijent_id := c1.klijent_id;
            p_os.inventurni_broj := c1.inventurni_broj;
            p_os.inventurni_naziv := c1.inventurni_naziv;
            p_os.stari_inventurni_broj := c1.stari_inventurni_broj;
            p_os.naziv := c1.naziv;
            p_os.kolicina := c1.kolicina;
            p_os.datum := c1.datum;
            p_os.klasa_id := c1.klasa_id;
            p_os.vijek_trajanja := c1.vijek_trajanja;
            p_os.amortizaciona_stopa := c1.amortizaciona_stopa;
            p_os.procijenjeni_vijek_trajanja := c1.procijenjeni_vijek_trajanja;
            p_os.poreska_amortizaciona_stopa := c1.poreska_amortizaciona_stopa;
            p_os.donacija := c1.donacija;
            p_os.reg_oznaka := c1.reg_oznaka;
            p_os.dokument := c1.dokument;
            p_os.dokument_filename := c1.dokument_filename;
            p_os.dokument_mimetype := c1.dokument_mimetype;
            p_os.dokument_charset := c1.dokument_charset;
            p_os.dokument_lastupd := c1.dokument_lastupd;
            p_os.dokument_broj := c1.dokument_broj;
            p_os.dokument_datum := c1.dokument_datum;
            p_os.vrijednost_donacija := c1.vrijednost_donacija;
            p_os.odlozeni_porezi := c1.odlozeni_porezi;
            p_os.rezidualna_vrijednost := c1.rezidualna_vrijednost;
            p_os.priprema := c1.priprema;
            p_os.priprema_id := c1.priprema_id;
            p_os.aktivirano := c1.aktivirano;
            p_os.history_id := c1.history_id;
            p_os.history_komentar := c1.history_komentar;
            p_os.status_id := c1.status_id;
            p_os.automatska_amortizacija := c1.automatska_amortizacija;
            p_os.indikator_id := c1.indikator_id;
            p_os.valid := c1.valid;
            p_os.row_version := c1.row_version;
            p_os.created := c1.created;
            p_os.created_by := c1.created_by;
            p_os.updated := c1.updated;
            p_os.updated_by := c1.updated_by;
        end loop;

    end get_osnovno_sredstvo;

    procedure insert_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    ) as
        l_table table_sec_osnovna_sredstva;
    begin
        l_table := table_sec_osnovna_sredstva(p_os);
        insert into sec_osnovna_sredstva
            select
                *
            from
                table ( l_table );

    end insert_osnovno_sredstvo;

    procedure update_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    ) as
        l_os_old t_sec_osnovna_sredstva;
    begin
        if p_os.id is not null then
            -- Uzimamo sve stare podatke, povezujemo sa OS i ubacujemo u istoriju
            l_os_old := t_sec_osnovna_sredstva(p_os.id);
            l_os_old.id := null;
            l_os_old.history_id := p_os.id;
            l_os_old.history_date := current_date;
            l_os_old.history_komentar := p_os.history_komentar;
            insert_osnovno_sredstvo(p_os => l_os_old);

            -- Azuriramo nove
            update sec_osnovna_sredstva
            set
                ooj_id = p_os.ooj_id,
                jm_id = p_os.jm_id,
                oj_id = p_os.oj_id,
                lokacija_id = p_os.lokacija_id,
                prostorija_id = p_os.prostorija_id,
                grad_id = p_os.grad_id,
                radnik_id = p_os.radnik_id,
                klijent_id = p_os.klijent_id,
                inventurni_broj = p_os.inventurni_broj,
                inventurni_naziv = p_os.inventurni_naziv,
                stari_inventurni_broj = p_os.stari_inventurni_broj,
                naziv = p_os.naziv,
                kolicina = p_os.kolicina,
                datum = p_os.datum,
                klasa_id = p_os.klasa_id,
                vijek_trajanja = p_os.vijek_trajanja,
                amortizaciona_stopa = p_os.amortizaciona_stopa,
                procijenjeni_vijek_trajanja = p_os.procijenjeni_vijek_trajanja,
                poreska_amortizaciona_stopa = p_os.poreska_amortizaciona_stopa,
                donacija = p_os.donacija,
                reg_oznaka = p_os.reg_oznaka,
                dokument = p_os.dokument,
                dokument_filename = p_os.dokument_filename,
                dokument_mimetype = p_os.dokument_mimetype,
                dokument_charset = p_os.dokument_charset,
                dokument_lastupd = p_os.dokument_lastupd,
                dokument_broj = p_os.dokument_broj,
                dokument_datum = p_os.dokument_datum,
                vrijednost_donacija = p_os.vrijednost_donacija,
                odlozeni_porezi = p_os.odlozeni_porezi,
                rezidualna_vrijednost = p_os.rezidualna_vrijednost,
                priprema = p_os.priprema,
                priprema_id = p_os.priprema_id,
                aktivirano = p_os.aktivirano,
                history_id = p_os.history_id,
                history_komentar = null,
                status_id = p_os.status_id,
                automatska_amortizacija = p_os.automatska_amortizacija,
                indikator_id = p_os.indikator_id,
                valid = p_os.valid,
                row_version = p_os.row_version,
                created = p_os.created,
                created_by = p_os.created_by,
                updated = p_os.updated,
                updated_by = p_os.updated_by
            where
                id = p_os.id;

            if sql%rowcount = 0 then
                raise_application_error(-20001, 'Record not found');
            end if;
        else
            raise_application_error(-20002, 'Primary key required for update');
        end if;
    end update_osnovno_sredstvo;

    procedure delete_osnovno_sredstvo (
        p_os in out t_sec_osnovna_sredstva
    ) as
    begin
        if p_os.id is not null then
            delete from sec_osnovna_sredstva
            where
                id = p_os.id;

            if sql%rowcount = 0 then
                raise_application_error(-20003, 'Record not found');
            end if;
        else
            raise_application_error(-20004, 'Primary key required for delete');
        end if;
    end delete_osnovno_sredstvo;
    
    --------------------------------------------------------------
    -- procedures for table SEC_OSNOVNO_SREDSTVO_ODRZAVANJE
    --------------------------------------------------------------

    procedure get_osnovno_sredstvo_odrzavanje (
        p_os_odrzavanje in out t_sec_osnovno_sredstvo_odrzavanje
    ) as
    begin
        for c1 in (
            select
                *
            from
                sec_osnovno_sredstvo_odrzavanje
            where
                id = p_os_odrzavanje.id
        ) loop
            p_os_odrzavanje.id := c1.id;
            p_os_odrzavanje.osnovno_sredstvo_id := c1.osnovno_sredstvo_id;
            p_os_odrzavanje.naziv := c1.naziv;
            p_os_odrzavanje.opis := c1.opis;
            p_os_odrzavanje.datum := c1.datum;
            p_os_odrzavanje.cijena := c1.cijena;
            p_os_odrzavanje.sledeci_servis := c1.sledeci_servis;
            p_os_odrzavanje.valid := c1.valid;
            p_os_odrzavanje.row_version := c1.row_version;
            p_os_odrzavanje.created := c1.created;
            p_os_odrzavanje.created_by := c1.created_by;
            p_os_odrzavanje.updated := c1.updated;
            p_os_odrzavanje.updated_by := c1.updated_by;
        end loop;
    end get_osnovno_sredstvo_odrzavanje;

    procedure insert_osnovno_sredstvo_odrzavanje (
        p_os_odrzavanje in out t_sec_osnovno_sredstvo_odrzavanje
    ) as
        l_table table_sec_osnovno_sredstvo_odrzavanje;
    begin
        l_table := table_sec_osnovno_sredstvo_odrzavanje(p_os_odrzavanje);
        insert into sec_osnovno_sredstvo_odrzavanje
            select
                *
            from
                table ( l_table );

    end insert_osnovno_sredstvo_odrzavanje;

    procedure delete_osnovno_sredstvo_odrzavanje (
        p_os_odrzavanje in out t_sec_osnovno_sredstvo_odrzavanje
    ) as
    begin
        if p_os_odrzavanje.id is not null then
            delete from sec_osnovno_sredstvo_odrzavanje
            where
                id = p_os_odrzavanje.id;

            if sql%rowcount = 0 then
                raise_application_error(-20003, 'Record not found');
            end if;
        else
            raise_application_error(-20004, 'Primary key required for delete');
        end if;
    end delete_osnovno_sredstvo_odrzavanje;

    --------------------------------------------------------------
    -- procedures for table OS_INDIKATORI
    --------------------------------------------------------------

    procedure get_os_indikator (
        p_id     in number,
        p_ooj_id out number,
        p_sifra  out varchar2,
        p_naziv  out varchar2,
        p_opis   out varchar2,
        p_valid  out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_os_indikatori
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_sifra := c1.sifra;
            p_naziv := c1.naziv;
            p_opis := c1.opis;
            p_valid := c1.valid;
        end loop;
    end get_os_indikator;

    procedure insert_os_indikator (
        p_ooj_id in number,
        p_sifra  in varchar2,
        p_naziv  in varchar2,
        p_opis   in varchar2
    ) is
    begin
        insert into sec_os_indikatori (
            ooj_id,
            sifra,
            naziv,
            opis
        ) values (
            p_ooj_id,
            p_sifra,
            p_naziv,
            p_opis
        );

    end insert_os_indikator;

    procedure update_os_indikator (
        p_id     in number,
        p_ooj_id in number,
        p_sifra  in varchar2,
        p_naziv  in varchar2,
        p_opis   in varchar2,
        p_valid  in varchar2
    ) is
    begin
        update sec_os_indikatori
        set
            ooj_id = p_ooj_id,
            sifra = p_sifra,
            naziv = p_naziv,
            opis = p_opis,
            valid = p_valid
        where
            id = p_id;

    end update_os_indikator;

    procedure delete_os_indikator (
        p_id in number
    ) is
    begin
        delete from sec_os_indikatori
        where
            id = p_id;

    end delete_os_indikator;

    --------------------------------------------------------------
    -- procedures for table SEC_OSNOVNO_SREDSTVO_AKTIVIRANJA
    --------------------------------------------------------------
    
    procedure insert_os_aktiviranje (
        p_osnovno_sredstvo_id in number,
        p_glavna_knjiga_id    in number,
        p_priprema_id         in number,
        p_datum               in date,
        p_iznos               in number
    ) is
    begin
        insert into sec_osnovno_sredstvo_aktiviranja (
            osnovno_sredstvo_id,
            glavna_knjiga_id,
            priprema_id,
            datum,
            iznos
        ) values (
            p_osnovno_sredstvo_id,
            p_glavna_knjiga_id,
            p_priprema_id,
            p_datum,
            p_iznos 
        );

    end insert_os_aktiviranje;
    
    --------------------------------------------------------------
    -- other procedures
    --------------------------------------------------------------
    
    -- Stvarno ne znam kako da nazovem proceduru....
    procedure insert_os_priprema_klase (
        p_ooj_id in number
    ) is
    begin
        for c1 in (
            select
                id
            from
                sif.acc_klase_os k
            where
                ooj_id = p_ooj_id
                and not exists (
                    select
                        1
                    from
                        sec_osnovna_sredstva os
                    where
                        os.ooj_id = p_ooj_id
                        and os.klasa_id = k.id
                        and priprema = 'Y'
                )
        ) loop
            insert_os_priprema (
                p_ooj_id   => p_ooj_id,
                p_klasa_id => c1.id
            );
        end loop;
    end insert_os_priprema_klase;
    
    procedure insert_os_priprema (
        p_ooj_id   in number,
        p_klasa_id in number
    ) is
        l_os t_sec_osnovna_sredstva;
        l_sifra varchar2(64);
    begin
        l_os := t_sec_osnovna_sredstva();
        
        l_os.ooj_id := p_ooj_id;
        l_os.klasa_id := p_klasa_id;
        
        get_inventurni_broj (
            p_ooj_id           => p_ooj_id,
            p_klasa_id         => p_klasa_id,
            p_inventurni_broj  => l_os.inventurni_broj,
            p_inventurni_naziv => l_os.inventurni_naziv
        );
        
        sif.acc_pkg.get_klasa_os (
            p_id             => p_klasa_id,
            p_sifra          => l_sifra,
            p_naziv          => l_os.naziv,
            p_procenat       => l_os.amortizaciona_stopa,
            p_vijek_trajanja => l_os.vijek_trajanja
        );
        
        l_os.procijenjeni_vijek_trajanja := l_os.vijek_trajanja;
        l_os.poreska_amortizaciona_stopa := l_os.amortizaciona_stopa;
        
        l_os.aktivirano := 'N';
        l_os.priprema := 'Y';
        l_os.priprema_id := null;
        l_os.status_id := 21;
        l_os.valid := 'Y';
        
        insert_osnovno_sredstvo (l_os);
    
    end insert_os_priprema;

    function is_osnovno_sredstvo_editable (
        p_id in number
    ) return boolean is
        l_os          t_sec_osnovna_sredstva;
    begin
        if p_id is null then
            return false;
        end if;
        
        l_os := t_sec_osnovna_sredstva();
        l_os.id := p_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os);
        
        -- Ako je aktivirano ne moze
        if l_os.aktivirano = 'Y' then
            return false;
        end if;
        
        return true;
    
    end is_osnovno_sredstvo_editable;

    procedure insert_group_os (
        p_os       in t_sec_osnovna_sredstva,
        p_kolicina in number
    ) is
        l_os t_sec_osnovna_sredstva;
    begin
        for x in 1..p_kolicina loop
            l_os := t_sec_osnovna_sredstva();
            l_os := p_os;
            os_pkg.get_inventurni_broj(
                p_ooj_id           => l_os.ooj_id,
                p_klasa_id         => l_os.klasa_id,
                p_inventurni_broj  => l_os.inventurni_broj,
                p_inventurni_naziv => l_os.inventurni_naziv
            );

            insert_osnovno_sredstvo(p_os => l_os);
        end loop;
    end insert_group_os;
    
    function get_vrijednost_priprema (
        p_id    in number,
        p_datum in date
    ) return number is
        l_iznos number;
    begin
        select
            sum(iznos)
        into
            l_iznos
        from
            vw_glavna_knjiga_stavke
        where
            osnovno_sredstvo_id = p_id
            and transakcija_sifra in ('priprema')
            and os_datum <= p_datum
            and proknjizeno = 'Y';
            
        return l_iznos;
        
    end get_vrijednost_priprema;
    
    function get_vrijednost_nabavka (
        p_id    in number,
        p_datum in date
    ) return number is
        l_iznos number;
    begin
        select
            sum(iznos)
        into
            l_iznos
        from
            vw_glavna_knjiga_stavke
        where
            osnovno_sredstvo_id = p_id
            and transakcija_sifra in ('nabavke', 'ps_nv')
            and os_datum <= p_datum
            and proknjizeno = 'Y';
            
        return l_iznos;
        
    end get_vrijednost_nabavka;

    function get_amortizacija_do_datuma (
        p_id    in number,
        p_datum in date
    ) return number is
        l_iznos number;
    begin
        select
            sum(abs(iznos))
        into l_iznos
        from
            vw_glavna_knjiga_stavke
        where
                osnovno_sredstvo_id = p_id
            and trunc(os_datum) <= trunc(p_datum)
            and transakcija_sifra in ('am_p', 'ps_iv')
            and proknjizeno = 'Y';

        return l_iznos;
    end get_amortizacija_do_datuma;

    function get_amortizacija_za_godinu (
        p_id     in number,
        p_godina in number
    ) return number is
        l_iznos number;
    begin
        select
            sum(abs(iznos))
        into l_iznos
        from
            vw_glavna_knjiga_stavke
        where
                osnovno_sredstvo_id = p_id
            and extract(year from os_datum) <= p_godina
            and transakcija_sifra in ('am_p', 'ps_iv')
            and proknjizeno = 'Y';

        return l_iznos;
    end get_amortizacija_za_godinu;
    
    function get_knjigovodstvena_vrijednost (
        p_id in number
    ) return number is
        l_vrijednost number;
    begin
        select (
            SUM(CASE WHEN transakcija_sifra in ('nabavke', 'ps_nv') THEN iznos ELSE 0 END)
                -
            SUM(CASE WHEN transakcija_sifra in ('am_p', 'ps_iv') THEN iznos ELSE 0 END)
            )
        into
            l_vrijednost
        from
            vw_glavna_knjiga_stavke
        where
            osnovno_sredstvo_id = p_id
            and proknjizeno = 'Y';
            
        return l_vrijednost;

    end get_knjigovodstvena_vrijednost;
    
    function get_otpis_vrijednost (
        p_id in number
    ) return number is
        l_vrijednost number;
    begin
        select
            SUM(CASE WHEN transakcija_sifra = 'otpis' THEN iznos ELSE 0 END)
        into
            l_vrijednost
        from
            vw_glavna_knjiga_stavke
        where
            osnovno_sredstvo_id = p_id
            and proknjizeno = 'Y';
            
        return l_vrijednost;
    
    end get_otpis_vrijednost;
    
    function get_prodaja_vrijednost (
        p_id in number
    ) return number is
        l_vrijednost number;
    begin
        select
            SUM(CASE WHEN transakcija_sifra IN ('pr_g', 'pr_d') THEN iznos ELSE 0 END)
        into
            l_vrijednost
        from
            vw_glavna_knjiga_stavke
        where
            osnovno_sredstvo_id = p_id
            and proknjizeno = 'Y';
            
        return l_vrijednost;
    
    end get_prodaja_vrijednost;
    
    function get_manjak_vrijednost (
        p_id in number
    ) return number is
        l_vrijednost number;
    begin
        select
            SUM(CASE WHEN transakcija_sifra = 'manjak' THEN iznos ELSE 0 END)
        into
            l_vrijednost
        from
            vw_glavna_knjiga_stavke
        where
            osnovno_sredstvo_id = p_id
            and proknjizeno = 'Y';
            
        return l_vrijednost;
    
    end get_manjak_vrijednost;
    
    function get_stepen_amortizovanosti (
        p_id in number
    ) return number is
        l_nabavna        NUMBER := 0;
        l_amortizacija   NUMBER := 0;
        l_rezidualna     NUMBER := 0;
        l_stepen         NUMBER := 0;
    begin
        -- nabavna vrijednost i amortizacija
        SELECT
            SUM(CASE WHEN g.transakcija_sifra in ('nabavke', 'ps_nv') THEN g.iznos ELSE 0 END),
            SUM(CASE WHEN g.transakcija_sifra in ('am_p', 'ps_iv') THEN g.iznos * -1 ELSE 0 END)
        INTO
            l_nabavna,
            l_amortizacija
        FROM
            vw_glavna_knjiga_stavke g
        WHERE
            g.osnovno_sredstvo_id = p_id
            and proknjizeno = 'Y';
    
        -- rezidualna vrijednost
        SELECT
            NVL(os.rezidualna_vrijednost, 0)
        INTO
            l_rezidualna
        FROM
            sec_osnovna_sredstva os
        WHERE
            os.id = p_id;
    
        -- izbjegavanje dijeljenja sa 0
        IF (l_nabavna - l_rezidualna) <= 0 THEN
            RETURN 0;
        END IF;
    
        -- izračun stepena
        l_stepen :=
            (l_amortizacija / (l_nabavna - l_rezidualna)) * 100;
    
        -- max 100%
        RETURN LEAST(ROUND(l_stepen, 2), 100);
    
    end get_stepen_amortizovanosti;

    function aktiviraj_osnovno_sredstvo (
        p_id               in number,
        p_vrijednost       in number,
        p_godina           in number,
        p_datum            in date,
        p_glavna_knjiga_id in number
    ) return number is
        l_nalog_id    number;
        l_os          t_sec_osnovna_sredstva;
        l_os_priprema t_sec_osnovna_sredstva;
    begin
        -- Azuriranje aktiviramo
        l_os := t_sec_osnovna_sredstva();
        l_os.id := p_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os);
        l_os.aktivirano := 'Y';
        os_pkg.update_osnovno_sredstvo(p_os => l_os);
        
        -- Knjizenje
        l_nalog_id := glavna_knjiga_pkg.knjizi_os_aktiviranje (
            p_godina              => p_godina,
            p_osnovno_sredstvo_id => l_os.id,
            p_priprema_id         => l_os.priprema_id,
            p_vrijednost          => p_vrijednost,
            p_datum               => p_datum
        );
        
        -- Dodavanje u listu aktivacija
        insert_os_aktiviranje (
            p_osnovno_sredstvo_id => p_id,
            p_glavna_knjiga_id    => p_glavna_knjiga_id,
            p_priprema_id         => l_os.priprema_id,
            p_datum               => p_datum,
            p_iznos               => p_vrijednost
        );

        return l_nalog_id;
    end aktiviraj_osnovno_sredstvo;

    function otpis_osnovno_sredstvo (
        p_id                    in number,
        p_godina                in number,
        p_proknjizeno           in varchar2,
        p_otpis_razlog          in varchar2,
        p_otpis_datum           in date,
        p_otpis_odgovorna_osoba in varchar2,
        p_kolicina              in number
    ) return number is
        l_os       t_sec_osnovna_sredstva;
        l_nalog_id number;
    begin
        l_os := t_sec_osnovna_sredstva();
        l_os.id := p_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os);
        l_os.otpis_razlog := p_otpis_razlog;
        l_os.otpis_datum := p_otpis_datum;
        l_os.otpis_odgovorna_osoba := p_otpis_odgovorna_osoba;
        l_nalog_id := glavna_knjiga_pkg.knjizi_os_otpis(
            p_os          => l_os,
            p_godina      => p_godina,
            p_kolicina    => p_kolicina,
            p_proknjizeno => p_proknjizeno
        );

        l_os.kolicina := p_kolicina;
        l_os.history_komentar := 'Otpis osnovnog sredstva - ' || p_otpis_razlog;
        if p_kolicina = 0 then
            l_os.valid := 'N';
        end if;
        os_pkg.update_osnovno_sredstvo(p_os => l_os);
        return l_nalog_id;
    end otpis_osnovno_sredstvo;
    
    function prodaja_osnovno_sredstvo (
        p_id                  in number,
        p_godina              in number,
        p_proknjizeno         in varchar2,
        p_prodajna_vrijednost in number,
        p_kolicina            in number,
        p_datum               in date
    ) return number is
        l_os       t_sec_osnovna_sredstva;
        l_nalog_id number;
    begin
        l_os := t_sec_osnovna_sredstva();
        l_os.id := p_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os);
        l_nalog_id := glavna_knjiga_pkg.knjizi_os_prodaja(
            p_os                  => l_os,
            p_godina              => p_godina,
            p_kolicina            => p_kolicina,
            p_proknjizeno         => p_proknjizeno,
            p_prodajna_vrijednost => p_prodajna_vrijednost,
            p_datum               => p_datum
        );

        l_os.kolicina := p_kolicina;
        l_os.history_komentar := 'Prodaja osnovnog sredstva - '
                                 || to_char(p_prodajna_vrijednost, '999G999G999G999G990D00')
                                 || 'KM';
        if p_kolicina = 0 then
            l_os.valid := 'N';
        end if;
        os_pkg.update_osnovno_sredstvo(p_os => l_os);
        return l_nalog_id;
    end prodaja_osnovno_sredstvo;
    
    function popis_osnovno_sredstvo (
        p_id             in number,
        p_godina         in number,
        p_kolicina       in number,
        p_stara_kolicina in number,
        p_proknjizeno    in varchar2,
        p_datum          in date
    ) return number is
        l_razlika  number := p_kolicina - p_stara_kolicina;
        l_nalog_id number;
        l_os       t_sec_osnovna_sredstva;
    begin
        l_os := t_sec_osnovna_sredstva();
        l_os.id := p_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os);
        if l_razlika < 0 then
            l_nalog_id := glavna_knjiga_pkg.knjizi_os_popis_manjak(
                p_os          => l_os,
                p_godina      => p_godina,
                p_kolicina    => p_kolicina,
                p_proknjizeno => p_proknjizeno,
                p_datum       => p_datum
            );

            l_os.kolicina := p_kolicina;
            if p_kolicina = 0 then
                l_os.valid := 'N';
            end if;
            l_os.history_komentar := 'Manjak osnovnog sredstva';
            os_pkg.update_osnovno_sredstvo(p_os => l_os);
        else
            -- Za sada nema automatskog viska
            null;
        end if;

        return l_nalog_id;
    end popis_osnovno_sredstvo;

    function prenos_osnovno_sredstvo (
        p_id          in number,
        p_prenos_id   in number,
        p_godina      in number,
        p_datum       in date,
        p_proknjizeno in varchar2,
        p_kolicina    in number
    ) return number is
        l_os        t_sec_osnovna_sredstva;
        l_os_prenos t_sec_osnovna_sredstva;
        l_nalog_id  number;
    begin
        l_os := t_sec_osnovna_sredstva();
        l_os.id := p_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os);
        l_os_prenos := t_sec_osnovna_sredstva();
        l_os_prenos.id := p_prenos_id;
        os_pkg.get_osnovno_sredstvo(p_os => l_os_prenos);
        l_nalog_id := glavna_knjiga_pkg.knjizi_os_prenos(
            p_os          => l_os,
            p_os_prenos   => l_os_prenos,
            p_datum       => p_datum,
            p_godina      => p_godina,
            p_kolicina    => p_kolicina,
            p_proknjizeno => p_proknjizeno
        );

        -- Staro OS update
        l_os.kolicina := p_kolicina;
        l_os.history_komentar := 'Prenos osnovnog sredstva - '
                                 || l_os.naziv
                                 || ' ( '
                                 || l_os.inventurni_naziv
                                 || ' ) => '
                                 || l_os_prenos.naziv
                                 || ' ( '
                                 || l_os_prenos.inventurni_naziv
                                 || ' )';

        if p_kolicina = 0 then
            l_os.valid := 'N';
        end if;
        os_pkg.update_osnovno_sredstvo(p_os => l_os);

        -- Novo OS update
        l_os_prenos.history_komentar := 'Prenos osnovnog sredstva - '
                                        || l_os.naziv
                                        || ' ( '
                                        || l_os.inventurni_naziv
                                        || ' ) => '
                                        || l_os_prenos.naziv
                                        || ' ( '
                                        || l_os_prenos.inventurni_naziv
                                        || ' )';

        os_pkg.update_osnovno_sredstvo(p_os => l_os_prenos);
        return l_nalog_id;
    end prenos_osnovno_sredstvo;
    
    procedure grupni_transfer (
        p_radnik_id        in number,
        p_os_list          in varchar2,
        p_transfer_id      in number,
        p_oj_id            in number,
        p_history_komentar in varchar2
    ) is

        cursor c_os_list is
        (
            select
                column_value as os_id
            from
                apex_string.split(p_os_list, ':')
        );

        l_os t_sec_osnovna_sredstva;
    begin
        for c1 in c_os_list loop
            l_os := t_sec_osnovna_sredstva();
            l_os.id := c1.os_id;
            os_pkg.get_osnovno_sredstvo(p_os => l_os);
            l_os.radnik_id := p_transfer_id;
            l_os.oj_id := p_oj_id;
            l_os.history_komentar := p_history_komentar;
            os_pkg.update_osnovno_sredstvo(p_os => l_os);
        end loop;
    end grupni_transfer;

end os_pkg;
/

prompt
prompt Creating package body PDV_PKG
prompt =============================
prompt
create or replace package body accounting.pdv_pkg as

    procedure get_pdv_prijava (
        p_id                        in number,
        p_ooj_id                    out number,
        p_poreski_period            out varchar2,
        p_isporuke_p11              out varchar2,
        p_izvoz_p12                 out varchar2,
        p_isporuke_osl_pdv_p13      out varchar2,
        p_nabavke_p21               out varchar2,
        p_uvoz_p22                  out varchar2,
        p_nabavke_poljoprivreda_p23 out varchar2,
        p_pdv_izlaz_p51             out varchar2,
        p_pdv_ulaz_p61              out varchar2,
        p_pdv_reg_obveznici_p41     out varchar2,
        p_pdv_uvoz_p42              out varchar2,
        p_pausal_poljoprivreda_p43  out varchar2,
        p_fbih_p32                  out varchar2,
        p_rs_p33                    out varchar2,
        p_dbr_p34                   out varchar2,
        p_pdv_uplata_povrat_p71     out varchar2,
        p_valid                     out varchar2
    ) as
    begin
        for c1 in (
            select
                *
            from
                pdv_prijave
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_poreski_period := to_char(c1.poreski_period, 'MM.YYYY');
            p_isporuke_p11 := to_char(c1.isporuke_p11, '999G999G999G999G990D00');
            p_izvoz_p12 := to_char(c1.izvoz_p12, '999G999G999G999G990D00');
            p_isporuke_osl_pdv_p13 := to_char(c1.isporuke_osl_pdv_p13, '999G999G999G999G990D00');
            p_nabavke_p21 := to_char(c1.nabavke_p21, '999G999G999G999G990D00');
            p_uvoz_p22 := to_char(c1.uvoz_p22, '999G999G999G999G990D00');
            p_nabavke_poljoprivreda_p23 := to_char(c1.nabavke_poljoprivreda_p23, '999G999G999G999G990D00');
            p_pdv_izlaz_p51 := to_char(c1.pdv_izlaz_p51, '999G999G999G999G990D00');
            p_pdv_ulaz_p61 := to_char(c1.pdv_ulaz_p61, '999G999G999G999G990D00');
            p_pdv_reg_obveznici_p41 := to_char(c1.pdv_reg_obveznici_p41, '999G999G999G999G990D00');
            p_pdv_uvoz_p42 := to_char(c1.pdv_uvoz_p42, '999G999G999G999G990D00');
            p_pausal_poljoprivreda_p43 := to_char(c1.pausal_poljoprivreda_p43, '999G999G999G999G990D00');
            p_fbih_p32 := to_char(c1.fbih_p32, '999G999G999G999G990D00');
            p_rs_p33 := to_char(c1.rs_p33, '999G999G999G999G990D00');
            p_dbr_p34 := to_char(c1.dbr_p34, '999G999G999G999G990D00');
            p_pdv_uplata_povrat_p71 := to_char(c1.pdv_uplata_povrat_p71, '999G999G999G999G990D00');
            p_valid := c1.valid;
        end loop;
    end get_pdv_prijava;

    procedure get_pdv_prijava (
        p_id                    in number,
        p_poreski_period        out date,
        p_pdv_uplata_povrat_p71 out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                pdv_prijave
            where
                id = p_id
        ) loop
            p_poreski_period := c1.poreski_period;
            p_pdv_uplata_povrat_p71 := c1.pdv_uplata_povrat_p71;
        end loop;
    end get_pdv_prijava;

    procedure insert_pdv_prijava (
        p_ooj_id         in number,
        p_poreski_period in date
    ) is

        l_11      number;
        l_12      number;
        l_13      number;
        l_21      number;
        l_22      number;
        l_23      number := 0;
        l_51      number;
        l_51_temp number;
        l_61      number;
        l_41      number;
        l_42      number;
        l_43      number := 0;
        l_32      number;
        l_33      number;
        l_33_temp number;
        l_34      number;
        l_71      number;
    begin
        pdv_pkg.pdv_prijava_kif_polja(
            p_ooj_id         => p_ooj_id,
            p_poreski_period => p_poreski_period,
            l_11             => l_11,
            l_12             => l_12,
            l_13             => l_13,
            l_51             => l_51,
            l_32             => l_32,
            l_33             => l_33,
            l_34             => l_34
        );

        pdv_pkg.pdv_prijava_kuf_polja(
            p_ooj_id         => p_ooj_id,
            p_poreski_period => p_poreski_period,
            l_42             => l_42,
            l_41             => l_41,
            l_33             => l_33_temp,
            l_22             => l_22,
            l_21             => l_21,
            l_51             => l_51_temp
        );

        l_61 := l_41 + l_42;
        l_33 := l_33 + l_33_temp;
        l_51 := l_51 + l_51_temp;
        l_71 := l_51 - l_61;
        insert_pdv_prijava(
            p_ooj_id                    => p_ooj_id,
            p_poreski_period            => p_poreski_period,
            p_isporuke_p11              => l_11,
            p_izvoz_p12                 => l_12,
            p_isporuke_osl_pdv_p13      => l_13,
            p_nabavke_p21               => l_21,
            p_uvoz_p22                  => l_22,
            p_nabavke_poljoprivreda_p23 => l_23,
            p_pdv_izlaz_p51             => l_51,
            p_pdv_ulaz_p61              => l_61,
            p_pdv_reg_obveznici_p41     => l_41,
            p_pdv_uvoz_p42              => l_42,
            p_pausal_poljoprivreda_p43  => l_43,
            p_fbih_p32                  => l_32,
            p_rs_p33                    => l_33,
            p_dbr_p34                   => l_34,
            p_pdv_uplata_povrat_p71     => l_71
        );

    end insert_pdv_prijava;

    procedure insert_pdv_prijava (
        p_ooj_id                    in number,
        p_poreski_period            in date,
        p_isporuke_p11              in number,
        p_izvoz_p12                 in number,
        p_isporuke_osl_pdv_p13      in number,
        p_nabavke_p21               in number,
        p_uvoz_p22                  in number,
        p_nabavke_poljoprivreda_p23 in number,
        p_pdv_izlaz_p51             in number,
        p_pdv_ulaz_p61              in number,
        p_pdv_reg_obveznici_p41     in number,
        p_pdv_uvoz_p42              in number,
        p_pausal_poljoprivreda_p43  in number,
        p_fbih_p32                  in number,
        p_rs_p33                    in number,
        p_dbr_p34                   in number,
        p_pdv_uplata_povrat_p71     in number
    ) as
    begin
        update pdv_prijave
        set
            valid = 'N'
        where
                ooj_id = p_ooj_id
            and poreski_period = p_poreski_period;

        insert into pdv_prijave (
            ooj_id,
            poreski_period,
            isporuke_p11,
            izvoz_p12,
            isporuke_osl_pdv_p13,
            nabavke_p21,
            uvoz_p22,
            nabavke_poljoprivreda_p23,
            pdv_izlaz_p51,
            pdv_ulaz_p61,
            pdv_reg_obveznici_p41,
            pdv_uvoz_p42,
            pausal_poljoprivreda_p43,
            fbih_p32,
            rs_p33,
            dbr_p34,
            pdv_uplata_povrat_p71
        ) values ( p_ooj_id,
                   p_poreski_period,
                   p_isporuke_p11,
                   p_izvoz_p12,
                   p_isporuke_osl_pdv_p13,
                   p_nabavke_p21,
                   p_uvoz_p22,
                   p_nabavke_poljoprivreda_p23,
                   p_pdv_izlaz_p51,
                   p_pdv_ulaz_p61,
                   p_pdv_reg_obveznici_p41,
                   p_pdv_uvoz_p42,
                   p_pausal_poljoprivreda_p43,
                   p_fbih_p32,
                   p_rs_p33,
                   p_dbr_p34,
                   p_pdv_uplata_povrat_p71 );

    end insert_pdv_prijava;

    procedure delete_pdv_prijava (
        p_id in number
    ) as
    begin
        delete from pdv_prijave
        where
            id = p_id;

    end delete_pdv_prijava;

    procedure pdv_prijava_kif_polja (
        p_ooj_id         in number,
        p_poreski_period in date,
        l_11             out number,
        l_12             out number,
        l_13             out number,
        l_51             out number,
        l_32             out number,
        l_33             out number,
        l_34             out number
    ) as

        cursor c1 is
        (
            select
                iznos,
                glavna_knjiga_id,
                pdv_indikator_id,
                pdv_indikator_sifra,
                nvl(pdv_indikator_vrijednost, 0) as piv,
                kontna_klasa_code,
                tip_stavke                       as tip_stavke_code
            from
                vw_glavna_knjiga_stavke
            where
                glavna_knjiga_id in (
                    select
                        id
                    from
                        vw_glavna_knjiga
                    where
                            proknjizeno = 'Y'
                        and ooj_id = p_ooj_id
                        and trunc(datum_knjizenja, 'MM') = trunc(to_date(p_poreski_period), 'MM')
                        and lower(vrsta_naloga_sifra) in ('if', 'ifs', 'av', 'avs', 'ko', 'kos', 'kz', 'kzs', 'in', 'ins')
                )
                and pdv_indikator_id is not null
        );
    
    begin
        l_11 := 0;
        l_12 := 0;
        l_13 := 0;
        l_51 := 0;
        l_32 := 0;
        l_33 := 0;
        l_34 := 0;
        for stavka in c1 loop
            if (
                stavka.pdv_indikator_sifra in ('B5', 'B6', 'B2', 'B3', 'A1', 'A2', 'A4', 'A5', 'A6', 'A7', 'B1', 'B4', 'D1', 'D2' )
                and stavka.tip_stavke_code like 'P'
            ) then
                l_51 := l_51 + stavka.iznos; --krhaj u polje 51 za pdv
                
                if (
                    stavka.pdv_indikator_sifra in ('A2', 'A4', 'A5', 'B1', 'B4', 'D2')
                    and stavka.tip_stavke_code like 'P'
                ) then
                    l_33 := l_33 + stavka.iznos;
                elsif (
                    stavka.pdv_indikator_sifra in ('B5', 'B2')
                    and stavka.tip_stavke_code like 'P'
                ) then
                    l_32 := l_32 + stavka.iznos;
                elsif (
                    stavka.pdv_indikator_sifra in ('B6', 'B3')
                    and stavka.tip_stavke_code like 'P'
                ) then
                    l_34 := l_34 + stavka.iznos;
                end if;

            elsif (
                stavka.pdv_indikator_sifra in ( 'C1' )
                and stavka.tip_stavke_code like 'P'
            ) then
                l_13 := l_13 + stavka.iznos;
            elsif (
                stavka.pdv_indikator_sifra in ( 'I1' )
                and stavka.tip_stavke_code like 'P'
            ) then
                l_12 := l_12 + stavka.iznos;
            elsif (
                stavka.pdv_indikator_sifra in ( 'C5' )
                and stavka.tip_stavke_code like 'P'
            ) then
                l_11 := l_11 + stavka.iznos;
            elsif (
                stavka.pdv_indikator_sifra in ( 'XI' )
                and stavka.tip_stavke_code like 'P'
            ) then
                l_11 := l_11 + stavka.iznos;
            elsif (
                stavka.pdv_indikator_sifra in ( 'C4' )
                and stavka.tip_stavke_code like 'P'
            ) then
                l_11 := l_11 + stavka.iznos;
            else
                null;
            end if;
        end loop;

        l_11 := abs(l_11);
        l_12 := abs(l_12);
        l_13 := abs(l_13);
        l_51 := abs(l_51);
        l_32 := abs(l_32);
        l_33 := abs(l_33);
        l_34 := abs(l_34);
    end pdv_prijava_kif_polja;

    procedure pdv_prijava_kuf_polja (
        p_ooj_id         in number,
        p_poreski_period in date,
        l_42             out number,
        l_41             out number,
        l_33             out number,
        l_22             out number,
        l_21             out number,
        l_51             out number
    ) as

        cursor c1 is
        (
            select
                iznos,
                glavna_knjiga_id,
                pdv_indikator_sifra,
                nvl(pdv_indikator_vrijednost, 0) as piv,
                kontna_klasa_code,
                tip_stavke                       as tip_stavke_code
            from
                vw_glavna_knjiga_stavke
            where
                glavna_knjiga_id in (
                    select
                        id
                    from
                        glavna_knjiga
                    where
                            proknjizeno = 'Y'
                        and ooj_id = p_ooj_id
                        and trunc(datum_knjizenja, 'MM') = trunc(to_date(p_poreski_period), 'MM')
                        and lower(vrsta_naloga_sifra) in ('uf', 'ufs')
                )
                and pdv_indikator_id is not null
        );

    begin
        l_21 := 0;
        l_22 := 0;
        l_33 := 0;
        l_41 := 0;
        l_42 := 0;
        l_51 := 0;
        for stavka in c1 loop
            if (
                stavka.pdv_indikator_sifra in ('P1', 'P2', 'P3', 'P6', 'P7')
                and stavka.tip_stavke_code like 'D'
            ) then
                l_41 := l_41 + stavka.iznos;
            elsif (
                stavka.pdv_indikator_sifra in ('XU', 'S1', 'S2', 'S3', 'S4')
                and stavka.tip_stavke_code like 'D'
            ) then
                l_21 := l_21 + round(stavka.iznos, 2);
            elsif ( stavka.pdv_indikator_sifra = 'R1' ) then
                l_33 := l_33 + ( stavka.iznos );
                l_21 := l_21 + round(stavka.iznos -(stavka.iznos ));

            elsif (
                stavka.pdv_indikator_sifra in ( 'U1', 'U2' )
                and stavka.tip_stavke_code like 'D'
            ) then
                l_42 := l_42 + stavka.iznos;
            elsif (
                stavka.pdv_indikator_sifra = 'BU'
                and stavka.tip_stavke_code like 'D'
            ) then
                l_22 := l_22 + ( stavka.iznos );
            elsif (
                stavka.pdv_indikator_sifra = 'A6'
                and stavka.tip_stavke_code like 'P'
            ) then
                l_51 := l_51 + ( stavka.iznos );
            else
                null;
            end if;
        end loop;

        l_21 := abs(l_21);
        l_22 := abs(l_22);
        l_33 := abs(l_33);
        l_41 := abs(l_41);
        l_42 := abs(l_42);
        l_51 := abs(l_51);
    end pdv_prijava_kuf_polja;

end pdv_pkg;
/

