prompt
create or replace package body accounting.proizvodnja_pkg is

    -- Normativi
    procedure setup_radni_nalog_from_normativ (
        p_normativ_id in number,
        p_kolicina    in number,
        p_stavke      in varchar2,
        p_radna_snaga in varchar2,
        p_troskovi    in varchar2,
        p_stavka_id   out number,
        p_opis        out varchar2
    ) is
    begin
        if apex_collection.collection_exists(p_stavke) then
            apex_collection.delete_collection(p_stavke);
        end if;
        if apex_collection.collection_exists(p_radna_snaga) then
            apex_collection.delete_collection(p_radna_snaga);
        end if;
        if apex_collection.collection_exists(p_troskovi) then
            apex_collection.delete_collection(p_troskovi);
        end if;
        for c1 in (
            select
                stavka_id,
                opis
            from
                normativi
            where
                id = p_normativ_id
        ) loop
            p_stavka_id := c1.stavka_id;
            p_opis := c1.opis;
        end loop;

        apex_collection.create_collection_from_query(
            p_collection_name => p_stavke,
            p_query           => '
                SELECT
                    stavka_id,
                    jm_id,
                    kolicina * '
                       || p_kolicina
                       || '
                FROM
                    normativ_stavke
                WHERE
                    valid = ''Y''
                    AND normativ_id = '
                       || p_normativ_id
                       || '
            '
        );

        apex_collection.create_collection_from_query(
            p_collection_name => p_radna_snaga,
            p_query           => '
                SELECT
                    obrazovanje_id,
                    broj_sati * '
                       || p_kolicina
                       || '
                FROM
                    normativ_radna_snaga
                WHERE
                    valid = ''Y''
                    AND normativ_id = '
                       || p_normativ_id
                       || '
            '
        );

        apex_collection.create_collection_from_query(
            p_collection_name => p_troskovi,
            p_query           => '
                SELECT
                    opis,
                    iznos * '
                       || p_kolicina
                       || '
                FROM
                    normativ_troskovi
                WHERE
                    valid = ''Y''
                    AND normativ_id = '
                       || p_normativ_id
                       || '
            '
        );

    end setup_radni_nalog_from_normativ;

    procedure get_normativ (
        p_id        in number,
        p_ooj_id    out number,
        p_stavka_id out number,
        p_naziv     out varchar2,
        p_opis      out varchar2,
        p_valid     out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                normativi
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_stavka_id := c1.stavka_id;
            p_naziv := c1.naziv;
            p_opis := c1.opis;
            p_valid := c1.valid;
        end loop;
    end get_normativ;

    function insert_normativ (
        p_ooj_id    in number,
        p_stavka_id in number,
        p_naziv     in varchar2,
        p_opis      in varchar2
    ) return number is
        l_id number;
    begin
        insert into normativi (
            ooj_id,
            stavka_id,
            naziv,
            opis
        ) values ( p_ooj_id,
                   p_stavka_id,
                   p_naziv,
                   p_opis ) returning id into l_id;

        return l_id;
    end insert_normativ;

    procedure update_normativ (
        p_id        in number,
        p_ooj_id    in number,
        p_stavka_id in number,
        p_naziv     in varchar2,
        p_opis      in varchar2,
        p_valid     in varchar2
    ) is
    begin
        update normativi
        set
            ooj_id = p_ooj_id,
            stavka_id = p_stavka_id,
            naziv = p_naziv,
            opis = p_opis,
            valid = p_valid
        where
            id = p_id;

    end update_normativ;

    procedure delete_normativ (
        p_id in number
    ) is
    begin
        delete from normativi
        where
            id = p_id;

    end delete_normativ;

    -- Normativ stavke
    procedure get_normativ_stavka (
        p_id          in number,
        p_normativ_id out number,
        p_stavka_id   out number,
        p_jm_id       out number,
        p_kolicina    out number,
        p_valid       out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                normativ_stavke
            where
                id = p_id
        ) loop
            p_normativ_id := c1.normativ_id;
            p_stavka_id := c1.stavka_id;
            p_jm_id := c1.jm_id;
            p_kolicina := c1.kolicina;
            p_valid := c1.valid;
        end loop;
    end get_normativ_stavka;

    procedure insert_normativ_stavka (
        p_normativ_id in number,
        p_stavka_id   in number,
        p_jm_id       in number,
        p_kolicina    in number
    ) is
    begin
        insert into normativ_stavke (
            normativ_id,
