        ) values ( p_normativ_id,
                   p_stavka_id,
                   p_jm_id,
                   p_kolicina );

    end insert_normativ_stavka;

    procedure update_normativ_stavka (
        p_id          in number,
        p_normativ_id in number,
        p_stavka_id   in number,
        p_jm_id       in number,
