        end loop;
    end get_normativ_radna_snaga;

    procedure insert_normativ_radna_snaga (
        p_normativ_id    in number,
        p_obrazovanje_id in number,
        p_broj_sati      in number
    ) is
    begin
        insert into normativ_radna_snaga (
            normativ_id,
