            broj_sati
        ) values ( p_normativ_id,
                   p_obrazovanje_id,
                   p_broj_sati );

    end insert_normativ_radna_snaga;

    procedure update_normativ_radna_snaga (
        p_id             in number,
        p_normativ_id    in number,
        p_obrazovanje_id in number,
        p_broj_sati      in number,
