            broj_sati = p_broj_sati,
            valid = p_valid
        where
            id = p_id;

    end update_normativ_radna_snaga;

    procedure delete_normativ_radna_snaga (
        p_id in number
    ) is
    begin
        delete from normativ_radna_snaga
        where
            id = p_id;

    end delete_normativ_radna_snaga;

    -- Normativ troskovi
    procedure get_normativ_trosak (
        p_id          in number,
        p_normativ_id out number,
        p_opis        out varchar2,
        p_iznos       out number,
        p_valid       out varchar2
    ) is
    begin
        for c1 in (
