    -- Radni nalozi
    procedure get_radni_nalog (
        p_id               in number,
        p_ooj_id           out number,
        p_glavna_knjiga_id out number,
        p_skladiste_id     out number,
        p_oj_id            out number,
        p_normativ_id      out number,
        p_stavka_id        out number,
        p_status_id        out number,
        p_storniran_id     out number,
        p_naziv            out varchar2,
        p_broj             out number,
        p_kolicina         out number,
        p_godina           out number,
        p_datum            out date,
        p_opis             out varchar2,
        p_stornirano       out varchar2,
        p_valid            out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                radni_nalozi
            where
