        ) loop
            p_ooj_id := c1.ooj_id;
            p_glavna_knjiga_id := c1.glavna_knjiga_id;
            p_skladiste_id := null; --c1.skladiste_id; sl20270709; Error(415,34): PLS-00302: component 'SKLADISTE_ID' must be declared
            p_oj_id := c1.oj_id;
            p_normativ_id := c1.normativ_id;
            p_stavka_id := c1.stavka_id;
            p_status_id := c1.status_id;
            p_storniran_id := c1.storniran_id;
            p_naziv := c1.naziv;
            p_broj := c1.broj;
            p_kolicina := c1.kolicina;
            p_godina := c1.godina;
            p_datum := c1.datum;
            p_opis := c1.opis;
            p_stornirano := c1.stornirano;
            p_valid := c1.valid;
        end loop;
    end get_radni_nalog;

    function insert_radni_nalog (
        p_ooj_id       in number,
        p_radnik_id    in number,
        p_skladiste_id in number,
        p_oj_id        in number,
        p_normativ_id  in number,
        p_stavka_id    in number,
        p_naziv        in varchar2,
        p_broj         in number,
        p_kolicina     in number,
        p_godina       in number,
        p_datum        in date,
        p_opis         in varchar2
    ) return number is
        l_id number;
    begin
        insert into radni_nalozi (
            ooj_id,
            --skladiste_id, sl20270709; Error(415,34): PLS-00302: component 'SKLADISTE_ID' must be declared
            oj_id,
            normativ_id,
            stavka_id,
            naziv,
            broj,
            kolicina,
            godina,
            datum,
            opis
        ) values ( p_ooj_id,
                   -- p_skladiste_id,sl20270709; Error(415,34): PLS-00302: component 'SKLADISTE_ID' must be declared
                   p_oj_id,
                   p_normativ_id,
                   p_stavka_id,
                   p_naziv,
                   p_broj,
                   p_kolicina,
                   p_godina,
                   p_datum,
                   p_opis ) returning id into l_id;

        insert_radni_nalog_hist(
            p_radni_nalog_id => l_id,
            p_status_id      => sif.sif_pkg.get_status_id('10'),
            p_radnik_id      => p_radnik_id,
            p_komentar       => null
        );

        return l_id;
    end insert_radni_nalog;

    procedure update_radni_nalog (
        p_id               in number,
        p_ooj_id           in number,
        p_glavna_knjiga_id in number,
        p_skladiste_id     in number,
        p_oj_id            in number,
        p_normativ_id      in number,
        p_stavka_id        in number,
        p_status_id        in number,
        p_storniran_id     in number,
        p_naziv            in varchar2,
        p_broj             in number,
        p_kolicina         in number,
        p_godina           in number,
        p_datum            in date,
        p_opis             in varchar2,
        p_stornirano       in varchar2,
        p_valid            in varchar2
    ) is
    begin
        update radni_nalozi
        set
            ooj_id = p_ooj_id,
            glavna_knjiga_id = p_glavna_knjiga_id,
            --skladiste_id = p_skladiste_id,  sl20270709; Error(415,34): PLS-00302: component 'SKLADISTE_ID' must be declared
            oj_id = p_oj_id,
            normativ_id = p_normativ_id,
            stavka_id = p_stavka_id,
            status_id = p_status_id,
            storniran_id = p_storniran_id,
            naziv = p_naziv,
            broj = p_broj,
            kolicina = p_kolicina,
            godina = p_godina,
            datum = p_datum,
            opis = p_opis,
            stornirano = p_stornirano,
            valid = p_valid
        where
            id = p_id;

    end update_radni_nalog;

    procedure delete_radni_nalog (
        p_id in number
    ) is
    begin
        delete from radni_nalozi
        where
            id = p_id;

    end delete_radni_nalog;

    -- Radni nalog stavke
    procedure get_radni_nalog_stavka (
        p_id             in number,
        p_radni_nalog_id out number,
        p_stavka_id      out number,
        p_jm_id          out number,
        p_kolicina       out number,
        p_iznos          out number,
        p_valid          out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                radni_nalog_stavke
            where
                id = p_id
        ) loop
            p_radni_nalog_id := c1.radni_nalog_id;
            p_stavka_id := c1.stavka_id;
            p_jm_id := c1.jm_id;
            p_kolicina := c1.kolicina;
            p_iznos := c1.iznos;
            p_valid := c1.valid;
        end loop;
    end get_radni_nalog_stavka;

    procedure insert_radni_nalog_stavka (
        p_radni_nalog_id in number,
        p_stavka_id      in number,
        p_jm_id          in number,
        p_kolicina       in number,
        p_iznos          in number
    ) is
    begin
        insert into radni_nalog_stavke (
            radni_nalog_id,
            stavka_id,
            jm_id,
            kolicina,
            iznos
        ) values ( p_radni_nalog_id,
                   p_stavka_id,
                   p_jm_id,
                   p_kolicina,
                   p_iznos );

    end insert_radni_nalog_stavka;

    procedure update_radni_nalog_stavka (
        p_id             in number,
        p_radni_nalog_id in number,
        p_stavka_id      in number,
        p_jm_id          in number,
        p_kolicina       in number,
        p_iznos          in number,
        p_valid          in varchar2
    ) is
    begin
        update radni_nalog_stavke
        set
            radni_nalog_id = p_radni_nalog_id,
            stavka_id = p_stavka_id,
            jm_id = p_jm_id,
            kolicina = p_kolicina,
            iznos = p_iznos,
            valid = p_valid
        where
            id = p_id;

    end update_radni_nalog_stavka;

    procedure delete_radni_nalog_stavka (
        p_id in number
    ) is
    begin
        delete from radni_nalog_stavke
        where
            id = p_id;

    end delete_radni_nalog_stavka;

    -- Radni nalog radna snaga
    procedure get_radni_nalog_radna_snaga (
        p_id             in number,
        p_radni_nalog_id out number,
        p_obrazovanje_id out number,
        p_radnik_id      out number,
        p_broj_sati      out number,
        p_iznos          out number,
        p_valid          out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                radni_nalog_radna_snaga
            where
                id = p_id
        ) loop
            p_radni_nalog_id := c1.radni_nalog_id;
            p_obrazovanje_id := c1.obrazovanje_id;
            p_radnik_id := c1.radnik_id;
            p_broj_sati := c1.broj_sati;
            p_iznos := c1.iznos;
            p_valid := c1.valid;
        end loop;
    end get_radni_nalog_radna_snaga;

    procedure insert_radni_nalog_radna_snaga (
        p_radni_nalog_id in number,
        p_obrazovanje_id in number,
        p_broj_sati      in number,
        p_iznos          in number
    ) is
    begin
        insert into radni_nalog_radna_snaga (
            radni_nalog_id,
            obrazovanje_id,
            broj_sati,
            iznos
        ) values ( p_radni_nalog_id,
                   p_obrazovanje_id,
                   p_broj_sati,
                   p_iznos );

    end insert_radni_nalog_radna_snaga;

    procedure update_radni_nalog_radna_snaga (
        p_id             in number,
        p_radni_nalog_id in number,
        p_obrazovanje_id in number,
        p_radnik_id      in number,
        p_broj_sati      in number,
        p_iznos          in number,
        p_valid          in varchar2
    ) is
    begin
        update radni_nalog_radna_snaga
        set
            radni_nalog_id = p_radni_nalog_id,
            obrazovanje_id = p_obrazovanje_id,
            radnik_id = p_radnik_id,
            broj_sati = p_broj_sati,
            iznos = p_iznos,
            valid = p_valid
        where
            id = p_id;

    end update_radni_nalog_radna_snaga;

    procedure delete_radni_nalog_radna_snaga (
        p_id in number
    ) is
    begin
        delete from radni_nalog_radna_snaga
        where
            id = p_id;

    end delete_radni_nalog_radna_snaga;

    -- Radni nalog troskovi
    procedure get_radni_nalog_trosak (
        p_id             in number,
        p_radni_nalog_id out number,
        p_opis           out varchar2,
        p_iznos          out number,
        p_valid          out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                radni_nalog_troskovi
            where
                id = p_id
        ) loop
            p_radni_nalog_id := c1.radni_nalog_id;
            p_opis := c1.opis;
            p_iznos := c1.iznos;
            p_valid := c1.valid;
        end loop;
    end get_radni_nalog_trosak;

    procedure insert_radni_nalog_trosak (
        p_radni_nalog_id in number,
        p_opis           in varchar2,
        p_iznos          in number
    ) is
    begin
        insert into radni_nalog_troskovi (
            radni_nalog_id,
            opis,
            iznos
        ) values ( p_radni_nalog_id,
                   p_opis,
                   p_iznos );

    end insert_radni_nalog_trosak;

    procedure update_radni_nalog_trosak (
        p_id             in number,
        p_radni_nalog_id in number,
        p_opis           in varchar2,
        p_iznos          in number,
        p_valid          in varchar2
    ) is
    begin
        update radni_nalog_troskovi
        set
            radni_nalog_id = p_radni_nalog_id,
            opis = p_opis,
            iznos = p_iznos,
            valid = p_valid
        where
            id = p_id;

    end update_radni_nalog_trosak;

    procedure delete_radni_nalog_trosak (
        p_id in number
    ) is
    begin
        delete from radni_nalog_troskovi
        where
            id = p_id;

    end delete_radni_nalog_trosak;

    -- Radni nalog HIST
    procedure insert_radni_nalog_hist (
        p_radni_nalog_id in number,
        p_status_id      in number,
        p_radnik_id      in number,
        p_komentar       in varchar2
    ) is
    begin
        update radni_nalozi
        set
            status_id = p_status_id
        where
            id = p_radni_nalog_id;

        insert into radni_nalog_hist (
            radni_nalog_id,
            status_id,
            radnik_id,
            komentar
        ) values ( p_radni_nalog_id,
                   p_status_id,
                   p_radnik_id,
                   p_komentar );

    end insert_radni_nalog_hist;

end proizvodnja_pkg;
/

prompt
prompt Creating package body SABLONI_PKG
prompt =================================
prompt
create or replace package body accounting.sabloni_pkg as

    function get_basic_sablon_id return number is
        l_sablon_id number := 17;
    begin
        for c1 in (
            select
                id
            from
                sabloni
            where
                ooj_id is null or id = l_sablon_id
        ) loop
            return c1.id;
        end loop;

        return null;
    end get_basic_sablon_id;

    -- Sabloni
    procedure get_sablon (
        p_id           in number,
        p_ooj_id       out number,
        p_naziv        out varchar2,
        p_opis         out varchar2,
        p_subscribe_id out number,
        p_valid        out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sabloni
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_naziv := c1.naziv;
            p_opis := c1.opis;
            p_subscribe_id := c1.subscribe_id;
            p_valid := c1.valid;
        end loop;
    end get_sablon;

    function insert_sablon (
        p_ooj_id       in number,
        p_naziv        in varchar2,
        p_opis         in varchar2,
        p_subscribe_id in number
    ) return number is
        l_id number;
    begin
        insert into sabloni (
            ooj_id,
            naziv,
            opis,
            subscribe_id
        ) values ( p_ooj_id,
                   p_naziv,
                   p_opis,
                   p_subscribe_id ) returning id into l_id;

        return l_id;
    end insert_sablon;

    procedure update_sablon (
        p_id           in number,
        p_ooj_id       in number,
        p_naziv        in varchar2,
        p_opis         in varchar2,
        p_subscribe_id in number,
        p_valid        in varchar2
    ) is
    begin
        update sabloni
        set
            ooj_id = p_ooj_id,
            naziv = p_naziv,
            opis = p_opis,
            subscribe_id = p_subscribe_id,
            valid = p_valid
        where
            id = p_id;

    end update_sablon;

    procedure delete_sablon (
        p_id in number
    ) is
    begin
        delete from sabloni_konta
        where
            sablon_id = p_id;

        delete from sabloni
        where
            id = p_id;

    end delete_sablon;

    procedure update_sablon_subscriptions (
        p_id in number
    ) is

        cursor c_sabloni is
        (
            select
                id
            from
                sabloni
            where
                subscribe_id = p_id
        );

        l_ooj_id       number;
        l_naziv        varchar2(255);
        l_opis         varchar2(255);
        l_subscribe_id number;
        l_valid        varchar2(1);
    begin
        apex_debug.message('dbg started');
        get_sablon(
            p_id           => p_id,
            p_ooj_id       => l_ooj_id,
            p_naziv        => l_naziv,
            p_opis         => l_opis,
            p_subscribe_id => l_subscribe_id,
            p_valid        => l_valid
        );

        apex_debug.message('updated');
        for c1 in c_sabloni loop
            apex_debug.message('started konta ' || c1.id);
            delete from sabloni_konta
            where
                sablon_id = c1.id;

            apex_debug.message('deleted konta ' || c1.id);
            insert into sabloni_konta (
                sablon_id,
                automatsko_knjizenje_id,
                kontna_klasa_id
            )
                select
                    c1.id,
                    automatsko_knjizenje_id,
                    kontna_klasa_id
                from
                    sabloni_konta
                where
                    sablon_id = p_id;

            apex_debug.message('inserted konta ' || c1.id);
        end loop;

    end update_sablon_subscriptions;

    -- Sabloni konta
    function get_sablon_konto (
        p_sablon_id                  in number,
        p_automatsko_knjizenje_sifra in varchar2
    ) return number is
    begin
--        apex_debug.message('AKS: ' || p_automatsko_knjizenje_sifra);
        for c1 in (
            select
                *
            from
                vw_sabloni_konta
            where
                    sablon_id = p_sablon_id
                and lower(automatsko_knjizenje_sifra) = lower(p_automatsko_knjizenje_sifra)
        ) loop
            return c1.kontna_klasa_id;
        end loop;

        return null;
    end get_sablon_konto;

    procedure insert_sablon_konto (
        p_sablon_id               in number,
        p_automatsko_knjizenje_id in number,
        p_kontna_klasa_id         in number
    ) is
    begin
        insert into sabloni_konta (
            sablon_id,
            automatsko_knjizenje_id,
            kontna_klasa_id
        ) values ( p_sablon_id,
                   p_automatsko_knjizenje_id,
                   p_kontna_klasa_id );

    end insert_sablon_konto;

    procedure update_sablon_konto (
        p_id                      in number,
        p_sablon_id               in number,
        p_automatsko_knjizenje_id in number,
        p_kontna_klasa_id         in number
    ) is
    begin
        update sabloni_konta
        set
            sablon_id = p_sablon_id,
            automatsko_knjizenje_id = p_automatsko_knjizenje_id,
            kontna_klasa_id = p_kontna_klasa_id
        where
            id = p_id;

    end update_sablon_konto;

end sabloni_pkg;
/

prompt
prompt Creating package body SADRZAJ_GK_PKG
prompt ====================================
prompt
create or replace package body accounting.SADRZAJ_GK_PKG is

procedure izvodi_sgk (
    p_izvod_ids in sys.odcinumberlist
)
is
    v_postoji_klijent_konto_os number;
    v_broj_os                  number;
    v_id_os                    number;
    v_broj_vd                  varchar2(500);
    v_opis_vd                  varchar2(1000);
    v_konto                    number;
    v_naziv_konta              varchar2(500);
    v_mt                       number;
    v_naziv_mt                 varchar2(500);
    v_radnik                   number;
    v_opstina                  number;
    v_partner                  number;
    
begin

    -- kreiranje kolekcije --
    if apex_collection.collection_exists('SADRZAJ_GK_IZVODI') then
        apex_collection.delete_collection('SADRZAJ_GK_IZVODI');
    end if;

    apex_collection.create_collection('SADRZAJ_GK_IZVODI');

    -- template za stavke glavne knjige --
    for r in (
        select *
        from (
                select 'A' as tip, izs.id as izvod_stavka_id, iz.id as izvod_id,
                       iz.datum as datum_dokumenta, iz.opis as opis_izvoda,
                       izs.svrha_doznake as opis_transakcije,
                       izs.klijent_id as partner, izs.opstina as opstina, null as radnik,
                       izs.smjer as smjer_placanja,
                       izs.konto_id as konto, nvl(ko.otvorene_stavke, 'N') as pracenje_os, null as mjesto_tr,
                       case when izs.smjer = 'P' then 'P' else 'D' end as strana_knjizenja,
                       case when izs.smjer = 'P' then -izs.iznos else izs.iznos end as iznos,
                       izs.rbr,
                       izs.valuta_id, 
                       ko.naziv as naziv_konta,
                       case when izs.smjer = 'P' then '2' else '4' end as kontna_grupa
                from accounting.izvodi iz
                join accounting.izvod_stavke izs on iz.id = izs.izvod_id
                left join sif.acc_kontni_okvir_klase ko on ko.id = izs.konto_id
                where iz.id in (select column_value from table(p_izvod_ids))

                union

                select 'S' as tip, 0 as izvod_stavka_id, iz.id as izvod_id,
                       iz.datum as datum_dokumenta, iz.opis as opis_izvoda,
                       iz.opis as opis_transakcije,
                       null as partner, null as opstina, null as radnik,
                       izs.smjer as smjer_placanja,
                       zr.kontna_klasa_id as konto, null pracenje_os, null as mjesto_tr,
                       case when izs.smjer = 'P' then 'D' else 'P' end as strana_knjizenja,
                       sum(case when izs.smjer = 'P' then izs.iznos else -izs.iznos end) as iznos,
                       999999 as rbr,
                       izs.valuta_id, 
                       ko.naziv as naziv_konta, 
                       null kontna_grupa
                from accounting.izvodi iz
                join accounting.izvod_stavke izs on iz.id = izs.izvod_id
                join sif.sif_ziro_racuni zr on zr.id = iz.ziro_racun_id
                join sif.acc_kontni_okvir_klase ko on ko.id=zr.kontna_klasa_id
                where iz.id in (select column_value from table(p_izvod_ids))
                group by iz.id, iz.datum, iz.opis, izs.smjer, zr.kontna_klasa_id, izs.valuta_id, ko.naziv
             )
        order by izvod_id, rbr
    )
    loop

        if r.tip='A' and (r.partner is not null or r.konto is not null) then

            if r.partner is null then

                if r.pracenje_os = 'N' then

                    v_id_os   := null;
                    v_broj_vd := null;
                    v_opis_vd := null;
                    v_mt      :=r.mjesto_tr;
                    v_naziv_mt:=null;
                    v_radnik  :=r.radnik;
                    v_opstina :=r.opstina;
                    v_partner :=r.partner;
                    

                else

                    select count(*)
                    into v_broj_os
                    from accounting.glavna_knjiga_stavke gks
                    left join (
                        select to_number(c011) as id_os
                        from apex_collections
                        where collection_name = 'SADRZAJ_GK_IZVODI'
                        and c011 is not null
                    ) kol on kol.id_os = gks.id
                    where gks.otvorena != 'Z'
                    and gks.kontna_klasa_id = r.konto
                    and gks.otvoreni_iznos = -r.iznos
                    and kol.id_os is null;

                    if v_broj_os = 1 then

                        select gks.id, gsd.dokument, gsd.opis, gks.mjesto_troska_id, mt.naziv, gks.radnik_id, gks.grad_id, gks.klijent_id
                        into v_id_os, v_broj_vd, v_opis_vd, v_mt, v_naziv_mt, v_radnik, v_opstina, v_partner
                        from accounting.glavna_knjiga_stavke gks
                        left join sif.acc_mjesta_troska mt on mt.id=gks.mjesto_troska_id
                        left join accounting.gk_stavke_dokument gsd on gsd.glavna_knjiga_stavka_id = gks.id
                        left join (
                            select to_number(c011) as id_os
                            from apex_collections
                            where collection_name = 'SADRZAJ_GK_IZVODI'
                            and c011 is not null
                        ) kol on kol.id_os = gks.id
                        where gks.otvorena != 'Z'
                        and gks.kontna_klasa_id = r.konto
                        and gks.otvoreni_iznos = -r.iznos
                        and kol.id_os is null;

                    else
                        v_id_os   := null;
                        v_broj_vd := null;
                        v_opis_vd := null;
                        v_mt      :=r.mjesto_tr;
                        v_naziv_mt:=null;
                        v_radnik  :=r.radnik;
                        v_opstina :=r.opstina;
                        v_partner :=r.partner;
                    end if;
                        
                end if;
                
                v_konto :=r.konto;
                v_naziv_konta :=r.naziv_konta;
                 
            elsif r.konto is null then

                select count(k.id)
                into v_postoji_klijent_konto_os
                from accounting.sec_klijenti k
                join accounting.sec_klijent_konta kk on kk.sec_klijent_id = k.id
                join sif.acc_kontni_okvir_klase ko on ko.id = kk.kontna_klasa_id and ko.otvorene_stavke = 'Y'
                where kk.valid = 'Y'
                and k.id = r.partner
                and substr(ko.code,1,1)=r.kontna_grupa;

                if v_postoji_klijent_konto_os = 1 then

                    select ko.id, ko.naziv
                    into v_konto, v_naziv_konta
                    from accounting.sec_klijenti k
                    join accounting.sec_klijent_konta kk on kk.sec_klijent_id = k.id
                    join sif.acc_kontni_okvir_klase ko on ko.id = kk.kontna_klasa_id and ko.otvorene_stavke = 'Y'
                    where kk.valid = 'Y'
                    and k.id = r.partner
                    and substr(ko.code,1,1)=r.kontna_grupa;

                    select count(*)
                    into v_broj_os
                    from accounting.glavna_knjiga_stavke gks
                    left join (
                        select to_number(c011) as id_os
                        from apex_collections
                        where collection_name = 'SADRZAJ_GK_IZVODI'
                        and c011 is not null
                    ) kol on kol.id_os = gks.id
                    where gks.otvorena != 'Z'
                    and gks.kontna_klasa_id = v_konto
                    and gks.klijent_id = r.partner
                    and gks.otvoreni_iznos = -r.iznos
                    and kol.id_os is null;

                    if v_broj_os = 1 then

                        select gks.id, gsd.dokument, gsd.opis, gks.mjesto_troska_id, mt.naziv, gks.radnik_id, gks.grad_id, gks.klijent_id
                        into v_id_os, v_broj_vd, v_opis_vd, v_mt, v_naziv_mt, v_radnik, v_opstina, v_partner
                        from accounting.glavna_knjiga_stavke gks
                        left join accounting.gk_stavke_dokument gsd on gsd.glavna_knjiga_stavka_id = gks.id
                        left join sif.acc_mjesta_troska mt on mt.id=gks.mjesto_troska_id
                        left join (
                            select to_number(c011) as id_os
                            from apex_collections
                            where collection_name = 'SADRZAJ_GK_IZVODI'
                            and c011 is not null
                        ) kol on kol.id_os = gks.id
                        where gks.otvorena != 'Z'
                        and gks.kontna_klasa_id = v_konto
                        and gks.klijent_id = r.partner
                        and gks.otvoreni_iznos = -r.iznos
                        and kol.id_os is null;

                    else
                        v_id_os   := null;
                        v_broj_vd := null;
                        v_opis_vd := null;
                        v_mt      :=r.mjesto_tr;
                        v_naziv_mt:=null;
                        v_radnik  :=r.radnik;
                        v_opstina :=r.opstina;
                        v_partner :=r.partner;
                    end if;

                end if;

            else

                select count(*)
                into v_broj_os
                from accounting.glavna_knjiga_stavke gks
                left join (
                    select to_number(c011) as id_os
                    from apex_collections
                    where collection_name = 'SADRZAJ_GK_IZVODI'
                    and c011 is not null
                ) kol on kol.id_os = gks.id
                where gks.otvorena != 'Z'
                and gks.kontna_klasa_id = r.konto
                and gks.klijent_id = r.partner
                and gks.otvoreni_iznos = -r.iznos
                and kol.id_os is null;

                if v_broj_os > 0 then

                    select gks.id, gsd.dokument, gsd.opis, gks.mjesto_troska_id, mt.naziv, gks.radnik_id, gks.grad_id, gks.klijent_id
                    into v_id_os, v_broj_vd, v_opis_vd, v_mt, v_naziv_mt, v_radnik, v_opstina, v_partner
                    from accounting.glavna_knjiga_stavke gks
                    left join accounting.gk_stavke_dokument gsd on gsd.glavna_knjiga_stavka_id = gks.id
                    left join sif.acc_mjesta_troska mt on mt.id=gks.mjesto_troska_id
                    left join (
                        select to_number(c011) as id_os
                        from apex_collections
                        where collection_name = 'SADRZAJ_GK_IZVODI'
                        and c011 is not null
                    ) kol on kol.id_os = gks.id
                    where gks.otvorena != 'Z'
                    and gks.kontna_klasa_id = r.konto
                    and gks.klijent_id = r.partner
                    and gks.otvoreni_iznos = -r.iznos
                    and kol.id_os is null
                    order by gks.datum_dokumenta
                    fetch first 1 row only;

                else
                        v_id_os   := null;
                        v_broj_vd := null;
                        v_opis_vd := null;
                        v_mt      :=r.mjesto_tr;
                        v_naziv_mt:=null;
                        v_radnik  :=r.radnik;
                        v_opstina :=r.opstina;
                        v_partner :=r.partner;
                end if;

            end if;
        
        else
          
          v_id_os   := null;
          v_broj_vd := null;
          v_opis_vd := null;
          v_mt      :=r.mjesto_tr;
          v_naziv_mt:=null;
          v_radnik  :=r.radnik;
          v_opstina :=r.opstina;
          v_partner :=r.partner;
          v_konto :=r.konto;
          v_naziv_konta :=r.naziv_konta; 
          
        end if;

        apex_collection.add_member(
            p_collection_name => 'SADRZAJ_GK_IZVODI',
            p_c001 => r.tip,
            p_c002 => r.opis_izvoda,
            p_c003 => r.opis_transakcije,
            p_c004 => v_partner,
            p_c005 => v_opstina,
            p_c006 => v_radnik,
            p_c007 => r.smjer_placanja,
            p_c008 => r.mjesto_tr,
            p_c009 => r.strana_knjizenja,
            p_c010 => r.pracenje_os,
            p_c011 => v_id_os,
            p_c012 => v_broj_vd,
            p_c013 => v_opis_vd,
            p_c014 => 'Y',
            p_c015 => v_konto,
            p_c016 => r.valuta_id,
            p_c017 => null, 
            p_c018 => v_naziv_konta, 
            p_n001 => abs(r.iznos),
            p_n002 => r.iznos,
            p_n003 => r.rbr,
            p_n004 => r.izvod_stavka_id,
            p_n005 => r.izvod_id,
            p_d001 => r.datum_dokumenta
        );

    end loop;
end;


procedure uf_sgk (
    p_uf_ids in sys.odcinumberlist
)
is

    v_konto_dobavljaca_id number;
    v_konto_dobavljaca_naziv varchar2(500);
    v_konto_dobavljaca_ot_st varchar2(1);
    v_rbr number:=1;
begin

    -- kreiranje kolekcije --
    if apex_collection.collection_exists('SADRZAJ_GK_UF') then
        apex_collection.delete_collection('SADRZAJ_GK_UF');
    end if;

    apex_collection.create_collection('SADRZAJ_GK_UF');

    -- template za stavke glavne knjige --
    for r in (
        select k.naziv_fakture as opis_transakcije,k.datum_fakture as datum_dokumenta, k.partner_id as partner,k.pdv_indikator_id as id_pdv_indikatora, k.pdv_indikator_sifra as sifra_pdv_indikatora, k.tip_dokumenta_sifra as vrsta_dokumenta, 
               k.valuta_id, k.iznos_bez_pdv, k.iznos_sa_pdv, k.kuf_id, 
               'Ulazne fakture - UF/'||k.broj||'/'||k.godina as dokument
              from vw_kufovi k
              where k.kuf_id in (select column_value from table(p_uf_ids))
              order by k.datum_fakture, k.kuf_id
    )
    loop
      
       ---- duguje (konta troska/nabavke i pdv)---
       
       --prvojera da li imamo iskazanu posebnu stavku pdv-a na osnovu pdv-indikatora---
       if r.sifra_pdv_indikatora  like 'S%' or  r.sifra_pdv_indikatora  like '%R' then --indikatori idu uz konta nabavke a ne pdv-a
         
       
         apex_collection.add_member(
            p_collection_name => 'SADRZAJ_GK_UF',
            p_c001 => r.opis_transakcije,
            p_c002 => null, --partner
            p_c003 => null, --mt
            p_c004 => r.id_pdv_indikatora,
            p_c005 => 'D',
            p_c006 => null, --konto
            p_c007 => r.valuta_id,
            p_c008 => null, --otvorena stavka
            p_c009 => r.dokument,
            p_c010 => r.opis_transakcije,
            p_c012 => null, --mt_naziv
            p_c013 => null, --konto_naziv
            p_n001 => r.iznos_sa_pdv,
            p_n002 => v_rbr,
            p_n003 => r.kuf_id,
            p_d001 => r.datum_dokumenta
        ); 
       
          v_rbr:=v_rbr+1;
       
       else -- pdv posebno iskazan--
         
        --nabavaka-
         apex_collection.add_member(
            p_collection_name => 'SADRZAJ_GK_UF',
            p_c001 => r.opis_transakcije,
            p_c002 => null,
            p_c003 => null,
            p_c004 => null,
            p_c005 => 'D',
            p_c006 => null,
            p_c007 => r.valuta_id,
            p_c008 => null,
            p_c009 => r.dokument,
            p_c010 => r.opis_transakcije,
            p_c012 => null, --mt_naziv
            p_c013 => null, --konto_naziv
            p_n001 => r.iznos_bez_pdv,
            p_n002 => v_rbr,
            p_n003 => r.kuf_id,
            p_d001 => r.datum_dokumenta
        ); 
        v_rbr:=v_rbr+1;
        --pdv--
        apex_collection.add_member(
            p_collection_name => 'SADRZAJ_GK_UF',
            p_c001 => r.opis_transakcije,
            p_c002 => null,
            p_c003 => null,
            p_c004 => r.id_pdv_indikatora,
            p_c005 => 'D',
            p_c006 => null,
            p_c007 => r.valuta_id,
            p_c008 => null,
            p_c009 => r.dokument,
            p_c010 => r.opis_transakcije,
            p_c012 => null, --mt_naziv
            p_c013 => null, --konto_naziv
            p_n001 => r.iznos_sa_pdv-r.iznos_bez_pdv,
            p_n002 => v_rbr,
            p_n003 => r.kuf_id,
            p_d001 => r.datum_dokumenta
        );
         v_rbr:=v_rbr+1;
        end if;
        
        ----potrazuje-----
        
        ---konto dobavljača---
         for j in (select g.kontna_klasa_id, nvl(k.otvorene_stavke,'N') as ot_st, k.naziv
                   from accounting.sec_klijent_konta  g
                   join sif.acc_kontni_okvir_klase k on g.kontna_klasa_id=k.id
                   where substr(k.code,1,1)= '4'
                   and k.valid='Y'
                   and g.sec_klijent_id=r.partner
                   and rownum=1)
         loop
           v_konto_dobavljaca_id:=j.kontna_klasa_id;
           v_konto_dobavljaca_ot_st:=j.ot_st;
           v_konto_dobavljaca_naziv:=j.naziv;
         end loop;
         
         apex_collection.add_member(
            p_collection_name => 'SADRZAJ_GK_UF',
            p_c001 => r.opis_transakcije,
            p_c002 => r.partner,
            p_c003 => null,
            p_c004 => null,
            p_c005 => 'P',
            p_c006 => v_konto_dobavljaca_id,
            p_c007 => r.valuta_id,
            p_c008 => v_konto_dobavljaca_ot_st,
            p_c009 => r.dokument,
            p_c010 => r.opis_transakcije,
            p_c012 => null,
            p_c013 => v_konto_dobavljaca_naziv,
            p_n001 => -r.iznos_sa_pdv,
            p_n002 => v_rbr,
            p_n003 => r.kuf_id,
            p_d001 => r.datum_dokumenta
        );
        v_rbr:=v_rbr+1;
                
        -------------------

    end loop;
   end;
end SADRZAJ_GK_PKG;
/

