prompt
create or replace package body accounting.sec_pkg is

    --------------------------------------------------------------
    -- procedures for table SEC_KLIJENTI
    --------------------------------------------------------------
    
    function get_klijent_fizicko_lice_id (
        p_naziv in varchar2
    ) return number is
    begin
        for c1 in (
            select
                id
            from
                sec_klijenti
            where
                naziv = p_naziv
        ) loop
            RETURN c1.id;
        end loop;
        
        return null;
        
    end get_klijent_fizicko_lice_id;

    procedure get_klijent (
        p_id              in number,
        p_ooj_id          out number,
        p_vrsta_klijenta  out varchar2,
        p_tip_klijenta_id out number,
        p_radnik_id       out number,
        p_drzava_id       out number,
        p_entitet_id      out number,
        p_naziv           out varchar2,
        p_adresa          out varchar2,
        p_grad            out varchar2,
        p_postanski_broj  out varchar2,
        p_tel             out varchar2,
        p_email           out varchar2,
        p_web             out varchar2,
        p_sud             out varchar2,
        p_jib             out varchar2,
        p_pib             out varchar2,
        p_sablon_id       out number,
        p_kontna_klasa_id out number,
        p_valid           out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_klijenti
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_vrsta_klijenta := c1.vrsta_klijenta;
            p_tip_klijenta_id := c1.tip_klijenta_id;
            p_radnik_id := c1.radnik_id;
            p_drzava_id := c1.drzava_id;
            p_entitet_id := c1.entitet_id;
            p_naziv := c1.naziv;
            p_adresa := c1.adresa;
            p_grad := c1.grad;
            p_postanski_broj := c1.postanski_broj;
            p_tel := c1.tel;
            p_email := c1.email;
            p_web := c1.web;
            p_sud := c1.sud;
            p_jib := c1.jib;
            p_pib := c1.pib;
            p_sablon_id := c1.sablon_id;
            p_kontna_klasa_id := c1.kontna_klasa_id;
            p_valid := c1.valid;
        end loop;
    end get_klijent;

    procedure get_klijent (
        p_id     in number,
        p_adresa out varchar2,
        p_grad   out varchar2,
        p_jib    out varchar2,
        p_pib    out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_klijenti
            where
                id = p_id
        ) loop
            p_adresa := c1.adresa;
            p_grad := c1.grad;
            p_jib := c1.jib;
            p_pib := c1.pib;
        end loop;
    end get_klijent;

    procedure get_klijent (
        p_id       in number,
        p_naziv    out varchar2,
        p_sjediste out varchar2,
        p_jib      out varchar2,
        p_pib      out varchar2
    ) is
        v_drzava_kupca varchar2(500);
    begin
        select
            drzava_naziv
        into v_drzava_kupca
        from
            vw_klijenti
        where
            id = p_id;

        for c1 in (
            select
                *
            from
                sec_klijenti
            where
                id = p_id
        ) loop
            p_naziv := c1.naziv;
            p_sjediste := c1.adresa
                          || ' '
                          || c1.grad
                          || ' '
                          || v_drzava_kupca;

            p_jib := c1.jib;
            p_pib := c1.pib;
        end loop;

    end get_klijent;

    procedure get_klijent (
        p_id    in number,
        p_naziv out varchar2
    ) is
    begin
        for c1 in (
            select
                naziv
            from
                sec_klijenti
            where
                id = p_id
        ) loop
            p_naziv := c1.naziv;
        end loop;
    end get_klijent;

    procedure get_klijent (
        p_id    in number,
        p_email out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_klijenti
            where
                id = p_id
        ) loop
            p_email := c1.email;
        end loop;
    end get_klijent;
    
    
    procedure get_klijent_entitet (
        p_id    in number,
        p_entitet_id out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_klijenti
            where
                id = p_id
        ) loop
            p_entitet_id := c1.entitet_id;
        end loop;
    end get_klijent_entitet;

    -- Za finansije, da dobijemo pdv indikator i uio tip dokumenta
    procedure get_klijent (
        p_id                 in number,
        p_tip_klijenta_sifra out varchar2,
        p_pdv_obaveznik      out varchar2,
        p_entitet_sifra      out varchar2,
        p_ino_drzava         out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                vw_klijenti
            where
                id = p_id
        ) loop
            p_tip_klijenta_sifra := lower(c1.tip_klijenta_sifra);
            p_pdv_obaveznik := c1.pdv_obaveznik;
            p_entitet_sifra := lower(c1.entitet_sifra);
            p_ino_drzava := c1.ino_drzava;
        end loop;
    end get_klijent;

    -- Za automatsko knjizenje KIF
    procedure get_klijent (
        p_id                 in number,
        p_sablon_id          out number,
        p_pdv_obaveznik      out varchar2,
        p_ino_drzava         out varchar2,
        p_entitet_sifra      out varchar2,
        p_tip_klijenta_sifra out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                vw_klijenti
            where
                id = p_id
        ) loop
            p_sablon_id := c1.sablon_id;
            p_tip_klijenta_sifra := lower(c1.tip_klijenta_sifra);
            p_pdv_obaveznik := c1.pdv_obaveznik;
            p_entitet_sifra := lower(c1.entitet_sifra);
            p_ino_drzava := c1.ino_drzava;
        end loop;
    end get_klijent;
    
    -- eRibolovac
    function insert_klijent (
        p_klijent in sec_klijenti%rowtype
    ) return number is
        l_id number;
    begin
        insert into sec_klijenti values p_klijent returning id into l_id;
        
        return l_id;
    end ;

    function insert_klijent (
        p_ooj_id          in number,
        p_vrsta_klijenta  in varchar2,
        p_tip_klijenta_id in number,
        p_radnik_id       in number,
