        p_postanski_broj  in varchar2,
        p_tel             in varchar2,
        p_email           in varchar2,
        p_web             in varchar2,
        p_sud             in varchar2,
        p_jib             in varchar2,
        p_pib             in varchar2,
        p_sablon_id       in number,
        p_kontna_klasa_id in number
    ) return number is
        l_id number;
    begin
        insert into sec_klijenti (
            ooj_id,
            vrsta_klijenta,
            tip_klijenta_id,
            radnik_id,
            drzava_id,
            entitet_id,
            naziv,
            adresa,
