            tel,
            email,
            web,
            sud,
            jib,
            pib,
            sablon_id,
            kontna_klasa_id
        ) values ( p_ooj_id,
                   p_vrsta_klijenta,
                   p_tip_klijenta_id,
                   p_radnik_id,
                   p_drzava_id,
                   p_entitet_id,
                   p_naziv,
                   p_adresa,
                   p_grad,
                   p_postanski_broj,
