                   p_email,
                   p_web,
                   p_sud,
                   p_jib,
                   p_pib,
                   p_sablon_id,
                   p_kontna_klasa_id ) returning id into l_id;

        return l_id;
    end insert_klijent;

    procedure update_klijent (
        p_id              in number,
        p_ooj_id          in number,
        p_vrsta_klijenta  in varchar2,
        p_tip_klijenta_id in number,
        p_radnik_id       in number,
        p_drzava_id       in number,
        p_entitet_id      in number,
        p_naziv           in varchar2,
        p_adresa          in varchar2,
        p_grad            in varchar2,
