        p_valid           in varchar2
    ) is
    begin
        update sec_klijenti
        set
            ooj_id = p_ooj_id,
            vrsta_klijenta = p_vrsta_klijenta,
            tip_klijenta_id = p_tip_klijenta_id,
            radnik_id = p_radnik_id,
            drzava_id = p_drzava_id,
