            kontna_klasa_id = p_kontna_klasa_id,
            valid = p_valid
        where
            id = p_id;

    end update_klijent;

    procedure delete_klijent (
        p_id in number
    ) is
    begin
        delete from sec_klijenti
        where
            id = p_id;

    end delete_klijent;
    

    procedure update_klijent_sablon (
        p_klijent_list in varchar2,
