            ziro_racun=p_ziro_racun,
            valid = p_valid
        where
            id = p_id;

    end update_klijent_car_service;
    
    --Treba popraviti baca child record found
    
    procedure delete_klijent_car_service(
        p_id in number
    )is 
    begin
        --1) Brišemo vozila klijenta koja pripadaju određenoj org. jedinici
    
        delete from car_service.vozilo_oj
        where klijent_id=p_id;
            
            
        --) Brišemo korisnički nalog klijenta koji pripda ordređenoj org.jedinici
        
         delete from core.korisnik_oj
        where klijent_id=p_id;
        
       
        --3) Brišemo klijenta
        delete from sec_klijenti
        where
            id=p_id;
    end delete_klijent_car_service;
    
     function insert_klijent_car_service (
        p_ooj_id          in number,
        p_vrsta_klijenta  in varchar2,
        p_tip_klijenta_id in number,
        p_drzava_id       in number,
        p_entitet_id      in number,
        p_naziv           in varchar2,
        p_adresa          in varchar2,
        p_grad            in varchar2,
        p_postanski_broj  in varchar2,
        p_tel             in varchar2,
        p_email           in varchar2,
        p_jib             in varchar2,
        p_pib             in varchar2,
        p_ziro_racun      in varchar2
     
    ) return number is
        l_id number;
    begin
        insert into sec_klijenti (
            ooj_id,
            vrsta_klijenta,
            tip_klijenta_id,
            drzava_id,
            entitet_id,
            naziv,
            adresa,
            grad,
            postanski_broj,
            tel,
            email,
            jib,
            pib,
            ziro_racun
        ) values ( p_ooj_id,
                   p_vrsta_klijenta,
                   p_tip_klijenta_id,
                   p_drzava_id,
                   p_entitet_id,
                   p_naziv,
                   p_adresa,
                   p_grad,
                   p_postanski_broj,
                   p_tel,
                   p_email,
                   p_jib,
                   p_pib,
                   p_ziro_racun) returning id into l_id;

        return l_id;
    end insert_klijent_car_service;
    

    --------------------------------------------------------------
    -- procedures for table SEC_KASE
    --------------------------------------------------------------

    function get_kasa_naziv (
        p_id in number
    ) return varchar2 is
    begin
        for c1 in (
            select
                naziv
            from
                sec_kase
            where
                id = p_id
        ) loop
            return c1.naziv;
        end loop;

        return 'Odaberi kasu';
    end get_kasa_naziv;

    procedure get_kasa (
        p_id     in number,
        p_ooj_id out number,
        p_naziv  out varchar2,
        p_bearer out varchar2,
        p_pin    out varchar2,
        p_host   out varchar2,
        p_valid  out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_kase
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_naziv := c1.naziv;
            p_bearer := c1.bearer;
            p_pin := c1.pin;
            p_host := c1.host;
            p_valid := c1.valid;
        end loop;
    end get_kasa;

    procedure insert_kasa (
        p_ooj_id in number,
        p_naziv  in varchar2,
        p_bearer in varchar2,
        p_pin    in varchar2,
        p_host   in varchar2
    ) is
    begin
        insert into sec_kase (
            ooj_id,
            naziv,
            bearer,
            pin,
            host
        ) values ( p_ooj_id,
                   p_naziv,
                   p_bearer,
                   p_pin,
                   p_host );

    end insert_kasa;

    procedure update_kasa (
        p_id     in number,
        p_ooj_id in number,
        p_naziv  in varchar2,
        p_bearer in varchar2,
        p_pin    in varchar2,
        p_host   in varchar2,
        p_valid  in varchar2
    ) is
    begin
        update sec_kase
        set
            ooj_id = p_ooj_id,
            naziv = p_naziv,
            bearer = p_bearer,
            pin = p_pin,
            host = p_host,
            valid = p_valid
        where
            id = p_id;

    end update_kasa;

    procedure delete_kasa (
        p_id in number
    ) is
    begin
        delete from sec_kase
        where
            id = p_id;

    end delete_kasa;

end sec_pkg;
/

prompt
prompt Creating package body SKLADISTA_PKG
prompt ===================================
prompt
create or replace package body accounting.skladista_pkg is

    g_prijemnica_sifra   constant varchar2(16) := 'pri';
    g_otpremnica_sifra   constant varchar2(16) := 'ot';

    --------------------------------------------------------------
    -- procedures for table SKLADISTA
    --------------------------------------------------------------
    
    function get_skladiste_sifra (
        p_id in number
    ) return varchar2 is
    begin
        for c1 in (
            select
                sifra
            from
                skladista
            where
                id = p_id
        ) loop
            return c1.sifra;
        end loop;

        return 'Odaberi skladište';
    end get_skladiste_sifra;
    
    procedure get_skladiste (
        p_id    in number,
        p_oj_id out number
    ) is
    begin
        for c1 in (
            select
                oj_id
            from
                skladista
            where
                id = p_id
        ) loop
            p_oj_id := c1.oj_id;
        end loop;
    end get_skladiste;
    
    procedure get_skladiste_cjenovnik (
        p_id    in number,
        p_cjenovnik_id out number
    ) is
    begin
        for c1 in (
            select
               s.cjenovnik_id 
            from
                skladista s
            where
                s.id = p_id
        ) loop
            p_cjenovnik_id := c1.cjenovnik_id;
        end loop;
    end get_skladiste_cjenovnik;
    

    PROCEDURE get_skladiste (
        p_id               IN NUMBER,
        p_ooj_id           OUT NUMBER,
        p_nadredjeno_id    OUT NUMBER,
        p_valuta_id        OUT NUMBER,
        p_tip_skladista_id OUT NUMBER,
        p_tip_cijene_id    OUT NUMBER,
        p_cjenovnik_id     OUT NUMBER,
        p_kontna_klasa_id  OUT NUMBER,
        p_radnik_id        OUT NUMBER,
        p_oj_id            OUT NUMBER,
        p_naziv            OUT VARCHAR2,
        p_sifra            OUT VARCHAR2,
        p_adresa           OUT VARCHAR2,
        p_fax              OUT VARCHAR2,
        p_napomena         OUT VARCHAR2,
        p_valid            OUT VARCHAR2
    ) IS
    BEGIN
        FOR c1 IN (
            SELECT
                *
            FROM
                skladista
            WHERE
                id = p_id
        ) LOOP
            p_ooj_id := c1.ooj_id;
            p_nadredjeno_id := c1.nadredjeno_id;
            p_valuta_id := c1.valuta_id;
            p_tip_skladista_id := c1.tip_skladista_id;
            p_tip_cijene_id := c1.tip_cijene_id;
            p_cjenovnik_id := c1.cjenovnik_id;
            p_kontna_klasa_id := c1.kontna_klasa_id;
            p_radnik_id := c1.radnik_id;
            p_oj_id := c1.oj_id;
            p_naziv := c1.naziv;
            p_sifra := c1.sifra;
            p_adresa := c1.adresa;
            p_fax := c1.fax;
            p_napomena := c1.napomena;
            p_valid := c1.valid;
        END LOOP;
    END get_skladiste;

    FUNCTION insert_skladiste (
        p_ooj_id           IN NUMBER,
        p_nadredjeno_id    IN NUMBER,
        p_valuta_id        IN NUMBER,
        p_tip_skladista_id IN NUMBER,
        p_tip_cijene_id    IN NUMBER,
        p_cjenovnik_id     IN NUMBER,
        p_kontna_klasa_id  IN NUMBER,
        p_radnik_id        IN NUMBER,
        p_oj_id            IN NUMBER,
        p_naziv            IN VARCHAR2,
        p_sifra            IN VARCHAR2,
        p_adresa           IN VARCHAR2,
        p_fax              IN VARCHAR2,
        p_napomena         IN VARCHAR2
    ) RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        INSERT INTO skladista (
            ooj_id,
            nadredjeno_id,
            valuta_id,
            tip_skladista_id,
            tip_cijene_id,
            cjenovnik_id,
            kontna_klasa_id,
            radnik_id,
            oj_id,
            naziv,
            sifra,
            adresa,
            fax,
            napomena
        ) VALUES (
            p_ooj_id,
            p_nadredjeno_id,
            p_valuta_id,
            p_tip_skladista_id,
            p_tip_cijene_id,
            p_cjenovnik_id,
            p_kontna_klasa_id,
            p_radnik_id,
            p_oj_id,
            p_naziv,
            p_sifra,
            p_adresa,
            p_fax,
            p_napomena
        ) RETURNING id INTO l_id;
        
        RETURN l_id;

    END insert_skladiste;

    PROCEDURE update_skladiste (
        p_id               IN NUMBER,
        p_ooj_id           IN NUMBER,
        p_nadredjeno_id    IN NUMBER,
        p_valuta_id        IN NUMBER,
        p_tip_skladista_id IN NUMBER,
        p_tip_cijene_id    IN NUMBER,
        p_cjenovnik_id     IN NUMBER,
        p_kontna_klasa_id  IN NUMBER,
        p_radnik_id        IN NUMBER,
        p_oj_id            IN NUMBER,
        p_naziv            IN VARCHAR2,
        p_sifra            IN VARCHAR2,
        p_adresa           IN VARCHAR2,
        p_fax              IN VARCHAR2,
        p_napomena         IN VARCHAR2,
        p_valid            IN VARCHAR2
    ) IS
    BEGIN
        UPDATE skladista
        SET
            ooj_id = p_ooj_id,
            nadredjeno_id = p_nadredjeno_id,
            valuta_id = p_valuta_id,
            tip_skladista_id = p_tip_skladista_id,
            tip_cijene_id = p_tip_cijene_id,
            cjenovnik_id = p_cjenovnik_id,
            kontna_klasa_id = p_kontna_klasa_id,
            radnik_id = p_radnik_id,
            oj_id = p_oj_id,
            naziv = p_naziv,
            sifra = p_sifra,
            adresa = p_adresa,
            fax = p_fax,
            napomena = p_napomena,
            valid = p_valid
        WHERE
            id = p_id;

    END update_skladiste;

    PROCEDURE delete_skladiste (
        p_id IN NUMBER
    ) IS
    BEGIN
        DELETE FROM skladista
        WHERE
            id = p_id;

    END delete_skladiste;

    --------------------------------------------------------------
    -- procedures for table SKLADISTE_KORISNICI
    --------------------------------------------------------------

    PROCEDURE insert_skladiste_korisnici (
        p_skladiste_id IN NUMBER,
        p_korisnik_id  IN VARCHAR2
    ) IS
    BEGIN
        
        INSERT INTO skladiste_korisnici (
            skladiste_id,
            korisnik_id
        ) 
        SELECT
            p_skladiste_id,
            column_value
        FROM
            apex_string.split(p_korisnik_id, ':');

    END insert_skladiste_korisnici;

    PROCEDURE delete_skladiste_korisnik (
        p_id IN NUMBER
    ) IS
    BEGIN
        DELETE FROM skladiste_korisnici
        WHERE
            id = p_id;

    END delete_skladiste_korisnik;

    --------------------------------------------------------------
    -- procedures for table TREBOVANJA
    --------------------------------------------------------------

    procedure get_trebovanje (
        p_id                  in number,
        p_ooj_id              out number,
        p_tip_kretanja_id     out number,
        p_skladiste_id        out number,
        p_osnovno_sredstvo_id out number,
        p_radni_nalog_id      out number,
        p_oj_id               out number,
        p_broj                out number,
        p_naziv               out varchar2,
        p_godina              out number,
        p_datum               out date,
        p_opis                out varchar2,
        p_zakljucano          out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                trebovanja
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_tip_kretanja_id := c1.tip_kretanja_id;
            p_skladiste_id := c1.skladiste_id;
            p_osnovno_sredstvo_id := c1.osnovno_sredstvo_id;
            p_radni_nalog_id := c1.radni_nalog_id;
            p_oj_id := c1.oj_id;
            p_broj := c1.broj;
            p_naziv := c1.naziv;
            p_godina := c1.godina;
            p_datum := c1.datum;
            p_opis := c1.opis;
            p_zakljucano := c1.zakljucano;
        end loop;
    end get_trebovanje;

    -- Za kreiranje operacija
    procedure get_trebovanje (
        p_id                  in number,
        p_tip_kretanja_id     out number,
        p_skladiste_id        out number,
        p_osnovno_sredstvo_id out number,
        p_radni_nalog_id      out number,
        p_oj_id               out number,
        p_datum               out date,
        p_opis                out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                trebovanja
            where
                id = p_id
        ) loop
            p_tip_kretanja_id := c1.tip_kretanja_id;
            p_skladiste_id := c1.skladiste_id;
            p_osnovno_sredstvo_id := c1.osnovno_sredstvo_id;
            p_radni_nalog_id := c1.radni_nalog_id;
            p_oj_id := c1.oj_id;
            p_datum := c1.datum;
            p_opis := c1.opis;
        end loop;
    end get_trebovanje;

    function insert_trebovanje (
        p_ooj_id              in number,
        p_tip_kretanja_id     in number,
        p_skladiste_id        in number,
        p_osnovno_sredstvo_id in number,
        p_radni_nalog_id      in number,
        p_skladiste_prenos_id in number,
        p_oj_id               in number,
        p_radnik_id           in number,
        p_broj                in number,
        p_naziv               in varchar2,
        p_godina              in number,
        p_datum               in date,
        p_opis                in varchar2,
        p_korisnik_id         in number
    ) return number is
        l_id number;
        l_status_id number := sif.acc_pkg.get_status_id('NEW');
    begin
        insert into trebovanja (
            ooj_id,
            tip_kretanja_id,
            skladiste_id,
            osnovno_sredstvo_id,
            radni_nalog_id,
            skladiste_prenos_id,
            oj_id,
            radnik_id,
            broj,
            naziv,
            godina,
            datum,
            opis,
            status_id
        ) values ( 
            p_ooj_id,
            p_tip_kretanja_id,
            p_skladiste_id,
            p_osnovno_sredstvo_id,
            p_radni_nalog_id,
            p_skladiste_prenos_id,
            p_oj_id,
            p_radnik_id,
            p_broj,
            p_naziv,
            p_godina,
            p_datum,
            p_opis,
            l_status_id
        ) returning id into l_id;
        
        insert_trebovanje_history (
            p_trebovanje_id => l_id,
            p_status_id     => l_status_id,
            p_korisnik_id   => p_korisnik_id
        );

        core.protokoli_pkg.update_brojac(
            p_ooj_id             => p_ooj_id,
            p_vrsta_naloga_sifra => 'tr',
            p_godina             => p_godina,
            p_value              => 1
        );

        return l_id;
    end insert_trebovanje;

    procedure update_trebovanje (
        p_id                  in number,
        p_tip_kretanja_id     in number,
        p_skladiste_id        in number,
        p_osnovno_sredstvo_id in number,
        p_radni_nalog_id      in number,
        p_skladiste_prenos_id in number,
        p_oj_id               in number,
        p_radnik_id           in number,
        p_opis                in varchar2,
        p_korisnik_id         in number
    ) is
        l_status_id number := sif.acc_pkg.get_status_id('NEW');
    begin
        update trebovanja set
            tip_kretanja_id = p_tip_kretanja_id,
            skladiste_id = p_skladiste_id,
            osnovno_sredstvo_id = p_osnovno_sredstvo_id,
            radni_nalog_id = p_radni_nalog_id,
            skladiste_prenos_id = p_skladiste_prenos_id,
            oj_id = p_oj_id,
            radnik_id = p_radnik_id,
            opis = p_opis
        where
            id = p_id;
    
        insert_trebovanje_history (
            p_trebovanje_id => p_id,
            p_status_id     => l_status_id,
            p_korisnik_id   => p_korisnik_id
        );
        
    end update_trebovanje;
    
    procedure update_trebovanje_odobri (
        p_id          in number,
        p_radnik_id   in number,
        p_korisnik_id in number
    ) is
        l_status_id number := sif.acc_pkg.get_status_id('ACCEPTED');
    begin
        update trebovanja set
            status_id = l_status_id,
            odobrio_radnik_id = p_radnik_id,
            zakljucano = 'Y'
        where
            id = p_id;
            
        insert_trebovanje_history (
            p_trebovanje_id => p_id,
            p_status_id     => l_status_id,
            p_korisnik_id   => p_korisnik_id
        );
            
    end update_trebovanje_odobri;
    
    procedure update_trebovanje_odbij (
        p_id          in number,
        p_radnik_id   in number,
        p_korisnik_id in number
    ) is
        l_status_id number := sif.acc_pkg.get_status_id('REJECTED');
    begin
        update trebovanja set
            status_id = l_status_id,
            zakljucano = 'Y'
        where
            id = p_id;
            
        insert_trebovanje_history (
            p_trebovanje_id => p_id,
            p_status_id     => l_status_id,
            p_korisnik_id   => p_korisnik_id
        );
    
    end update_trebovanje_odbij;
    
    procedure update_trebovanje_realizuj (
        p_id          in number,
        p_radnik_id   in number,
        p_korisnik_id in number
    ) is
        l_status_id number := sif.acc_pkg.get_status_id('REALIZED');
        l_operacija_id number;
    begin
        update trebovanja set
            status_id = l_status_id,
            primio_radnik_id = p_radnik_id
        where
            id = p_id;
            
        insert_trebovanje_history (
            p_trebovanje_id => p_id,
            p_status_id     => l_status_id,
            p_korisnik_id   => p_korisnik_id
        );
        
        l_operacija_id := insert_operacija_from_trebovanje (
            p_trebovanje_id => p_id
        );
    
    end update_trebovanje_realizuj;

    procedure delete_trebovanje (
        p_id in number
    ) is
    begin
        delete from trebovanje_history
        where
            trebovanje_id = p_id;
            
        delete from trebovanje_stavke
        where
            trebovanje_id = p_id;

        delete from trebovanja
        where
            id = p_id;

    end delete_trebovanje;

    --------------------------------------------------------------
    -- procedures for table TREBOVANJE_STAVKE
    --------------------------------------------------------------

    procedure add_trebovanje_to_collection (
        p_id              in number,
        p_collection_name in varchar2
    ) is
    begin
        if apex_collection.collection_exists(p_collection_name => p_collection_name) then
            apex_collection.delete_collection(p_collection_name => p_collection_name);
        end if;

        apex_collection.create_collection_from_query(
            p_collection_name => p_collection_name,
            p_query           => '
                SELECT
                    stavka_id,
                    kolicina
                FROM
                    trebovanje_stavke
                WHERE
                    trebovanje_id = '
                       || p_id
                       || ''
        );

    end add_trebovanje_to_collection;

    procedure insert_trebovanje_stavka (
        p_trebovanje_id in number,
        p_stavka_id     in number,
        p_kolicina      in number
    ) is
    begin
        insert into trebovanje_stavke (
            trebovanje_id,
            stavka_id,
            kolicina
        ) values (
            p_trebovanje_id,
            p_stavka_id,
            p_kolicina
        );
    end insert_trebovanje_stavka;

    procedure update_trebovanje_stavka (
        p_id            in number,
        p_trebovanje_id in number,
        p_stavka_id     in number,
        p_kolicina      in number
    ) is
    begin
        update trebovanje_stavke set
            trebovanje_id = p_trebovanje_id,
            stavka_id = p_stavka_id,
            kolicina = p_kolicina
        where
            id = p_id;
    
    end update_trebovanje_stavka;

    procedure delete_trebovanje_stavka (
        p_id in number
    ) is
    begin
        delete from trebovanje_stavke
        where
            id = p_id;

    end delete_trebovanje_stavka;

    --------------------------------------------------------------
    -- procedures for table TREBOVANJE_HISTORY
    --------------------------------------------------------------

    PROCEDURE insert_trebovanje_history (
        p_trebovanje_id IN NUMBER,
        p_status_id     IN NUMBER,
        p_korisnik_id   IN NUMBER
    ) IS
    BEGIN
        INSERT INTO trebovanje_history (
            trebovanje_id,
            status_id,
            korisnik_id,
            datum
        ) VALUES (
            p_trebovanje_id,
            p_status_id,
            p_korisnik_id,
            current_date 
        );

    END insert_trebovanje_history;

    --------------------------------------------------------------
    -- procedures for table OPERACIJE
    --------------------------------------------------------------
    
    procedure get_operacija_dokument (
        p_tip_kretanja_id in number,
        p_skladiste_id    in number,
        p_godina          in number,
        p_naziv           out varchar2,
        p_broj            out number
    ) is
        l_skracenica varchar2(32);
        l_skladiste_sifra varchar2(32);
        l_broj number;
    begin
        select
            skracenica
        into
            l_skracenica
        from
            sif.acc_tipovi_kretanja_robe
        where
            id = p_tip_kretanja_id;
            
        select
            sifra
        into
            l_skladiste_sifra
        from
            skladista
        where
            id = p_skladiste_id;
            
        select
            coalesce(max(broj) + 1, 1)
        into
            l_broj
        from
            operacije
        where
            skladiste_id = p_skladiste_id
            and tip_kretanja_id = p_tip_kretanja_id
            and godina = p_godina;
            
        p_broj := l_broj;
        p_naziv := l_skracenica || '/' || l_skladiste_sifra || '/' || l_broj || '/' || p_godina;
            
    end get_operacija_dokument;
    
    procedure get_operacija (
        p_id                  in number,
        p_ooj_id              out number,
        p_tip_kretanja_id     out number,
        p_osnovno_sredstvo_id out number,
        p_radni_nalog_id      out number,
        p_skladiste_prenos_id out number,
        p_veza_id             out number,
        p_oj_id               out number,
        p_broj                out number,
        p_naziv               out varchar2,
        p_datum               out date,
        p_opis                out varchar2,
        p_zakljucano          out varchar2
    ) is
    begin
        for c1 in (
            select
                ooj_id,
                tip_kretanja_id,
                osnovno_sredstvo_id,
                radni_nalog_id,
                skladiste_prenos_id,
                veza_id,
                oj_id,
                broj,
                naziv,
                datum,
                opis,
                zakljucano
            from
                operacije
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_tip_kretanja_id := c1.tip_kretanja_id;
            p_osnovno_sredstvo_id := c1.osnovno_sredstvo_id;
            p_radni_nalog_id := c1.radni_nalog_id;
            p_skladiste_prenos_id := c1.skladiste_prenos_id;
            p_veza_id := c1.veza_id;
            p_oj_id := c1.oj_id;
            p_broj := c1.broj;
            p_naziv := c1.naziv;
            p_datum := c1.datum;
            p_opis := c1.opis;
            p_zakljucano := c1.zakljucano;
        
        end loop;
    end get_operacija;
    
    procedure zakljucaj_operaciju (
        p_id in number
    ) is
    begin
        update operacije set
            zakljucano = 'Y'
        where
            id = p_id;
        
    end zakljucaj_operaciju;
    
    function insert_operacija (
        p_ooj_id              in number,
        p_skladiste_id        in number,
        p_tip_kretanja_id     in number,
        p_osnovno_sredstvo_id in number default null,
        p_radni_nalog_id      in number default null,
        p_skladiste_prenos_id in number default null,
        p_faktura_id          in number default null,
        p_veza_id             in number default null,
        p_oj_id               in number,
        p_broj                in number,
        p_naziv               in varchar2,
        p_godina              in number,
        p_datum               in date,
        p_opis                in varchar2
    ) return number is
        l_id                 number;
    begin
        insert into operacije (
            ooj_id,
            skladiste_id,
            tip_kretanja_id,
            osnovno_sredstvo_id,
            radni_nalog_id,
            skladiste_prenos_id,
            veza_id,
            oj_id,
            broj,
            naziv,
            godina,
            datum,
            opis
        ) values ( 
            p_ooj_id,
            p_skladiste_id,
            p_tip_kretanja_id,
            p_osnovno_sredstvo_id,
            p_radni_nalog_id,
            p_skladiste_prenos_id,
            p_veza_id,
            p_oj_id,
            p_broj,
            p_naziv,
            p_godina,
            p_datum,
            p_opis
        ) returning id into l_id;

        return l_id;
    end insert_operacija;
    
    function insert_operacija_from_trebovanje (
        p_trebovanje_id in number
    ) return number is
        r_trebovanje trebovanja%rowtype;
        r_operacija operacije%rowtype;
    begin
        select * into r_trebovanje from trebovanja where id = p_trebovanje_id;
        
        skladista_pkg.get_operacija_dokument (
            p_tip_kretanja_id => r_trebovanje.tip_kretanja_id,
            p_skladiste_id    => r_trebovanje.skladiste_id,
            p_godina          => r_trebovanje.godina,
            p_naziv           => r_operacija.naziv,
            p_broj            => r_operacija.broj
        );
        
        r_operacija.ooj_id := r_trebovanje.ooj_id;
        r_operacija.skladiste_id := r_trebovanje.skladiste_id;
        r_operacija.tip_kretanja_id := r_trebovanje.tip_kretanja_id;
        r_operacija.trebovanje_id := p_trebovanje_id;
        r_operacija.oj_id := r_trebovanje.oj_id;
        r_operacija.godina := r_trebovanje.godina;
        r_operacija.datum  := sysdate;
        r_operacija.opis := r_trebovanje.opis;
        r_operacija.zakljucano := 'N';
        
        insert into operacije values r_operacija returning id into r_operacija.id;
        
        for c1 in (
            select
                stavka_id,
                kolicina,
                stavke_pkg.get_stavka_prosjecna_cijena (
                    p_stavka_id    => stavka_id,
                    p_skladiste_id => r_operacija.skladiste_id
                ) as prosjecna_cijena,
                
                (
                    SELECT
                        stanje_kolicina
                    FROM
                        vw_skladiste_stavke
                    WHERE
                        skladiste_id = r_operacija.skladiste_id
                        AND stavka_id = stavka_id
                ) as stanje_kolicina
            
            from
                trebovanje_stavke
            where
                trebovanje_id = p_trebovanje_id
        ) loop
        
            insert into operacija_stavke (
                operacija_id,
                stavka_id,
                kolicina,
                obradjena_kolicina,
                nabavna_cijena
            ) 
            values (
                r_operacija.id,
                c1.stavka_id,
                CASE
                    WHEN c1.stanje_kolicina > c1.kolicina THEN
                        c1.kolicina
                    ELSE
                        0
                END,
                CASE
                    WHEN c1.stanje_kolicina > c1.kolicina THEN
                        c1.kolicina
                    ELSE
                        0
                END,
                c1.prosjecna_cijena
            );
        
        end loop;
        
        return r_operacija.id;
    
    end insert_operacija_from_trebovanje;
    
    function is_operacija_editable (
        p_id number
    ) return boolean is
        l_glavna_knjiga_id number;
        l_zakljucano       varchar2(1);
        l_veza_count       number;
        l_trebovanje_count number;
    begin
        if p_id is null then
            return false;
        end if;
        
        -- Ako je proknjižen
        select
            glavna_knjiga_id,
            zakljucano
        into    
            l_glavna_knjiga_id,
            l_zakljucano
        from
            operacije
        where
            id = p_id;
        
        if l_glavna_knjiga_id is not null or l_zakljucano = 'Y' then
            return false;
        end if;
        
        -- Ako je veza negdje..
        select
            count(*)
        into
            l_veza_count
        from
            operacije
        where
            veza_id = p_id;
            
        if l_veza_count > 0 then
            return false;
        end if;
        
        -- Ako je nastao iz trebovanja
        select
            count(*)
        into
            l_trebovanje_count
        from
            operacije
        where
            trebovanje_id = p_id;
            
        if l_trebovanje_count > 0 then
            return false;
        end if;
        
        return true;
    
    end is_operacija_editable;
    
    function is_operacija_editable_wrapper (
        p_id number
    ) return number is
        l_editable boolean;
    begin
        l_editable := is_operacija_editable (p_id);
        
        if l_editable = true then
            return 1;
        end if;
        
        return 0;
    
    end is_operacija_editable_wrapper;
    
    procedure delete_operacija (
        p_id in number
    ) is
    begin
        delete from operacija_stavke
        where
            operacija_id = p_id;
            
        delete from operacije
        where
            id = p_id;
    
    end delete_operacija;
    
    function storniraj_operacija (
        p_id in number
    ) return number is
        r_operacija operacije%rowtype;
        
        cursor c_stavke is
        (
            select
                stavka_id,
                porez,
                porez_procenat,
                marza,
                marza_procenat,
                rabat,
                rabat_procenat,
                nabavna_cijena,
                mpc,
                kolicina,
                obradjena_kolicina
            from
                operacija_stavke
            where
                operacija_id = p_id
        )
        order by
            id asc;
            
        l_operacija_id number;
    begin
        select * into r_operacija from operacije where id = p_id;
    
        r_operacija.id := null;
        skladista_pkg.get_operacija_dokument (
            p_tip_kretanja_id => r_operacija.tip_kretanja_id,
            p_skladiste_id    => r_operacija.skladiste_id,
            p_godina          => r_operacija.godina,
            p_naziv           => r_operacija.naziv,
            p_broj            => r_operacija.broj
        );
        
        r_operacija.stornirano := 'N';
        r_operacija.storniran_id := p_id;
        r_operacija.datum := sysdate;
        
        insert into operacije values r_operacija returning id into l_operacija_id;
        
        insert into operacija_stavke (
            operacija_id,
            stavka_id,
            porez,
            porez_procenat,
            marza,
            marza_procenat,
            rabat,
            rabat_procenat,
            nabavna_cijena,
            mpc,
            kolicina,
            obradjena_kolicina
        ) select
            l_operacija_id,
            stavka_id,
            porez * -1,
            porez_procenat * -1,
            marza * -1,
            marza_procenat * -1,
            rabat * -1,
            rabat_procenat * -1,
            nabavna_cijena * -1,
            mpc * -1,
            kolicina * -1,
            obradjena_kolicina * -1
        from
            operacija_stavke
        where
            operacija_id = p_id;
            
        -- Update stari dokument
        update operacije set
            stornirano = 'Y'
        where
            id = p_id;
            
        return l_operacija_id;
    end storniraj_operacija;

