    --------------------------------------------------------------
    -- procedures for table KALKULACIJE
    --------------------------------------------------------------

    FUNCTION insert_kalkulacija (
        p_ooj_id IN NUMBER,
        p_broj   IN NUMBER,
        p_naziv  IN VARCHAR2,
        p_godina IN NUMBER,
        p_datum  IN DATE,
        p_opis   IN VARCHAR2
    ) RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        INSERT INTO kalkulacije (
            ooj_id,
            broj,
            naziv,
            godina,
            datum,
            opis,
            zakljucano
        ) VALUES (
            p_ooj_id,
            p_broj,
            p_naziv,
            p_godina,
            p_datum,
            p_opis,
            'N'
        ) RETURNING id INTO l_id;
        
        core.protokoli_pkg.update_brojac(
            p_ooj_id             => p_ooj_id,
            p_vrsta_naloga_sifra => 'kalk',
            p_godina             => p_godina,
            p_value              => 1
        );
    
        
        RETURN l_id;

    END insert_kalkulacija;
    
    PROCEDURE check_kalkulacija (
        p_id IN NUMBER
    ) IS
        l_sum_stavke          NUMBER;
        l_sum_kuf             NUMBER;
        l_sum_rasporedjen_kuf NUMBER;
    BEGIN
        SELECT
            sum(iznos)
        INTO
            l_sum_stavke
        FROM
            kalkulacija_stavke
        WHERE
            kalkulacija_id = p_id;
            
        SELECT
            sum(rasporedjen_iznos)
        INTO
            l_sum_rasporedjen_kuf
        FROM
            kalkulacija_kuf
        WHERE
            kalkulacija_id = p_id;
            
        SELECT
            sum(iznos_bez_pdv)
        INTO
            l_sum_kuf
        FROM
            kuf
        WHERE
            id IN (
                SELECT
                    kuf_id
                FROM
                    kalkulacija_kuf
                WHERE
                    kalkulacija_id = p_id
            );
            
        IF l_sum_stavke != l_sum_rasporedjen_kuf OR l_sum_stavke != l_sum_kuf THEN
            raise_application_error(-20001, 'Niste rasporedili kompletan iznos.');
        END IF;
        
    END check_kalkulacija;
    
    PROCEDURE zakljucaj_kalkulaciju (
        p_ooj_id         IN NUMBER,
        p_godina         IN NUMBER,
        p_kalkulacija_id IN NUMBER
    ) IS
        CURSOR c_stavke IS (
            SELECT
                operacija_stavka_id,
                stavka_id,
                kolicina,
                cijena,
                iznos,
                tip_skladista_sifra,
                cjenovnik_id
            FROM
                vw_kalkulacija_stavke
            WHERE
                kalkulacija_id = p_kalkulacija_id
        );
        
        l_cijena NUMBER;
    BEGIN
        -- Zaključavamo kalkulaciju
        UPDATE kalkulacije SET
            zakljucano = 'Y'
        WHERE
            id = p_kalkulacija_id;
            
        FOR c1 IN c_stavke LOOP
            -- Upisujemo u prijemnicu
            UPDATE operacija_stavke SET
                nabavna_cijena = c1.cijena,
                obradjena_kolicina = c1.kolicina
            WHERE
                id = c1.operacija_stavka_id;
                          
            -- Provjera za cjenovnik
            IF c1.tip_skladista_sifra = 'ROB' THEN
                l_cijena := stavke_pkg.get_nabavna_cijena (c1.cjenovnik_id, c1.stavka_id);
                IF coalesce(l_cijena, 0) != c1.cijena THEN
                    -- Azuriramo cijenu
                    stavke_pkg.insert_cjenovnik_stavka (
                        p_cjenovnik_id => c1.cjenovnik_id,
                        p_stavka_id    => c1.stavka_id,
                        p_cijena       => c1.cijena
                    );
        
                    -- Kreiramo nivelaciju
                    insert_nivelacija_cijene (
                        p_ooj_id       => p_ooj_id,
                        p_godina       => p_godina,
                        p_stavka_id    => c1.stavka_id,
                        p_stara_cijena => l_cijena,
                        p_nova_cijena  => c1.cijena
                    );
                
                END IF;
            END IF;
        
        END LOOP;
        
    END zakljucaj_kalkulaciju;
    
    PROCEDURE delete_kalkulacija (
        p_id IN NUMBER
    ) IS
    BEGIN
        DELETE FROM kalkulacija_stavke
        WHERE
            kalkulacija_id = p_id;
    
        DELETE FROM kalkulacija_operacije
        WHERE
            kalkulacija_id = p_id;
            
        DELETE FROM kalkulacija_kuf
        WHERE
            kalkulacija_id = p_id;
            
        DELETE FROM kalkulacije
        WHERE
            id = p_id;
            
    END delete_kalkulacija;

