    -- procedures for table KALKULACIJA_OPERACIJE
    --------------------------------------------------------------

    PROCEDURE insert_kalkulacija_operacija (
        p_kalkulacija_id IN NUMBER
    ) IS
    BEGIN  
        INSERT INTO kalkulacija_operacije (
            kalkulacija_id,
            operacija_id
        ) 
        SELECT
