    END insert_kalkulacija_operacija;

    PROCEDURE insert_kalkulacija_operacije (
        p_kalkulacija_id IN NUMBER,
        p_operacija_id   IN VARCHAR2
    ) IS
    BEGIN
        INSERT INTO kalkulacija_operacije (
            kalkulacija_id,
            operacija_id
        ) 
        SELECT
            p_kalkulacija_id,
            column_value
        FROM
            apex_string.split(p_operacija_id, ':');
            
            
        INSERT INTO kalkulacija_stavke (
            kalkulacija_id,
            operacija_stavka_id,
