            );
    
    END insert_kalkulacija_operacije;

    --------------------------------------------------------------
    -- procedures for table KALKULACIJA_STAVKE
    --------------------------------------------------------------

    PROCEDURE insert_kalkulacija_stavka (
        p_kalkulacija_id IN NUMBER
    ) IS
    BEGIN
        INSERT INTO kalkulacija_stavke (
            kalkulacija_id,
            operacija_stavka_id,
            kolicina
        ) 
        SELECT
            p_kalkulacija_id,
            c001,
            os.kolicina
        FROM
            apex_collections c
            LEFT JOIN operacija_stavke os ON c.c001 = os.id
        WHERE
            collection_name = 'KALKULACIJA_STAVKE';


    END insert_kalkulacija_stavka;
    
    PROCEDURE check_kalkulacija_stavke_vrijednosti (
        p_kalkulacija_kuf_id IN NUMBER,
        p_tip_kalkulacije    IN VARCHAR2
    ) IS
        l_sum NUMBER;
        l_preostalo NUMBER;
    BEGIN
        IF p_tip_kalkulacije = 'U' THEN
            SELECT
                sum(to_number(c005, '999G999G999G999G990D00'))
            INTO
                l_sum
            FROM
                apex_collections
            WHERE
                collection_name = 'KALKULACIJA_STAVKE';
                
        ELSIF p_tip_kalkulacije = 'R' THEN
            SELECT
                sum(to_number(c005, '999G999G999G999G990D00') * c002)
            INTO
                l_sum
            FROM
                apex_collections
            WHERE
                collection_name = 'KALKULACIJA_STAVKE';
        
        ELSE
            raise_application_error(-20001, 'Ne bi trebalo da se desi.');
        END IF;
        
        SELECT
            k.iznos_bez_pdv - coalesce(kk.rasporedjen_iznos, 0) 
        INTO
            l_preostalo
        FROM 
            kalkulacija_kuf kk
            LEFT JOIN vw_kuf k ON kk.kuf_id = k.id
        WHERE
            kk.id = p_kalkulacija_kuf_id;
            
        IF l_sum > l_preostalo THEN
            raise_application_error(-20001, 'Greska.');
        END IF;
    
    END check_kalkulacija_stavke_vrijednosti;
    
    PROCEDURE update_kalkulacija_stavka (
        p_id                 IN NUMBER,
        p_kolicina           IN NUMBER,
        p_kalkulacija_kuf_id IN NUMBER,
        p_tip_kalkulacije    IN VARCHAR2,
        p_vrijednost         IN NUMBER
    ) IS
        l_cijena NUMBER;
        l_iznos NUMBER;
        
        l_novi_iznos NUMBER;
        l_nova_cijena NUMBER;
    BEGIN
        SELECT
            coalesce(cijena, 0),
            coalesce(iznos, 0)
        INTO
            l_cijena,
            l_iznos
        FROM
            kalkulacija_stavke
        WHERE
            id = p_id;
            
        IF p_tip_kalkulacije = 'R' THEN
            l_nova_cijena := l_cijena + p_vrijednost;
            l_novi_iznos := l_nova_cijena * p_kolicina;
        
            UPDATE kalkulacija_stavke SET
                cijena = l_nova_cijena,
                iznos = l_novi_iznos
            WHERE
                id = p_id;
                
            UPDATE kalkulacija_kuf SET
                rasporedjen_iznos = coalesce(rasporedjen_iznos, 0) + (l_novi_iznos - l_iznos)
            WHERE
                id = p_kalkulacija_kuf_id;
        
        ELSIF p_tip_kalkulacije = 'U' THEN
            l_novi_iznos := l_iznos + p_vrijednost;
            l_nova_cijena := l_novi_iznos / p_kolicina;
        
            UPDATE kalkulacija_stavke SET
                cijena = l_nova_cijena,
                iznos = l_novi_iznos
            WHERE
                id = p_id;
                
            UPDATE kalkulacija_kuf SET
                rasporedjen_iznos = coalesce(rasporedjen_iznos, 0) + (l_novi_iznos - l_iznos)
            WHERE
                id = p_kalkulacija_kuf_id;
        
        END IF;
            
    END update_kalkulacija_stavka;
    
    PROCEDURE update_kalkulacija_stavke_automatski (
        p_kalkulacija_id     IN NUMBER,
        p_kalkulacija_kuf_id IN NUMBER
    ) IS
        l_count     NUMBER;
        l_preostalo NUMBER;
        l_iznos     NUMBER;
    BEGIN       
        SELECT
            k.iznos_bez_pdv - coalesce(kk.rasporedjen_iznos, 0) 
        INTO
            l_preostalo
        FROM 
            kalkulacija_kuf kk
            LEFT JOIN vw_kuf k ON kk.kuf_id = k.id
        WHERE
            kk.id = p_kalkulacija_kuf_id;
            
        IF l_preostalo = 0 THEN
            raise_application_error(-20001, 'Greska. 0 preostalo');
        END IF;
            
        SELECT
            count(*)
        INTO
            l_count
        FROM
            kalkulacija_stavke
        WHERE
            kalkulacija_id = p_kalkulacija_id;
            
        l_iznos := l_preostalo / l_count;
        
        UPDATE kalkulacija_stavke SET
            iznos = coalesce(iznos, 0) + l_iznos,
            cijena = (coalesce(iznos, 0) + l_iznos) / kolicina
        WHERE
            kalkulacija_id = p_kalkulacija_id;
            
        UPDATE kalkulacija_kuf SET
            rasporedjen_iznos = coalesce(rasporedjen_iznos, 0) + l_preostalo
        WHERE
            id = p_kalkulacija_kuf_id;
    
    END update_kalkulacija_stavke_automatski;

    --------------------------------------------------------------
    -- procedures for table KALKULACIJA_KUF
    --------------------------------------------------------------

    PROCEDURE insert_kalkulacija_kuf (
        p_kalkulacija_id IN NUMBER
    ) IS
    BEGIN
        INSERT INTO kalkulacija_kuf (
            kalkulacija_id,
            kuf_id,
            tip_kalkulacije
        ) 
        SELECT
            p_kalkulacija_id,
            c001,
            c002
        FROM
            apex_collections
        WHERE
            collection_name = 'KALKULACIJA_KUF';

    END insert_kalkulacija_kuf;

    PROCEDURE insert_kalkulacija_kuf (
        p_kalkulacija_id  IN NUMBER,
        p_kuf_id          IN VARCHAR2,
        p_tip_kalkulacije IN VARCHAR2
    ) IS
    BEGIN
        INSERT INTO kalkulacija_kuf (
            kalkulacija_id,
            kuf_id,
            tip_kalkulacije
        ) 
        SELECT
            p_kalkulacija_id,
            column_value,
            p_tip_kalkulacije
        FROM
            apex_string.split(p_kuf_id, ':');
    
    END insert_kalkulacija_kuf;

    --------------------------------------------------------------
    -- procedures for table NIVELACIJA
    --------------------------------------------------------------
    
    PROCEDURE insert_nivelacija_cijene (
        p_ooj_id       IN NUMBER,
        p_godina       IN NUMBER,
        p_stavka_id    IN NUMBER,
        p_stara_cijena IN NUMBER,
        p_nova_cijena  IN NUMBER
    ) IS
        l_oj_id NUMBER;
        l_broj  NUMBER;
        l_naziv VARCHAR2(255);
        l_operacija_id NUMBER;
    BEGIN
        FOR c1 IN (
            SELECT
                skladiste_id,
                stanje_kolicina
            FROM
                vw_skladiste_stavke
            WHERE
                stavka_id = p_stavka_id
                
        ) LOOP
            get_skladiste (
                p_id    => c1.skladiste_id,
                p_oj_id => l_oj_id
            );
            
            core.protokoli_pkg.get_brojac (
                p_ooj_id             => p_ooj_id,
                p_godina             => p_godina,
                p_vrsta_naloga_sifra => 'niv',
                p_broj               => l_broj,
                p_naziv              => l_naziv
            );
        
            l_operacija_id := insert_operacija (
                p_ooj_id              => p_ooj_id,
                p_skladiste_id        => c1.skladiste_id,
                p_tip_kretanja_id     => sif.acc_pkg.get_tip_kretanja_robe_id('NIV'),
                p_osnovno_sredstvo_id => null,
                p_radni_nalog_id      => null,
                p_skladiste_prenos_id => null,
                p_oj_id               => l_oj_id,
                p_broj                => l_broj,
                p_naziv               => l_naziv,
                p_godina              => p_godina,
                p_datum               => current_date,
                p_opis                => 'Automatska nivelacija cijene, nakon kalkulacije (ažuriranje nabavne cijene)'
            );
            
            core.protokoli_pkg.update_brojac(
                p_ooj_id             => p_ooj_id,
                p_vrsta_naloga_sifra => 'niv',
                p_godina             => p_godina,
                p_value              => 1
            );
            
            -- Dodavamo prvu stavku (kolicina = trenutno stanje na skladistu, iznos je razlika u cijeni)
            insert_operacija_stavka (
                p_operacija_id => l_operacija_id,
                p_stavka_id    => p_stavka_id,
                p_kolicina     => c1.stanje_kolicina,
                p_cijena       => (p_nova_cijena - p_stara_cijena)
            );
    
            -- Dodavamo drugu stavku (kolicina = -(trenutno stanje na skladistu), iznos je nula)
            insert_operacija_stavka (
                p_operacija_id => l_operacija_id,
                p_stavka_id    => p_stavka_id,
                p_kolicina     => c1.stanje_kolicina * -1,
                p_cijena       => 0
            );
            
        END LOOP;
    
    END insert_nivelacija_cijene;
    
    PROCEDURE insert_nivelacija_cijene (
        p_ooj_id       IN NUMBER,
        p_godina       IN NUMBER,
        p_stavka_id    IN NUMBER,
        p_razlika      IN NUMBER,
        p_skladista    IN VARCHAR2,
        p_skladiste_id IN NUMBER,
        p_opis         IN VARCHAR2
    ) IS
        l_oj_id NUMBER;
        l_broj  NUMBER;
        l_naziv VARCHAR2(255);
        l_operacija_id NUMBER;
    BEGIN
        FOR c1 IN (
            SELECT
                skladiste_id,
                stanje_kolicina
            FROM
                vw_skladiste_stavke
            WHERE
                stavka_id = p_stavka_id
                AND (
                    CASE
                        WHEN p_skladista = 'Y' THEN
                            1
                        WHEN p_skladista = 'N' AND skladiste_id = p_skladiste_id THEN
                            1
                    END
                ) = 1
                
        ) LOOP
            get_skladiste (
                p_id    => c1.skladiste_id,
                p_oj_id => l_oj_id
            );
            
            core.protokoli_pkg.get_brojac (
                p_ooj_id             => p_ooj_id,
                p_godina             => p_godina,
                p_vrsta_naloga_sifra => 'niv',
                p_broj               => l_broj,
                p_naziv              => l_naziv
            );
        
            l_operacija_id := insert_operacija (
                p_ooj_id              => p_ooj_id,
                p_skladiste_id        => c1.skladiste_id,
                p_tip_kretanja_id     => sif.acc_pkg.get_tip_kretanja_robe_id('NIV'),
                p_osnovno_sredstvo_id => null,
                p_radni_nalog_id      => null,
                p_skladiste_prenos_id => null,
                p_oj_id               => l_oj_id,
                p_broj                => l_broj,
                p_naziv               => l_naziv,
                p_godina              => p_godina,
                p_datum               => current_date,
                p_opis                => p_opis
            );
            
            core.protokoli_pkg.update_brojac(
                p_ooj_id             => p_ooj_id,
                p_vrsta_naloga_sifra => 'niv',
                p_godina             => p_godina,
                p_value              => 1
            );
            
            -- Dodavamo prvu stavku (kolicina = trenutno stanje na skladistu, iznos je razlika u cijeni)
            insert_operacija_stavka (
                p_operacija_id => l_operacija_id,
                p_stavka_id    => p_stavka_id,
                p_kolicina     => c1.stanje_kolicina,
                p_cijena       => p_razlika
            );
    
            -- Dodavamo drugu stavku (kolicina = -(trenutno stanje na skladistu), iznos je nula)
            insert_operacija_stavka (
                p_operacija_id => l_operacija_id,
                p_stavka_id    => p_stavka_id,
                p_kolicina     => c1.stanje_kolicina * -1,
                p_cijena       => 0
            );
            
        END LOOP;
    
    END insert_nivelacija_cijene;

    --------------------------------------------------------------
    -- procedures for table KIF
    --------------------------------------------------------------
    
    PROCEDURE insert_kif (
        p_ooj_id IN NUMBER,
        p_godina IN NUMBER,
        p_kif_id IN NUMBER
    ) IS
        r_kif kif%rowtype;
        l_tip_kretanja_id number := sif.acc_pkg.get_tip_kretanja_robe_id ('prodaja');
        l_naziv varchar2(255);
        l_broj number;
        l_operacija_id number;
    BEGIN
        select * into r_kif from kif where id = p_kif_id;
    
        skladista_pkg.get_operacija_dokument (
            p_tip_kretanja_id => l_tip_kretanja_id,
            p_skladiste_id    => r_kif.skladiste_id,
            p_godina          => r_kif.godina,
            p_naziv           => l_naziv,
            p_broj            => l_broj
        );

        l_operacija_id := insert_operacija (
            p_ooj_id          => r_kif.ooj_id,
            p_skladiste_id    => r_kif.skladiste_id,
            p_tip_kretanja_id => l_tip_kretanja_id,
            p_faktura_id      => p_kif_id,
            p_oj_id           => r_kif.oj_id,
            p_broj            => l_broj,
            p_naziv           => l_naziv,
            p_godina          => r_kif.godina,
            p_datum           => current_date,
            p_opis            => 'Automatski kreirano iz fakture.'
        );
        
        for c1 in (
            select
                stavka_id,
                kolicina,
                cijena
            from
                vw_kif_stavke
            where
                kif_id = p_kif_id
                and tip_stavke_id = 1
        ) loop
            if stavke_pkg.get_stavka_stanje_kolicina (
                p_stavka_id    => c1.stavka_id,
                p_skladiste_id => r_kif.skladiste_id
            ) < c1.kolicina then
                raise_application_error(-20001, 'Nemate tu količinu na stanju.');
            end if;

            insert_operacija_stavka (
                p_operacija_id => l_operacija_id,
                p_stavka_id    => c1.stavka_id,
                p_kolicina     => c1.kolicina,
                p_cijena       => c1.cijena
            );
        
        end loop;
    
    END insert_kif;
    
    --------------------------------------------------------------
    -- procedures for table POPISI
    --------------------------------------------------------------
    
    procedure get_popis (
        p_id           in number,
        p_skladiste_id out number
    ) is
    begin
        for c1 in (
            select
                skladiste_id
            from
                popisi
            where
                id = p_id
        ) loop
            p_skladiste_id := c1.skladiste_id;
        end loop;
    
    end get_popis;

    procedure insert_popis (
        p_ooj_id       in number,
        p_skladiste_id in number,
        p_godina       in number,
        p_naziv        in varchar2,
        p_broj         in number,
        p_datum        in date,
        p_opis         in varchar2
    ) is
        l_id NUMBER;
    begin
        insert into popisi (
            ooj_id,
            skladiste_id,
            godina,
            naziv,
            broj,
            datum,
            opis
        ) values ( 
            p_ooj_id,
            p_skladiste_id,
            p_godina,
            p_naziv,
            p_broj,
            p_datum,
            p_opis
        ) returning id into l_id;
        
        insert_popis_stavke (
            p_popis_id     => l_id,
            p_skladiste_id => p_skladiste_id,
            p_datum        => p_datum
        );
        
        core.protokoli_pkg.update_brojac (
            p_ooj_id             => p_ooj_id,
            p_vrsta_naloga_sifra => 'pop',
            p_godina             => p_godina,
            p_value              => 1
        );

    end insert_popis;

    procedure delete_popis (
        p_id in number
    ) is
    begin
        delete from popisi
        where
            id = p_id;

    end delete_popis;
    
    procedure zakljucaj_popis (
        p_ooj_id   IN NUMBER,
        p_godina   IN NUMBER,
        p_popis_id IN NUMBER
    ) is
        l_count        number;
        l_count_manjak number;
        l_count_visak  number;
        l_skladiste_id number;
        l_oj_id        number;
        
        l_broj         number;
        l_naziv        varchar2(255);
        l_operacija_id number;
    begin
        select
            count(*)
        into
            l_count
        from
            popis_stavke
        where
            popis_id = p_popis_id
            and popis_kolicina is null;
            
        select
            count(*)
        into
            l_count_manjak
        from
            popis_stavke
        where
            popis_id = p_popis_id
            and popis_kolicina > prethodna_kolicina;
            
        select
            count(*)
        into
            l_count_visak
        from
            popis_stavke
        where
            popis_id = p_popis_id
            and prethodna_kolicina > popis_kolicina;
            
        IF l_count > 0 THEN
            raise_application_error(-20001, 'Popunite sve stavke popisa.');
        END IF;
        
        get_popis (
            p_id           => p_popis_id,
            p_skladiste_id => l_skladiste_id
        );
        
        get_skladiste (
            p_id    => l_skladiste_id,
            p_oj_id => l_oj_id
        );
            
        <<popis_manjak>>
        begin
            if l_count_manjak > 0 then
                get_operacija_dokument (
                    p_tip_kretanja_id => sif.acc_pkg.get_tip_kretanja_robe_id('P_M'),
                    p_skladiste_id    => l_skladiste_id,
                    p_godina          => p_godina,
                    p_naziv           => l_naziv,
                    p_broj            => l_broj
                );
            
                l_operacija_id := insert_operacija (
                    p_ooj_id              => p_ooj_id,
                    p_skladiste_id        => l_skladiste_id,
                    p_tip_kretanja_id     => sif.acc_pkg.get_tip_kretanja_robe_id('P_M'),
                    p_osnovno_sredstvo_id => null,
                    p_radni_nalog_id      => null,
                    p_skladiste_prenos_id => null,
                    p_oj_id               => l_oj_id,
                    p_broj                => l_broj,
                    p_naziv               => l_naziv,
                    p_godina              => p_godina,
                    p_datum               => current_date,
                    p_opis                => 'Automatski popis (manjak)'
                );
        
                for c1 in (
                    select
                        stavka_id,
                        (popis_kolicina - prethodna_kolicina) AS razlika
                    from
                        popis_stavke
                    where
                        popis_id = p_popis_id
                        and popis_kolicina > prethodna_kolicina
                ) loop
                    insert_operacija_stavka (
                        p_operacija_id => l_operacija_id,
                        p_stavka_id    => c1.stavka_id,
                        p_kolicina     => c1.razlika,
                        p_cijena       => null
                    );
                end loop;
            end if;
        end;
        
        <<popis_visak>>
        begin
            if l_count_visak > 0 then
                get_operacija_dokument (
                    p_tip_kretanja_id => sif.acc_pkg.get_tip_kretanja_robe_id('P_V'),
                    p_skladiste_id    => l_skladiste_id,
                    p_godina          => p_godina,
                    p_naziv           => l_naziv,
                    p_broj            => l_broj
                );
            
                l_operacija_id := insert_operacija (
                    p_ooj_id              => p_ooj_id,
                    p_skladiste_id        => l_skladiste_id,
                    p_tip_kretanja_id     => sif.acc_pkg.get_tip_kretanja_robe_id('P_V'),
                    p_osnovno_sredstvo_id => null,
                    p_radni_nalog_id      => null,
                    p_skladiste_prenos_id => null,
                    p_oj_id               => l_oj_id,
                    p_broj                => l_broj,
                    p_naziv               => l_naziv,
                    p_godina              => p_godina,
                    p_datum               => current_date,
                    p_opis                => 'Automatski popis (višak)'
                );

                for c1 in (
                    select
                        stavka_id,
                        (prethodna_kolicina - popis_kolicina) AS razlika
                    from
                        popis_stavke
                    where
                        popis_id = p_popis_id
                        and prethodna_kolicina > popis_kolicina
                ) loop
                    insert_operacija_stavka (
                        p_operacija_id => l_operacija_id,
                        p_stavka_id    => c1.stavka_id,
                        p_kolicina     => c1.razlika,
                        p_cijena       => null
                    );
                end loop;
            end if;
        end;
        
        update popisi set
            zakljucano = 'Y'
        where
            id = p_popis_id;

    end zakljucaj_popis;

    --------------------------------------------------------------
    -- procedures for table POPIS_STAVKE
    --------------------------------------------------------------

    procedure insert_popis_stavke (
        p_popis_id     in number,
        p_skladiste_id in number,
        p_datum        in date
    ) is
    begin
        INSERT INTO popis_stavke (
            popis_id,
            stavka_id,
            redni_broj,
            prethodna_kolicina
        )
        SELECT
            p_popis_id,
            stavka_id,
            row_number() over (order by stavka_id) AS redni_broj,
            SUM(
                CASE tip_kretanja
                    WHEN 'U' THEN obradjena_kolicina
                    WHEN 'I' THEN -obradjena_kolicina
                    WHEN 'N' THEN obradjena_kolicina
                END
            ) AS stanje_kolicina
            
        FROM 
            vw_operacija_stavke
        WHERE
            skladiste_id = p_skladiste_id
            AND trunc(operacija_datum) <= trunc(p_datum)
        GROUP BY
            p_popis_id,
            stavka_id;

    end insert_popis_stavke;

    procedure update_popis_stavka (
        p_id             in number,
        p_popis_kolicina in number
    ) is
    begin
        update popis_stavke
        set
            popis_kolicina = p_popis_kolicina
        where
            id = p_id;

    end update_popis_stavka;


end skladista_pkg;
/

prompt
prompt Creating package body STAVKE_PKG
prompt ================================
prompt
create or replace package body accounting.stavke_pkg is

    -- Klase stavki
    procedure get_klasa (
        p_id            in number,
        p_ooj_id        out number,
        p_nadredjeno_id out number,
        p_naziv         out varchar2,
        p_valid         out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_klase_stavki
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_nadredjeno_id := c1.nadredjeno_id;
            p_naziv := c1.naziv;
            p_valid := c1.valid;
        end loop;
    end get_klasa;

    procedure insert_klasa (
        p_ooj_id        in number,
        p_nadredjeno_id in number,
        p_naziv         in varchar2
    ) is
    begin
        insert into sec_klase_stavki (
            ooj_id,
            nadredjeno_id,
            naziv
        ) values ( p_ooj_id,
                   p_nadredjeno_id,
                   p_naziv );

    end insert_klasa;

    procedure update_klasa (
        p_id            in number,
        p_ooj_id        in number,
        p_nadredjeno_id in number,
        p_naziv         in varchar2,
        p_valid         in varchar2
    ) is
        l_nadredjeno_id number := p_nadredjeno_id;
    begin
        if l_nadredjeno_id = p_id then
            l_nadredjeno_id := null;
        end if;
        update sec_klase_stavki
        set
            ooj_id = p_ooj_id,
            nadredjeno_id = l_nadredjeno_id,
            naziv = p_naziv,
            valid = p_valid
        where
            id = p_id;

    end update_klasa;

    procedure delete_klasa (
        p_id in number
    ) is
    begin
        delete from sec_klase_stavki
        where
            id = p_id;

    end delete_klasa;

    -- Stavke
    procedure get_stavka (
        p_id               in number,
        p_ooj_id           out number,
        p_tip_stavke_id    out number,
        p_grupa_id         out number,
        p_jm_id            out number,
        p_naziv            out varchar2,
        p_sifra            out varchar2,
        p_marza            out number,
        p_klasa_id         out number,
        p_pdv_indikator    out varchar2,
        p_pdv_indikator_id out number,
        p_ino_usluga       out varchar2,
        p_serijski_broj    out varchar2,
        p_valid            out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_stavke
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_tip_stavke_id := c1.tip_stavke_id;
            p_grupa_id := c1.grupa_id;
            p_jm_id := c1.jm_id;
            p_naziv := c1.naziv;
            p_sifra := c1.sifra;
            p_marza := c1.marza;
            p_klasa_id := c1.klasa_id;
            p_pdv_indikator := c1.pdv_indikator;
            p_pdv_indikator_id := c1.pdv_indikator_id;
            p_ino_usluga := c1.ino_usluga;
            p_serijski_broj := c1.serijski_broj;
            p_valid := c1.valid;
        end loop;
    end get_stavka;

    procedure get_stavka (
        p_id               in number,
        p_jm_id            out number,
        p_pdv_indikator    out varchar2,
        p_pdv_indikator_id out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_stavke
            where
                id = p_id
        ) loop
            p_jm_id := c1.jm_id;
            p_pdv_indikator := c1.pdv_indikator;
            p_pdv_indikator_id := c1.pdv_indikator_id;
        end loop;
    end get_stavka;

    procedure get_stavka_cijene (
        p_stavka_id      in number,
        p_nabavna_cijena in number,
        p_vpc            out number,
        p_mpc            out number
    ) is
    begin
        for c1 in (
            select
                coalesce(marza, 0) as marza
            from
                sec_stavke
            where
                id = p_stavka_id
        ) loop
             p_vpc := p_nabavna_cijena + ( p_nabavna_cijena * c1.marza / 100 );
             p_mpc := p_vpc * 1.17;
        
        end loop;
        
    end get_stavka_cijene;
    
    
    
   procedure get_stavka_cjenovnik_cijene (
      p_stavka_id in number,
      p_cjenovnik_id in number, 
      p_nabavna_cijena out number, 
      p_vpc out number,
      p_mpc out number
    ) is 
    begin
      
      p_nabavna_cijena:=0;
      p_vpc:=0;
      p_mpc:=0;
    
      for c in (select cs.nabavna_cijena, cs.vpc, cs.mpc 
                from cjenovnici cj
                join cjenovnik_stavke cs on cs.cjenovnik_id=cj.id
                where cj.id=p_cjenovnik_id
                and cs.stavka_id=p_stavka_id
                and cs.valid='Y')
                
      loop
        
          p_nabavna_cijena:=c.nabavna_cijena;
          p_vpc:=c.vpc;
          p_mpc:=c.mpc;
      
      end loop;    
    
    end get_stavka_cjenovnik_cijene;
    
    
    

    function get_stavka_naziv (
        p_id in number
    ) return varchar2 is
    begin
        for c1 in (
            select
                naziv
            from
                sec_stavke
            where
                id = p_id
        ) loop
            return c1.naziv;
        end loop;

        return null;
    end get_stavka_naziv;

    function get_stavka_jm_id (
