        p_datum_od              in date,
        p_datum_do              in date,
        p_tip_grobnog_mjesta_id in number,
        p_valid                 in varchar2
    ) is
    begin
        update sec_stavke
        set
            ooj_id = p_ooj_id,
            naziv = p_naziv,
            sifra = p_sifra,
            datum_od = p_datum_od,
            datum_do = p_datum_do,
