    --Car Service
    procedure get_stavka_car_service (
        p_id               in number,
        p_ooj_id           out number,
        p_tip_stavke_id    out number,
        p_jm_id            out number,
        p_naziv            out varchar2,
        p_sifra            out varchar2,
        p_valid            out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                sec_stavke
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_tip_stavke_id := c1.tip_stavke_id;
            p_jm_id := c1.jm_id;
            p_naziv := c1.naziv;
            p_sifra := c1.sifra;
            p_valid := c1.valid;
        end loop;
    end get_stavka_car_service;
    
    procedure insert_stavka_car_service(
        p_ooj_id           in number,
        p_tip_stavke_id    in number,
        p_jm_id            in number,
