            jm_id,
            naziv,
            sifra
        ) values ( p_ooj_id,
                   p_tip_stavke_id,
                   p_jm_id,
                   p_naziv,
                   p_sifra

                   );

    end insert_stavka_car_service;

    procedure update_stavka_car_service (
        p_id               in number,
        p_ooj_id           in number,
        p_tip_stavke_id    in number,
        p_jm_id            in number,
        p_naziv            in varchar2,
