    end update_stavka_car_service;
    
    -- Cjenovnik
    procedure get_cjenovnik (
        p_id     in number,
        p_ooj_id out number,
        p_sifra  out varchar2,
        p_naziv  out varchar2,
        p_opis   out varchar2,
        p_tip    out varchar2,
        p_valid  out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                cjenovnici
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_sifra := c1.sifra;
            p_naziv := c1.naziv;
            p_opis := c1.opis;
            p_tip := c1.tip;
            p_valid := c1.valid;
        end loop;
    end get_cjenovnik;

    procedure insert_cjenovnik (
        p_ooj_id in number,
        p_sifra  in varchar2,
        p_naziv  in varchar2,
        p_opis   in varchar2,
        p_tip    in varchar2
    ) is
    begin
        insert into cjenovnici (
            ooj_id,
            sifra,
            naziv,
            opis,
            tip
        ) values (
            p_ooj_id,
            p_sifra,
            p_naziv,
            p_opis,
            p_tip
        );

    end insert_cjenovnik;

    procedure update_cjenovnik (
        p_id     in number,
        p_ooj_id in number,
        p_sifra  in varchar2,
        p_naziv  in varchar2,
        p_opis   in varchar2,
        p_tip    in varchar2,
        p_valid  in varchar2
    ) is
    begin
        update cjenovnici
        set
            ooj_id = p_ooj_id,
            sifra = p_sifra,
            naziv = p_naziv,
            opis = p_opis,
            tip = p_tip,
            valid = p_valid
        where
            id = p_id;

    end update_cjenovnik;

    procedure delete_cjenovnik (
        p_id in number
    ) is
    begin
        delete from cjenovnici
        where
            id = p_id;

    end delete_cjenovnik;

    -- Cjenovnik stavke
    function get_nabavna_cijena (
        p_cjenovnik_id in number,
        p_stavka_id    in number
    ) return number is
    begin
        for c1 in (
            select
                nabavna_cijena
            from
                cjenovnik_stavke
            where
                cjenovnik_id = p_cjenovnik_id
                and stavka_id = p_stavka_id
                and valid = 'Y'
        ) loop
            return c1.nabavna_cijena;
        end loop;

        return null;
    end get_nabavna_cijena;

    ---izmjenjeno djordjije 21.09.2026.---
    function get_stavka_cijena (
        p_cjenovnik_id in number,
        p_stavka_id    in number,
        p_tip_cijene   in varchar2
    ) return number is
    begin
        for c1 in (
            select
                case c.tip when 'M' then cs.mpc when 'V' then cs.vpc else 0 end as jed_cijena
            from cjenovnik_stavke cs
            join cjenovnici c on c.id=cs.cjenovnik_id    
            where cjenovnik_id = p_cjenovnik_id
            and cs.stavka_id = p_stavka_id
            and cs.valid = 'Y'
        ) loop
           return c1.jed_cijena;
        end loop;

        return null;
    end get_stavka_cijena;

    procedure get_cjenovnik_stavka (
        p_id             in number,
        p_cjenovnik_id   out number,
        p_stavka_id      out number,
        p_datum          out date,
        p_nabavna_cijena out number,
        p_mpc            out number,
        p_vpc            out number,
        p_valid          out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                cjenovnik_stavke
            where
                id = p_id
        ) loop
            p_cjenovnik_id := c1.cjenovnik_id;
            p_stavka_id := c1.stavka_id;
            p_datum := c1.datum;
            p_nabavna_cijena := c1.nabavna_cijena;
            p_mpc := c1.mpc;
            p_vpc := c1.vpc;
            p_valid := c1.valid;
        end loop;
    end get_cjenovnik_stavka;

    procedure insert_cjenovnik_stavka (
        p_cjenovnik_id   in number,
        p_stavka_id      in number,
        p_datum          in date,
        p_nabavna_cijena in number,
        p_mpc            in number,
        p_vpc            in number
    ) is
    begin
      
        update cjenovnik_stavke
        set
            valid = 'N'
        where
            stavka_id = p_stavka_id
            and cjenovnik_id = p_cjenovnik_id
            and valid='Y';

        insert into cjenovnik_stavke (
            cjenovnik_id,
            stavka_id,
            datum,
            nabavna_cijena,
            mpc,
            vpc
        ) values ( p_cjenovnik_id,
                   p_stavka_id,
                   p_datum,
                   p_nabavna_cijena,
                   p_mpc,
                   p_vpc );

    end insert_cjenovnik_stavka;

    procedure insert_cjenovnik_stavka (
        p_cjenovnik_id in number,
        p_stavka_id    in number,
        p_cijena       in number
    ) is
        l_vpc number;
        l_mpc number;
    begin
        update cjenovnik_stavke
        set
            valid = 'N'
        where
            stavka_id = p_stavka_id
        and valid='Y'
        and cjenovnik_id=p_cjenovnik_id;
            
        get_stavka_cijene (
            p_stavka_id      => p_stavka_id,
            p_nabavna_cijena => p_cijena,
            p_vpc            => l_vpc,
            p_mpc            => l_mpc
        );

        insert into cjenovnik_stavke (
            cjenovnik_id,
            stavka_id,
            datum,
            nabavna_cijena,
            mpc,
            vpc
        ) values ( p_cjenovnik_id,
                   p_stavka_id,
                   sysdate,
                   p_cijena,
                   l_mpc,
                   l_vpc
        );

    end insert_cjenovnik_stavka;

    procedure update_cjenovnik_stavka (
        p_cjenovnik_id   in number,
        p_id             in number,
        p_stavka_id      in number,
        p_datum          in date,
        p_nabavna_cijena in number,
        p_mpc            in number,
        p_vpc            in number,
        p_valid          in varchar2
    ) is
    begin
  
    
    
        update cjenovnik_stavke
        set
            cjenovnik_id = p_cjenovnik_id,
            stavka_id = p_stavka_id,
            datum = p_datum,
            nabavna_cijena = p_nabavna_cijena,
            mpc = p_mpc,
            vpc = p_vpc,
            valid = p_valid
        where
            id = p_id;

    end update_cjenovnik_stavka;

    procedure delete_cjenovnik_stavka (
        p_id in number
    ) is
    begin
        delete from cjenovnik_stavke
        where
            id = p_id;

    end delete_cjenovnik_stavka;
    
    procedure deaktiviraj_cjenovnik_stavka (
        p_id in number
    ) is
    begin
      
        update cjenovnik_stavke
        set
            valid = 'N'
        where
            id=p_id;

    end deaktiviraj_cjenovnik_stavka;
    
    
    

end stavke_pkg;
/

prompt
prompt Creating package body UGOVORI_PKG
prompt =================================
prompt
CREATE OR REPLACE PACKAGE BODY ACCOUNTING.ugovori_pkg IS

    -- Šifra greške za poruke korisniku. Razlog: postojeći kod šeme koristi -20001.
    c_greska constant number := -20001;

    --------------------------------------------------------------
    -- Interne procedure
    --------------------------------------------------------------

    -- Vraća sljedeći redni broj aneksa za osnovni ugovor.
    -- Razlog: broj aneksa se ranije pravio kao decimala u BROJ, pa je deseti aneks dobijao isti broj kao prvi.
    --         Stariji aneksi nemaju ANEKS_BROJ, pa se uzima i njihov broj, da se brojevi ne ponove.
    function next_aneks_broj (
        p_osnovni_id in number
    ) return number is
        l_max   number;
        l_count number;
    begin
        select
            coalesce(max(aneks_broj), 0),
            count(*)
        into
            l_max,
            l_count
        from
            ugovori
        where
            referenca_id = p_osnovni_id;

        return greatest(l_max, l_count) + 1;
    end next_aneks_broj;

    -- Određuje kurs ugovora: ručno unesen kurs ima prednost, inače kurs na dan početka ugovora.
    -- Razlog: odgovor 10 traži iznos u KM po kursu na dan početka ugovora. Funkcija iz SIF za valute
    --         osim BAM i EUR vraća prazno ako za taj dan nema kursa, pa korisnik tada kurs unosi ručno.
    function odredi_kurs (
        p_kurs      in number,
        p_valuta_id in number,
        p_ooj_id    in number,
        p_datum     in date
    ) return number is
        l_kurs number := p_kurs;
    begin
        if p_valuta_id is null then
            return null;
        end if;

        if l_kurs is null then
            l_kurs := get_kurs(p_valuta_id, p_ooj_id, p_datum);
        end if;

        if l_kurs is null then
            raise_application_error(c_greska,
                'Za valutu ugovora ne postoji kurs na dan početka ugovora. Unesite kurs ili dopunite kursnu listu.');
        end if;

        return l_kurs;
    end odredi_kurs;

    -- Odbija izmjenu ugovora koji nije u pripremi.
    -- Razlog: zaključen ugovor se ne mijenja; svaka izmjena se radi kroz novi aneks (odgovor 14).
    procedure provjeri_editable (
        p_id in number
    ) is
    begin
        if not is_ugovor_editable(p_id) then
            raise_application_error(c_greska,
                'Ugovor nije u pripremi i ne može se mijenjati. Za izmjenu napravite aneks.');
        end if;
    end provjeri_editable;

    -- Preračunava ukupnu vrijednost ugovora iz stavki i iznos u KM.
    -- Razlog: kad ugovor ima stavke, ukupna vrijednost je njihov zbir (odgovor 12); bez stavki ostaje unesen iznos.
    procedure preracunaj_iznos (
        p_ugovor_id in number
    ) is
        l_broj number;
        l_zbir number;
    begin
        select
            count(*),
            sum(iznos)
        into
            l_broj,
            l_zbir
        from
            ugovor_stavke
        where
            ugovor_id = p_ugovor_id;

        update ugovori
        set
            iznos = case when l_broj > 0 then l_zbir else iznos end,
            iznos_km = round((case when l_broj > 0 then l_zbir else iznos end) * kurs, 2)
        where
            id = p_ugovor_id;
    end preracunaj_iznos;

    -- Provjerava da stavka iz šifarnika pripada istoj firmi kao ugovor i da je aktivna.
    -- Razlog: šifarnik stavki je po firmi, a izbor sa stranice se može zaobići.
    procedure provjeri_stavku (
        p_ugovor_id in number,
        p_stavka_id in number
    ) is
        l_broj number;
    begin
        select
            count(*)
        into l_broj
        from
            sec_stavke s
            join ugovori u on u.ooj_id = s.ooj_id
        where
                u.id = p_ugovor_id
            and s.id = p_stavka_id
            and s.valid = 'Y';

        if l_broj = 0 then
            raise_application_error(c_greska, 'Izabrana stavka ne pripada firmi ugovora ili nije aktivna.');
        end if;
    end provjeri_stavku;

    -- Računa iznos stavke: količina x cijena, umanjeno za rabat.
    function iznos_stavke (
        p_kolicina in number,
        p_cijena   in number,
        p_rabat    in number
    ) return number is
    begin
        return round(p_kolicina * p_cijena * (1 - coalesce(p_rabat, 0) / 100), 2);
    end iznos_stavke;

    -- Vraća ugovor kojem pripada stavka i zaključava njegov red.
    -- Razlog: dvije istovremene izmjene stavki istog ugovora ne smiju dati pogrešan redni broj ni zbir.
    function zakljucaj_ugovor_stavke (
        p_ugovor_id in number
    ) return number is
        l_id number;
    begin
        select
            id
        into l_id
        from
            ugovori
        where
            id = p_ugovor_id
        for update;

        return l_id;
    end zakljucaj_ugovor_stavke;

    --------------------------------------------------------------
    -- Procedures for table UGOVORI
    --------------------------------------------------------------

    procedure get_referenca (
        p_ooj_id       in number,
        p_referenca_id in number,
        p_godina       in number,
        p_naziv        out varchar2,
        p_broj         out number
    ) is
        l_prefix varchar2(16);
        l_duzina number;
        l_sufix  varchar2(16);
        l_aneks  number;
    begin
        core.protokoli_pkg.get_brojac(
            p_ooj_id             => p_ooj_id,
            p_vrsta_naloga_sifra => 'ug',
            p_godina             => p_godina,
            p_prefix             => l_prefix,
            p_duzina             => l_duzina,
            p_sufix              => l_sufix
        );

        for c1 in (
            select
                broj
            from
                ugovori u
            where
                id = p_referenca_id
        ) loop
            l_aneks := next_aneks_broj(p_referenca_id);

            p_naziv := l_prefix
                       || lpad(
                to_char(c1.broj),
                l_duzina,
                '0'
            )
                       || '-'
                       || to_char(l_aneks)
                       || l_sufix;

            -- Vraća broj osnovnog ugovora bez decimale.
            -- Razlog: redni broj aneksa se sada čuva u ANEKS_BROJ (ispravka greške sa desetim aneksom).
            p_broj := c1.broj;
        end loop;

    end get_referenca;

    procedure get_ugovor (
        p_id                 in number,
        p_ooj_id             out number,
        p_klijent_id         out number,
        p_valuta_id          out number,
        p_izvrsilac_narucioc out varchar2,
        p_ugovor_start       out date,
        p_ugovor_end         out date,
        p_iznos              out number,
        p_naziv              out varchar2,
        p_broj               out varchar2,
        p_predmet            out varchar2,
        p_referenca          out varchar2,
        p_referenca_id       out number,
        p_oj_id              out number,
        p_interval_id        out number,
        p_valid              out varchar2
    ) is
    begin
        for c1 in (
            select
                *
            from
                ugovori
            where
                id = p_id
        ) loop
            p_ooj_id := c1.ooj_id;
            p_klijent_id := c1.klijent_id;
            p_valuta_id := c1.valuta_id;
            p_izvrsilac_narucioc := c1.izvrsilac_narucioc;
            p_ugovor_start := c1.ugovor_start;
            p_ugovor_end := c1.ugovor_end;
            p_iznos := c1.iznos;
            p_naziv := c1.naziv;
            p_broj := c1.broj;
            p_predmet := c1.predmet;
            p_referenca := c1.referenca;
            p_referenca_id := c1.referenca_id;
            p_oj_id := c1.oj_id;
            p_interval_id := c1.interval_id;
            p_valid := c1.valid;
        end loop;
    end get_ugovor;

    procedure get_ugovor_dodatno (
        p_id                    in number,
        p_vrsta_ugovora_id      out number,
        p_status                out varchar2,
        p_status_naziv          out varchar2,
        p_kurs                  out number,
        p_iznos_km              out number,
        p_dan_dospijeca         out number,
        p_otkazni_rok_dana      out number,
        p_automatsko_produzenje out varchar2,
        p_produzenje_mjeseci    out number,
        p_aneks_broj            out number,
        p_broj_stavki           out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                vw_ugovori
            where
                id = p_id
        ) loop
            p_vrsta_ugovora_id := c1.vrsta_ugovora_id;
            p_status := c1.status;
            p_status_naziv := c1.status_naziv;
            p_kurs := c1.kurs;
            p_iznos_km := c1.iznos_km;
            p_dan_dospijeca := c1.dan_dospijeca;
            p_otkazni_rok_dana := c1.otkazni_rok_dana;
            p_automatsko_produzenje := c1.automatsko_produzenje;
            p_produzenje_mjeseci := c1.produzenje_mjeseci;
            p_aneks_broj := c1.aneks_broj;
            p_broj_stavki := c1.broj_stavki;
        end loop;
    end get_ugovor_dodatno;

    procedure get_ugovor (
        p_id    in number,
        p_naziv out varchar2
    ) is
    begin
        for c1 in (
            select
                naziv
            from
                ugovori
            where
                id = p_id
        ) loop
            p_naziv := c1.naziv;
        end loop;
    end get_ugovor;

    procedure get_ugovor (
        p_id         in number,
        p_klijent_id out number,
        p_oj_id      out varchar2
    ) is
    begin
        for c1 in (
            select
                klijent_id,
                oj_id
            from
                ugovori
            where
                id = p_id
        ) loop
            p_klijent_id := c1.klijent_id;
            p_oj_id := c1.oj_id;
        end loop;
    end get_ugovor;

    function get_posljednja_verzija (
        p_osnovni_id in number
    ) return number is
        l_id number;
    begin
        -- Bira posljednji zaključeni aneks, a ako ga nema, osnovni ugovor.
        -- Razlog: novi aneks nastaje kao kopija važećih uslova.
        select
            id
        into l_id
        from
            (
                select
                    id
                from
                    ugovori
                where
                    ( id = p_osnovni_id
                      or referenca_id = p_osnovni_id )
                    and status = 'Z'
                order by
                    case when id = p_osnovni_id then 0 else 1 end desc,
                    coalesce(aneks_broj, 0) desc,
                    id desc
            )
        where
            rownum = 1;

        return l_id;
    exception
        when no_data_found then
            return p_osnovni_id;
    end get_posljednja_verzija;

    function get_kurs (
        p_valuta_id in number,
        p_ooj_id    in number,
        p_datum     in date
    ) return number is
    begin
        return sif.acc_pkg.get_kurs_na_dan(
            p_valuta_id => p_valuta_id,
            p_ooj_id    => p_ooj_id,
            p_datum     => trunc(p_datum)
        );
    end get_kurs;

    function is_ugovor_editable (
        p_id in number
    ) return boolean is
        l_status ugovori.status%type;
    begin
        select
            status
        into l_status
        from
            ugovori
        where
            id = p_id;

        return l_status = 'P';
    exception
        when no_data_found then
            return false;
    end is_ugovor_editable;

    function is_ugovor_editable_yn (
        p_id in number
    ) return varchar2 is
    begin
        return case when is_ugovor_editable(p_id) then 'Y' else 'N' end;
    end is_ugovor_editable_yn;

    function insert_ugovor (
        p_ooj_id                in number,
        p_klijent_id            in number,
        p_valuta_id             in number,
        p_izvrsilac_narucioc    in varchar2,
        p_ugovor_start          in date,
        p_ugovor_end            in date,
        p_iznos                 in number,
        p_naziv                 in varchar2,
        p_broj                  in varchar2,
        p_predmet               in varchar2,
        p_referenca             in varchar2,
        p_referenca_id          in number,
        p_oj_id                 in number,
        p_interval_id           in number,
        p_system                in varchar2 default 'N',
        p_vrsta_ugovora_id      in number default null,
        p_status                in varchar2 default null,
        p_kurs                  in number default null,
        p_dan_dospijeca         in number default null,
        p_otkazni_rok_dana      in number default null,
        p_automatsko_produzenje in varchar2 default null,
        p_produzenje_mjeseci    in number default null,
        p_godina                in number default null
    ) return number is
        l_id     number;
        -- Upisuje status Z kad ga pozivalac ne pošalje.
        -- Razlog: sistemski ugovor iz CORE.SYSTEM_PKG nastaje odmah zaključen, kao i danas; stranica 71 šalje P.
        l_status varchar2(1) := coalesce(p_status, 'Z');
        l_kurs   number;
        l_aneks  number;
        l_izvor  number;
    begin
        if l_status not in ('P', 'Z') then
            raise_application_error(c_greska, 'Novi ugovor može biti samo u pripremi ili zaključen.');
        end if;

        l_kurs := odredi_kurs(p_kurs, p_valuta_id, p_ooj_id, p_ugovor_start);

        if p_referenca = 'Y' and p_referenca_id is not null then
            l_aneks := next_aneks_broj(p_referenca_id);
        end if;

        insert into ugovori (
            ooj_id,
            klijent_id,
            valuta_id,
            izvrsilac_narucioc,
            ugovor_start,
            ugovor_end,
            iznos,
            naziv,
            broj,
            predmet,
            referenca,
            referenca_id,
            oj_id,
            interval_id,
            system,
            vrsta_ugovora_id,
            status,
            kurs,
            iznos_km,
            dan_dospijeca,
            otkazni_rok_dana,
            automatsko_produzenje,
            produzenje_mjeseci,
            aneks_broj,
            godina
        ) values ( p_ooj_id,
                   p_klijent_id,
                   p_valuta_id,
                   p_izvrsilac_narucioc,
                   p_ugovor_start,
                   p_ugovor_end,
                   p_iznos,
                   p_naziv,
                   p_broj,
                   p_predmet,
                   p_referenca,
                   p_referenca_id,
                   p_oj_id,
                   p_interval_id,
                   p_system,
                   p_vrsta_ugovora_id,
                   l_status,
                   l_kurs,
                   round(p_iznos * l_kurs, 2),
                   p_dan_dospijeca,
                   p_otkazni_rok_dana,
                   coalesce(p_automatsko_produzenje, 'N'),
                   p_produzenje_mjeseci,
                   l_aneks,
                   coalesce(p_godina, extract(year from p_ugovor_start)) ) returning id into l_id;

        -- Kopira stavke posljednje zaključene verzije osnovnog ugovora u novi aneks.
        -- Razlog: aneks nastaje kao kopija važećih uslova, a korisnik mijenja samo ono što se mijenja.
        if p_referenca = 'Y' and p_referenca_id is not null then
            l_izvor := get_posljednja_verzija(p_referenca_id);

            insert into ugovor_stavke (
                ugovor_id,
                redni_broj,
                stavka_id,
                opis,
                jm_id,
                kolicina,
                cijena,
                rabat,
                iznos
            )
                select
                    l_id,
                    redni_broj,
                    stavka_id,
                    opis,
                    jm_id,
                    kolicina,
                    cijena,
                    rabat,
                    iznos
                from
                    ugovor_stavke
                where
                    ugovor_id = l_izvor;

            preracunaj_iznos(l_id);
        end if;

        return l_id;
    end insert_ugovor;

    procedure update_ugovor (
        p_id                    in number,
        p_klijent_id            in number,
        p_valuta_id             in number,
        p_izvrsilac_narucioc    in varchar2,
        p_ugovor_start          in date,
        p_ugovor_end            in date,
        p_iznos                 in number,
        p_predmet               in varchar2,
        p_oj_id                 in number,
        p_interval_id           in number,
        p_system                in varchar2 default null,
        p_valid                 in varchar2,
        p_vrsta_ugovora_id      in number default null,
        p_kurs                  in number default null,
        p_dan_dospijeca         in number default null,
        p_otkazni_rok_dana      in number default null,
        p_automatsko_produzenje in varchar2 default null,
        p_produzenje_mjeseci    in number default null
    ) is
        l_ooj_id number;
        l_kurs   number;
    begin
        provjeri_editable(p_id);

        select
            ooj_id
        into l_ooj_id
        from
            ugovori
        where
            id = p_id;

        l_kurs := odredi_kurs(p_kurs, p_valuta_id, l_ooj_id, p_ugovor_start);

        update ugovori
        set
            klijent_id = p_klijent_id,
            valuta_id = p_valuta_id,
            izvrsilac_narucioc = p_izvrsilac_narucioc,
            ugovor_start = p_ugovor_start,
            ugovor_end = p_ugovor_end,
            iznos = p_iznos,
            predmet = p_predmet,
            oj_id = p_oj_id,
            interval_id = p_interval_id,
            -- Zadržava oznaku sistemskog ugovora kad je pozivalac ne pošalje.
            -- Razlog: stranica 71 je ne šalje, pa je ranije svaka izmjena postavljala SYSTEM na N (ispravka greške).
            system = coalesce(p_system, system),
            valid = p_valid,
            vrsta_ugovora_id = p_vrsta_ugovora_id,
            kurs = l_kurs,
            dan_dospijeca = p_dan_dospijeca,
            otkazni_rok_dana = p_otkazni_rok_dana,
            automatsko_produzenje = coalesce(p_automatsko_produzenje, 'N'),
            produzenje_mjeseci = p_produzenje_mjeseci
        where
            id = p_id;

        preracunaj_iznos(p_id);
    end update_ugovor;

    procedure zakljuci_ugovor (
        p_id in number
    ) is
        l_u ugovori%rowtype;
    begin
        select
            *
        into l_u
        from
            ugovori
        where
            id = p_id
        for update;

        if l_u.status <> 'P' then
            raise_application_error(c_greska, 'Zaključiti se može samo ugovor u pripremi.');
        end if;

        -- Provjerava obavezne podatke.
        -- Razlog: zaključen ugovor se više ne mijenja, pa podaci moraju biti potpuni prije zaključenja.
        if l_u.vrsta_ugovora_id is null
           or l_u.klijent_id is null
           or l_u.valuta_id is null
           or l_u.ugovor_start is null
           or l_u.ugovor_end is null
           or l_u.iznos is null then
            raise_application_error(c_greska,
                'Ugovor nije potpun. Za zaključenje su obavezni vrsta, klijent, valuta, početak, kraj i iznos.');
        end if;

        if l_u.ugovor_end < l_u.ugovor_start then
            raise_application_error(c_greska, 'Kraj ugovora je prije početka.');
        end if;

        update ugovori
        set
            status = 'Z'
        where
            id = p_id;
    end zakljuci_ugovor;

    procedure raskini_ugovor (
        p_id in number
    ) is
        l_status       ugovori.status%type;
        l_referenca_id ugovori.referenca_id%type;
    begin
        select
            status,
            referenca_id
        into
            l_status,
            l_referenca_id
        from
            ugovori
        where
            id = p_id
        for update;

        -- Odbija raskid aneksa.
        -- Razlog: aneks je vezan za osnovni ugovor i raskida se zajedno s njim (odluka nadređenog, 27.10.2026).
        if l_referenca_id is not null then
            raise_application_error(c_greska, 'Aneks se ne raskida zasebno. Raskinite osnovni ugovor.');
        end if;

        if l_status <> 'Z' then
            raise_application_error(c_greska, 'Raskinuti se može samo zaključen ugovor.');
        end if;

        -- Raskida osnovni ugovor i sve njegove anekse koji još nisu raskinuti, i zaključene i one u pripremi.
        -- Razlog: inače bi se zaključeni aneksi raskinutog ugovora i dalje nudili na fakturama.
        update ugovori
        set
            status = 'R'
        where
            id = p_id
            or ( referenca_id = p_id
                 and status <> 'R' );
    end raskini_ugovor;

    procedure delete_ugovor (
        p_id in number
    ) is
        l_broj number;
    begin
        -- Dozvoljava brisanje samo ugovora u pripremi.
        -- Razlog: zaključen ugovor se ne briše nego raskida, da ostane trag.
        if not is_ugovor_editable(p_id) then
            raise_application_error(c_greska, 'Briše se samo ugovor u pripremi. Zaključen ugovor se raskida.');
        end if;

        -- Odbija brisanje ugovora koji ima fakture ili anekse.
        -- Razlog: inače bi fakture i aneksi pokazivali na nepostojeći ugovor.
        select
            count(*)
        into l_broj
        from
            (
                select 1 from kif where ugovor_id = p_id
                union all
                select 1 from kuf where ugovor_id = p_id
                union all
                select 1 from ugovori where referenca_id = p_id
            );

        if l_broj > 0 then
            raise_application_error(c_greska, 'Ugovor ima vezane fakture ili anekse i ne može se obrisati.');
        end if;

        delete from ugovor_stavke
        where
            ugovor_id = p_id;

        delete from ugovor_dokumenta
        where
            ugovor_id = p_id;

        delete from ugovori
        where
            id = p_id;

    end delete_ugovor;

    --------------------------------------------------------------
    -- Procedures for table UGOVOR_STAVKE
    --------------------------------------------------------------

    procedure get_ugovor_stavka (
        p_id         in number,
        p_ugovor_id  out number,
        p_redni_broj out number,
        p_stavka_id  out number,
        p_opis       out varchar2,
        p_jm_id      out number,
        p_kolicina   out number,
        p_cijena     out number,
        p_rabat      out number,
        p_iznos      out number
    ) is
    begin
        for c1 in (
            select
                *
            from
                ugovor_stavke
            where
                id = p_id
        ) loop
            p_ugovor_id := c1.ugovor_id;
            p_redni_broj := c1.redni_broj;
            p_stavka_id := c1.stavka_id;
            p_opis := c1.opis;
            p_jm_id := c1.jm_id;
            p_kolicina := c1.kolicina;
            p_cijena := c1.cijena;
            p_rabat := c1.rabat;
            p_iznos := c1.iznos;
        end loop;
    end get_ugovor_stavka;

    function insert_ugovor_stavka (
        p_ugovor_id in number,
        p_stavka_id in number,
        p_opis      in varchar2,
        p_jm_id     in number,
        p_kolicina  in number,
        p_cijena    in number,
        p_rabat     in number
    ) return number is
        l_id     number;
        l_rb     number;
        l_jm_id  number := p_jm_id;
        l_ugovor number;
        -- Računa iznos stavke prije INSERT naredbe.
        -- Razlog: interna funkcija paketa se ne može pozvati iz SQL naredbe (PLS-00231).
        l_iznos  number := iznos_stavke(p_kolicina, p_cijena, p_rabat);
    begin
        l_ugovor := zakljucaj_ugovor_stavke(p_ugovor_id);
        provjeri_editable(p_ugovor_id);
        provjeri_stavku(p_ugovor_id, p_stavka_id);

        -- Preuzima jedinicu mjere sa stavke šifarnika kad nije unesena.
        if l_jm_id is null then
            select
                jm_id
            into l_jm_id
            from
                sec_stavke
            where
                id = p_stavka_id;
        end if;

        select
            coalesce(max(redni_broj), 0) + 1
        into l_rb
        from
            ugovor_stavke
        where
            ugovor_id = p_ugovor_id;

        insert into ugovor_stavke (
            ugovor_id,
            redni_broj,
            stavka_id,
            opis,
            jm_id,
            kolicina,
            cijena,
            rabat,
            iznos
        ) values ( p_ugovor_id,
                   l_rb,
                   p_stavka_id,
                   p_opis,
                   l_jm_id,
                   p_kolicina,
                   p_cijena,
                   coalesce(p_rabat, 0),
                   l_iznos ) returning id into l_id;

        preracunaj_iznos(p_ugovor_id);
        return l_id;
    end insert_ugovor_stavka;

    procedure update_ugovor_stavka (
        p_id        in number,
        p_stavka_id in number,
        p_opis      in varchar2,
        p_jm_id     in number,
        p_kolicina  in number,
        p_cijena    in number,
        p_rabat     in number
    ) is
        l_ugovor_id number;
        l_ugovor    number;
        -- Računa iznos stavke prije UPDATE naredbe.
        -- Razlog: interna funkcija paketa se ne može pozvati iz SQL naredbe (PLS-00231).
        l_iznos     number := iznos_stavke(p_kolicina, p_cijena, p_rabat);
    begin
        select
            ugovor_id
        into l_ugovor_id
        from
            ugovor_stavke
        where
            id = p_id;

        l_ugovor := zakljucaj_ugovor_stavke(l_ugovor_id);
        provjeri_editable(l_ugovor_id);
        provjeri_stavku(l_ugovor_id, p_stavka_id);

        update ugovor_stavke
        set
            stavka_id = p_stavka_id,
            opis = p_opis,
            jm_id = p_jm_id,
            kolicina = p_kolicina,
            cijena = p_cijena,
            rabat = coalesce(p_rabat, 0),
            iznos = l_iznos
        where
            id = p_id;

        preracunaj_iznos(l_ugovor_id);
    end update_ugovor_stavka;

    procedure delete_ugovor_stavka (
        p_id in number
    ) is
        l_ugovor_id number;
        l_ugovor    number;
    begin
        select
            ugovor_id
        into l_ugovor_id
        from
            ugovor_stavke
        where
            id = p_id;

        l_ugovor := zakljucaj_ugovor_stavke(l_ugovor_id);
        provjeri_editable(l_ugovor_id);

        delete from ugovor_stavke
        where
            id = p_id;

        preracunaj_iznos(l_ugovor_id);
    end delete_ugovor_stavka;

    --------------------------------------------------------------
    -- Procedures for table UGOVOR_DOKUMENTA
    -- Dokumenta se mogu dodavati i brisati i kod zaključenog ugovora.
    -- Razlog: prilog (sken) nije uslov ugovora.
    --------------------------------------------------------------
    procedure insert_ugovor_dokument (
        p_ugovor_id in number,
        p_dokument  in varchar2
    ) is
        l_blob     blob;
        l_filename varchar2(255);
        l_mimetype varchar2(255);
    begin
        sif.utils_pkg.get_apex_file_upload(
            p_apex_filename => p_dokument,
            p_blob          => l_blob,
            p_filename      => l_filename,
            p_mimetype      => l_mimetype
        );

        insert into ugovor_dokumenta (
            ugovor_id,
            dokument,
            dokument_filename,
            dokument_mimetype,
            dokument_lastupd
        ) values ( p_ugovor_id,
                   l_blob,
                   l_filename,
                   l_mimetype,
                   sysdate );

    end insert_ugovor_dokument;

    procedure insert_ugovor_dokumenta (
        p_ugovor_id in number,
        p_dokumenta in varchar2
    ) is
    begin
        for x in (
            select
                column_value as dokument
            from
                apex_string.split(p_dokumenta, ':')
        ) loop
            insert_ugovor_dokument(
                p_ugovor_id => p_ugovor_id,
                p_dokument  => x.dokument
            );
        end loop;
    end insert_ugovor_dokumenta;

    procedure delete_ugovor_dokument (
        p_id in number
    ) is
    begin
        delete from ugovor_dokumenta
        where
            id = p_id;

    end delete_ugovor_dokument;

end ugovori_pkg;
/

