prompt Creating package body UIO_PKG
prompt =============================
prompt
create or replace package body accounting.uio_pkg is

    function is_pp_editable (
        p_ooj_id         in number,
        p_poreski_period in varchar2
    ) return boolean is
        l_period_zakljucan_do date;
    begin
        if p_poreski_period is null then
            return false;
        end if;

        -- Provjera da li je period zakljucan
        select
            period_zakljucan_do
        into l_period_zakljucan_do
        from
            core.ooj
        where
            id = p_ooj_id;

        if trunc(l_period_zakljucan_do) > to_date ( p_poreski_period, 'YYMM' ) then
            return false;
        end if;

        return true;
    end is_pp_editable;

    procedure posalji_uio_odgovor (
        p_app_id  in number,
        p_ooj_id  in number,
        p_odgovor in varchar2
    ) is
        l_username varchar2(255);
        l_mail     varchar2(255);
        l_name     varchar2(255);
    begin
        for c1 in (
            select
                korisnicko_ime,
                email,
                initcap(ime)
                || ' '
                || initcap(prezime) as name
            from
                core.korisnici
            where
                    email = (
                        select
                            email
                        from
                            core.firme
                        where
                            id = (
                                select
                                    firma_id
                                from
                                    core.ooj
                                where
                                    id = p_ooj_id
                            )
                    )
                and rownum = 1
        ) loop
            mail_pkg.posalji_uio_odgovor(
                p_app_id   => p_app_id,
                p_username => c1.korisnicko_ime,
                p_mail_to  => c1.email,
                p_name     => c1.name,
                p_odgovor  => p_odgovor
            );
        end loop;
    end posalji_uio_odgovor;

    --------------------------------------------------------------
    -- procedures for table UIO_KIF
    --------------------------------------------------------------

    function get_uio_kif_redni_broj (
        p_ooj_id         in number,
        p_poreski_period in varchar2
    ) return varchar2 is
    begin
        for c1 in (
            select
                coalesce(
                    max(redni_br + 1),
                    1
                ) as output
            from
                uio_kif
            where
                    ooj_id = p_ooj_id
                and poreski_period = p_poreski_period
        ) loop
            return c1.output;
        end loop;

        return 1;
    end get_uio_kif_redni_broj;

    procedure insert_uio_kif (
        p_ooj_id                   in number,
        p_faktura_id               in number,
        p_vrsta_sloga              in varchar2,
        p_poreski_period           in varchar2,
        p_redni_br                 in varchar2,
        p_tip_dokumenta            in varchar2,
        p_broj_fakture             in varchar2,
        p_datum_fakture            in date,
        p_naziv_kupca              in varchar2,
        p_sjediste_kupca           in varchar2,
        p_pdv_broj_kupca           in varchar2,
        p_jib_broj_kupca           in varchar2,
        p_iznos_fakture            in varchar2,
        p_iznos_fakture_interne    in varchar2,
        p_iznos_fakture_izvozne    in varchar2,
        p_iznos_ostale_bez_pdv     in varchar2,
        p_iznos_osnovice_za_pdv    in varchar2,
        p_iznos_izlaz_pdv_za_pdv   in varchar2,
        p_iznos_osnovice_za_nepdv  in varchar2,
        p_iznos_izlaz_pdv_za_nepdv in varchar2,
        p_iznos_pdv_32polje        in varchar2,
        p_iznos_pdv_33polje        in varchar2,
        p_iznos_pdv_34polje        in varchar2
    ) is
        l_rb varchar2(10);
    begin
        if not is_pp_editable(p_ooj_id, p_poreski_period) then
            raise_application_error(-20001, 'Poreski period je zaključan, nije moguće dodati novi unos u UIO KIF.');
        end if;

        if not regexp_like(p_redni_br, '^[0-9]+$') then
            l_rb := p_redni_br;
        else
            if ( to_number ( p_redni_br ) < 10 ) then
                l_rb := '0' || p_redni_br;
            else
                l_rb := p_redni_br;
            end if;
        end if;

        insert into uio_kif (
            ooj_id,
            faktura_id,
            vrsta_sloga,
            poreski_period,
            redni_br,
            tip_dokumenta,
            broj_fakture,
            datum_fakture,
            naziv_kupca,
            sjediste_kupca,
            pdv_broj_kupca,
