            iznos_osnovice_za_nepdv,
            iznos_izlaz_pdv_za_nepdv,
            iznos_pdv_32polje,
            iznos_pdv_33polje,
            iznos_pdv_34polje
        ) values ( p_ooj_id,
                   p_faktura_id,
                   p_vrsta_sloga,
                   p_poreski_period,
                   l_rb,
                   p_tip_dokumenta,
                   p_broj_fakture,
                   p_datum_fakture,
                   p_naziv_kupca,
                   p_sjediste_kupca,
                   p_pdv_broj_kupca,
                   p_jib_broj_kupca,
                   p_iznos_fakture,
                   p_iznos_fakture_interne,
                   p_iznos_fakture_izvozne,
                   p_iznos_ostale_bez_pdv,
                   p_iznos_osnovice_za_pdv,
                   p_iznos_izlaz_pdv_za_pdv,
                   p_iznos_osnovice_za_nepdv,
                   p_iznos_izlaz_pdv_za_nepdv,
                   p_iznos_pdv_32polje,
                   p_iznos_pdv_33polje,
                   p_iznos_pdv_34polje );

    end insert_uio_kif;

    procedure update_uio_kif (
        p_id                       in number,
        p_ooj_id                   in number,
        p_vrsta_sloga              in varchar2,
        p_poreski_period           in varchar2,
