                l_rb := '0' || p_redni_br;
            else
                l_rb := p_redni_br;
            end if;
        end if;

        update uio_kif
        set
            vrsta_sloga = p_vrsta_sloga,
            poreski_period = p_poreski_period,
            redni_br = l_rb,
            tip_dokumenta = p_tip_dokumenta,
