prompt
prompt Creating trigger NARUDZBENICE_BIU
prompt =================================
prompt
CREATE OR REPLACE TRIGGER ACCOUNTING."NARUDZBENICE_BIU" BEFORE
    INSERT OR UPDATE ON accounting.narudzbenice
    FOR EACH ROW
BEGIN
    IF inserting THEN
        :new.row_version := 1;
        :new.created_by := coalesce(
            sys_context('APEX$SESSION', 'APP_USER'),
            sys_context('userenv', 'proxy_user'),
            user
        );

        :new.created := sysdate;
    ELSIF updating THEN
        :new.row_version := nvl(:old.row_version,
                                0) + 1;
    END IF;

    :new.updated_by := coalesce(
        sys_context('APEX$SESSION', 'APP_USER'),
        sys_context('userenv', 'proxy_user'),
        user
    );

    :new.updated := sysdate;

END narudzbenice_biu;
/

